//! Minimal terminal size detection (Unix only).

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

/// Returns the size of the terminal, if stdout, stderr or stdin is a tty.
pub fn terminal_size() -> Option<(Width, Height)> {
    for fd in [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO] {
        if let Some(size) = size_of_fd(fd) {
            return Some(size);
        }
    }
    None
}

fn size_of_fd(fd: i32) -> Option<(Width, Height)> {
    unsafe {
        if libc::isatty(fd) != 1 {
            return None;
        }
        let mut winsize: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsize) == -1 {
            return None;
        }
        if winsize.ws_col == 0 || winsize.ws_row == 0 {
            return None;
        }
        Some((Width(winsize.ws_col), Height(winsize.ws_row)))
    }
}
EOF
