{"command":"cd /workspace && cat > src/term.rs <<'EOF'
//! Terminal color handling.

use std::sync::atomic::{AtomicU8, Ordering};

static COLOR_MODE: AtomicU8 = AtomicU8::new(0);

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum ColorChoice {
    Auto,
    Always,
    Never,
}

pub fn set_color_choice(choice: ColorChoice) {
    COLOR_MODE.store(
        match choice {
            ColorChoice::Auto => 0,
            ColorChoice::Always => 1,
            ColorChoice::Never => 2,
        },
        Ordering::Relaxed,
    );
}

fn is_tty(fd: i32) -> bool {
    unsafe { libc::isatty(fd) == 1 }
}

/// Whether colors should be used for stderr output.
pub fn colors_for_stderr() -> bool {
    match COLOR_MODE.load(Ordering::Relaxed) {
        1 => true,
        2 => false,
        _ => is_tty(libc::STDERR_FILENO) && std::env::var_os("NO_COLOR").is_none(),
    }
}

/// Whether colors should be used for stdout output.
pub fn colors_for_stdout() -> bool {
    match COLOR_MODE.load(Ordering::Relaxed) {
        1 => true,
        2 => false,
        _ => is_tty(libc::STDOUT_FILENO) && std::env::var_os("NO_COLOR").is_none(),
    }
}

/// A termcolor-like style.
#[derive(Clone, Copy, Default)]
pub struct Style {
    pub bold: bool,
    pub fg: Option<Color>,
}

#[derive(Clone, Copy)]
pub enum Color {
    Red,
    Green,
    Yellow,
    Blue,
    Cyan,
    BrightRed,
    BrightYellow,
}

impl Style {
    pub fn new() -> Self {
        Self::default()
    }
    pub fn bold(mut self) -> Self {
        self.bold = true;
        self
    }
    pub fn fg(mut self, color: Color) -> Self {
        self.fg = Some(color);
        self
    }

    /// Renders the opening escape sequence (termcolor style).
    pub fn open(&self) -> String {
        let mut s = String::from("\x1b[0m");
        if self.bold {
            s.push_str("\x1b[1m");
        }
        if let Some(fg) = self.fg {
            s.push_str(match fg {
                Color::Red => "\x1b[31m",
                Color::Green => "\x1b[32m",
                Color::Yellow => "\x1b[33m",
                Color::Blue => "\x1b[34m",
                Color::Cyan => "\x1b[36m",
                Color::BrightRed => "\x1b[38;5;9m",
                Color::BrightYellow => "\x1b[38;5;11m",
            });
        }
        s
    }

    pub fn paint(&self, text: &str, enabled: bool) -> String {
        if enabled {
            format!("{}{}\x1b[0m", self.open(), text)
        } else {
            text.to_string()
        }
    }
}

/// Prints an error message in the CLI style.
pub fn print_error(msg: &str) {
    let colors = colors_for_stderr();
    let label = Style::new().bold().fg(Color::BrightRed).paint("error", colors);
    eprintln!("{label}: {msg}");
}
EOF
