        Ok(v) => {
            let v = v.to_lowercase();
            !matches!(v.as_str(), "" | "0" | "false" | "n" | "no" | "off")
        }
        Err(_) => false,
    }
}

pub fn font_paths_from_env() -> Vec<PathBuf> {
    match std::env::var_os("TYPST_FONT_PATHS") {
        Some(v) => std::env::split_paths(&v)
            .filter(|p| !p.as_os_str().is_empty())
            .collect(),
        None => vec![],
    }
}

#[derive(Serialize)]
struct Info {
    version: &'static str,
    build: Build,
    features: Features,
    fonts: Fonts,
    packages: Packages,
    env: indexmap::IndexMap<String, Option<String>>,
}

#[derive(Serialize)]
struct Build {
    commit: &'static str,
    platform: Platform,
    settings: Settings,
}

#[derive(Serialize)]
struct Platform {
    os: &'static str,
    arch: &'static str,
}

#[derive(Serialize)]
struct Settings {
    #[serde(rename = "self-update")]
    self_update: bool,
    #[serde(rename = "http-server")]
    http_server: bool,
}

#[derive(Serialize)]
struct Features {
    html: bool,
    #[serde(rename = "a11y-extras")]
    a11y_extras: bool,
}

#[derive(Serialize)]
struct Fonts {
    paths: Vec<PathBuf>,
    system: bool,
    embedded: bool,
}

#[derive(Serialize)]
struct Packages {
    #[serde(rename = "package-path")]
    package_path: Option<PathBuf>,
    #[serde(rename = "package-cache-path")]
    package_cache_path: Option<PathBuf>,
}

pub fn run(format: Option<&str>, pretty: bool) -> i32 {
    let mut html = false;
    let mut a11y = false;
    if let Ok(features) = std::env::var("TYPST_FEATURES") {
        for feat in features.split(',') {
            match feat {
                "html" => html = true,
                "a11y-extras" => a11y = true,
                other => {
                    term::print_error(&format!("Unknown runtime feature: `{other}`"));
                    return 0;
                }
            }
        }
    }

    let info = Info {
        version: crate::cli::VERSION,
        build: Build {
            commit: crate::cli::COMMIT_LONG,
            platform: Platform { os: std::env::consts::OS, arch: std::env::consts::ARCH },
            settings: Settings { self_update: false, http_server: true },
        },
        features: Features { html, a11y_extras: a11y },
        fonts: Fonts {
            paths: font_paths_from_env(),
            system: !env_flag("TYPST_IGNORE_SYSTEM_FONTS"),
            embedded: !env_flag("TYPST_IGNORE_EMBEDDED_FONTS"),
        },
        packages: Packages {
            package_path: package_path(),
            package_cache_path: package_cache_path(),
        },
        env: ENV_VARS
            .iter()
            .map(|v| (v.to_string(), std::env::var(v).ok()))
            .collect(),
    };

    match format {
        Some("json") => {
            let s = if pretty {
                serde_json::to_string_pretty(&info).unwrap()
            } else {
                serde_json::to_string(&info).unwrap()
            };
            println!("{s}");
        }
        Some("yaml") => {
            let s = serde_yaml::to_string(&info).unwrap();
            println!("{s}");
        }
        _ => print_human(&info),
    }
    0
}

fn print_human(info: &Info) {
    let colors = term::colors_for_stderr();
    let key = |s: &str| Style::new().fg(Color::Cyan).paint(s, colors);
    let val = |s: &str| Style::new().fg(Color::Green).paint(s, colors);
    let flag = |s: &str| Style::new().fg(Color::Blue).paint(s, colors);
    let onoff = |b: bool, pad: bool| {
        let s = if b { if pad { "on " } else { "on" } } else { "off" };
        flag(s)
    };

    let mut out = String::new();
    out.push_str(&format!(
        "{} {} ({}, {} on {})\n\n",
        key("Version"),
        val(info.version),
        val(crate::cli::COMMIT_SHORT),
        val(info.build.platform.os),
        val(info.build.platform.arch)
    ));
    out.push_str("Build settings\n");
    out.push_str(&format!(
        "  {} {} (Update Typst via `typst update`)\n",
        key("self-update"),
        onoff(info.build.settings.self_update, true)
    ));
    out.push_str(&format!(
        "  {} {} (Serve HTML via `typst watch`)\n\n",
        key("http-server"),
        onoff(info.build.settings.http_server, true)
    ));
    out.push_str("Features\n");
    out.push_str(&format!(
        "  {} {} (Experimental HTML support)\n",
        key("html       "),
        onoff(info.features.html, true)
    ));
    out.push_str(&format!(
        "  {} {} (Experimental accessibility additions)\n\n",
        key("a11y-extras"),
        onoff(info.features.a11y_extras, true)
    ));
    out.push_str("Fonts\n");
    if info.fonts.paths.is_empty() {
        out.push_str(&format!("  {} {}\n", key("Custom font paths"), flag("<none>")));
    } else {
        out.push_str(&format!("  {}\n", key("Custom font paths")));
        for p in &info.fonts.paths {
            out.push_str(&format!("    - {}\n", val(&p.display().to_string())));
        }
    }
    out.push_str(&format!("  {} {}\n", key("System fonts  "), onoff(info.fonts.system, false)));
    out.push_str(&format!("  {} {}\n\n", key("Embedded fonts"), onoff(info.fonts.embedded, false)));
    out.push_str("Packages\n");
    match &info.packages.package_path {
        Some(p) => out.push_str(&format!(
            "  {} {}\n",
            key("Package path      "),
            val(&p.display().to_string())
        )),
        None => out.push_str(&format!("  {} {}\n", key("Package path      "), flag("<none>"))),
    }
    match &info.packages.package_cache_path {
        Some(p) => out.push_str(&format!(
            "  {} {}\n\n",
            key("Package cache path"),
            val(&p.display().to_string())
        )),
        None => out.push_str(&format!("  {} {}\n\n", key("Package cache path"), flag("<none>"))),
    }
    out.push_str("Environment variables\n");
    let width = ENV_VARS.iter().map(|v| v.len()).max().unwrap_or(0);
    for (name, value) in &info.env {
        let padded = format!("{name:<width$}");
        match value {
            Some(v) => out.push_str(&format!("  {} {}\n", key(&padded), val(v))),
            None => out.push_str(&format!("  {} {}\n", key(&padded), flag("<unset>"))),
        }
    }
    eprint!("{out}");
}
EOF
