        let len = be_u32(data, rec + 12)? as usize;
        tables.insert(tag, (off, len));
    }

    let name = tables.get(b"name").copied()?;
    let name_data = data.get(name.0..(name.0 + name.1).min(data.len()))?;
    let family = find_name(name_data, 16)
        .or_else(|| find_name(name_data, 1))?;
    let family = typographic_family(&family).to_string();

    let mut style = FontStyle::Normal;
    let mut weight = 400;
    let mut stretch = 1000;
    if let Some(&(off, len)) = tables.get(b"OS/2") {
        let os2 = data.get(off..(off + len).min(data.len()))?;
        let version = be_u16(os2, 0).unwrap_or(0);
        let w = be_u16(os2, 4).unwrap_or(400);
        if (1..=1000).contains(&w) {
            weight = w;
        }
        let width_class = be_u16(os2, 6).unwrap_or(5);
        stretch = match width_class {
            1 => 500,
            2 => 625,
            3 => 750,
            4 => 875,
            5 => 1000,
            6 => 1125,
            7 => 1250,
            8 => 1500,
            9 => 2000,
            _ => 1000,
        };
        let selection = be_u16(os2, 62).unwrap_or(0);
        if selection & 1 != 0 {
            style = FontStyle::Italic;
        } else if version >= 4 && selection & (1 << 9) != 0 {
            style = FontStyle::Oblique;
        }
    } else if let Some(&(off, _)) = tables.get(b"head") {
        let mac_style = be_u16(data, off + 44).unwrap_or(0);
        if mac_style & 2 != 0 {
            style = FontStyle::Italic;
        }
    }

    Some(FaceInfo { family, style, weight, stretch, path: None })
}

fn find_name(name: &[u8], id: u16) -> Option<String> {
    let count = be_u16(name, 2)? as usize;
    let string_off = be_u16(name, 4)? as usize;
    let mut unicode: Option<String> = None;
    let mut mac: Option<String> = None;
    for i in 0..count {
        let rec = 6 + i * 12;
        let platform = be_u16(name, rec)?;
        let encoding = be_u16(name, rec + 2)?;
        let language = be_u16(name, rec + 4)?;
        let name_id = be_u16(name, rec + 6)?;
        let len = be_u16(name, rec + 8)? as usize;
        let off = be_u16(name, rec + 10)? as usize;
        if name_id != id {
            continue;
        }
        let bytes = name.get(string_off + off..string_off + off + len)?;
        match platform {
            0 | 3 => {
                let is_english = platform == 0 || language == 0x409;
                let s: String = bytes
                    .chunks(2)
                    .filter_map(|c| if c.len() == 2 { Some(u16::from_be_bytes([c[0], c[1]])) } else { None })
                    .collect::<Vec<u16>>()
                    .pipe(|v| String::from_utf16_lossy(&v));
                let _ = encoding;
                if is_english || unicode.is_none() {
                    if unicode.is_none() || is_english {
                        unicode = Some(s);
                    }
                }
            }
            1 => {
                if mac.is_none() && encoding == 0 {
                    mac = Some(bytes.iter().map(|&b| b as char).collect());
                }
            }
            _ => {}
        }
    }
    unicode.or(mac)
}

trait Pipe: Sized {
    fn pipe<R>(self, f: impl FnOnce(Self) -> R) -> R {
        f(self)
    }
}
impl<T> Pipe for T {}

/// Trim style naming from a family name.
pub fn typographic_family(mut family: &str) -> &str {
    const SEPARATORS: [char; 3] = [' ', '-', '_'];
    const MODIFIERS: &[&str] =
        &["extra", "ext", "ex", "x", "semi", "sem", "sm", "demi", "dem", "ultra"];
    const SUFFIXES: &[&str] = &[
        "normal", "italic", "oblique", "slanted", "thin", "th", "hairline", "light", "lt",
        "regular", "medium", "med", "md", "bold", "bd", "demi", "extb", "black", "blk", "bk",
        "heavy", "narrow", "condensed", "cond", "cn", "cd", "compressed", "expanded", "exp",
    ];

    let mut extra = [].as_slice();
    let newcm = family.starts_with("NewCM") || family.starts_with("NewComputerModern");
    if newcm {
        extra = &["book"];
    }

    family = family.trim().trim_start_matches('.');

    let mut len = family.len();
    let mut trimmed = family;

    'outer: loop {
        let mut v = trimmed;
        let mut matched = false;
        loop {
            let Some(idx) = v.rfind(SEPARATORS) else { break };
            let (rest, word) = v.split_at(idx);
            let word = word[1..].to_lowercase();
            v = rest;
            let is_suffix = SUFFIXES.contains(&word.as_str()) || extra.contains(&word.as_str());
            let is_modifier = MODIFIERS.contains(&word.as_str());
            if is_suffix || (matched && is_modifier) {
                matched = true;
                len = rest.len();
                trimmed = rest.trim_end_matches(SEPARATORS);
                if is_suffix {
                    continue 'outer;
                }
            } else {
                break;
            }
        }
        break;
    }

    let _ = len;
    let trimmed = trimmed.trim_end_matches(SEPARATORS);
    if trimmed.is_empty() { family } else { trimmed }
}

pub fn run(font_paths: &[PathBuf], ignore_system: bool, ignore_embedded: bool, variants: bool) -> i32 {
    let book = search(font_paths, !ignore_system, !ignore_embedded);
    for (name, faces) in book.families() {
        println!("{name}");
        if variants {
            for face in faces {
                let path = match &face.path {
                    Some(p) => p.display().to_string(),
                    None => "<embedded>".to_string(),
                };
                println!(
                    "- Style: {:?}, Weight: {}, Stretch: FontStretch({}), Path: {}",
                    face.style, face.weight, face.stretch, path
                );
            }
        }
    }
    0
}
