/// Reorders the "[default: ...]"-style specs in long help output to appear
/// before the "Possible values:" list.
fn fix_help(text: &str) -> String {
    let lines: Vec<&str> = text.split('\n').collect();
    let mut out: Vec<String> = Vec::new();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        if line.trim_start().starts_with("Possible values:") && line.starts_with(' ') {
            // Collect list items.
            let mut j = i + 1;
            while j < lines.len() && lines[j].trim_start().starts_with("- ") {
                j += 1;
            }
            // Check for specs following.
            if j + 1 < lines.len()
                && lines[j].trim().is_empty()
                && !lines[j].is_empty()
                && lines[j + 1].trim_start().starts_with('[')
            {
                let mut k = j + 1;
                while k < lines.len() && lines[k].trim_start().starts_with('[') {
                    k += 1;
                }
                // The blank line before "Possible values:" is `out.last()`.
                let blank_before = out.pop().unwrap_or_default();
                // Push the spec block (with indented blank line) first.
                out.push(lines[j].to_string());
                for l in &lines[j + 1..k] {
                    out.push(l.to_string());
                }
                out.push(blank_before);
                for l in &lines[i..j] {
                    out.push(l.to_string());
                }
                i = k;
                continue;
            }
        }
        out.push(line.to_string());
        i += 1;
    }
    out.join("\n")
}

fn main() {
    let raw_args: Vec<std::ffi::OsString> = std::env::args_os().collect();
    if raw_args.len() <= 1 {
        print!("{GREETING}");
        return;
    }

    let mut cmd = cli::build();
    let matches = match cmd.try_get_matches_from_mut(&raw_args) {
        Ok(m) => m,
        Err(e) => {
            use clap::error::ErrorKind;
            match e.kind() {
                ErrorKind::DisplayHelp => {
                    let rendered = e.render();
                    let text = if term::colors_for_stdout() {
                        rendered.ansi().to_string()
                    } else {
                        rendered.to_string()
                    };
                    let text = fix_help(&text);
                    let mut stdout = std::io::stdout();
                    let _ = stdout.write_all(text.as_bytes());
                    let _ = stdout.flush();
                    std::process::exit(0);
                }
                _ => e.exit(),
            }
        }
    };

    let color = match matches.get_one::<String>("color").map(|s| s.as_str()) {
        Some("always") => term::ColorChoice::Always,
        Some("never") => term::ColorChoice::Never,
        _ => term::ColorChoice::Auto,
    };
    term::set_color_choice(color);

    let code = match matches.subcommand() {
        Some(("info", sub)) => {
            let format = sub.get_one::<String>("format").map(|s| s.as_str());
            info::run(format, sub.get_flag("pretty"))
        }
        Some(("fonts", sub)) => {
            let paths: Vec<PathBuf> = sub
                .get_many::<PathBuf>("font-path")
                .map(|v| v.cloned().collect())
                .unwrap_or_default();
            fonts::run(
                &paths,
                sub.get_flag("ignore-system-fonts"),
                sub.get_flag("ignore-embedded-fonts"),
                sub.get_flag("variants"),
            )
        }
        Some(("completions", sub)) => {
            let shell = sub.get_one::<String>("shell").unwrap();
            let shell: clap_complete::Shell = shell.parse().unwrap();
            let mut cmd = cli::build();
            clap_complete::generate(shell, &mut cmd, "typst", &mut std::io::stdout());
            0
        }
        Some(("update", _)) => {
            term::print_error("self-updating is not enabled for this executable, please use the package manager that installed Typst to update it");
            1
        }
        Some((name, _)) => {
            term::print_error(&format!("unimplemented: {name}"));
            1
        }
        None => 0,
    };
    std::process::exit(code);
}
