    pub fn eat(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.cursor += c.len_utf8();
        Some(c)
    }

    pub fn uneat(&mut self) -> Option<char> {
        let c = self.before().chars().next_back()?;
        self.cursor -= c.len_utf8();
        Some(c)
    }

    pub fn at<P: Pattern>(&self, pat: P) -> bool {
        pat.matches(self.after()).is_some()
    }

    pub fn eat_if<P: Pattern>(&mut self, pat: P) -> bool {
        if let Some(len) = pat.matches(self.after()) {
            self.cursor += len;
            true
        } else {
            false
        }
    }

    pub fn eat_while<P: Pattern>(&mut self, pat: P) -> &'a str {
        let start = self.cursor;
        while !self.done() && self.eat_if(pat) {}
        self.from(start)
    }

    pub fn eat_until<P: Pattern>(&mut self, pat: P) -> &'a str {
        let start = self.cursor;
        while !self.done() && !self.at(pat) {
            self.eat();
        }
        self.from(start)
    }

    pub fn eat_whitespace(&mut self) -> &'a str {
        self.eat_while(char::is_whitespace)
    }
}

pub trait Pattern: Copy {
    /// Returns the length of the match at the start of `s`.
    fn matches(self, s: &str) -> Option<usize>;
}

impl Pattern for char {
    fn matches(self, s: &str) -> Option<usize> {
        s.chars().next().filter(|&c| c == self).map(|c| c.len_utf8())
    }
}

impl Pattern for &str {
    fn matches(self, s: &str) -> Option<usize> {
        s.starts_with(self).then_some(self.len())
    }
}

impl<F: Fn(char) -> bool + Copy> Pattern for F {
    fn matches(self, s: &str) -> Option<usize> {
        s.chars().next().filter(|&c| self(c)).map(|c| c.len_utf8())
    }
}

impl<const N: usize> Pattern for [char; N] {
    fn matches(self, s: &str) -> Option<usize> {
        s.chars().next().filter(|c| self.contains(c)).map(|c| c.len_utf8())
    }
}

impl Pattern for &[char] {
    fn matches(self, s: &str) -> Option<usize> {
        s.chars().next().filter(|c| self.contains(c)).map(|c| c.len_utf8())
    }
}
