#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LexMode {
    Markup,
    Code,
    Math,
}

/// Extra data produced by the lexer for some tokens.
#[derive(Debug, Clone, Default)]
pub struct TokenData {
    pub newlines: usize,
    pub error: Option<(String, Vec<String>)>,
    pub raw: Option<RawData>,
}

#[derive(Debug, Clone)]
pub struct RawData {
    pub text: String,
    pub lang: Option<String>,
    pub block: bool,
}

pub struct Lexer<'a> {
    pub s: Scanner<'a>,
    pub mode: LexMode,
    pub newline: bool,
    pub data: TokenData,
}

pub fn is_newline(c: char) -> bool {
    matches!(c, '\n' | '\x0B' | '\x0C' | '\r' | '\u{0085}' | '\u{2028}' | '\u{2029}')
}

pub fn is_id_start(c: char) -> bool {
    c.is_alphabetic() || c == '_' || (c as u32 > 127 && is_xid_start(c))
}

pub fn is_id_continue(c: char) -> bool {
    c.is_alphanumeric() || c == '_' || c == '-' || (c as u32 > 127 && is_xid_continue(c))
}

fn is_xid_start(c: char) -> bool {
    c.is_alphabetic()
}

fn is_xid_continue(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

pub fn is_ident(s: &str) -> bool {
    let mut chars = s.chars();
    chars.next().is_some_and(is_id_start) && chars.all(is_id_continue)
}

/// Count newlines in a whitespace string.
pub fn count_newlines(text: &str) -> usize {
    let mut newlines = 0;
    let mut s = Scanner::new(text);
    while let Some(c) = s.eat() {
        if is_newline(c) {
            if c == '\r' {
                s.eat_if('\n');
            }
            newlines += 1;
        }
    }
    newlines
}

impl<'a> Lexer<'a> {
    pub fn new(text: &'a str, mode: LexMode) -> Self {
        Self { s: Scanner::new(text), mode, newline: false, data: TokenData::default() }
    }

    pub fn cursor(&self) -> usize {
        self.s.cursor()
    }

    pub fn jump(&mut self, pos: usize) {
        self.s.jump(pos);
    }

    fn error(&mut self, msg: impl Into<String>) -> Kind {
        self.data.error = Some((msg.into(), vec![]));
        Kind::Error
    }

    fn error_hint(&mut self, msg: impl Into<String>, hints: Vec<String>) -> Kind {
        self.data.error = Some((msg.into(), hints));
        Kind::Error
    }

    /// Lex the next token.
    pub fn next(&mut self) -> Kind {
        self.data = TokenData::default();
        self.newline = false;
        let start = self.s.cursor();
        match self.s.eat() {
            Some(c) if c.is_whitespace() => self.whitespace(start, c),
            Some('/') if self.s.eat_if('/') => self.line_comment(),
            Some('/') if self.s.eat_if('*') => self.block_comment(),
            Some('*') if self.s.eat_if('/') => {
                self.error("unexpected end of block comment")
            }
            Some(c) => match self.mode {
                LexMode::Markup => self.markup(start, c),
                LexMode::Math => self.math(start, c),
                LexMode::Code => self.code(start, c),
            },
            None => Kind::End,
        }
    }

    fn whitespace(&mut self, start: usize, c: char) -> Kind {
        let more = self.s.eat_while(|c: char| c.is_whitespace());
        let newlines = match c {
            ' ' if more.is_empty() => 0,
            _ => count_newlines(self.s.from(start)),
        };
        self.newline = newlines > 0;
        self.data.newlines = newlines;
        if self.mode == LexMode::Markup && newlines >= 2 {
            Kind::Parbreak
        } else {
            Kind::Space
        }
    }

    fn line_comment(&mut self) -> Kind {
        self.s.eat_until(is_newline);
        Kind::LineComment
    }

    fn block_comment(&mut self) -> Kind {
        let mut state = '_';
        let mut depth = 1;
        while let Some(c) = self.s.eat() {
            state = match (state, c) {
                ('*', '/') => {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                    '_'
                }
                ('/', '*') => {
                    depth += 1;
                    '_'
                }
                _ => c,
            }
        }
        Kind::BlockComment
    }

    // ---------------------------------------------------------------- Markup

    fn markup(&mut self, start: usize, c: char) -> Kind {
        match c {
            '\\' => self.backslash(start),
            '`' => self.raw(),
            'h' if self.s.eat_if("ttp://") => self.link(),
            'h' if self.s.eat_if("ttps://") => self.link(),
            '<' if self.s.at(is_id_continue) => self.label(),
            '@' => self.ref_marker(),
            '.' if self.s.eat_if("..") => Kind::Shorthand,
            '-' if self.s.eat_if("--") => Kind::Shorthand,
            '-' if self.s.eat_if('-') => Kind::Shorthand,
            '-' if self.s.eat_if('?') => Kind::Shorthand,
            '-' if self.s.at(char::is_numeric) => Kind::Shorthand,
            '*' if !self.in_word() => Kind::Star,
            '_' if !self.in_word() => Kind::Underscore,
            '#' => Kind::Hash,
            '[' => Kind::LeftBracket,
            ']' => Kind::RightBracket,
            '\'' => Kind::SmartQuote,
            '"' => Kind::SmartQuote,
            '$' => Kind::Dollar,
            '~' => Kind::Shorthand,
            ':' => Kind::Colon,
            '=' => {
                self.s.eat_while('=');
                if self.space_or_end() {
                    Kind::HeadingMarker
                } else {
                    self.text()
                }
            }
            '-' if self.space_or_end() => Kind::ListMarker,
            '+' if self.space_or_end() => Kind::EnumMarker,
            '0'..='9' => {
                let mut s = self.s;
                s.eat_while(char::is_ascii_digit);
                if s.eat_if('.') && (s.done() || s.at(char::is_whitespace)) {
                    self.s = s;
                    Kind::EnumMarker
                } else {
                    self.text()
                }
            }
            '/' if self.space_or_end() => Kind::TermMarker,
            _ => self.text(),
        }
    }

    fn space_or_end(&self) -> bool {
        self.s.done() || self.s.at(char::is_whitespace)
    }

    fn in_word(&self) -> bool {
        let wordy = |c: Option<char>| {
            c.is_some_and(|c| {
                c.is_alphanumeric()
                    && !matches!(c as u32, 0x3040..=0x30FF | 0x3400..=0x4DBF | 0x4E00..=0x9FFF | 0xF900..=0xFAFF | 0xAC00..=0xD7AF)
            })
        };
        let prev = self.s.scout(-2);
        let next = self.s.peek();
        wordy(prev) && wordy(next)
    }

    fn backslash(&mut self, start: usize) -> Kind {
        if self.s.eat_if("u{") {
            let hex = self.s.eat_while(char::is_ascii_alphanumeric);
            if !self.s.eat_if('}') {
                return self.error("unclosed Unicode escape sequence");
            }
            if u32::from_str_radix(hex, 16).ok().and_then(std::char::from_u32).is_none() {
                return self.error(format!("invalid Unicode codepoint: {hex}"));
            }
            return Kind::Escape;
        }
        let _ = start;
        if self.s.done() || self.s.at(char::is_whitespace) {
            Kind::Linebreak
        } else {
            self.s.eat();
            Kind::Escape
        }
    }

    fn raw(&mut self) -> Kind {
        let start = self.s.cursor() - 1;
        let mut backticks = 1;
        while self.s.eat_if('`') {
            backticks += 1;
        }

        // Special case for ``.
        if backticks == 2 {
            self.data.raw = Some(RawData { text: String::new(), lang: None, block: false });
            return Kind::Raw;
        }

        let mut found = 0;
        while found < backticks {
            match self.s.eat() {
                Some('`') => found += 1,
                Some(_) => found = 0,
                None => {
                    return self.error("unclosed raw text");
                }
            }
        }

        let end = self.s.cursor();
        let inner = self.s.get(start + backticks..end - backticks);
        let block = backticks >= 3;

        let mut lang = None;
        let mut text = inner;
        if block {
            // Language tag.
            let mut sc = Scanner::new(inner);
            let tag = sc.eat_while(|c: char| is_id_continue(c) || c == '.' );
            let valid_tag = !tag.is_empty() && is_id_start(tag.chars().next().unwrap());
            if valid_tag && (sc.done() || sc.at(char::is_whitespace)) {
                // Only counts as a language if there is whitespace after it or end.
                if !sc.done() {
                    lang = Some(tag.to_string());
                    text = sc.after();
                } else {
                    // Entire content is just the tag: it's the text, no lang.
                    lang = None;
                    text = inner;
                }
            } else {
                text = inner;
            }
            if lang.is_some() {
                // Strip first newline if the first line is empty.
                let mut lines: Vec<&str> = split_newlines(text);
                // Remove leading line if it only contains whitespace.
                if lines.first().is_some_and(|l| l.chars().all(char::is_whitespace)) {
                    lines.remove(0);
                } else if let Some(first) = lines.first_mut() {
                    *first = first.trim_start_matches(|c: char| c == ' ' || c == '\t');
                }
                text_from_lines(self, lines, start, end, backticks, true);
                return Kind::Raw;
            } else {
                let mut lines: Vec<&str> = split_newlines(text);
                if lines.first().is_some_and(|l| l.chars().all(char::is_whitespace)) && lines.len() > 1 {
                    lines.remove(0);
                }
                text_from_lines(self, lines, start, end, backticks, false);
                return Kind::Raw;
            }
        }

        self.data.raw = Some(RawData { text: text.to_string(), lang: None, block: false });
        Kind::Raw
    }

    fn link(&mut self) -> Kind {
        let (link, balanced) = link_prefix(self.s.after());
        self.s.jump(self.s.cursor() + link.len());
        if !balanced {
            return self.error("automatic links cannot contain unbalanced brackets, use the `link` function instead");
        }
        Kind::Link
    }

    fn label(&mut self) -> Kind {
        let label = self.s.eat_while(|c: char| is_id_continue(c) || c == ':' || c == '.');
        if label.is_empty() {
            return self.error("label cannot be empty");
        }
        if !self.s.eat_if('>') {
            return self.error("unclosed label");
        }
        Kind::Label
    }

    fn ref_marker(&mut self) -> Kind {
        self.s.eat_while(|c: char| is_id_continue(c) || c == ':' || c == '.');
        // Don't include the trailing characters likely to be part of text.
        while matches!(self.s.scout(-1), Some('.' | ':')) {
            self.s.uneat();
        }
        Kind::RefMarker
    }

    fn text(&mut self) -> Kind {
        fn is_stop(c: char) -> bool {
            matches!(
                c,
                ' ' | '\t' | '\n' | '\x0b' | '\x0c' | '\r' | '\\' | '/' | '[' | ']' | '~' | '-'
                    | '.' | '\'' | '"' | '*' | '_' | ':' | 'h' | '`' | '$' | '<' | '>' | '@' | '#'
            ) || c.is_whitespace()
        }
        loop {
            self.s.eat_until(is_stop);
            let mut s = self.s;
            match s.eat() {
                Some(' ') if s.at(char::is_alphanumeric) => {}
                Some('/') if !s.at(['/', '*']) => {}
                Some('-') if !s.at(['-', '?']) => {}
                Some('.') if !s.at("..") => {}
                Some('h') if !s.at("ttp://") && !s.at("ttps://") => {}
                Some('@') if !s.at(is_id_start) => {}
                _ => break,
            }
            self.s = s;
        }
        Kind::Text
    }

    // ------------------------------------------------------------------ Math

    fn math(&mut self, start: usize, c: char) -> Kind {
        match c {
            '\\' => self.backslash(start),
            '"' => self.string(),
            '-' if self.s.eat_if(">>") => Kind::MathShorthand,
            '-' if self.s.eat_if('>') => Kind::MathShorthand,
            '-' if self.s.eat_if("->") => Kind::MathShorthand,
            ':' if self.s.eat_if('=') => Kind::MathShorthand,
            ':' if self.s.eat_if(":=") => Kind::MathShorthand,
            '!' if self.s.eat_if('=') => Kind::MathShorthand,
            '.' if self.s.eat_if("..") => Kind::MathShorthand,
            '[' if self.s.eat_if('|') => Kind::MathShorthand,
            '<' if self.s.eat_if("==>") => Kind::MathShorthand,
            '<' if self.s.eat_if("-->") => Kind::MathShorthand,
            '<' if self.s.eat_if("--") => Kind::MathShorthand,
            '<' if self.s.eat_if("-<") => Kind::MathShorthand,
            '<' if self.s.eat_if("->") => Kind::MathShorthand,
            '<' if self.s.eat_if("<-") => Kind::MathShorthand,
            '<' if self.s.eat_if("<<") => Kind::MathShorthand,
            '<' if self.s.eat_if("=>") => Kind::MathShorthand,
            '<' if self.s.eat_if("==") => Kind::MathShorthand,
            '<' if self.s.eat_if("~~") => Kind::MathShorthand,
            '<' if self.s.eat_if('=') => Kind::MathShorthand,
            '<' if self.s.eat_if('<') => Kind::MathShorthand,
            '<' if self.s.eat_if('-') => Kind::MathShorthand,
            '<' if self.s.eat_if('~') => Kind::MathShorthand,
            '>' if self.s.eat_if("->") => Kind::MathShorthand,
            '>' if self.s.eat_if(">>") => Kind::MathShorthand,
            '=' if self.s.eat_if("=>") => Kind::MathShorthand,
            '=' if self.s.eat_if('>') => Kind::MathShorthand,
            '=' if self.s.eat_if(':') => Kind::MathShorthand,
            '>' if self.s.eat_if('=') => Kind::MathShorthand,
            '>' if self.s.eat_if('>') => Kind::MathShorthand,
            '|' if self.s.eat_if("->") => Kind::MathShorthand,
            '|' if self.s.eat_if("=>") => Kind::MathShorthand,
            '|' if self.s.eat_if(']') => Kind::MathShorthand,
            '|' if self.s.eat_if('|') => Kind::MathShorthand,
            '~' if self.s.eat_if("~>") => Kind::MathShorthand,
            '~' if self.s.eat_if('>') => Kind::MathShorthand,
            '*' | '-' | '~' => Kind::MathShorthand,

            '.' => Kind::Dot,
            ',' => Kind::Comma,
            ';' => Kind::Semicolon,
            ')' => Kind::RightParen,

            '#' => Kind::Hash,
            '_' => Kind::Underscore,
            '$' => Kind::Dollar,
            '/' => Kind::Slash,
            '^' => Kind::Hat,
            '\'' => Kind::Prime,
            '&' => Kind::MathAlignPoint,
            '√' | '∛' | '∜' => Kind::Root,

            // Identifiers.
            c if is_id_start(c) => {
                let s = &mut self.s;
                s.eat_while(|c: char| is_id_continue(c) && c != '-' && c != '_');
                let ident = s.from(start);
                let _ = ident;
                if self.s.cursor() - start > c.len_utf8() {
                    Kind::MathIdent
                } else {
                    Kind::MathText
                }
            }

            // Numbers.
            c if c.is_numeric() => {
                self.s.eat_while(char::is_numeric);
                let mut s = self.s;
                if s.eat_if('.') && !s.eat_while(char::is_numeric).is_empty() {
                    self.s = s;
                }
                Kind::MathText
            }

            // Other math atoms.
            _ => Kind::MathText,
        }
    }

    // ------------------------------------------------------------------ Code

    fn code(&mut self, start: usize, c: char) -> Kind {
        match c {
            '`' => self.raw(),
            '<' if self.s.at(is_id_continue) => self.label(),
            '0'..='9' => self.number(start, c),
            '.' if self.s.at(char::is_ascii_digit) => self.number(start, c),
            '"' => self.string(),

            '=' if self.s.eat_if('=') => Kind::EqEq,
            '!' if self.s.eat_if('=') => Kind::ExclEq,
            '<' if self.s.eat_if('=') => Kind::LtEq,
            '>' if self.s.eat_if('=') => Kind::GtEq,
            '+' if self.s.eat_if('=') => Kind::PlusEq,
            '-' | '\u{2212}' if self.s.eat_if('=') => Kind::HyphEq,
            '*' if self.s.eat_if('=') => Kind::StarEq,
            '/' if self.s.eat_if('=') => Kind::SlashEq,
            '.' if self.s.eat_if('.') => Kind::Dots,
            '=' if self.s.eat_if('>') => Kind::Arrow,

            '{' => Kind::LeftBrace,
            '}' => Kind::RightBrace,
            '[' => Kind::LeftBracket,
            ']' => Kind::RightBracket,
            '(' => Kind::LeftParen,
            ')' => Kind::RightParen,
            '$' => Kind::Dollar,
            ',' => Kind::Comma,
            ';' => Kind::Semicolon,
            ':' => Kind::Colon,
            '.' => Kind::Dot,
            '+' => Kind::Plus,
            '-' | '\u{2212}' => Kind::Minus,
            '*' => Kind::Star,
            '/' => Kind::Slash,
            '=' => Kind::Eq,
            '<' => Kind::Lt,
            '>' => Kind::Gt,

            c if is_id_start(c) => self.ident(start),

            c => self.error_hint(
                format!("the character `{c}` is not valid in code"),
                if c == '#' {
                    vec!["you are already in code mode".into(), "try removing the `#`".into()]
                } else {
                    vec![]
                },
            ),
        }
    }

    fn ident(&mut self, start: usize) -> Kind {
        self.s.eat_while(is_id_continue);
        let ident = self.s.from(start);
        let prev = self.s.get(0..start);
        if !prev.ends_with(['.', '@']) || prev.ends_with("..") {
            if let Some(keyword) = keyword(ident) {
                return keyword;
            }
        }
        if ident == "_" {
            Kind::Underscore
        } else {
            Kind::Ident
        }
    }

    fn number(&mut self, start: usize, first_c: char) -> Kind {
        // Handle alternative integer bases.
        let base = match first_c {
            '0' if self.s.eat_if('b') => 2,
            '0' if self.s.eat_if('o') => 8,
            '0' if self.s.eat_if('x') => 16,
            _ => 10,
        };

        // Read the first part (integer or fractional part).
        if base == 16 {
            self.s.eat_while(char::is_ascii_alphanumeric);
        } else {
            self.s.eat_while(char::is_ascii_digit);
        }

        let mut is_float = false;
        let mut has_frac = first_c == '.';
        if base == 10 {
            // Read the fractional part if not already done.
            if !has_frac && self.s.at('.') && !self.s.at("..") && !self.s.at(|c: char| c == '.' ) == false {
                // handled below
            }
            if first_c != '.' && self.s.eat_if('.') {
                has_frac = true;
                self.s.eat_while(char::is_ascii_digit);
            }
            if has_frac {
                is_float = true;
            }
            // Read the exponent.
            if !self.s.at("em") && self.s.eat_if(['e', 'E']) {
                self.s.eat_if(['+', '-']);
                self.s.eat_while(char::is_ascii_digit);
                is_float = true;
            }
        }

        // Read the suffix.
        let suffix_start = self.s.cursor();
        if !self.s.eat_if('%') {
            self.s.eat_while(char::is_ascii_alphanumeric);
        }

        let number = self.s.get(start..suffix_start);
        let suffix = self.s.from(suffix_start);

        let kind = if i64::from_str_radix(number.trim_start_matches(['0'].as_slice()).trim_start_matches(['b', 'o', 'x'].as_slice()), base).is_ok()
            || (base == 10 && !is_float && number.parse::<i64>().is_ok())
        {
            Kind::Int
        } else if base == 10 && number.parse::<f64>().is_ok() {
            Kind::Float
        } else {
            let name = match base {
                2 => "binary",
                8 => "octal",
                16 => "hexadecimal",
                _ => "floating point",
            };
            return self.error(format!("invalid {name} number: {number}"));
        };

        if suffix.is_empty() {
            return kind;
        }

        if !matches!(suffix, "pt" | "mm" | "cm" | "in" | "deg" | "rad" | "em" | "fr" | "%") {
            return self.error(format!("invalid number suffix: {suffix}"));
        }

        if base != 10 {
            let kind = self.error(format!("invalid base-{base} prefix for number with suffix"));
            return kind;
        }

        Kind::Numeric
    }

    fn string(&mut self) -> Kind {
        let mut escaped = false;
        self.s.eat_until(|c| {
            let stop = c == '"' && !escaped;
            escaped = c == '\\' && !escaped;
            stop
        });
        if !self.s.eat_if('"') {
            return self.error("unclosed string");
        }
        Kind::Str
    }
}

fn split_newlines(text: &str) -> Vec<&str> {
    let mut lines = Vec::new();
    let mut s = Scanner::new(text);
    let mut start = 0;
    let mut end = 0;
    while let Some(c) = s.eat() {
        if is_newline(c) {
            if c == '\r' {
                s.eat_if('\n');
            }
            lines.push(&text[start..end]);
            start = s.cursor();
        }
        end = s.cursor();
    }
    lines.push(&text[start..]);
    lines
}

fn text_from_lines(lexer: &mut Lexer, mut lines: Vec<&str>, _start: usize, _end: usize, _backticks: usize, has_lang: bool) {
    // Trailing line: if it's only whitespace, remove it and dedent.
    let mut dedent = usize::MAX;
    if lines.len() > 1 {
        if let Some(last) = lines.last() {
            if last.chars().all(char::is_whitespace) {
                let last_indent = last.len();
                lines.pop();
                dedent = dedent.min(last_indent);
            }
        }
    }
    // Compute dedent from non-empty lines (excluding the first).
    for line in lines.iter().skip(1) {
        if !line.chars().all(char::is_whitespace) {
            let indent = line.len() - line.trim_start_matches(|c: char| c == ' ' || c == '\t').len();
            dedent = dedent.min(indent);
        }
    }
    if dedent == usize::MAX {
        dedent = 0;
    }
    let mut out: Vec<String> = Vec::new();
    for (i, line) in lines.iter().enumerate() {
        if i == 0 && !has_lang {
            out.push(line.to_string());
        } else {
            let strip = line
                .char_indices()
                .take_while(|(idx, c)| *idx < dedent && (*c == ' ' || *c == '\t'))
                .count();
            out.push(line[strip.min(line.len())..].to_string());
        }
    }
    let _ = &mut lines;
    let text = out.join("\n");
    let lang = if has_lang {
        // The caller stored lang separately; re-derive it.
        None
    } else {
        None
    };
    lexer.data.raw = Some(RawData { text, lang, block: true });
}

fn keyword(ident: &str) -> Option<Kind> {
    Some(match ident {
        "none" => Kind::None,
        "auto" => Kind::Auto,
        "true" | "false" => Kind::Bool,
        "not" => Kind::Not,
        "and" => Kind::And,
        "or" => Kind::Or,
        "let" => Kind::Let,
        "set" => Kind::Set,
        "show" => Kind::Show,
        "context" => Kind::Context,
        "if" => Kind::If,
        "else" => Kind::Else,
        "for" => Kind::For,
        "in" => Kind::In,
        "while" => Kind::While,
        "break" => Kind::Break,
        "continue" => Kind::Continue,
        "return" => Kind::Return,
        "import" => Kind::Import,
        "include" => Kind::Include,
        "as" => Kind::As,
        _ => return None,
    })
}

/// Determine the prefix of a link and whether its brackets are balanced.
fn link_prefix(text: &str) -> (&str, bool) {
    let mut s = Scanner::new(text);
    let mut brackets = Vec::new();

    #[rustfmt::skip]
    s.eat_while(|c: char| {
        match c {
            | '0' ..= '9'
            | 'a' ..= 'z'
            | 'A' ..= 'Z'
            | '!' | '#' | '$' | '%' | '&' | '*' | '+'
            | ',' | '-' | '.' | '/' | ':' | ';' | '='
            | '?' | '@' | '_' | '~' | '\'' => true,
            '[' => { brackets.push(b'['); true }
            '(' => { brackets.push(b'('); true }
            ']' => brackets.pop() == Some(b'['),
            ')' => brackets.pop() == Some(b'('),
            _ => false,
        }
    });

    // Don't include the trailing characters likely to be part of text.
    while matches!(s.scout(-1), Some('!' | ',' | '.' | ':' | ';' | '?' | '\'')) {
        s.uneat();
    }

    (s.before(), brackets.is_empty())
}
