        let inner_end = end - backticks;
        if backticks >= 3 {
            self.blocky_raw(inner_start, inner_end);
        } else {
            let text = self.s.get(inner_start..inner_end).to_string();
            self.data.raw = Some(RawData { text, lang: None, block: false });
        }
        Kind::Raw
    }

    fn blocky_raw(&mut self, inner_start: usize, inner_end: usize) {
        let mut sc = Scanner::new(self.s.get(inner_start..inner_end));
        let mut lang = None;
        if sc.eat_if(is_id_start) {
            sc.eat_while(is_id_continue);
            lang = Some(sc.before().to_string());
        }
        let inner = sc.after();

        let mut lines: Vec<&str> = split_newlines(inner);

        // Determine dedent level.
        let dedent = lines
            .iter()
            .skip(1)
            .filter(|line| !line.chars().all(char::is_whitespace))
            .chain(lines.last())
            .map(|line| line.chars().take_while(|c| c.is_whitespace()).count())
            .min()
            .unwrap_or(0);

        // Trim single space in last line if text ends with a backtick.
        if inner.trim_end().ends_with('`') {
            if let Some(last) = lines.last_mut() {
                *last = last.strip_suffix(' ').unwrap_or(last);
            }
        }

        // Trim single space in first line if text starts with a backtick.
        if inner.trim_start().starts_with('`') {
            if let Some(first) = lines.first_mut() {
                *first = first.strip_prefix(' ').unwrap_or(first);
            }
        }

        // Trim first line if it is just whitespace.
        if lines.first().is_some_and(|line| line.chars().all(char::is_whitespace)) {
            lines.remove(0);
        }

        // Trim last line if it is just whitespace.
        if lines.last().is_some_and(|line| line.chars().all(char::is_whitespace)) {
            lines.pop();
        }

        let text = lines
            .iter()
            .map(|line| {
                let mut chars = line.chars();
                let mut skipped = 0;
                let mut rest = *line;
                while skipped < dedent {
                    match chars.next() {
                        Some(c) if c.is_whitespace() => {
                            skipped += 1;
                            rest = &rest[c.len_utf8()..];
                        }
                        _ => break,
                    }
                }
                rest
            })
            .collect::<Vec<_>>()
            .join("\\n");

        self.data.raw = Some(RawData { text, lang, block: true });
    }

