        // Handle alternative integer bases.
        let mut base = 10;
        if c == '0' {
            if self.s.eat_if('b') {
                base = 2;
            } else if self.s.eat_if('o') {
                base = 8;
            } else if self.s.eat_if('x') {
                base = 16;
            }
            if base != 10 {
                start = self.s.cursor();
            }
        }

        // Read the first part (integer or fractional part).
        if base == 16 {
            self.s.eat_while(char::is_ascii_alphanumeric);
        } else {
            self.s.eat_while(char::is_ascii_digit);
        }

        // Read the fractional part if not already done.
        if c != '.'
            && !self.s.at("..")
            && !self.s.scout(1).is_some_and(is_id_start)
            && self.s.eat_if('.')
            && base == 10
        {
            self.s.eat_while(char::is_ascii_digit);
        }

        // Read the exponent.
        if !self.s.at("em") && self.s.eat_if(['e', 'E']) && base == 10 {
            self.s.eat_if(['+', '-']);
            self.s.eat_while(char::is_ascii_digit);
        }

        // Read the suffix.
        let suffix_start = self.s.cursor();
        if !self.s.eat_if('%') {
            self.s.eat_while(char::is_ascii_alphabetic);
        }

        let number = self.s.get(start..suffix_start);
        let suffix = self.s.from(suffix_start);

        let kind = if i64::from_str_radix(number, base).is_ok() {
            Kind::Int
        } else if base == 10 && number.parse::<f64>().is_ok() {
            Kind::Float
        } else {
            return self.error(match base {
                2 => format!("invalid binary number: 0b{number}"),
                8 => format!("invalid octal number: 0o{number}"),
                16 => format!("invalid hexadecimal number: 0x{number}"),
                _ => format!("invalid floating point number: {number}"),
            });
        };

        if suffix.is_empty() {
            return kind;
        }

        if !matches!(suffix, "pt" | "mm" | "cm" | "in" | "deg" | "rad" | "em" | "fr" | "%") {
            return self.error(format!("invalid number suffix: {suffix}"));
        }

        if base != 10 {
            return self.error(format!("invalid base-{base} prefix for number with suffix"));
        }

        Kind::Numeric
    }

