    pub fn span(&self) -> Span {
        match self {
            Pattern::Normal(e) => e.span,
            Pattern::Placeholder(s) => *s,
            Pattern::Parenthesized(_, s) => *s,
            Pattern::Destructuring(d) => d.span,
        }
    }

    /// All identifiers bound by this pattern.
    pub fn bindings(&self) -> Vec<Ident> {
        let mut out = Vec::new();
        self.collect_bindings(&mut out);
        out
    }

    fn collect_bindings(&self, out: &mut Vec<Ident>) {
        match self {
            Pattern::Normal(e) => {
                if let ExprKind::Ident(name) = &e.kind {
                    out.push(Ident { name: name.clone(), span: e.span });
                }
            }
            Pattern::Placeholder(_) => {}
            Pattern::Parenthesized(p, _) => p.collect_bindings(out),
            Pattern::Destructuring(d) => {
                for item in &d.items {
                    match item {
                        DestructuringItem::Pattern(p) => p.collect_bindings(out),
                        DestructuringItem::Named(_, p) => p.collect_bindings(out),
                        DestructuringItem::Spread(Some(id), _) => out.push(id.clone()),
                        DestructuringItem::Spread(None, _) => {}
                    }
                }
            }
        }
    }
