//! Parser producing an AST from Typst source.

use std::collections::HashSet;
use std::rc::Rc;

use super::ast::*;
use super::lexer::{Kind, LexMode, Lexer, TokenData};

#[derive(Debug, Clone)]
pub struct SyntaxError {
    pub span: Span,
    pub message: String,
    pub hints: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Newline {
    Continue,
    Stop,
    Contextual,
    RequireColumn(usize),
}

#[derive(Clone)]
struct Token {
    kind: Kind,
    start: usize,
    end: usize,
    data: TokenData,
    /// Whether there was a newline in the trivia before this token.
    newline: Option<NewlineInfo>,
    /// End of the previous non-trivia token.
    prev_end: usize,
}

#[derive(Clone, Copy)]
struct NewlineInfo {
    column: usize,
    parbreak: bool,
}

struct Checkpoint {
    token: Token,
    lexer_cursor: usize,
    errors: usize,
}

pub struct Parser<'a> {
    text: &'a str,
    lexer: Lexer<'a>,
    token: Token,
    nl_mode: Newline,
    errors: Vec<SyntaxError>,
}

/// The kinds a parsed group of items may be.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GroupKind {
    Parenthesized,
    Array,
    Dict,
}

enum GroupItem {
    Pos(Expr),
    Named(Ident, Expr),
    Keyed(Expr, Expr),
    Spread(Expr),
    Placeholder(Span),
}

impl<'a> Parser<'a> {
    pub fn new(text: &'a str, mode: LexMode) -> Self {
        let lexer = Lexer::new(text, mode);
        let mut p = Self {
            text,
            lexer,
            token: Token {
                kind: Kind::End,
                start: 0,
                end: 0,
                data: TokenData::default(),
                newline: None,
                prev_end: 0,
            },
            nl_mode: Newline::Continue,
            errors: vec![],
        };
        p.lex();
        p.skip();
        p
    }

    pub fn finish(self) -> Vec<SyntaxError> {
        self.errors
    }

    // --- Token access ---

    fn current(&self) -> Kind {
        self.token.kind
    }

    fn current_text(&self) -> &'a str {
        &self.text[self.token.start..self.token.end]
    }

    fn current_start(&self) -> usize {
        self.token.start
    }

    fn current_end(&self) -> usize {
        self.token.end
    }

    fn current_span(&self) -> Span {
        Span::new(self.token.start, self.token.end)
    }

    fn prev_end(&self) -> usize {
        self.token.prev_end
    }

    fn end(&self) -> bool {
        self.current() == Kind::End
    }

    fn at(&self, kind: Kind) -> bool {
        self.current() == kind
    }

    fn at_set(&self, set: &[Kind]) -> bool {
        set.contains(&self.current())
    }

    fn directly_at(&self, kind: Kind) -> bool {
        self.current() == kind && self.token.prev_end == self.token.start
    }

    fn had_trivia(&self) -> bool {
        self.token.prev_end != self.token.start
    }

    fn had_newline(&self) -> bool {
        self.token.newline.is_some()
    }

    fn column(&self, at: usize) -> usize {
        self.text[..at].chars().rev().take_while(|&c| !super::lexer::is_newline(c)).count()
    }

    // --- Lexing ---

    fn lex(&mut self) {
        let prev_end = self.token.end;
        let start = self.lexer.cursor();
        let kind = self.lexer.next();
        let end = self.lexer.cursor();
        let data = std::mem::take(&mut self.lexer.data);
        let mut newline = None;
        if self.lexer.newline {
            let column = self.column(end);
            newline = Some(NewlineInfo { column, parbreak: data.newlines >= 2 });
        }
        self.token = Token { kind, start, end, data, newline, prev_end };

        if let Some(info) = newline {
            if self.stops_at_newline(info) {
                self.token.kind = Kind::End;
            }
        }
    }

    fn stops_at_newline(&mut self, info: NewlineInfo) -> bool {
        match self.nl_mode {
            Newline::Continue => false,
            Newline::Stop => true,
            Newline::Contextual => {
                // Look ahead at the next token.
                let saved_cursor = self.lexer.cursor();
                let saved_newline = self.lexer.newline;
                let saved_data = std::mem::take(&mut self.lexer.data);
                let mut next = self.lexer.next();
                while next.is_trivia() {
                    next = self.lexer.next();
                }
                self.lexer.jump(saved_cursor);
                self.lexer.newline = saved_newline;
                self.lexer.data = saved_data;
                !matches!(next, Kind::Else | Kind::Dot)
            }
            Newline::RequireColumn(min_col) => {
                let _ = info.parbreak;
                info.column < min_col
            }
        }
    }

    /// Skip trivia in code mode (and comments in math mode).
    fn skip(&mut self) {
        match self.lexer.mode {
            LexMode::Code => {
                while self.current().is_trivia() {
                    self.lex_keep_prev();
                }
            }
            LexMode::Math => {
                while matches!(self.current(), Kind::LineComment | Kind::BlockComment) {
                    self.lex_keep_prev();
                }
            }
            LexMode::Markup => {}
        }
    }

    /// Lex the next token but keep `prev_end` pointing to the last
    /// non-trivia token and accumulate newline information.
    fn lex_keep_prev(&mut self) {
        let prev_end = self.token.prev_end;
        let had_newline = self.token.newline;
        self.lex();
        self.token.prev_end = prev_end;
        if self.token.newline.is_none() {
            if let Some(info) = had_newline {
                self.token.newline = Some(info);
                if self.stops_at_newline(info) {
                    self.token.kind = Kind::End;
                }
            }
        }
    }

    /// Consume the current token and return its span and text.
    fn eat(&mut self) -> (Span, &'a str) {
        let span = self.current_span();
        let text = self.current_text();
        self.lex();
        self.skip();
        (span, text)
    }

    fn eat_data(&mut self) -> (Span, &'a str, TokenData) {
        let data = std::mem::take(&mut self.token.data);
        let (span, text) = self.eat();
        (span, text, data)
    }

    fn eat_if(&mut self, kind: Kind) -> bool {
        if self.at(kind) {
            self.eat();
            true
        } else {
            false
        }
    }

    fn eat_if_direct(&mut self, kind: Kind) -> bool {
        if self.directly_at(kind) {
            self.eat();
            true
        } else {
            false
        }
    }

    fn assert(&mut self, kind: Kind) -> Span {
        debug_assert_eq!(self.current(), kind);
        self.eat().0
    }

    fn expect(&mut self, kind: Kind) -> bool {
        if self.at(kind) {
            self.eat();
            true
        } else {
            if kind == Kind::Ident && self.current().is_keyword() {
                self.trim_errors();
                self.eat_and_error_keyword();
            } else {
                self.expected(kind.name());
            }
            false
        }
    }

    fn eat_and_error_keyword(&mut self) {
        let span = self.current_span();
        let text = self.current_text();
        self.errors.push(SyntaxError {
            span,
            message: format!("expected identifier, found keyword `{text}`"),
            hints: vec![],
        });
        self.eat();
    }

    fn expect_closing_delimiter(&mut self, open: Span, kind: Kind) {
        if !self.eat_if(kind) {
            self.errors.push(SyntaxError {
                span: open,
                message: "unclosed delimiter".into(),
                hints: vec![],
            });
        }
    }

    /// Produce an "expected X" error at the end of the previous token.
    fn expected(&mut self, thing: &str) {
        if !self.after_error() {
            let at = self.prev_end();
            self.errors.push(SyntaxError {
                span: Span::new(at, at),
                message: format!("expected {thing}"),
                hints: vec![],
            });
        }
    }

    fn expected_at(&mut self, at: usize, thing: &str) {
        self.errors.push(SyntaxError {
            span: Span::new(at, at),
            message: format!("expected {thing}"),
            hints: vec![],
        });
    }

    /// Whether the last error was produced at the current position.
    fn after_error(&self) -> bool {
        self.errors
            .last()
            .is_some_and(|e| e.span.end as usize == self.prev_end() && e.message.starts_with("expected"))
    }

    fn trim_errors(&mut self) {}

    /// Consume the current token and produce an "unexpected" error.
    fn unexpected(&mut self) {
        let span = self.current_span();
        let kind = self.current();
        let data = std::mem::take(&mut self.token.data);
        if kind == Kind::Error {
            if let Some((msg, hints)) = data.error {
                self.errors.push(SyntaxError { span, message: msg, hints });
            }
        } else {
            self.errors.push(SyntaxError {
                span,
                message: format!("unexpected {}", kind.name()),
                hints: vec![],
            });
        }
        self.lex();
        self.skip();
    }

    fn error_at(&mut self, span: Span, message: impl Into<String>) {
        self.errors.push(SyntaxError { span, message: message.into(), hints: vec![] });
    }

    fn hint(&mut self, hint: impl Into<String>) {
        if let Some(e) = self.errors.last_mut() {
            e.hints.push(hint.into());
        }
    }

    /// Eat an error token and record its message.
    fn eat_error(&mut self) -> Expr {
        let span = self.current_span();
        let data = std::mem::take(&mut self.token.data);
        if let Some((msg, hints)) = data.error {
            self.errors.push(SyntaxError { span, message: msg, hints });
        }
        self.eat();
        Expr::new(ExprKind::None, span)
    }

    // --- Mode handling ---

    fn with_nl_mode<T>(&mut self, mode: Newline, f: impl FnOnce(&mut Self) -> T) -> T {
        let previous = self.nl_mode;
        self.nl_mode = mode;
        let result = f(self);
        self.nl_mode = previous;
        // Relex if the newline mode change affects the current token.
        if let Some(info) = self.token.newline {
            let stops = self.stops_at_newline(info);
            if stops != (self.token.kind == Kind::End) || self.token.kind == Kind::End {
                // Re-lex from before the trivia.
                self.relex();
            }
        }
        result
    }

    fn relex(&mut self) {
        let prev_end = self.token.prev_end;
        self.lexer.jump(prev_end);
        self.token.end = prev_end;
        self.lex();
        self.skip();
    }

    fn enter_modes<T>(&mut self, mode: LexMode, nl: Newline, f: impl FnOnce(&mut Self) -> T) -> T {
        let previous_mode = self.lexer.mode;
        let previous_nl = self.nl_mode;
        self.lexer.mode = mode;
        self.nl_mode = nl;
        let result = f(self);
        self.lexer.mode = previous_mode;
        self.nl_mode = previous_nl;
        self.relex();
        result
    }

    fn checkpoint(&self) -> Checkpoint {
        Checkpoint {
            token: self.token.clone(),
            lexer_cursor: self.lexer.cursor(),
            errors: self.errors.len(),
        }
    }

    fn restore(&mut self, c: Checkpoint) {
        self.token = c.token;
        self.lexer.jump(c.lexer_cursor);
        self.errors.truncate(c.errors);
    }
}

// ------------------------------------------------------------------ Entry

/// Parse a file in markup mode.
pub fn parse_markup(text: &str) -> (Expr, Vec<SyntaxError>) {
    let mut p = Parser::new(text, LexMode::Markup);
    let body = markup(&mut p, true, true, &[Kind::End]);
    let span = Span::new(0, text.len());
    let _ = &mut p;
    (Expr::new(ExprKind::Markup(body), span), p.finish())
}

/// Parse code (for `eval`).
pub fn parse_code(text: &str) -> (Vec<Expr>, Vec<SyntaxError>) {
    let mut p = Parser::new(text, LexMode::Code);
    let exprs = code_exprs(&mut p, &[Kind::End]);
    (exprs, p.finish())
}

/// Parse math.
pub fn parse_math(text: &str) -> (Expr, Vec<SyntaxError>) {
    let mut p = Parser::new(text, LexMode::Math);
    let body = math(&mut p, &[Kind::End]);
    let span = Span::new(0, text.len());
    (Expr::new(ExprKind::Math(body), span), p.finish())
}

// ----------------------------------------------------------------- Markup

fn markup(p: &mut Parser, mut at_start: bool, wrap_trivia: bool, stop: &[Kind]) -> Vec<Expr> {
    let mut out = Vec::new();
    let mut nesting: usize = 0;
    while !p.end() && (nesting > 0 || !p.at_set(stop)) {
        let was_trivia = p.current().is_trivia();
        let had_nl = p.current() == Kind::Parbreak
            || (p.current() == Kind::Space && p.token.data.newlines > 0);
        markup_expr(p, at_start, &mut nesting, &mut out);
        if was_trivia {
            at_start |= had_nl;
        } else {
            at_start = false;
        }
    }
    if !wrap_trivia {
        // Trailing trivia is excluded from the wrapped node; return them
        // via the pending list.
        let mut trailing = Vec::new();
        while let Some(last) = out.last() {
            if matches!(last.kind, ExprKind::Space | ExprKind::Parbreak) {
                trailing.push(out.pop().unwrap());
            } else {
                break;
            }
        }
        trailing.reverse();
        p.pending_trivia = trailing;
    }
    out
}

fn markup_expr(p: &mut Parser, at_start: bool, nesting: &mut usize, out: &mut Vec<Expr>) {
    match p.current() {
        Kind::Space => {
            let (span, _, data) = p.eat_data();
            let _ = data;
            out.push(Expr::new(ExprKind::Space, span));
        }
        Kind::Parbreak => {
            let (span, _) = p.eat();
            out.push(Expr::new(ExprKind::Parbreak, span));
        }
        Kind::LineComment | Kind::BlockComment => {
            p.eat();
        }
        Kind::Text => {
            let (span, text) = p.eat();
            out.push(Expr::new(ExprKind::Text(text.to_string()), span));
        }
        Kind::Linebreak => {
            let (span, _) = p.eat();
            out.push(Expr::new(ExprKind::Linebreak, span));
        }
        Kind::Escape => {
            let (span, text) = p.eat();
            out.push(Expr::new(ExprKind::Escape(parse_escape(text)), span));
        }
        Kind::Shorthand => {
            let (span, text) = p.eat();
            out.push(Expr::new(ExprKind::Shorthand(shorthand_char(text)), span));
        }
        Kind::SmartQuote => {
            let (span, text) = p.eat();
            out.push(Expr::new(ExprKind::SmartQuote { double: text == "\"" }, span));
        }
        Kind::Link => {
            let (span, text) = p.eat();
            out.push(Expr::new(ExprKind::Link(text.to_string()), span));
        }
        Kind::Label => {
            let (span, text) = p.eat();
            out.push(Expr::new(ExprKind::Label(text[1..text.len() - 1].to_string()), span));
        }
        Kind::Raw => {
            let (span, _, data) = p.eat_data();
            let raw = data.raw.unwrap_or_default_raw();
            out.push(Expr::new(
                ExprKind::Raw { text: raw.text, lang: raw.lang, block: raw.block },
                span,
            ));
        }
        Kind::Hash => {
            if let Some(e) = embedded_code_expr(p) {
                out.push(e);
            }
        }
        Kind::Star => out.push(strong(p)),
        Kind::Underscore => out.push(emph(p)),
        Kind::HeadingMarker if at_start => {
            let e = heading(p);
            out.push(e);
            flush_pending(p, out);
        }
        Kind::ListMarker if at_start => {
            let e = list_item(p);
            out.push(e);
            flush_pending(p, out);
        }
        Kind::EnumMarker if at_start => {
            let e = enum_item(p);
            out.push(e);
            flush_pending(p, out);
        }
        Kind::TermMarker if at_start => {
            let e = term_item(p);
            out.push(e);
            flush_pending(p, out);
        }
        Kind::RefMarker => out.push(reference(p)),
        Kind::Dollar => out.push(equation(p)),
        Kind::LeftBracket => {
            *nesting += 1;
            let (span, text) = p.eat();
            out.push(Expr::new(ExprKind::Text(text.to_string()), span));
        }
        Kind::RightBracket => {
            if *nesting > 0 {
                *nesting -= 1;
            }
            let (span, text) = p.eat();
            out.push(Expr::new(ExprKind::Text(text.to_string()), span));
        }
        Kind::HeadingMarker | Kind::ListMarker | Kind::EnumMarker | Kind::TermMarker | Kind::Colon => {
            let (span, text) = p.eat();
            out.push(Expr::new(ExprKind::Text(text.to_string()), span));
        }
        Kind::Error => {
            p.eat_error();
        }
        _ => p.unexpected(),
    }
}

fn flush_pending(p: &mut Parser, out: &mut Vec<Expr>) {
    let pending = std::mem::take(&mut p.pending_trivia);
    out.extend(pending);
}

trait RawDefault {
    fn unwrap_or_default_raw(self) -> super::lexer::RawData;
}

impl RawDefault for Option<super::lexer::RawData> {
    fn unwrap_or_default_raw(self) -> super::lexer::RawData {
        self.unwrap_or(super::lexer::RawData { text: String::new(), lang: None, block: false })
    }
}

pub fn parse_escape(text: &str) -> char {
    let s = &text[1..];
    if let Some(hex) = s.strip_prefix("u{").and_then(|s| s.strip_suffix('}')) {
        u32::from_str_radix(hex, 16).ok().and_then(char::from_u32).unwrap_or('\u{FFFD}')
    } else {
        s.chars().next().unwrap_or('\\')
    }
}

fn shorthand_char(text: &str) -> char {
    match text {
        "~" => '\u{00A0}',
        "..." => '…',
        "--" => '–',
        "---" => '—',
        "-?" => '\u{00AD}',
        "-" => '\u{2212}',
        _ => text.chars().next().unwrap_or(' '),
    }
}

fn strong(p: &mut Parser) -> Expr {
    let open = p.assert(Kind::Star);
    let body = markup(p, false, true, &[Kind::Star, Kind::Parbreak, Kind::RightBracket]);
    let end = p.current_end();
    p.expect_closing_delimiter(open, Kind::Star);
    let end = if p.prev_end() > open.end as usize { p.prev_end() } else { end };
    Expr::new(ExprKind::Strong(body), Span::new(open.start as usize, end))
}

fn emph(p: &mut Parser) -> Expr {
    let open = p.assert(Kind::Underscore);
    let body = markup(p, false, true, &[Kind::Underscore, Kind::Parbreak, Kind::RightBracket]);
    let end = p.current_end();
    p.expect_closing_delimiter(open, Kind::Underscore);
    let end = if p.prev_end() > open.end as usize { p.prev_end() } else { end };
    Expr::new(ExprKind::Emph(body), Span::new(open.start as usize, end))
}

fn whitespace_line(p: &mut Parser) {
    while p.current() == Kind::Space && p.token.data.newlines == 0 {
        p.eat();
    }
}

fn heading(p: &mut Parser) -> Expr {
    let start = p.current_start();
    let (body, depth) = p.with_nl_mode(Newline::Stop, |p| {
        let (_, marker) = p.eat();
        let depth = marker.len();
        whitespace_line(p);
        let body = markup(p, false, false, &[Kind::End, Kind::Label, Kind::RightBracket]);
        (body, depth)
    });
    let end = body.last().map(|e| e.span.end as usize).unwrap_or(p.prev_end());
    Expr::new(ExprKind::Heading { depth, body }, Span::new(start, end.max(start + depth)))
}

fn list_item(p: &mut Parser) -> Expr {
    let start = p.current_start();
    let min_indent = p.column(start) + 1;
    let body = p.with_nl_mode(Newline::RequireColumn(min_indent), |p| {
        p.assert(Kind::ListMarker);
        whitespace_line(p);
        markup(p, false, false, &[Kind::End, Kind::RightBracket])
    });
    let end = body.last().map(|e| e.span.end as usize).unwrap_or(start + 1);
    Expr::new(ExprKind::ListItem { body }, Span::new(start, end))
}

fn enum_item(p: &mut Parser) -> Expr {
    let start = p.current_start();
    let min_indent = p.column(start) + 1;
    let (number, body) = p.with_nl_mode(Newline::RequireColumn(min_indent), |p| {
        let (_, marker) = p.eat();
        let number = marker.strip_suffix('.').and_then(|s| s.parse::<u64>().ok());
        whitespace_line(p);
        (number, markup(p, false, false, &[Kind::End, Kind::RightBracket]))
    });
    let end = body.last().map(|e| e.span.end as usize).unwrap_or(start + 1);
    Expr::new(ExprKind::EnumItem { number, body }, Span::new(start, end))
}

fn term_item(p: &mut Parser) -> Expr {
    let start = p.current_start();
    let min_indent = p.column(start) + 1;
    let (term, description) = p.with_nl_mode(Newline::RequireColumn(min_indent), |p| {
        p.assert(Kind::TermMarker);
        whitespace_line(p);
        let term = markup(p, false, false, &[Kind::Colon, Kind::End, Kind::RightBracket]);
        let trailing = std::mem::take(&mut p.pending_trivia);
        let _ = trailing;
        if !p.eat_if(Kind::Colon) {
            p.expected("colon");
        }
        whitespace_line(p);
        let description = markup(p, false, false, &[Kind::End, Kind::RightBracket]);
        (term, description)
    });
    let end = description
        .last()
        .map(|e| e.span.end as usize)
        .or_else(|| term.last().map(|e| e.span.end as usize))
        .unwrap_or(start + 1);
    Expr::new(ExprKind::TermItem { term, description }, Span::new(start, end))
}

fn reference(p: &mut Parser) -> Expr {
    let (span, text) = p.eat();
    let target = text[1..].to_string();
    let mut supplement = None;
    let mut end = span.end as usize;
    if p.directly_at(Kind::LeftBracket) {
        let block = content_block(p);
        end = block.span.end as usize;
        supplement = Some(Box::new(block));
    }
    Expr::new(ExprKind::Ref { target, supplement }, Span::new(span.start as usize, end))
}

fn equation(p: &mut Parser) -> Expr {
    let start = p.current_start();
    let (body, has_space_before, has_space_after) =
        p.enter_modes(LexMode::Math, Newline::Continue, |p| {
            p.assert(Kind::Dollar);
            let space_before = p.current() == Kind::Space;
            let body = math(p, &[Kind::Dollar, Kind::End]);
            let space_after = body.last().is_some_and(|e| matches!(e.kind, ExprKind::Space));
            (body, space_before, space_after)
        });
    let open = Span::new(start, start + 1);
    p.expect_closing_delimiter(open, Kind::Dollar);
    let end = p.prev_end();
    let block = has_space_before && has_space_after && body.len() > 1;
    Expr::new(ExprKind::Equation { block, body }, Span::new(start, end))
}

// ------------------------------------------------------------------- Math

fn math(p: &mut Parser, stop: &[Kind]) -> Vec<Expr> {
    let mut out = Vec::new();
    while !p.end() && !p.at_set(stop) {
        if let Some(e) = math_expr(p) {
            out.push(e);
        }
    }
    out
}

fn math_expr(p: &mut Parser) -> Option<Expr> {
    math_expr_prec(p, 0, Kind::End)
}

fn math_class_is_continuable(text: &str) -> bool {
    // Letters and other "alphabetic" or unknown things are continuable.
    text.chars().all(|c| c.is_alphanumeric())
}

fn math_expr_prec(p: &mut Parser, min_prec: usize, stop: Kind) -> Option<Expr> {
    let start = p.current_start();
    let mut continuable = false;
    let mut expr = match p.current() {
        Kind::Hash => {
            let e = embedded_code_expr(p)?;
            e
        }
        Kind::Space => {
            let (span, _) = p.eat();
            return Some(Expr::new(ExprKind::Space, span));
        }
        Kind::Linebreak => {
            let (span, _) = p.eat();
            return Some(Expr::new(ExprKind::Linebreak, span));
        }
        Kind::MathAlignPoint => {
            let (span, _) = p.eat();
            Expr::new(ExprKind::MathAlignPoint, span)
        }
        Kind::Escape => {
            continuable = true;
            let (span, text) = p.eat();
            Expr::new(ExprKind::Escape(parse_escape(text)), span)
        }
        Kind::Str => {
            continuable = true;
            let (span, text) = p.eat();
            Expr::new(ExprKind::Str(parse_str(text)), span)
        }
        Kind::MathIdent => {
            continuable = true;
            let (span, text) = p.eat();
            let mut e = Expr::new(ExprKind::MathIdent(text.to_string()), span);
            // Field access: `a.b`.
            while p.directly_at(Kind::Dot) {
                // Lookahead: is next an identifier?
                let cp = p.checkpoint();
                p.eat();
                if p.directly_at(Kind::MathIdent) || p.directly_at(Kind::MathText) {
                    let (fspan, ftext) = p.eat();
                    if ftext.chars().all(|c| super::lexer::is_id_continue(c)) && ftext.chars().next().is_some_and(super::lexer::is_id_start) {
                        let total = Span::new(start, fspan.end as usize);
                        e = Expr::new(
                            ExprKind::FieldAccess {
                                target: Box::new(e),
                                field: Ident { name: ftext.to_string(), span: fspan },
                            },
                            total,
                        );
                        continue;
                    }
                }
                p.restore(cp);
                break;
            }
            // Function call.
            if min_prec < 3 && p.directly_at(Kind::MathText) && p.current_text() == "(" {
                let args = math_args(p);
                let total = Span::new(start, args.span.end as usize);
                e = Expr::new(ExprKind::FuncCall { callee: Box::new(e), args }, total);
                continuable = false;
            }
            e
        }
        Kind::MathText | Kind::MathShorthand | Kind::Dot | Kind::Comma | Kind::Semicolon | Kind::RightParen => {
            let text = p.current_text();
            continuable = p.current() == Kind::MathText && math_class_is_continuable(text);
            if let Some(d) = maybe_delimited(p) {
                d
            } else {
                let (span, text) = p.eat();
                if span.end - span.start == 0 {
                    return None;
                }
                let kind = if matches!(text, "->" | "=>" | "<=" | ">=" | "!=" | "<-" | ":=" | "..." | "<<" | ">>" | "|->" | "<->" | "<=>" | "=:" | "::=" | "-->" | "<--" | "<-->" | "==>" | "<==" | "<==>" | "~>" | "~~>" | "<~" | "<~~" | ">->" | "<-<" | "[|" | "|]" | "||" | "*" | "-" | "~" | "->>" | "<<-" | "<<<" | ">>>")
                    && p_kind_was_shorthand(text)
                {
                    ExprKind::MathShorthand(math_shorthand_char(text))
                } else {
                    ExprKind::MathText(text.to_string())
                };
                Expr::new(kind, span)
            }
        }
        Kind::Root => {
            if min_prec < 3 {
                let (span, text) = p.eat();
                let index = match text {
                    "∛" => Some(3),
                    "∜" => Some(4),
                    _ => None,
                };
                let radicand = math_expr_prec(p, 2, stop);
                let radicand = radicand.unwrap_or(Expr::new(ExprKind::Math(vec![]), span));
                let radicand = math_unparen(radicand);
                let total = Span::new(start, radicand.span.end as usize);
                Expr::new(ExprKind::MathRoot { index, radicand: Box::new(radicand) }, total)
            } else {
                let (span, text) = p.eat();
                Expr::new(ExprKind::MathText(text.to_string()), span)
            }
        }
        Kind::Prime => {
            continuable = true;
            let mut count = 0;
            let mut span = p.current_span();
            while p.at(Kind::Prime) {
                let (s, _) = p.eat();
                span = span.join(s);
                count += 1;
                while p.directly_at(Kind::Prime) {
                    let (s, _) = p.eat();
                    span = span.join(s);
                    count += 1;
                }
            }
            Expr::new(ExprKind::MathPrimes(count), span)
        }
        Kind::Error => {
            p.eat_error();
            return None;
        }
        Kind::Dollar | Kind::End => return None,
        _ => {
            p.unexpected();
            return None;
        }
    };

    if continuable && min_prec < 3 && p.prev_end() == p.current_start() {
        if let Some(d) = maybe_delimited(p) {
            let total = Span::new(start, d.span.end as usize);
            expr = Expr::new(ExprKind::Math(vec![expr, d]), total);
        }
    }

    let mut primed = false;
    while !p.end() && !p.at(stop) {
        if p.directly_at(Kind::MathText) && p.current_text() == "!" {
            let (span, text) = p.eat();
            let total = Span::new(start, span.end as usize);
            expr = Expr::new(
                ExprKind::Math(vec![expr, Expr::new(ExprKind::MathText(text.to_string()), span)]),
                total,
            );
            continue;
        }
        if p.directly_at(Kind::Prime) {
            let mut count = 0;
            let mut span = p.current_span();
            while p.eat_if_direct(Kind::Prime) {
                count += 1;
                span.end = p.prev_end() as u32;
            }
            let primes = Expr::new(ExprKind::MathPrimes(count), span);
            let total = Span::new(start, span.end as usize);
            expr = Expr::new(
                ExprKind::MathAttach {
                    base: Box::new(expr),
                    bottom: None,
                    top: None,
                    primes: Some(Box::new(primes)),
                },
                total,
            );
            primed = true;
            continue;
        }

        if primed && p.current() == Kind::Hat {
            primed = false;
        }

        let Some((is_frac, other, assoc, mut prec)) = math_op(p.current()) else {
            break;
        };
        if prec < min_prec {
            break;
        }
        match assoc {
            Assoc::Left => prec += 1,
            Assoc::Right => {}
        }
        if is_frac {
            expr = math_unparen(expr);
        }
        let op_kind = p.current();
        p.eat();
        let rhs = math_expr_prec(p, prec, other);
        let rhs = rhs.map(math_unparen);
        let rhs = rhs.unwrap_or_else(|| Expr::new(ExprKind::Math(vec![]), Span::new(p.prev_end(), p.prev_end())));

        if is_frac {
            let total = Span::new(start, rhs.span.end as usize);
            expr = Expr::new(ExprKind::MathFrac { num: Box::new(expr), denom: Box::new(rhs) }, total);
        } else {
            let mut bottom = None;
            let mut top = None;
            if op_kind == Kind::Underscore {
                bottom = Some(Box::new(rhs));
            } else {
                top = Some(Box::new(rhs));
            }
            if p.at(Kind::Underscore) || p.at(Kind::Hat) {
                let second = p.current();
                p.eat();
                let r2 = math_expr_prec(p, prec, Kind::End).map(math_unparen);
                let r2 = r2.unwrap_or_else(|| Expr::new(ExprKind::Math(vec![]), Span::new(p.prev_end(), p.prev_end())));
                if second == Kind::Underscore {
                    bottom = Some(Box::new(r2));
                } else {
                    top = Some(Box::new(r2));
                }
            }
            let end = p.prev_end();
            // Merge with existing primed attach.
            let (base, primes) = match expr.kind {
                ExprKind::MathAttach { base, primes, bottom: None, top: None } if primed || primes.is_some() => (base, primes),
                _ => (Box::new(expr), None),
            };
            primed = false;
            expr = Expr::new(
                ExprKind::MathAttach { base, bottom, top, primes },
                Span::new(start, end),
            );
        }
    }
    Some(expr)
}

fn p_kind_was_shorthand(_text: &str) -> bool {
    true
}

fn math_shorthand_char(text: &str) -> char {
    match text {
        "->" => '→',
        "->>" => '↠',
        "-->" => '⟶',
        "<-" => '←',
        "<<-" => '↞',
        "<--" => '⟵',
        "<->" => '↔',
        "<-->" => '⟷',
        "=>" => '⇒',
        "==>" => '⟹',
        "<==" => '⟸',
        "<=>" => '⇔',
        "<==>" => '⟺',
        "|->" => '↦',
        "|=>" => '⤇',
        "<=" => '≤',
        ">=" => '≥',
        "!=" => '≠',
        ":=" => '≔',
        "::=" => '⩴',
        "=:" => '≕',
        "..." => '…',
        "<<" => '≪',
        "<<<" => '⋘',
        ">>" => '≫',
        ">>>" => '⋙',
        "~>" => '⇝',
        "~~>" => '⟿',
        "<~" => '⇜',
        "<~~" => '⬳',
        ">->" => '↣',
        "<-<" => '↢',
        "[|" => '⟦',
        "|]" => '⟧',
        "||" => '‖',
        "*" => '∗',
        "-" => '−',
        "~" => '∼',
        _ => text.chars().next().unwrap_or(' '),
    }
}

fn math_op(kind: Kind) -> Option<(bool, Kind, Assoc, usize)> {
    match kind {
        Kind::Underscore => Some((false, Kind::Hat, Assoc::Right, 2)),
        Kind::Hat => Some((false, Kind::Underscore, Assoc::Right, 2)),
        Kind::Slash => Some((true, Kind::End, Assoc::Left, 1)),
        _ => None,
    }
}

fn math_unparen(expr: Expr) -> Expr {
    if let ExprKind::MathDelimited { open, body, close } = &expr.kind {
        let is_paren = |e: &Expr| matches!(&e.kind, ExprKind::MathText(t) if t == "(" || t == ")");
        if is_paren(open) && is_paren(close) {
            let span = expr.span;
            return Expr::new(ExprKind::Math(body.clone()), span);
        }
    }
    expr
}

fn maybe_delimited(p: &mut Parser) -> Option<Expr> {
    if p.current() != Kind::MathText && p.current() != Kind::MathShorthand {
        return None;
    }
    let text = p.current_text();
    if !is_opening_delim(text) {
        return None;
    }
    let start = p.current_start();
    let (open_span, open_text) = p.eat();
    let open = Expr::new(ExprKind::MathText(open_text.to_string()), open_span);
    let mut body = Vec::new();
    loop {
        if p.end() || p.at(Kind::Dollar) {
            break;
        }
        if (p.at(Kind::MathText) || p.at(Kind::MathShorthand) || p.at(Kind::RightParen)) && is_closing_delim(p.current_text()) {
            break;
        }
        if let Some(e) = math_expr(p) {
            body.push(e);
        }
    }
    if (p.at(Kind::MathText) || p.at(Kind::MathShorthand) || p.at(Kind::RightParen)) && is_closing_delim(p.current_text()) {
        let (close_span, close_text) = p.eat();
        let close = Expr::new(ExprKind::MathText(close_text.to_string()), close_span);
        let total = Span::new(start, close_span.end as usize);
        Some(Expr::new(
            ExprKind::MathDelimited { open: Box::new(open), body, close: Box::new(close) },
            total,
        ))
    } else {
        // Unclosed: emit as plain math sequence.
        let end = body.last().map(|e| e.span.end as usize).unwrap_or(open_span.end as usize);
        let mut seq = vec![open];
        seq.extend(body);
        Some(Expr::new(ExprKind::Math(seq), Span::new(start, end)))
    }
}

fn is_opening_delim(text: &str) -> bool {
    matches!(text, "(" | "[" | "{" | "⟨" | "⟦" | "⌈" | "⌊" | "⟮" | "⦃" | "[|" | "‖" | "|")
        && text != "|"
        && text != "‖"
}

fn is_closing_delim(text: &str) -> bool {
    matches!(text, ")" | "]" | "}" | "⟩" | "⟧" | "⌉" | "⌋" | "⟯" | "⦄" | "|]")
}

fn math_args(p: &mut Parser) -> Args {
    let start = p.current_start();
    p.assert(Kind::MathText); // "("
    let mut items: Vec<Arg> = Vec::new();
    let mut array: Vec<Vec<Arg>> = Vec::new();
    let mut current: Vec<Expr> = Vec::new();
    let mut named: Option<Ident> = None;
    let mut has_arrays = false;
    let mut seen_semicolon = false;

    let flush = |current: &mut Vec<Expr>, named: &mut Option<Ident>, items: &mut Vec<Arg>, p: &Parser| {
        let mut body = std::mem::take(current);
        // Trim leading/trailing spaces.
        while body.first().is_some_and(|e| matches!(e.kind, ExprKind::Space)) {
            body.remove(0);
        }
        while body.last().is_some_and(|e| matches!(e.kind, ExprKind::Space)) {
            body.pop();
        }
        let _ = p;
        let span = if body.is_empty() {
            Span::new(p.prev_end(), p.prev_end())
        } else {
            Span::new(body[0].span.start as usize, body.last().unwrap().span.end as usize)
        };
        let expr = if body.len() == 1 { body.pop().unwrap() } else { Expr::new(ExprKind::Math(body), span) };
        match named.take() {
            Some(name) => items.push(Arg::Named(name, expr)),
            None => items.push(Arg::Pos(expr)),
        }
    };

    let mut row: Vec<Arg> = Vec::new();
    loop {
        if p.end() || p.at(Kind::Dollar) {
            break;
        }
        if p.at(Kind::RightParen) || (p.at(Kind::MathText) && p.current_text() == ")") {
            break;
        }
        match p.current() {
            Kind::Comma => {
                p.eat();
                flush(&mut current, &mut named, &mut row, p);
                continue;
            }
            Kind::Semicolon => {
                p.eat();
                flush(&mut current, &mut named, &mut row, p);
                has_arrays = true;
                seen_semicolon = true;
                array.push(std::mem::take(&mut row));
                continue;
            }
            Kind::MathIdent if current.is_empty() && named.is_none() => {
                // Possibly a named argument.
                let cp = p.checkpoint();
                let (span, text) = p.eat();
                if p.directly_at(Kind::MathText) && p.current_text() == ":" || p.at(Kind::Colon) {
                    p.eat();
                    named = Some(Ident { name: text.to_string(), span });
                    continue;
                }
                p.restore(cp);
            }
            _ => {}
        }
        if let Some(e) = math_expr(p) {
            current.push(e);
        }
    }

    // Final flush.
    let had_content = !current.is_empty() || named.is_some();
    if had_content || !row.is_empty() || !seen_semicolon {
        if had_content || !row.is_empty() || !has_arrays {
            if had_content {
                flush(&mut current, &mut named, &mut row, p);
            } else if !has_arrays && row.is_empty() {
                // `f()` - no args
            }
        }
    }
    if has_arrays {
        if !row.is_empty() {
            array.push(row);
        }
        for r in array {
            let exprs: Vec<ArrayItem> = r
                .into_iter()
                .filter_map(|a| match a {
                    Arg::Pos(e) => Some(ArrayItem::Pos(e)),
                    _ => None,
                })
                .collect();
            let span = Span::new(start, p.prev_end());
            items.push(Arg::Pos(Expr::new(ExprKind::Array(exprs), span)));
        }
    } else {
        items = row;
    }

    let open = Span::new(start, start + 1);
    if p.at(Kind::RightParen) || (p.at(Kind::MathText) && p.current_text() == ")") {
        p.eat();
    } else {
        p.expect_closing_delimiter(open, Kind::RightParen);
    }
    let end = p.prev_end();
    Args { items, span: Span::new(start, end), trailing_comma: false }
}

// ------------------------------------------------------------------- Code

fn embedded_code_expr(p: &mut Parser) -> Option<Expr> {
    p.enter_modes(LexMode::Code, Newline::Stop, |p| {
        let hash = p.assert(Kind::Hash);
        if p.had_trivia() || p.end() {
            p.expected("expression");
            return None;
        }
        let stmt = p.at_set(STMT);
        let at = p.at_set(ATOMIC_CODE_EXPR);
        let expr = code_expr_prec(p, true, 0);

        // Consume error for things like `#12p` or `#"abc\"`.
        if !at && !p.current().is_trivia() && !p.end() {
            p.unexpected();
        }

        let semi = (stmt || p.directly_at(Kind::Semicolon)) && p.eat_if(Kind::Semicolon);
        if stmt && !semi && !p.end() && !p.at(Kind::RightBracket) {
            p.expected("semicolon or line break");
        }
        let _ = hash;
        expr
    })
}

const STMT: &[Kind] = &[Kind::Let, Kind::Set, Kind::Show, Kind::Import, Kind::Include, Kind::Return];

const ATOMIC_CODE_EXPR: &[Kind] = &[
    Kind::Ident,
    Kind::LeftBrace,
    Kind::LeftBracket,
    Kind::LeftParen,
    Kind::Dollar,
    Kind::Let,
    Kind::Set,
    Kind::Show,
    Kind::Context,
    Kind::If,
    Kind::While,
    Kind::For,
    Kind::Import,
    Kind::Include,
    Kind::Break,
    Kind::Continue,
    Kind::Return,
    Kind::None,
    Kind::Auto,
    Kind::Bool,
    Kind::Int,
    Kind::Float,
    Kind::Numeric,
    Kind::Str,
    Kind::Label,
    Kind::Raw,
];

const CODE_EXPR: &[Kind] = &[
    Kind::Ident,
    Kind::LeftBrace,
    Kind::LeftBracket,
    Kind::LeftParen,
    Kind::Dollar,
    Kind::Let,
    Kind::Set,
    Kind::Show,
    Kind::Context,
    Kind::If,
    Kind::While,
    Kind::For,
    Kind::Import,
    Kind::Include,
    Kind::Break,
    Kind::Continue,
    Kind::Return,
    Kind::None,
    Kind::Auto,
    Kind::Bool,
    Kind::Int,
    Kind::Float,
    Kind::Numeric,
    Kind::Str,
    Kind::Label,
    Kind::Raw,
    Kind::Plus,
    Kind::Minus,
    Kind::Not,
    Kind::Underscore,
];

const PATTERN_LEAF: &[Kind] = &[
    Kind::Ident,
    Kind::LeftBrace,
    Kind::LeftBracket,
    Kind::LeftParen,
    Kind::Dollar,
    Kind::None,
    Kind::Auto,
    Kind::Bool,
    Kind::Int,
    Kind::Float,
    Kind::Numeric,
    Kind::Str,
    Kind::Label,
    Kind::Raw,
];

const PATTERN: &[Kind] = &[
    Kind::Ident,
    Kind::LeftBrace,
    Kind::LeftBracket,
    Kind::LeftParen,
    Kind::Dollar,
    Kind::None,
    Kind::Auto,
    Kind::Bool,
    Kind::Int,
    Kind::Float,
    Kind::Numeric,
    Kind::Str,
    Kind::Label,
    Kind::Raw,
    Kind::Underscore,
];

fn is_terminator(kind: Kind) -> bool {
    matches!(
        kind,
        Kind::End | Kind::Semicolon | Kind::RightBrace | Kind::RightParen | Kind::RightBracket
    )
}

fn code_exprs(p: &mut Parser, stop: &[Kind]) -> Vec<Expr> {
    let mut out = Vec::new();
    while !p.at_set(stop) {
        p.with_nl_mode(Newline::Contextual, |p| {
            if !p.at_set(CODE_EXPR) {
                p.unexpected();
                return;
            }
            if let Some(e) = code_expr(p) {
                out.push(e);
            }
            if !p.at_set(stop) && !p.eat_if(Kind::Semicolon) {
                p.expected("semicolon or line break");
                if p.at(Kind::Else) {
                    p.hint("see https://github.com/typst/typst/issues/3209");
                }
            }
        });
    }
    out
}

fn code_expr(p: &mut Parser) -> Option<Expr> {
    code_expr_prec(p, false, 0)
}

fn unop_from_kind(kind: Kind) -> Option<UnOp> {
    match kind {
        Kind::Plus => Some(UnOp::Pos),
        Kind::Minus => Some(UnOp::Neg),
        Kind::Not => Some(UnOp::Not),
        _ => None,
    }
}

fn binop_from_kind(kind: Kind) -> Option<BinOp> {
    match kind {
        Kind::Plus => Some(BinOp::Add),
        Kind::Minus => Some(BinOp::Sub),
        Kind::Star => Some(BinOp::Mul),
        Kind::Slash => Some(BinOp::Div),
        Kind::And => Some(BinOp::And),
        Kind::Or => Some(BinOp::Or),
        Kind::EqEq => Some(BinOp::Eq),
        Kind::ExclEq => Some(BinOp::Neq),
        Kind::Lt => Some(BinOp::Lt),
        Kind::LtEq => Some(BinOp::Leq),
        Kind::Gt => Some(BinOp::Gt),
        Kind::GtEq => Some(BinOp::Geq),
        Kind::Eq => Some(BinOp::Assign),
        Kind::In => Some(BinOp::In),
        Kind::PlusEq => Some(BinOp::AddAssign),
        Kind::HyphEq => Some(BinOp::SubAssign),
        Kind::StarEq => Some(BinOp::MulAssign),
        Kind::SlashEq => Some(BinOp::DivAssign),
        _ => None,
    }
}

fn code_expr_prec(p: &mut Parser, atomic: bool, min_prec: usize) -> Option<Expr> {
    let start = p.current_start();
    let mut expr = if !atomic && unop_from_kind(p.current()).is_some() {
        let op = unop_from_kind(p.current()).unwrap();
        p.eat();
        let inner = code_expr_prec(p, atomic, op.precedence());
        let inner = inner?;
        let span = Span::new(start, inner.span.end as usize);
        Expr::new(ExprKind::Unary { op, expr: Box::new(inner) }, span)
    } else {
        code_primary(p, atomic)?
    };

    loop {
        if p.directly_at(Kind::LeftParen) || p.directly_at(Kind::LeftBracket) {
            let args = args(p);
            let span = Span::new(start, args.span.end as usize);
            expr = Expr::new(ExprKind::FuncCall { callee: Box::new(expr), args }, span);
            continue;
        }

        let at_field_or_method = p.directly_at(Kind::Dot) && {
            // Lookahead for identifier after the dot.
            let mut lx = Lexer::new(p.text, LexMode::Code);
            lx.jump(p.current_end());
            let k = lx.next();
            k == Kind::Ident || (k.is_keyword())
        };

        if atomic && !at_field_or_method {
            break;
        }

        if p.eat_if(Kind::Dot) {
            if p.at(Kind::Ident) {
                let (fspan, ftext) = p.eat();
                let span = Span::new(start, fspan.end as usize);
                expr = Expr::new(
                    ExprKind::FieldAccess {
                        target: Box::new(expr),
                        field: Ident { name: ftext.to_string(), span: fspan },
                    },
                    span,
                );
            } else if p.current().is_keyword() {
                // Keywords after dot are treated as identifiers by the lexer,
                // but handle just in case.
                let (fspan, ftext) = p.eat();
                let span = Span::new(start, fspan.end as usize);
                expr = Expr::new(
                    ExprKind::FieldAccess {
                        target: Box::new(expr),
                        field: Ident { name: ftext.to_string(), span: fspan },
                    },
                    span,
                );
            } else {
                p.expected("identifier");
            }
            continue;
        }

        let binop = if let Some(op) = binop_from_kind(p.current()) {
            Some(op)
        } else if min_prec <= BinOp::NotIn.precedence() && p.at(Kind::Not) {
            // Peek for `in`.
            let cp = p.checkpoint();
            p.eat();
            if p.at(Kind::In) {
                Some(BinOp::NotIn)
            } else {
                p.restore(cp);
                p.eat();
                p.expected("keyword `in`");
                break;
            }
        } else {
            None
        };

        let Some(op) = binop else { break };
        let mut prec = op.precedence();
        if prec < min_prec {
            break;
        }
        match op.assoc() {
            Assoc::Left => prec += 1,
            Assoc::Right => {}
        }
        p.eat();
        let rhs = code_expr_prec(p, false, prec);
        let rhs = match rhs {
            Some(r) => r,
            None => {
                let at = p.prev_end();
                Expr::new(ExprKind::None, Span::new(at, at))
            }
        };
        let span = Span::new(start, rhs.span.end as usize);
        expr = Expr::new(ExprKind::Binary { op, lhs: Box::new(expr), rhs: Box::new(rhs) }, span);
    }

    Some(expr)
}

pub fn parse_str(text: &str) -> String {
    let inner = &text[1..text.len().saturating_sub(1).max(1)];
    let inner = if text.len() >= 2 && text.ends_with('"') && text.len() > 1 { &text[1..text.len() - 1] } else { inner };
    let mut out = String::new();
    let mut s = super::scanner::Scanner::new(inner);
    while let Some(c) = s.eat() {
        if c != '\\' {
            out.push(c);
            continue;
        }
        let start = s.cursor() - 1;
        match s.eat() {
            Some('\\') => out.push('\\'),
            Some('"') => out.push('"'),
            Some('n') => out.push('\n'),
            Some('r') => out.push('\r'),
            Some('t') => out.push('\t'),
            Some('u') if s.eat_if('{') => {
                let hex = s.eat_while(char::is_ascii_alphanumeric);
                let closed = s.eat_if('}');
                match u32::from_str_radix(hex, 16).ok().and_then(char::from_u32) {
                    Some(ch) if closed => out.push(ch),
                    _ => out.push_str(s.get(start..s.cursor())),
                }
            }
            _ => out.push_str(s.get(start..s.cursor())),
        }
    }
    out
}

fn code_primary(p: &mut Parser, atomic: bool) -> Option<Expr> {
    let start = p.current_start();
    match p.current() {
        Kind::Ident => {
            let (span, text) = p.eat();
            let ident = Expr::new(ExprKind::Ident(text.to_string()), span);
            if !atomic && p.at(Kind::Arrow) {
                p.assert(Kind::Arrow);
                let body = code_expr(p);
                let body = body.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
                let total = Span::new(start, body.span.end as usize);
                let params = vec![Param::Pos(Pattern::Normal(ident))];
                return Some(Expr::new(
                    ExprKind::Closure(Rc::new(Closure { name: None, params, body })),
                    total,
                ));
            }
            Some(ident)
        }
        Kind::Underscore if !atomic => {
            let (span, _) = p.eat();
            if p.at(Kind::Arrow) {
                p.eat();
                let body = code_expr(p);
                let body = body.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
                let total = Span::new(start, body.span.end as usize);
                Some(Expr::new(
                    ExprKind::Closure(Rc::new(Closure {
                        name: None,
                        params: vec![Param::Pos(Pattern::Placeholder(span))],
                        body,
                    })),
                    total,
                ))
            } else if p.eat_if(Kind::Eq) {
                let value = code_expr(p);
                let value = value.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
                let total = Span::new(start, value.span.end as usize);
                Some(Expr::new(
                    ExprKind::DestructAssign { pattern: Pattern::Placeholder(span), value: Box::new(value) },
                    total,
                ))
            } else {
                p.error_at(span, "expected expression, found underscore");
                None
            }
        }
        Kind::LeftBrace => Some(code_block(p)),
        Kind::LeftBracket => Some(content_block(p)),
        Kind::LeftParen => expr_with_paren(p, atomic),
        Kind::Dollar => Some(equation(p)),
        Kind::Let => let_binding(p),
        Kind::Set => set_rule(p),
        Kind::Show => show_rule(p),
        Kind::Context => contextual(p, atomic),
        Kind::If => conditional(p),
        Kind::While => while_loop(p),
        Kind::For => for_loop(p),
        Kind::Import => module_import(p),
        Kind::Include => module_include(p),
        Kind::Break => {
            let (span, _) = p.eat();
            Some(Expr::new(ExprKind::Break, span))
        }
        Kind::Continue => {
            let (span, _) = p.eat();
            Some(Expr::new(ExprKind::Continue, span))
        }
        Kind::Return => return_stmt(p),
        Kind::Raw => {
            let (span, _, data) = p.eat_data();
            let raw = data.raw.unwrap_or_default_raw();
            Some(Expr::new(ExprKind::Raw { text: raw.text, lang: raw.lang, block: raw.block }, span))
        }
        Kind::None => {
            let (span, _) = p.eat();
            Some(Expr::new(ExprKind::None, span))
        }
        Kind::Auto => {
            let (span, _) = p.eat();
            Some(Expr::new(ExprKind::Auto, span))
        }
        Kind::Bool => {
            let (span, text) = p.eat();
            Some(Expr::new(ExprKind::Bool(text == "true"), span))
        }
        Kind::Int => {
            let (span, text) = p.eat();
            Some(Expr::new(ExprKind::Int(parse_int(text)), span))
        }
        Kind::Float => {
            let (span, text) = p.eat();
            Some(Expr::new(ExprKind::Float(text.parse().unwrap_or(0.0)), span))
        }
        Kind::Numeric => {
            let (span, text) = p.eat();
            let (v, unit) = parse_numeric(text);
            Some(Expr::new(ExprKind::Numeric(v, unit), span))
        }
        Kind::Str => {
            let (span, text) = p.eat();
            Some(Expr::new(ExprKind::Str(parse_str(text)), span))
        }
        Kind::Label => {
            let (span, text) = p.eat();
            Some(Expr::new(ExprKind::Label(text[1..text.len() - 1].to_string()), span))
        }
        Kind::Error => {
            p.eat_error();
            None
        }
        _ => {
            p.expected("expression");
            None
        }
    }
}

pub fn parse_int(text: &str) -> i64 {
    if let Some(h) = text.strip_prefix("0x") {
        i64::from_str_radix(h, 16).unwrap_or(0)
    } else if let Some(b) = text.strip_prefix("0b") {
        i64::from_str_radix(b, 2).unwrap_or(0)
    } else if let Some(o) = text.strip_prefix("0o") {
        i64::from_str_radix(o, 8).unwrap_or(0)
    } else {
        text.parse().unwrap_or(0)
    }
}

pub fn parse_numeric(text: &str) -> (f64, Unit) {
    let count = text.trim_end_matches(|c: char| c.is_ascii_alphabetic() || c == '%');
    let suffix = &text[count.len()..];
    let value: f64 = count.parse().unwrap_or(0.0);
    let unit = match suffix {
        "pt" => Unit::Pt,
        "mm" => Unit::Mm,
        "cm" => Unit::Cm,
        "in" => Unit::In,
        "em" => Unit::Em,
        "deg" => Unit::Deg,
        "rad" => Unit::Rad,
        "%" => Unit::Percent,
        "fr" => Unit::Fr,
        _ => Unit::Pt,
    };
    (value, unit)
}

fn code_block(p: &mut Parser) -> Expr {
    let start = p.current_start();
    let exprs = p.enter_modes(LexMode::Code, Newline::Continue, |p| {
        p.assert(Kind::LeftBrace);
        code_exprs(p, &[Kind::RightBrace, Kind::RightBracket, Kind::RightParen, Kind::End])
    });
    let open = Span::new(start, start + 1);
    p.expect_closing_delimiter(open, Kind::RightBrace);
    let end = p.prev_end();
    Expr::new(ExprKind::CodeBlock(exprs), Span::new(start, end))
}

fn content_block(p: &mut Parser) -> Expr {
    let start = p.current_start();
    let body = p.enter_modes(LexMode::Markup, Newline::Continue, |p| {
        p.assert(Kind::LeftBracket);
        markup(p, true, true, &[Kind::RightBracket, Kind::End])
    });
    let open = Span::new(start, start + 1);
    p.expect_closing_delimiter(open, Kind::RightBracket);
    let end = p.prev_end();
    Expr::new(ExprKind::ContentBlock(body), Span::new(start, end))
}

fn expr_with_paren(p: &mut Parser, atomic: bool) -> Option<Expr> {
    if atomic {
        return Some(parenthesized_or_array_or_dict(p).0);
    }
    let cp = p.checkpoint();
    let (expr, kind) = parenthesized_or_array_or_dict(p);
    if p.at(Kind::Arrow) {
        p.restore(cp);
        let start = p.current_start();
        let params = params(p);
        if !p.expect(Kind::Arrow) {
            return None;
        }
        let body = code_expr(p);
        let body = body.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
        let total = Span::new(start, body.span.end as usize);
        return Some(Expr::new(
            ExprKind::Closure(Rc::new(Closure { name: None, params, body })),
            total,
        ));
    } else if p.at(Kind::Eq) && kind != GroupKind::Parenthesized {
        p.restore(cp);
        let start = p.current_start();
        let mut seen = HashSet::new();
        let pattern = destructuring_or_parenthesized(p, true, &mut seen);
        if !p.expect(Kind::Eq) {
            return None;
        }
        let value = code_expr(p);
        let value = value.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
        let total = Span::new(start, value.span.end as usize);
        return Some(Expr::new(ExprKind::DestructAssign { pattern, value: Box::new(value) }, total));
    }
    Some(expr)
}

fn parenthesized_or_array_or_dict(p: &mut Parser) -> (Expr, GroupKind) {
    let start = p.current_start();
    let mut count = 0;
    let mut maybe_just_parens = true;
    let mut kind: Option<GroupKind> = None;
    let mut seen: HashSet<String> = HashSet::new();
    let mut items: Vec<GroupItem> = Vec::new();

    p.with_nl_mode(Newline::Continue, |p| {
        p.assert(Kind::LeftParen);
        if p.eat_if(Kind::Colon) {
            kind = Some(GroupKind::Dict);
            maybe_just_parens = false;
        }
        while !is_terminator(p.current()) {
            if !p.at_set(ARRAY_OR_DICT_ITEM) {
                p.unexpected();
                continue;
            }
            array_or_dict_item(p, &mut kind, &mut maybe_just_parens, &mut seen, &mut items);
            count += 1;
            if !is_terminator(p.current()) && p.expect(Kind::Comma) {
                maybe_just_parens = false;
            }
        }
        let open = Span::new(start, start + 1);
        p.expect_closing_delimiter(open, Kind::RightParen);
    });

    let end = p.prev_end();
    let span = Span::new(start, end);
    let kind = if maybe_just_parens && count == 1 {
        GroupKind::Parenthesized
    } else {
        kind.unwrap_or(GroupKind::Array)
    };

    let expr = match kind {
        GroupKind::Parenthesized => {
            let inner = items.into_iter().next();
            match inner {
                Some(GroupItem::Pos(e)) => Expr::new(ExprKind::Parenthesized(Box::new(e)), span),
                Some(GroupItem::Placeholder(s)) => {
                    p.error_at(s, "expected expression, found underscore");
                    Expr::new(ExprKind::None, span)
                }
                _ => Expr::new(ExprKind::None, span),
            }
        }
        GroupKind::Array => {
            let mut out = Vec::new();
            for item in items {
                match item {
                    GroupItem::Pos(e) => out.push(ArrayItem::Pos(e)),
                    GroupItem::Spread(e) => out.push(ArrayItem::Spread(e)),
                    GroupItem::Placeholder(s) => p.error_at(s, "expected expression, found underscore"),
                    GroupItem::Named(..) | GroupItem::Keyed(..) => {}
                }
            }
            Expr::new(ExprKind::Array(out), span)
        }
        GroupKind::Dict => {
            let mut out = Vec::new();
            for item in items {
                match item {
                    GroupItem::Named(n, e) => out.push(DictItem::Named(n, e)),
                    GroupItem::Keyed(k, e) => out.push(DictItem::Keyed(k, e)),
                    GroupItem::Spread(e) => out.push(DictItem::Spread(e)),
                    GroupItem::Placeholder(s) => p.error_at(s, "expected expression, found underscore"),
                    GroupItem::Pos(_) => {}
                }
            }
            Expr::new(ExprKind::Dict(out), span)
        }
    };
    (expr, kind)
}

const ARRAY_OR_DICT_ITEM: &[Kind] = &[
    Kind::Ident,
    Kind::LeftBrace,
    Kind::LeftBracket,
    Kind::LeftParen,
    Kind::Dollar,
    Kind::Let,
    Kind::Set,
    Kind::Show,
    Kind::Context,
    Kind::If,
    Kind::While,
    Kind::For,
    Kind::Import,
    Kind::Include,
    Kind::Break,
    Kind::Continue,
    Kind::Return,
    Kind::None,
    Kind::Auto,
    Kind::Bool,
    Kind::Int,
    Kind::Float,
    Kind::Numeric,
    Kind::Str,
    Kind::Label,
    Kind::Raw,
    Kind::Plus,
    Kind::Minus,
    Kind::Not,
    Kind::Underscore,
    Kind::Dots,
];

fn expr_kind_name(e: &Expr) -> &'static str {
    match &e.kind {
        ExprKind::Ident(_) => "identifier",
        ExprKind::None => "`none`",
        ExprKind::Auto => "`auto`",
        ExprKind::Bool(_) => "boolean",
        ExprKind::Int(_) => "integer",
        ExprKind::Float(_) => "float",
        ExprKind::Numeric(..) => "numeric value",
        ExprKind::Str(_) => "string",
        ExprKind::CodeBlock(_) => "code block",
        ExprKind::ContentBlock(_) => "content block",
        ExprKind::Parenthesized(_) => "group",
        ExprKind::Array(_) => "array",
        ExprKind::Dict(_) => "dictionary",
        ExprKind::Unary { .. } => "unary expression",
        ExprKind::Binary { .. } => "binary expression",
        ExprKind::FieldAccess { .. } => "field access",
        ExprKind::FuncCall { .. } => "function call",
        ExprKind::Closure(_) => "closure",
        ExprKind::Let { .. } => "`let` expression",
        ExprKind::DestructAssign { .. } => "destructuring assignment expression",
        ExprKind::Set { .. } => "`set` expression",
        ExprKind::Show { .. } => "`show` expression",
        ExprKind::Contextual(_) => "`context` expression",
        ExprKind::Conditional { .. } => "`if` expression",
        ExprKind::While { .. } => "while-loop expression",
        ExprKind::For { .. } => "for-loop expression",
        ExprKind::Import { .. } => "`import` expression",
        ExprKind::Include(_) => "`include` expression",
        ExprKind::Break => "`break` expression",
        ExprKind::Continue => "`continue` expression",
        ExprKind::Return(_) => "`return` expression",
        ExprKind::Equation { .. } => "equation",
        ExprKind::Raw { .. } => "raw block",
        ExprKind::Label(_) => "label",
        _ => "expression",
    }
}

fn array_or_dict_item(
    p: &mut Parser,
    kind: &mut Option<GroupKind>,
    maybe_just_parens: &mut bool,
    seen: &mut HashSet<String>,
    items: &mut Vec<GroupItem>,
) {
    let start = p.current_start();
    if p.eat_if(Kind::Dots) {
        let e = code_expr(p);
        if let Some(e) = e {
            items.push(GroupItem::Spread(e));
        }
        *maybe_just_parens = false;
        return;
    }

    if p.at(Kind::Underscore) {
        let (span, _) = p.eat();
        items.push(GroupItem::Placeholder(span));
        if *kind == Some(GroupKind::Dict) {
            // will error later
        } else {
            *kind = Some(GroupKind::Array);
        }
        return;
    }

    let Some(e) = code_expr(p) else { return };
    let _ = start;
    if p.eat_if(Kind::Colon) {
        let value = code_expr(p);
        let value = value.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
        let pair_name = match &e.kind {
            ExprKind::Ident(_) => "named pair",
            _ => "keyed pair",
        };
        match &e.kind {
            ExprKind::Ident(name) => {
                if !seen.insert(name.clone()) {
                    p.error_at(e.span, format!("duplicate key: {name}"));
                }
            }
            ExprKind::Str(s) => {
                if !seen.insert(s.clone()) {
                    p.error_at(e.span, format!("duplicate key: {s}"));
                }
            }
            _ => {}
        }
        *maybe_just_parens = false;
        if *kind == Some(GroupKind::Array) {
            p.error_at(Span::new(e.span.start as usize, value.span.end as usize), format!("expected expression, found {pair_name}"));
        } else {
            *kind = Some(GroupKind::Dict);
        }
        match e.kind {
            ExprKind::Ident(name) => items.push(GroupItem::Named(Ident { name, span: e.span }, value)),
            _ => items.push(GroupItem::Keyed(e, value)),
        }
    } else {
        if *kind == Some(GroupKind::Dict) {
            p.error_at(e.span, format!("expected named or keyed pair, found {}", expr_kind_name(&e)));
        } else {
            *kind = Some(GroupKind::Array);
        }
        items.push(GroupItem::Pos(e));
    }
}

fn args(p: &mut Parser) -> Args {
    let start = p.current_start();
    let mut items = Vec::new();
    let mut trailing_comma = false;
    if p.at(Kind::LeftParen) {
        p.with_nl_mode(Newline::Continue, |p| {
            p.assert(Kind::LeftParen);
            let mut seen: HashSet<String> = HashSet::new();
            while !is_terminator(p.current()) {
                if !p.at_set(ARG) {
                    p.unexpected();
                    continue;
                }
                arg(p, &mut seen, &mut items);
                trailing_comma = false;
                if !is_terminator(p.current()) {
                    if p.expect(Kind::Comma) {
                        trailing_comma = true;
                    }
                }
            }
            let open = Span::new(start, start + 1);
            p.expect_closing_delimiter(open, Kind::RightParen);
        });
    }
    while p.directly_at(Kind::LeftBracket) {
        let block = content_block(p);
        items.push(Arg::Pos(block));
    }
    let end = p.prev_end();
    Args { items, span: Span::new(start, end), trailing_comma }
}

const ARG: &[Kind] = ARRAY_OR_DICT_ITEM;

fn arg(p: &mut Parser, seen: &mut HashSet<String>, items: &mut Vec<Arg>) {
    if p.eat_if(Kind::Dots) {
        if let Some(e) = code_expr(p) {
            items.push(Arg::Spread(e));
        }
        return;
    }
    if p.at(Kind::Underscore) {
        let (span, _) = p.eat();
        p.error_at(span, "expected expression, found underscore");
        return;
    }
    let was_at_expr = p.at_set(CODE_EXPR);
    let text = p.current_text().to_string();
    let Some(e) = code_expr(p) else { return };
    if p.eat_if(Kind::Colon) {
        let value = code_expr(p);
        let value = value.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
        if was_at_expr && !matches!(e.kind, ExprKind::Ident(_)) {
            p.error_at(e.span, format!("expected identifier, found {}", expr_kind_name(&e)));
            items.push(Arg::Pos(value));
            return;
        }
        if !seen.insert(text.clone()) {
            p.error_at(e.span, format!("duplicate argument: {text}"));
        }
        if let ExprKind::Ident(name) = e.kind {
            items.push(Arg::Named(Ident { name, span: e.span }, value));
        }
    } else {
        items.push(Arg::Pos(e));
    }
}

fn params(p: &mut Parser) -> Vec<Param> {
    let start = p.current_start();
    let mut seen: HashSet<String> = HashSet::new();
    let mut sink = false;
    let mut out = Vec::new();
    p.with_nl_mode(Newline::Continue, |p| {
        p.assert(Kind::LeftParen);
        while !is_terminator(p.current()) {
            if !p.at_set(PARAM) {
                p.unexpected();
                continue;
            }
            param(p, &mut seen, &mut sink, &mut out);
            if !is_terminator(p.current()) {
                p.expect(Kind::Comma);
            }
        }
        let open = Span::new(start, start + 1);
        p.expect_closing_delimiter(open, Kind::RightParen);
    });
    out
}

const PARAM: &[Kind] = &[
    Kind::Ident,
    Kind::LeftBrace,
    Kind::LeftBracket,
    Kind::LeftParen,
    Kind::Dollar,
    Kind::None,
    Kind::Auto,
    Kind::Bool,
    Kind::Int,
    Kind::Float,
    Kind::Numeric,
    Kind::Str,
    Kind::Label,
    Kind::Raw,
    Kind::Underscore,
    Kind::Dots,
];

fn param(p: &mut Parser, seen: &mut HashSet<String>, sink: &mut bool, out: &mut Vec<Param>) {
    let start = p.current_start();
    if p.eat_if(Kind::Dots) {
        let mut name = None;
        if p.at_set(PATTERN_LEAF) {
            if let Some(Pattern::Normal(e)) = pattern_leaf(p, false, seen, Some("parameter")) {
                if let ExprKind::Ident(n) = e.kind {
                    name = Some(Ident { name: n, span: e.span });
                }
            }
        }
        let span = Span::new(start, p.prev_end());
        if std::mem::replace(sink, true) {
            p.error_at(span, "only one argument sink is allowed");
        }
        out.push(Param::Spread(name, span));
        return;
    }

    let was_at_pat = p.at_set(PATTERN);
    let pat = pattern(p, false, seen, Some("parameter"));
    if p.eat_if(Kind::Colon) {
        let default = code_expr(p);
        let default = default.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
        match pat {
            Some(Pattern::Normal(Expr { kind: ExprKind::Ident(name), span })) => {
                out.push(Param::Named(Ident { name, span }, default));
            }
            Some(other) => {
                if was_at_pat {
                    p.error_at(other.span(), "expected identifier");
                }
            }
            None => {}
        }
    } else if let Some(pat) = pat {
        out.push(Param::Pos(pat));
    }
}

fn pattern(
    p: &mut Parser,
    reassignment: bool,
    seen: &mut HashSet<String>,
    dupe: Option<&str>,
) -> Option<Pattern> {
    match p.current() {
        Kind::Underscore => {
            let (span, _) = p.eat();
            Some(Pattern::Placeholder(span))
        }
        Kind::LeftParen => Some(destructuring_or_parenthesized(p, reassignment, seen)),
        _ => pattern_leaf(p, reassignment, seen, dupe),
    }
}

fn destructuring_or_parenthesized(
    p: &mut Parser,
    reassignment: bool,
    seen: &mut HashSet<String>,
) -> Pattern {
    let start = p.current_start();
    let mut maybe_just_parens = true;
    let mut at_pattern_or_spread = false;
    let mut items: Vec<DestructuringItem> = Vec::new();

    p.with_nl_mode(Newline::Continue, |p| {
        p.assert(Kind::LeftParen);
        while !is_terminator(p.current()) {
            if !p.at_set(DESTRUCTURING_ITEM) {
                p.unexpected();
                continue;
            }
            destructuring_item(p, reassignment, seen, &mut maybe_just_parens, &mut at_pattern_or_spread, &mut items);
            if !is_terminator(p.current()) && p.expect(Kind::Comma) {
                maybe_just_parens = false;
            }
        }
        let open = Span::new(start, start + 1);
        p.expect_closing_delimiter(open, Kind::RightParen);
    });

    let span = Span::new(start, p.prev_end());
    if at_pattern_or_spread && maybe_just_parens && items.len() == 1 {
        match items.pop().unwrap() {
            DestructuringItem::Pattern(pat) => Pattern::Parenthesized(Box::new(pat), span),
            other => Pattern::Destructuring(Destructuring { items: vec![other], span }),
        }
    } else {
        Pattern::Destructuring(Destructuring { items, span })
    }
}

const DESTRUCTURING_ITEM: &[Kind] = PARAM;

fn destructuring_item(
    p: &mut Parser,
    reassignment: bool,
    seen: &mut HashSet<String>,
    maybe_just_parens: &mut bool,
    at_pattern_or_spread: &mut bool,
    items: &mut Vec<DestructuringItem>,
) {
    let start = p.current_start();
    if p.eat_if(Kind::Dots) {
        let mut name = None;
        if p.at_set(PATTERN_LEAF) {
            if let Some(Pattern::Normal(e)) = pattern_leaf(p, reassignment, seen, None) {
                if let ExprKind::Ident(n) = e.kind {
                    name = Some(Ident { name: n, span: e.span });
                }
            }
        }
        *at_pattern_or_spread = true;
        *maybe_just_parens = false;
        items.push(DestructuringItem::Spread(name, Span::new(start, p.prev_end())));
        return;
    }

    let at_pattern = p.at_set(PATTERN);
    let pat = pattern(p, reassignment, seen, None);
    if p.eat_if(Kind::Colon) {
        *maybe_just_parens = false;
        let value = pattern(p, reassignment, seen, None);
        match (pat, value) {
            (Some(Pattern::Normal(Expr { kind: ExprKind::Ident(name), span })), Some(value)) => {
                items.push(DestructuringItem::Named(Ident { name, span }, value));
            }
            (Some(other), _) => {
                if at_pattern {
                    p.error_at(other.span(), "expected pattern");
                }
            }
            _ => {}
        }
    } else {
        *at_pattern_or_spread |= at_pattern;
        if let Some(pat) = pat {
            items.push(DestructuringItem::Pattern(pat));
        }
    }
}

fn pattern_leaf(
    p: &mut Parser,
    reassignment: bool,
    seen: &mut HashSet<String>,
    dupe: Option<&str>,
) -> Option<Pattern> {
    if p.current().is_keyword() {
        let (span, text) = p.eat();
        p.error_at(span, format!("expected pattern, found keyword `{text}`"));
        return None;
    } else if !p.at_set(PATTERN_LEAF) {
        p.expected("pattern");
        return None;
    }

    let text = p.current_text().to_string();
    let expr = code_expr_prec(p, true, 0)?;
    if !reassignment {
        if let ExprKind::Ident(_) = &expr.kind {
            if !seen.insert(text.clone()) {
                p.error_at(expr.span, format!("duplicate {}: {text}", dupe.unwrap_or("binding")));
            }
        } else {
            p.error_at(expr.span, format!("expected pattern, found {}", expr_kind_name(&expr)));
            return None;
        }
    }
    Some(Pattern::Normal(expr))
}

fn let_binding(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::Let);
    let mut closure: Option<(Ident, Vec<Param>)> = None;
    let mut other = false;
    let mut pat: Option<Pattern> = None;

    match p.current() {
        Kind::Ident => {
            let (span, text) = p.eat();
            let ident = Ident { name: text.to_string(), span };
            if p.directly_at(Kind::LeftParen) {
                let params = params(p);
                closure = Some((ident, params));
            } else {
                pat = Some(Pattern::Normal(Expr::new(ExprKind::Ident(text.to_string()), span)));
            }
        }
        _ => {
            let mut seen = HashSet::new();
            pat = pattern(p, false, &mut seen, None);
            other = true;
        }
    }

    let has_eq = if closure.is_some() || other {
        p.expect(Kind::Eq)
    } else {
        p.eat_if(Kind::Eq)
    };

    let init = if has_eq { code_expr(p) } else { None };
    let end = p.prev_end();
    let span = Span::new(start, end);

    if let Some((name, params)) = closure {
        let body = init.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(end, end)));
        let closure_expr = Expr::new(
            ExprKind::Closure(Rc::new(Closure { name: Some(name.clone()), params, body })),
            Span::new(name.span.start as usize, end),
        );
        return Some(Expr::new(
            ExprKind::Let {
                pattern: Pattern::Normal(Expr::new(ExprKind::Ident(name.name), name.span)),
                init: Some(Box::new(closure_expr)),
            },
            span,
        ));
    }

    let pattern = pat?;
    Some(Expr::new(ExprKind::Let { pattern, init: init.map(Box::new) }, span))
}

fn set_rule(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::Set);
    let tstart = p.current_start();
    if !p.at(Kind::Ident) {
        p.expect(Kind::Ident);
        return None;
    }
    let (span, text) = p.eat();
    let mut target = Expr::new(ExprKind::Ident(text.to_string()), span);
    while p.eat_if(Kind::Dot) {
        if p.at(Kind::Ident) {
            let (fspan, ftext) = p.eat();
            target = Expr::new(
                ExprKind::FieldAccess {
                    target: Box::new(target),
                    field: Ident { name: ftext.to_string(), span: fspan },
                },
                Span::new(tstart, fspan.end as usize),
            );
        } else {
            p.expect(Kind::Ident);
        }
    }
    if !p.directly_at(Kind::LeftParen) && !p.directly_at(Kind::LeftBracket) {
        p.expected("argument list");
        if p.at(Kind::LeftParen) || p.at(Kind::LeftBracket) {
            p.hint("there may not be any spaces before the argument list");
        }
    }
    let args = args(p);
    let condition = if p.eat_if(Kind::If) { code_expr(p).map(Box::new) } else { None };
    let end = p.prev_end();
    Some(Expr::new(ExprKind::Set { target: Box::new(target), args, condition }, Span::new(start, end)))
}

fn show_rule(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::Show);
    let before = p.prev_end();
    let selector = if !p.at(Kind::Colon) { code_expr(p) } else { None };
    let transform = if p.eat_if(Kind::Colon) {
        code_expr(p)
    } else {
        p.expected_at(before.max(p.prev_end()), "colon");
        None
    };
    let end = p.prev_end();
    let transform = transform.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(end, end)));
    Some(Expr::new(
        ExprKind::Show { selector: selector.map(Box::new), transform: Box::new(transform) },
        Span::new(start, end),
    ))
}

fn contextual(p: &mut Parser, atomic: bool) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::Context);
    let body = code_expr_prec(p, atomic, 0)?;
    let span = Span::new(start, body.span.end as usize);
    Some(Expr::new(ExprKind::Contextual(Box::new(body)), span))
}

fn block(p: &mut Parser) -> Option<Expr> {
    match p.current() {
        Kind::LeftBracket => Some(content_block(p)),
        Kind::LeftBrace => Some(code_block(p)),
        _ => {
            p.expected("block");
            None
        }
    }
}

fn conditional(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::If);
    let cond = code_expr(p);
    let if_body = block(p);
    let mut else_body = None;
    if p.eat_if(Kind::Else) {
        if p.at(Kind::If) {
            else_body = conditional(p);
        } else {
            else_body = block(p);
        }
    }
    let end = p.prev_end();
    let cond = cond?;
    let if_body = if_body?;
    Some(Expr::new(
        ExprKind::Conditional {
            cond: Box::new(cond),
            if_body: Box::new(if_body),
            else_body: else_body.map(Box::new),
        },
        Span::new(start, end),
    ))
}

fn while_loop(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::While);
    let cond = code_expr(p);
    let body = block(p);
    let end = p.prev_end();
    Some(Expr::new(
        ExprKind::While { cond: Box::new(cond?), body: Box::new(body?) },
        Span::new(start, end),
    ))
}

fn for_loop(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::For);
    let mut seen = HashSet::new();
    let pat = pattern(p, false, &mut seen, None);
    let iterable = if p.eat_if(Kind::In) {
        code_expr(p)
    } else {
        p.expected("keyword `in`");
        None
    };
    let body = block(p);
    let end = p.prev_end();
    Some(Expr::new(
        ExprKind::For { pattern: pat?, iterable: Box::new(iterable?), body: Box::new(body?) },
        Span::new(start, end),
    ))
}

fn module_import(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::Import);
    let source = code_expr(p);
    let mut new_name = None;
    if p.eat_if(Kind::As) {
        if p.at(Kind::Ident) {
            let (span, text) = p.eat();
            new_name = Some(Ident { name: text.to_string(), span });
        } else {
            p.expect(Kind::Ident);
        }
    }
    let mut imports = None;
    if p.eat_if(Kind::Colon) {
        if p.at(Kind::Star) {
            p.eat();
            imports = Some(Imports::Wildcard);
        } else {
            imports = Some(Imports::Items(import_items(p)));
        }
    }
    let end = p.prev_end();
    Some(Expr::new(
        ExprKind::Import { source: Box::new(source?), new_name, imports },
        Span::new(start, end),
    ))
}

fn import_items(p: &mut Parser) -> Vec<ImportItem> {
    let mut out = Vec::new();
    while !is_terminator(p.current()) {
        let mut path = Vec::new();
        if p.at(Kind::Ident) {
            let (span, text) = p.eat();
            path.push(Ident { name: text.to_string(), span });
        } else {
            p.unexpected();
        }
        while p.eat_if(Kind::Dot) {
            if p.at(Kind::Ident) {
                let (span, text) = p.eat();
                path.push(Ident { name: text.to_string(), span });
            } else {
                p.expect(Kind::Ident);
            }
        }
        let mut rename = None;
        if p.eat_if(Kind::As) {
            if p.at(Kind::Ident) {
                let (span, text) = p.eat();
                rename = Some(Ident { name: text.to_string(), span });
            } else {
                p.expect(Kind::Ident);
            }
        }
        if !path.is_empty() {
            out.push(ImportItem { path, rename });
        }
        if !is_terminator(p.current()) {
            p.expect(Kind::Comma);
        }
    }
    out
}

fn module_include(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::Include);
    let source = code_expr(p)?;
    let span = Span::new(start, source.span.end as usize);
    Some(Expr::new(ExprKind::Include(Box::new(source)), span))
}

fn return_stmt(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::Return);
    let mut body = None;
    if p.at_set(CODE_EXPR) {
        body = code_expr(p);
    }
    let end = p.prev_end();
    Some(Expr::new(ExprKind::Return(body.map(Box::new)), Span::new(start, end)))
}
