];

const PATTERN: &[Kind] = &[
    Kind::Ident,
    Kind::LeftBrace,
    Kind::LeftBracket,
    Kind::LeftParen,
    Kind::Dollar,
    Kind::None,
    Kind::Auto,
    Kind::Bool,
    Kind::Int,
    Kind::Float,
    Kind::Numeric,
    Kind::Str,
    Kind::Label,
    Kind::Raw,
    Kind::Underscore,
];

fn is_terminator(kind: Kind) -> bool {
    matches!(
        kind,
        Kind::End | Kind::Semicolon | Kind::RightBrace | Kind::RightParen | Kind::RightBracket
    )
}

fn code_exprs(p: &mut Parser, stop: &[Kind]) -> Vec<Expr> {
    let mut out = Vec::new();
    while !p.at_set(stop) {
        p.with_nl_mode(Newline::Contextual, |p| {
            if !p.at_set(CODE_EXPR) {
                p.unexpected();
                return;
            }
            if let Some(e) = code_expr(p) {
                out.push(e);
            }
            if !p.at_set(stop) && !p.eat_if(Kind::Semicolon) {
                p.expected("semicolon or line break");
                if p.at(Kind::Else) {
                    p.hint("see https://github.com/typst/typst/issues/3209");
                }
            }
        });
    }
    out
}

fn code_expr(p: &mut Parser) -> Option<Expr> {
    code_expr_prec(p, false, 0)
}

fn unop_from_kind(kind: Kind) -> Option<UnOp> {
    match kind {
        Kind::Plus => Some(UnOp::Pos),
        Kind::Minus => Some(UnOp::Neg),
        Kind::Not => Some(UnOp::Not),
        _ => None,
    }
}

fn binop_from_kind(kind: Kind) -> Option<BinOp> {
    match kind {
        Kind::Plus => Some(BinOp::Add),
        Kind::Minus => Some(BinOp::Sub),
        Kind::Star => Some(BinOp::Mul),
        Kind::Slash => Some(BinOp::Div),
        Kind::And => Some(BinOp::And),
        Kind::Or => Some(BinOp::Or),
        Kind::EqEq => Some(BinOp::Eq),
        Kind::ExclEq => Some(BinOp::Neq),
        Kind::Lt => Some(BinOp::Lt),
        Kind::LtEq => Some(BinOp::Leq),
        Kind::Gt => Some(BinOp::Gt),
        Kind::GtEq => Some(BinOp::Geq),
        Kind::Eq => Some(BinOp::Assign),
        Kind::In => Some(BinOp::In),
        Kind::PlusEq => Some(BinOp::AddAssign),
        Kind::HyphEq => Some(BinOp::SubAssign),
        Kind::StarEq => Some(BinOp::MulAssign),
        Kind::SlashEq => Some(BinOp::DivAssign),
        _ => None,
    }
}

fn code_expr_prec(p: &mut Parser, atomic: bool, min_prec: usize) -> Option<Expr> {
    let start = p.current_start();
    let mut expr = if !atomic && unop_from_kind(p.current()).is_some() {
        let op = unop_from_kind(p.current()).unwrap();
        p.eat();
        let inner = code_expr_prec(p, atomic, op.precedence());
        let inner = inner?;
        let span = Span::new(start, inner.span.end as usize);
        Expr::new(ExprKind::Unary { op, expr: Box::new(inner) }, span)
    } else {
        code_primary(p, atomic)?
    };

    loop {
        if p.directly_at(Kind::LeftParen) || p.directly_at(Kind::LeftBracket) {
            let args = args(p);
            let span = Span::new(start, args.span.end as usize);
            expr = Expr::new(ExprKind::FuncCall { callee: Box::new(expr), args }, span);
            continue;
        }

        let at_field_or_method = p.directly_at(Kind::Dot) && {
            // Lookahead for identifier after the dot.
            let mut lx = Lexer::new(p.text, LexMode::Code);
            lx.jump(p.current_end());
            let k = lx.next();
            k == Kind::Ident || (k.is_keyword())
        };

        if atomic && !at_field_or_method {
            break;
        }

        if p.eat_if(Kind::Dot) {
            if p.at(Kind::Ident) {
                let (fspan, ftext) = p.eat();
                let span = Span::new(start, fspan.end as usize);
                expr = Expr::new(
                    ExprKind::FieldAccess {
                        target: Box::new(expr),
                        field: Ident { name: ftext.to_string(), span: fspan },
                    },
                    span,
                );
            } else if p.current().is_keyword() {
                // Keywords after dot are treated as identifiers by the lexer,
                // but handle just in case.
                let (fspan, ftext) = p.eat();
                let span = Span::new(start, fspan.end as usize);
                expr = Expr::new(
                    ExprKind::FieldAccess {
                        target: Box::new(expr),
                        field: Ident { name: ftext.to_string(), span: fspan },
                    },
                    span,
                );
            } else {
                p.expected("identifier");
            }
            continue;
        }

        let binop = if let Some(op) = binop_from_kind(p.current()) {
            Some(op)
        } else if min_prec <= BinOp::NotIn.precedence() && p.at(Kind::Not) {
            // Peek for `in`.
            let cp = p.checkpoint();
            p.eat();
            if p.at(Kind::In) {
                Some(BinOp::NotIn)
            } else {
                p.restore(cp);
                p.eat();
                p.expected("keyword `in`");
                break;
            }
        } else {
            None
        };

        let Some(op) = binop else { break };
        let mut prec = op.precedence();
        if prec < min_prec {
            break;
        }
        match op.assoc() {
            Assoc::Left => prec += 1,
            Assoc::Right => {}
        }
        p.eat();
        let rhs = code_expr_prec(p, false, prec);
        let rhs = match rhs {
            Some(r) => r,
            None => {
                let at = p.prev_end();
                Expr::new(ExprKind::None, Span::new(at, at))
            }
        };
        let span = Span::new(start, rhs.span.end as usize);
        expr = Expr::new(ExprKind::Binary { op, lhs: Box::new(expr), rhs: Box::new(rhs) }, span);
    }

    Some(expr)
}

pub fn parse_str(text: &str) -> String {
    let inner = &text[1..text.len().saturating_sub(1).max(1)];
    let inner = if text.len() >= 2 && text.ends_with('"') && text.len() > 1 { &text[1..text.len() - 1] } else { inner };
    let mut out = String::new();
    let mut s = super::scanner::Scanner::new(inner);
    while let Some(c) = s.eat() {
        if c != '\\' {
            out.push(c);
            continue;
        }
        let start = s.cursor() - 1;
        match s.eat() {
            Some('\\') => out.push('\\'),
            Some('"') => out.push('"'),
            Some('n') => out.push('\n'),
            Some('r') => out.push('\r'),
            Some('t') => out.push('\t'),
            Some('u') if s.eat_if('{') => {
                let hex = s.eat_while(char::is_ascii_alphanumeric);
                let closed = s.eat_if('}');
                match u32::from_str_radix(hex, 16).ok().and_then(char::from_u32) {
                    Some(ch) if closed => out.push(ch),
                    _ => out.push_str(s.get(start..s.cursor())),
                }
            }
            _ => out.push_str(s.get(start..s.cursor())),
        }
    }
    out
}

fn code_primary(p: &mut Parser, atomic: bool) -> Option<Expr> {
    let start = p.current_start();
    match p.current() {
        Kind::Ident => {
            let (span, text) = p.eat();
            let ident = Expr::new(ExprKind::Ident(text.to_string()), span);
            if !atomic && p.at(Kind::Arrow) {
                p.assert(Kind::Arrow);
                let body = code_expr(p);
                let body = body.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
                let total = Span::new(start, body.span.end as usize);
                let params = vec![Param::Pos(Pattern::Normal(ident))];
                return Some(Expr::new(
                    ExprKind::Closure(Rc::new(Closure { name: None, params, body })),
                    total,
                ));
            }
            Some(ident)
        }
        Kind::Underscore if !atomic => {
            let (span, _) = p.eat();
            if p.at(Kind::Arrow) {
                p.eat();
                let body = code_expr(p);
                let body = body.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
                let total = Span::new(start, body.span.end as usize);
                Some(Expr::new(
                    ExprKind::Closure(Rc::new(Closure {
                        name: None,
                        params: vec![Param::Pos(Pattern::Placeholder(span))],
                        body,
                    })),
                    total,
                ))
            } else if p.eat_if(Kind::Eq) {
                let value = code_expr(p);
                let value = value.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
                let total = Span::new(start, value.span.end as usize);
                Some(Expr::new(
                    ExprKind::DestructAssign { pattern: Pattern::Placeholder(span), value: Box::new(value) },
                    total,
                ))
            } else {
                p.error_at(span, "expected expression, found underscore");
                None
            }
        }
        Kind::LeftBrace => Some(code_block(p)),
        Kind::LeftBracket => Some(content_block(p)),
        Kind::LeftParen => expr_with_paren(p, atomic),
        Kind::Dollar => Some(equation(p)),
        Kind::Let => let_binding(p),
        Kind::Set => set_rule(p),
        Kind::Show => show_rule(p),
        Kind::Context => contextual(p, atomic),
        Kind::If => conditional(p),
        Kind::While => while_loop(p),
        Kind::For => for_loop(p),
        Kind::Import => module_import(p),
        Kind::Include => module_include(p),
        Kind::Break => {
            let (span, _) = p.eat();
            Some(Expr::new(ExprKind::Break, span))
        }
        Kind::Continue => {
            let (span, _) = p.eat();
            Some(Expr::new(ExprKind::Continue, span))
        }
        Kind::Return => return_stmt(p),
        Kind::Raw => {
            let (span, _, data) = p.eat_data();
            let raw = data.raw.unwrap_or_default_raw();
            Some(Expr::new(ExprKind::Raw { text: raw.text, lang: raw.lang, block: raw.block }, span))
        }
        Kind::None => {
            let (span, _) = p.eat();
            Some(Expr::new(ExprKind::None, span))
        }
        Kind::Auto => {
            let (span, _) = p.eat();
            Some(Expr::new(ExprKind::Auto, span))
        }
        Kind::Bool => {
            let (span, text) = p.eat();
            Some(Expr::new(ExprKind::Bool(text == "true"), span))
        }
        Kind::Int => {
            let (span, text) = p.eat();
            Some(Expr::new(ExprKind::Int(parse_int(text)), span))
        }
        Kind::Float => {
            let (span, text) = p.eat();
            Some(Expr::new(ExprKind::Float(text.parse().unwrap_or(0.0)), span))
        }
        Kind::Numeric => {
            let (span, text) = p.eat();
            let (v, unit) = parse_numeric(text);
            Some(Expr::new(ExprKind::Numeric(v, unit), span))
        }
        Kind::Str => {
            let (span, text) = p.eat();
            Some(Expr::new(ExprKind::Str(parse_str(text)), span))
        }
        Kind::Label => {
            let (span, text) = p.eat();
            Some(Expr::new(ExprKind::Label(text[1..text.len() - 1].to_string()), span))
        }
        Kind::Error => {
            p.eat_error();
            None
        }
        _ => {
            p.expected("expression");
            None
        }
    }
}

pub fn parse_int(text: &str) -> i64 {
    if let Some(h) = text.strip_prefix("0x") {
        i64::from_str_radix(h, 16).unwrap_or(0)
    } else if let Some(b) = text.strip_prefix("0b") {
        i64::from_str_radix(b, 2).unwrap_or(0)
    } else if let Some(o) = text.strip_prefix("0o") {
        i64::from_str_radix(o, 8).unwrap_or(0)
    } else {
        text.parse().unwrap_or(0)
    }
}

pub fn parse_numeric(text: &str) -> (f64, Unit) {
    let count = text.trim_end_matches(|c: char| c.is_ascii_alphabetic() || c == '%');
    let suffix = &text[count.len()..];
    let value: f64 = count.parse().unwrap_or(0.0);
    let unit = match suffix {
        "pt" => Unit::Pt,
        "mm" => Unit::Mm,
        "cm" => Unit::Cm,
        "in" => Unit::In,
        "em" => Unit::Em,
        "deg" => Unit::Deg,
        "rad" => Unit::Rad,
        "%" => Unit::Percent,
        "fr" => Unit::Fr,
        _ => Unit::Pt,
    };
    (value, unit)
}

fn code_block(p: &mut Parser) -> Expr {
    let start = p.current_start();
    let exprs = p.enter_modes(LexMode::Code, Newline::Continue, |p| {
        p.assert(Kind::LeftBrace);
        code_exprs(p, &[Kind::RightBrace, Kind::RightBracket, Kind::RightParen, Kind::End])
    });
    let open = Span::new(start, start + 1);
    p.expect_closing_delimiter(open, Kind::RightBrace);
    let end = p.prev_end();
    Expr::new(ExprKind::CodeBlock(exprs), Span::new(start, end))
}

fn content_block(p: &mut Parser) -> Expr {
    let start = p.current_start();
    let body = p.enter_modes(LexMode::Markup, Newline::Continue, |p| {
        p.assert(Kind::LeftBracket);
        markup(p, true, true, &[Kind::RightBracket, Kind::End])
    });
    let open = Span::new(start, start + 1);
    p.expect_closing_delimiter(open, Kind::RightBracket);
    let end = p.prev_end();
    Expr::new(ExprKind::ContentBlock(body), Span::new(start, end))
}

fn expr_with_paren(p: &mut Parser, atomic: bool) -> Option<Expr> {
    if atomic {
        return Some(parenthesized_or_array_or_dict(p).0);
    }
    let cp = p.checkpoint();
    let (expr, kind) = parenthesized_or_array_or_dict(p);
    if p.at(Kind::Arrow) {
        p.restore(cp);
        let start = p.current_start();
        let params = params(p);
        if !p.expect(Kind::Arrow) {
            return None;
        }
        let body = code_expr(p);
        let body = body.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
        let total = Span::new(start, body.span.end as usize);
        return Some(Expr::new(
            ExprKind::Closure(Rc::new(Closure { name: None, params, body })),
            total,
        ));
    } else if p.at(Kind::Eq) && kind != GroupKind::Parenthesized {
        p.restore(cp);
        let start = p.current_start();
        let mut seen = HashSet::new();
        let pattern = destructuring_or_parenthesized(p, true, &mut seen);
        if !p.expect(Kind::Eq) {
            return None;
        }
        let value = code_expr(p);
        let value = value.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
        let total = Span::new(start, value.span.end as usize);
        return Some(Expr::new(ExprKind::DestructAssign { pattern, value: Box::new(value) }, total));
    }
    Some(expr)
}

fn parenthesized_or_array_or_dict(p: &mut Parser) -> (Expr, GroupKind) {
    let start = p.current_start();
    let mut count = 0;
    let mut maybe_just_parens = true;
    let mut kind: Option<GroupKind> = None;
    let mut seen: HashSet<String> = HashSet::new();
    let mut items: Vec<GroupItem> = Vec::new();

    p.with_nl_mode(Newline::Continue, |p| {
        p.assert(Kind::LeftParen);
        if p.eat_if(Kind::Colon) {
            kind = Some(GroupKind::Dict);
            maybe_just_parens = false;
        }
        while !is_terminator(p.current()) {
            if !p.at_set(ARRAY_OR_DICT_ITEM) {
                p.unexpected();
                continue;
            }
            array_or_dict_item(p, &mut kind, &mut maybe_just_parens, &mut seen, &mut items);
            count += 1;
            if !is_terminator(p.current()) && p.expect(Kind::Comma) {
                maybe_just_parens = false;
            }
        }
        let open = Span::new(start, start + 1);
        p.expect_closing_delimiter(open, Kind::RightParen);
    });

    let end = p.prev_end();
    let span = Span::new(start, end);
    let kind = if maybe_just_parens && count == 1 {
        GroupKind::Parenthesized
    } else {
        kind.unwrap_or(GroupKind::Array)
    };

    let expr = match kind {
        GroupKind::Parenthesized => {
            let inner = items.into_iter().next();
            match inner {
                Some(GroupItem::Pos(e)) => Expr::new(ExprKind::Parenthesized(Box::new(e)), span),
                Some(GroupItem::Placeholder(s)) => {
                    p.error_at(s, "expected expression, found underscore");
                    Expr::new(ExprKind::None, span)
                }
                _ => Expr::new(ExprKind::None, span),
            }
        }
        GroupKind::Array => {
            let mut out = Vec::new();
            for item in items {
                match item {
                    GroupItem::Pos(e) => out.push(ArrayItem::Pos(e)),
                    GroupItem::Spread(e) => out.push(ArrayItem::Spread(e)),
                    GroupItem::Placeholder(s) => p.error_at(s, "expected expression, found underscore"),
                    GroupItem::Named(..) | GroupItem::Keyed(..) => {}
                }
            }
            Expr::new(ExprKind::Array(out), span)
        }
        GroupKind::Dict => {
            let mut out = Vec::new();
            for item in items {
                match item {
                    GroupItem::Named(n, e) => out.push(DictItem::Named(n, e)),
                    GroupItem::Keyed(k, e) => out.push(DictItem::Keyed(k, e)),
                    GroupItem::Spread(e) => out.push(DictItem::Spread(e)),
                    GroupItem::Placeholder(s) => p.error_at(s, "expected expression, found underscore"),
                    GroupItem::Pos(_) => {}
                }
            }
            Expr::new(ExprKind::Dict(out), span)
        }
    };
    (expr, kind)
}

const ARRAY_OR_DICT_ITEM: &[Kind] = &[
    Kind::Ident,
    Kind::LeftBrace,
    Kind::LeftBracket,
    Kind::LeftParen,
    Kind::Dollar,
    Kind::Let,
    Kind::Set,
    Kind::Show,
    Kind::Context,
    Kind::If,
    Kind::While,
    Kind::For,
    Kind::Import,
    Kind::Include,
    Kind::Break,
    Kind::Continue,
    Kind::Return,
    Kind::None,
    Kind::Auto,
    Kind::Bool,
    Kind::Int,
    Kind::Float,
    Kind::Numeric,
    Kind::Str,
    Kind::Label,
    Kind::Raw,
    Kind::Plus,
    Kind::Minus,
    Kind::Not,
    Kind::Underscore,
    Kind::Dots,
];

fn expr_kind_name(e: &Expr) -> &'static str {
    match &e.kind {
        ExprKind::Ident(_) => "identifier",
        ExprKind::None => "`none`",
        ExprKind::Auto => "`auto`",
        ExprKind::Bool(_) => "boolean",
        ExprKind::Int(_) => "integer",
        ExprKind::Float(_) => "float",
        ExprKind::Numeric(..) => "numeric value",
        ExprKind::Str(_) => "string",
        ExprKind::CodeBlock(_) => "code block",
        ExprKind::ContentBlock(_) => "content block",
        ExprKind::Parenthesized(_) => "group",
        ExprKind::Array(_) => "array",
        ExprKind::Dict(_) => "dictionary",
        ExprKind::Unary { .. } => "unary expression",
        ExprKind::Binary { .. } => "binary expression",
        ExprKind::FieldAccess { .. } => "field access",
        ExprKind::FuncCall { .. } => "function call",
        ExprKind::Closure(_) => "closure",
        ExprKind::Let { .. } => "`let` expression",
        ExprKind::DestructAssign { .. } => "destructuring assignment expression",
        ExprKind::Set { .. } => "`set` expression",
        ExprKind::Show { .. } => "`show` expression",
        ExprKind::Contextual(_) => "`context` expression",
        ExprKind::Conditional { .. } => "`if` expression",
        ExprKind::While { .. } => "while-loop expression",
        ExprKind::For { .. } => "for-loop expression",
        ExprKind::Import { .. } => "`import` expression",
        ExprKind::Include(_) => "`include` expression",
        ExprKind::Break => "`break` expression",
        ExprKind::Continue => "`continue` expression",
        ExprKind::Return(_) => "`return` expression",
        ExprKind::Equation { .. } => "equation",
        ExprKind::Raw { .. } => "raw block",
        ExprKind::Label(_) => "label",
        _ => "expression",
    }
}

fn array_or_dict_item(
    p: &mut Parser,
    kind: &mut Option<GroupKind>,
    maybe_just_parens: &mut bool,
    seen: &mut HashSet<String>,
    items: &mut Vec<GroupItem>,
) {
    let start = p.current_start();
    if p.eat_if(Kind::Dots) {
        let e = code_expr(p);
        if let Some(e) = e {
            items.push(GroupItem::Spread(e));
        }
        *maybe_just_parens = false;
        return;
    }

    if p.at(Kind::Underscore) {
        let (span, _) = p.eat();
        items.push(GroupItem::Placeholder(span));
        if *kind == Some(GroupKind::Dict) {
            // will error later
        } else {
            *kind = Some(GroupKind::Array);
        }
        return;
    }

    let Some(e) = code_expr(p) else { return };
    let _ = start;
    if p.eat_if(Kind::Colon) {
        let value = code_expr(p);
        let value = value.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
        let pair_name = match &e.kind {
            ExprKind::Ident(_) => "named pair",
            _ => "keyed pair",
        };
        match &e.kind {
            ExprKind::Ident(name) => {
                if !seen.insert(name.clone()) {
                    p.error_at(e.span, format!("duplicate key: {name}"));
                }
            }
            ExprKind::Str(s) => {
                if !seen.insert(s.clone()) {
                    p.error_at(e.span, format!("duplicate key: {s}"));
                }
            }
            _ => {}
        }
        *maybe_just_parens = false;
        if *kind == Some(GroupKind::Array) {
            p.error_at(Span::new(e.span.start as usize, value.span.end as usize), format!("expected expression, found {pair_name}"));
        } else {
            *kind = Some(GroupKind::Dict);
        }
        match e.kind {
            ExprKind::Ident(name) => items.push(GroupItem::Named(Ident { name, span: e.span }, value)),
            _ => items.push(GroupItem::Keyed(e, value)),
        }
    } else {
        if *kind == Some(GroupKind::Dict) {
            p.error_at(e.span, format!("expected named or keyed pair, found {}", expr_kind_name(&e)));
        } else {
            *kind = Some(GroupKind::Array);
        }
        items.push(GroupItem::Pos(e));
    }
}

fn args(p: &mut Parser) -> Args {
    let start = p.current_start();
    let mut items = Vec::new();
    let mut trailing_comma = false;
    if p.at(Kind::LeftParen) {
        p.with_nl_mode(Newline::Continue, |p| {
            p.assert(Kind::LeftParen);
            let mut seen: HashSet<String> = HashSet::new();
            while !is_terminator(p.current()) {
                if !p.at_set(ARG) {
                    p.unexpected();
                    continue;
                }
                arg(p, &mut seen, &mut items);
                trailing_comma = false;
                if !is_terminator(p.current()) {
                    if p.expect(Kind::Comma) {
                        trailing_comma = true;
                    }
                }
            }
            let open = Span::new(start, start + 1);
            p.expect_closing_delimiter(open, Kind::RightParen);
        });
    }
    while p.directly_at(Kind::LeftBracket) {
        let block = content_block(p);
        items.push(Arg::Pos(block));
    }
    let end = p.prev_end();
    Args { items, span: Span::new(start, end), trailing_comma }
}

const ARG: &[Kind] = ARRAY_OR_DICT_ITEM;

fn arg(p: &mut Parser, seen: &mut HashSet<String>, items: &mut Vec<Arg>) {
    if p.eat_if(Kind::Dots) {
        if let Some(e) = code_expr(p) {
            items.push(Arg::Spread(e));
        }
        return;
    }
    if p.at(Kind::Underscore) {
        let (span, _) = p.eat();
        p.error_at(span, "expected expression, found underscore");
        return;
    }
    let was_at_expr = p.at_set(CODE_EXPR);
    let text = p.current_text().to_string();
    let Some(e) = code_expr(p) else { return };
    if p.eat_if(Kind::Colon) {
        let value = code_expr(p);
        let value = value.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
        if was_at_expr && !matches!(e.kind, ExprKind::Ident(_)) {
            p.error_at(e.span, format!("expected identifier, found {}", expr_kind_name(&e)));
            items.push(Arg::Pos(value));
            return;
        }
        if !seen.insert(text.clone()) {
            p.error_at(e.span, format!("duplicate argument: {text}"));
        }
        if let ExprKind::Ident(name) = e.kind {
            items.push(Arg::Named(Ident { name, span: e.span }, value));
        }
    } else {
        items.push(Arg::Pos(e));
    }
}

fn params(p: &mut Parser) -> Vec<Param> {
    let start = p.current_start();
    let mut seen: HashSet<String> = HashSet::new();
    let mut sink = false;
    let mut out = Vec::new();
    p.with_nl_mode(Newline::Continue, |p| {
        p.assert(Kind::LeftParen);
        while !is_terminator(p.current()) {
            if !p.at_set(PARAM) {
                p.unexpected();
                continue;
            }
            param(p, &mut seen, &mut sink, &mut out);
            if !is_terminator(p.current()) {
                p.expect(Kind::Comma);
            }
        }
        let open = Span::new(start, start + 1);
        p.expect_closing_delimiter(open, Kind::RightParen);
    });
    out
}

const PARAM: &[Kind] = &[
    Kind::Ident,
    Kind::LeftBrace,
    Kind::LeftBracket,
    Kind::LeftParen,
    Kind::Dollar,
    Kind::None,
    Kind::Auto,
    Kind::Bool,
    Kind::Int,
    Kind::Float,
    Kind::Numeric,
    Kind::Str,
    Kind::Label,
    Kind::Raw,
    Kind::Underscore,
    Kind::Dots,
];

fn param(p: &mut Parser, seen: &mut HashSet<String>, sink: &mut bool, out: &mut Vec<Param>) {
    let start = p.current_start();
    if p.eat_if(Kind::Dots) {
        let mut name = None;
        if p.at_set(PATTERN_LEAF) {
            if let Some(Pattern::Normal(e)) = pattern_leaf(p, false, seen, Some("parameter")) {
                if let ExprKind::Ident(n) = e.kind {
                    name = Some(Ident { name: n, span: e.span });
                }
            }
        }
        let span = Span::new(start, p.prev_end());
        if std::mem::replace(sink, true) {
            p.error_at(span, "only one argument sink is allowed");
        }
        out.push(Param::Spread(name, span));
        return;
    }

    let was_at_pat = p.at_set(PATTERN);
    let pat = pattern(p, false, seen, Some("parameter"));
    if p.eat_if(Kind::Colon) {
        let default = code_expr(p);
        let default = default.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(p.prev_end(), p.prev_end())));
        match pat {
            Some(Pattern::Normal(Expr { kind: ExprKind::Ident(name), span })) => {
                out.push(Param::Named(Ident { name, span }, default));
            }
            Some(other) => {
                if was_at_pat {
                    p.error_at(other.span(), "expected identifier");
                }
            }
            None => {}
        }
    } else if let Some(pat) = pat {
        out.push(Param::Pos(pat));
    }
}

fn pattern(
    p: &mut Parser,
    reassignment: bool,
    seen: &mut HashSet<String>,
    dupe: Option<&str>,
) -> Option<Pattern> {
    match p.current() {
        Kind::Underscore => {
            let (span, _) = p.eat();
            Some(Pattern::Placeholder(span))
        }
        Kind::LeftParen => Some(destructuring_or_parenthesized(p, reassignment, seen)),
        _ => pattern_leaf(p, reassignment, seen, dupe),
    }
}

fn destructuring_or_parenthesized(
    p: &mut Parser,
    reassignment: bool,
    seen: &mut HashSet<String>,
) -> Pattern {
    let start = p.current_start();
    let mut maybe_just_parens = true;
    let mut at_pattern_or_spread = false;
    let mut items: Vec<DestructuringItem> = Vec::new();

    p.with_nl_mode(Newline::Continue, |p| {
        p.assert(Kind::LeftParen);
        while !is_terminator(p.current()) {
            if !p.at_set(DESTRUCTURING_ITEM) {
                p.unexpected();
                continue;
            }
            destructuring_item(p, reassignment, seen, &mut maybe_just_parens, &mut at_pattern_or_spread, &mut items);
            if !is_terminator(p.current()) && p.expect(Kind::Comma) {
                maybe_just_parens = false;
            }
        }
        let open = Span::new(start, start + 1);
        p.expect_closing_delimiter(open, Kind::RightParen);
    });

    let span = Span::new(start, p.prev_end());
    if at_pattern_or_spread && maybe_just_parens && items.len() == 1 {
        match items.pop().unwrap() {
            DestructuringItem::Pattern(pat) => Pattern::Parenthesized(Box::new(pat), span),
            other => Pattern::Destructuring(Destructuring { items: vec![other], span }),
        }
    } else {
        Pattern::Destructuring(Destructuring { items, span })
    }
}

const DESTRUCTURING_ITEM: &[Kind] = PARAM;

fn destructuring_item(
    p: &mut Parser,
    reassignment: bool,
    seen: &mut HashSet<String>,
    maybe_just_parens: &mut bool,
    at_pattern_or_spread: &mut bool,
    items: &mut Vec<DestructuringItem>,
) {
    let start = p.current_start();
    if p.eat_if(Kind::Dots) {
        let mut name = None;
        if p.at_set(PATTERN_LEAF) {
            if let Some(Pattern::Normal(e)) = pattern_leaf(p, reassignment, seen, None) {
                if let ExprKind::Ident(n) = e.kind {
                    name = Some(Ident { name: n, span: e.span });
                }
            }
        }
        *at_pattern_or_spread = true;
        *maybe_just_parens = false;
        items.push(DestructuringItem::Spread(name, Span::new(start, p.prev_end())));
        return;
    }

    let at_pattern = p.at_set(PATTERN);
    let pat = pattern(p, reassignment, seen, None);
    if p.eat_if(Kind::Colon) {
        *maybe_just_parens = false;
        let value = pattern(p, reassignment, seen, None);
        match (pat, value) {
            (Some(Pattern::Normal(Expr { kind: ExprKind::Ident(name), span })), Some(value)) => {
                items.push(DestructuringItem::Named(Ident { name, span }, value));
            }
            (Some(other), _) => {
                if at_pattern {
                    p.error_at(other.span(), "expected pattern");
                }
            }
            _ => {}
        }
    } else {
        *at_pattern_or_spread |= at_pattern;
        if let Some(pat) = pat {
            items.push(DestructuringItem::Pattern(pat));
        }
    }
}

fn pattern_leaf(
    p: &mut Parser,
    reassignment: bool,
    seen: &mut HashSet<String>,
    dupe: Option<&str>,
) -> Option<Pattern> {
    if p.current().is_keyword() {
        let (span, text) = p.eat();
        p.error_at(span, format!("expected pattern, found keyword `{text}`"));
        return None;
    } else if !p.at_set(PATTERN_LEAF) {
        p.expected("pattern");
        return None;
    }

    let text = p.current_text().to_string();
    let expr = code_expr_prec(p, true, 0)?;
    if !reassignment {
        if let ExprKind::Ident(_) = &expr.kind {
            if !seen.insert(text.clone()) {
                p.error_at(expr.span, format!("duplicate {}: {text}", dupe.unwrap_or("binding")));
            }
        } else {
            p.error_at(expr.span, format!("expected pattern, found {}", expr_kind_name(&expr)));
            return None;
        }
    }
    Some(Pattern::Normal(expr))
}

fn let_binding(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::Let);
    let mut closure: Option<(Ident, Vec<Param>)> = None;
    let mut other = false;
    let mut pat: Option<Pattern> = None;

    match p.current() {
        Kind::Ident => {
            let (span, text) = p.eat();
            let ident = Ident { name: text.to_string(), span };
            if p.directly_at(Kind::LeftParen) {
                let params = params(p);
                closure = Some((ident, params));
            } else {
                pat = Some(Pattern::Normal(Expr::new(ExprKind::Ident(text.to_string()), span)));
            }
        }
        _ => {
            let mut seen = HashSet::new();
            pat = pattern(p, false, &mut seen, None);
            other = true;
        }
    }

    let has_eq = if closure.is_some() || other {
        p.expect(Kind::Eq)
    } else {
        p.eat_if(Kind::Eq)
    };

    let init = if has_eq { code_expr(p) } else { None };
    let end = p.prev_end();
    let span = Span::new(start, end);

    if let Some((name, params)) = closure {
        let body = init.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(end, end)));
        let closure_expr = Expr::new(
            ExprKind::Closure(Rc::new(Closure { name: Some(name.clone()), params, body })),
            Span::new(name.span.start as usize, end),
        );
        return Some(Expr::new(
            ExprKind::Let {
                pattern: Pattern::Normal(Expr::new(ExprKind::Ident(name.name), name.span)),
                init: Some(Box::new(closure_expr)),
            },
            span,
        ));
    }

    let pattern = pat?;
    Some(Expr::new(ExprKind::Let { pattern, init: init.map(Box::new) }, span))
}

fn set_rule(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::Set);
    let tstart = p.current_start();
    if !p.at(Kind::Ident) {
        p.expect(Kind::Ident);
        return None;
    }
    let (span, text) = p.eat();
    let mut target = Expr::new(ExprKind::Ident(text.to_string()), span);
    while p.eat_if(Kind::Dot) {
        if p.at(Kind::Ident) {
            let (fspan, ftext) = p.eat();
            target = Expr::new(
                ExprKind::FieldAccess {
                    target: Box::new(target),
                    field: Ident { name: ftext.to_string(), span: fspan },
                },
                Span::new(tstart, fspan.end as usize),
            );
        } else {
            p.expect(Kind::Ident);
        }
    }
    if !p.directly_at(Kind::LeftParen) && !p.directly_at(Kind::LeftBracket) {
        p.expected("argument list");
        if p.at(Kind::LeftParen) || p.at(Kind::LeftBracket) {
            p.hint("there may not be any spaces before the argument list");
        }
    }
    let args = args(p);
    let condition = if p.eat_if(Kind::If) { code_expr(p).map(Box::new) } else { None };
    let end = p.prev_end();
    Some(Expr::new(ExprKind::Set { target: Box::new(target), args, condition }, Span::new(start, end)))
}

fn show_rule(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::Show);
    let before = p.prev_end();
    let selector = if !p.at(Kind::Colon) { code_expr(p) } else { None };
    let transform = if p.eat_if(Kind::Colon) {
        code_expr(p)
    } else {
        p.expected_at(before.max(p.prev_end()), "colon");
        None
    };
    let end = p.prev_end();
    let transform = transform.unwrap_or_else(|| Expr::new(ExprKind::None, Span::new(end, end)));
    Some(Expr::new(
        ExprKind::Show { selector: selector.map(Box::new), transform: Box::new(transform) },
        Span::new(start, end),
    ))
}

fn contextual(p: &mut Parser, atomic: bool) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::Context);
    let body = code_expr_prec(p, atomic, 0)?;
    let span = Span::new(start, body.span.end as usize);
    Some(Expr::new(ExprKind::Contextual(Box::new(body)), span))
}

fn block(p: &mut Parser) -> Option<Expr> {
    match p.current() {
        Kind::LeftBracket => Some(content_block(p)),
        Kind::LeftBrace => Some(code_block(p)),
        _ => {
            p.expected("block");
            None
        }
    }
}

fn conditional(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::If);
    let cond = code_expr(p);
    let if_body = block(p);
    let mut else_body = None;
    if p.eat_if(Kind::Else) {
        if p.at(Kind::If) {
            else_body = conditional(p);
        } else {
            else_body = block(p);
        }
    }
    let end = p.prev_end();
    let cond = cond?;
    let if_body = if_body?;
    Some(Expr::new(
        ExprKind::Conditional {
            cond: Box::new(cond),
            if_body: Box::new(if_body),
            else_body: else_body.map(Box::new),
        },
        Span::new(start, end),
    ))
}

fn while_loop(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::While);
    let cond = code_expr(p);
    let body = block(p);
    let end = p.prev_end();
    Some(Expr::new(
        ExprKind::While { cond: Box::new(cond?), body: Box::new(body?) },
        Span::new(start, end),
    ))
}

fn for_loop(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::For);
    let mut seen = HashSet::new();
    let pat = pattern(p, false, &mut seen, None);
    let iterable = if p.eat_if(Kind::In) {
        code_expr(p)
    } else {
        p.expected("keyword `in`");
        None
    };
    let body = block(p);
    let end = p.prev_end();
    Some(Expr::new(
        ExprKind::For { pattern: pat?, iterable: Box::new(iterable?), body: Box::new(body?) },
        Span::new(start, end),
    ))
}

fn module_import(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::Import);
    let source = code_expr(p);
    let mut new_name = None;
    if p.eat_if(Kind::As) {
        if p.at(Kind::Ident) {
            let (span, text) = p.eat();
            new_name = Some(Ident { name: text.to_string(), span });
        } else {
            p.expect(Kind::Ident);
        }
    }
    let mut imports = None;
    if p.eat_if(Kind::Colon) {
        if p.at(Kind::Star) {
            p.eat();
            imports = Some(Imports::Wildcard);
        } else {
            imports = Some(Imports::Items(import_items(p)));
        }
    }
    let end = p.prev_end();
    Some(Expr::new(
        ExprKind::Import { source: Box::new(source?), new_name, imports },
        Span::new(start, end),
    ))
}

fn import_items(p: &mut Parser) -> Vec<ImportItem> {
    let mut out = Vec::new();
    while !is_terminator(p.current()) {
        let mut path = Vec::new();
        if p.at(Kind::Ident) {
            let (span, text) = p.eat();
            path.push(Ident { name: text.to_string(), span });
        } else {
            p.unexpected();
        }
        while p.eat_if(Kind::Dot) {
            if p.at(Kind::Ident) {
                let (span, text) = p.eat();
                path.push(Ident { name: text.to_string(), span });
            } else {
                p.expect(Kind::Ident);
            }
        }
        let mut rename = None;
        if p.eat_if(Kind::As) {
            if p.at(Kind::Ident) {
                let (span, text) = p.eat();
                rename = Some(Ident { name: text.to_string(), span });
            } else {
                p.expect(Kind::Ident);
            }
        }
        if !path.is_empty() {
            out.push(ImportItem { path, rename });
        }
        if !is_terminator(p.current()) {
            p.expect(Kind::Comma);
        }
    }
    out
}

fn module_include(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::Include);
    let source = code_expr(p)?;
    let span = Span::new(start, source.span.end as usize);
    Some(Expr::new(ExprKind::Include(Box::new(source)), span))
}

fn return_stmt(p: &mut Parser) -> Option<Expr> {
    let start = p.current_start();
    p.assert(Kind::Return);
    let mut body = None;
    if p.at_set(CODE_EXPR) {
        body = code_expr(p);
    }
    let end = p.prev_end();
    Some(Expr::new(ExprKind::Return(body.map(Box::new)), Span::new(start, end)))
}
