#[derive(Debug)]
pub struct Module {
    pub name: String,
    pub scope: Scope,
    pub content: Option<Content>,
}

#[derive(Debug, Default, Clone)]
pub struct Scope {
    pub map: IndexMap<String, Binding>,
}

#[derive(Debug, Clone)]
pub struct Binding {
    pub value: Value,
    pub span: Span,
    pub deprecation: Option<&'static str>,
}

impl Scope {
    pub fn new() -> Self {
        Self::default()
    }
    pub fn define(&mut self, name: impl Into<String>, value: impl Into<Value>) {
        self.map.insert(name.into(), Binding { value: value.into(), span: Span::detached(), deprecation: None });
    }
    pub fn define_spanned(&mut self, name: impl Into<String>, value: Value, span: Span) {
        self.map.insert(name.into(), Binding { value, span, deprecation: None });
    }
    pub fn get(&self, name: &str) -> Option<&Binding> {
        self.map.get(name)
    }
    pub fn get_mut(&mut self, name: &str) -> Option<&mut Binding> {
        self.map.get_mut(name)
    }
}

