#[derive(Clone, Debug)]
pub enum Func {
    Native(Rc<NativeFunc>),
    Elem(&'static str),
    Closure(Rc<ClosureValue>),
    With(Rc<(Func, Args)>),
}

pub type NativeFn = fn(&mut super::vm::Vm, &mut Args, Span) -> super::vm::Result<Value>;

pub struct NativeFunc {
    pub name: &'static str,
    /// Human-readable parameter list for `repr` purposes, unused mostly.
    pub func: NativeFn,
    pub scope: Scope,
    /// Whether this function is contextual.
    pub contextual: bool,
    pub deprecation: Option<&'static str>,
}

impl std::fmt::Debug for NativeFunc {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "NativeFunc({})", self.name)
    }
}

#[derive(Debug)]
pub struct ClosureValue {
    pub ast: Rc<AstClosure>,
    pub captured: Scope,
    pub defaults: Vec<Value>,
    pub file: u16,
}

impl Func {
    pub fn native(name: &'static str, func: NativeFn) -> Self {
        Func::Native(Rc::new(NativeFunc { name, func, scope: Scope::new(), contextual: false, deprecation: None }))
    }

    pub fn native_with_scope(name: &'static str, func: NativeFn, scope: Scope) -> Self {
        Func::Native(Rc::new(NativeFunc { name, func, scope, contextual: false, deprecation: None }))
    }

    pub fn name(&self) -> Option<String> {
        match self {
            Func::Native(n) => Some(n.name.to_string()),
            Func::Elem(e) => Some(e.to_string()),
            Func::Closure(c) => c.ast.name.as_ref().map(|n| n.name.clone()),
            Func::With(w) => w.0.name(),
        }
    }

    pub fn elem(&self) -> Option<&'static str> {
        match self {
            Func::Elem(e) => Some(e),
            Func::With(w) => w.0.elem(),
            _ => None,
        }
    }

    pub fn same(&self, other: &Func) -> bool {
        match (self, other) {
            (Func::Native(a), Func::Native(b)) => Rc::ptr_eq(a, b) || a.name == b.name,
            (Func::Elem(a), Func::Elem(b)) => a == b,
