impl Args {
    pub fn new(span: Span, values: Vec<Value>) -> Self {
        Args {
            span,
            items: values
                .into_iter()
                .map(|v| Arg { span, name: None, value: v, value_span: span })
                .collect(),
        }
    }

    pub fn push(&mut self, span: Span, value: Value) {
        self.items.push(Arg { span, name: None, value, value_span: span });
    }

    pub fn push_named(&mut self, span: Span, name: &str, value: Value) {
        self.items.push(Arg { span, name: Some(name.to_string()), value, value_span: span });
    }

    /// Take the first positional argument, if any.
    pub fn eat_pos(&mut self) -> Option<Arg> {
        let idx = self.items.iter().position(|a| a.name.is_none())?;
        Some(self.items.remove(idx))
    }

    /// Take a named argument.
    pub fn take_named(&mut self, name: &str) -> Option<Arg> {
        let idx = self.items.iter().position(|a| a.name.as_deref() == Some(name))?;
        Some(self.items.remove(idx))
    }

    pub fn has_named(&self, name: &str) -> bool {
        self.items.iter().any(|a| a.name.as_deref() == Some(name))
    }

    pub fn remaining_pos(&self) -> usize {
        self.items.iter().filter(|a| a.name.is_none()).count()
    }

    pub fn take_all_pos(&mut self) -> Vec<Arg> {
        let mut out = Vec::new();
        let mut rest = Vec::new();
        for a in std::mem::take(&mut self.items) {
            if a.name.is_none() {
                out.push(a);
            } else {
                rest.push(a);
            }
        }
        self.items = rest;
        out
    }
}

/// A lazily computed cache for things like regex compilation.
thread_local! {
    pub static REGEX_CACHE: RefCell<HashMap<String, regex::Regex>> = RefCell::new(HashMap::new());
}

pub fn write_joined(out: &mut String, items: impl Iterator<Item = String>, sep: &str) {
    let mut first = true;
    for item in items {
        if !first {
            out.push_str(sep);
        }
        first = false;
        let _ = write!(out, "{item}");
    }
}
