//! Content model.

use std::rc::Rc;

use crate::syntax::ast::Span;

use super::value::{Location, Value};

#[derive(Clone, Debug)]
pub struct Content(pub Rc<ContentInner>);

#[derive(Clone, Debug)]
pub struct ContentInner {
    pub elem: &'static str,
    pub fields: Vec<(String, Value)>,
    pub label: Option<Rc<str>>,
    pub span: Span,
    pub location: Option<Location>,
}

impl Content {
    pub fn new(elem: &'static str) -> Self {
        Content(Rc::new(ContentInner {
            elem,
            fields: Vec::new(),
            label: None,
            span: Span::detached(),
            location: None,
        }))
    }

    pub fn with_field(mut self, name: &str, value: impl Into<Value>) -> Self {
        self.set_field(name, value.into());
        self
    }

    pub fn with_span(mut self, span: Span) -> Self {
        Rc::make_mut(&mut self.0).span = span;
        self
    }

    pub fn empty() -> Self {
        Content::new("sequence").with_field("children", Value::array(vec![]))
    }

    pub fn sequence(children: Vec<Content>) -> Self {
        if children.len() == 1 {
            return children.into_iter().next().unwrap();
        }
        Content::new("sequence")
            .with_field("children", Value::array(children.into_iter().map(Value::Content).collect()))
    }

    pub fn text(s: &str) -> Self {
        Content::new("text").with_field("text", Value::str(s))
    }

    pub fn space() -> Self {
        Content::new("space")
    }

    pub fn symbol(s: &str) -> Self {
        Content::new("symbol").with_field("text", Value::str(s))
    }

    pub fn elem(&self) -> &'static str {
        self.0.elem
    }

    pub fn is(&self, elem: &str) -> bool {
        self.0.elem == elem
    }

    pub fn span(&self) -> Span {
        self.0.span
    }

    pub fn label(&self) -> Option<&Rc<str>> {
        self.0.label.as_ref()
    }

    pub fn set_label(&mut self, label: Rc<str>) {
        Rc::make_mut(&mut self.0).label = Some(label);
    }

    pub fn location(&self) -> Option<Location> {
        self.0.location
    }

    pub fn set_location(&mut self, loc: Location) {
        Rc::make_mut(&mut self.0).location = Some(loc);
    }

    pub fn field(&self, name: &str) -> Option<&Value> {
        self.0.fields.iter().find(|(n, _)| n == name).map(|(_, v)| v)
    }

    pub fn has_field(&self, name: &str) -> bool {
        self.field(name).is_some()
    }

    pub fn set_field(&mut self, name: &str, value: Value) {
        let inner = Rc::make_mut(&mut self.0);
        if let Some(slot) = inner.fields.iter_mut().find(|(n, _)| n == name) {
            slot.1 = value;
        } else {
            inner.fields.push((name.to_string(), value));
        }
    }

    pub fn fields(&self) -> &[(String, Value)] {
        &self.0.fields
    }

    /// Sort the fields according to the element's parameter order.
    pub fn sort_fields(&mut self, order: &[&str]) {
        let inner = Rc::make_mut(&mut self.0);
        inner.fields.sort_by_key(|(n, _)| {
            order.iter().position(|o| o == n).unwrap_or(usize::MAX)
        });
    }

    /// Children of a sequence.
    pub fn children(&self) -> Option<Vec<Content>> {
        if !self.is("sequence") {
            return None;
        }
        match self.field("children") {
            Some(Value::Array(a)) => Some(
                a.iter()
                    .filter_map(|v| match v {
                        Value::Content(c) => Some(c.clone()),
                        _ => None,
                    })
                    .collect(),
            ),
            _ => Some(vec![]),
        }
    }

    pub fn is_empty(&self) -> bool {
        self.children().is_some_and(|c| c.is_empty())
    }

    /// Whether this content can carry a label.
    pub fn is_labellable(&self) -> bool {
        !matches!(self.0.elem, "space" | "parbreak" | "tag" | "styled" | "sequence" | "flush")
            || matches!(self.0.elem, "sequence" | "styled") && false
    }

    /// Repeat the content `n` times.
    pub fn repeat(&self, n: usize) -> Content {
        let mut children = Vec::with_capacity(n);
        for _ in 0..n {
            children.push(self.clone());
        }
        Content::sequence(children)
    }

    /// Plain text extraction.
    pub fn plain_text(&self) -> String {
        let mut out = String::new();
        self.plain_text_into(&mut out);
        out
    }

    fn plain_text_into(&self, out: &mut String) {
        match self.elem() {
            "text" => {
                if let Some(Value::Str(s)) = self.field("text") {
                    out.push_str(s);
                }
            }
            "symbol" => {
                if let Some(Value::Str(s)) = self.field("text") {
                    out.push_str(s);
                }
            }
            "space" => out.push(' '),
            "linebreak" => out.push('\n'),
            "parbreak" => out.push_str("\n\n"),
            "smartquote" => {
                if let Some(Value::Bool(true)) = self.field("double") {
                    out.push('"');
                } else {
                    out.push('\'');
                }
            }
            "sequence" => {
                for c in self.children().unwrap_or_default() {
                    c.plain_text_into(out);
                }
            }
            "styled" => {
                if let Some(Value::Content(c)) = self.field("child") {
                    c.plain_text_into(out);
                }
            }
            "raw" => {
                if let Some(Value::Str(s)) = self.field("text") {
                    out.push_str(s);
                }
            }
            _ => {
                if let Some(Value::Content(c)) = self.field("body") {
                    c.plain_text_into(out);
                }
            }
        }
    }
}

/// Join two contents, flattening sequences.
pub fn join_content(a: Content, b: Content) -> Content {
    let mut children = Vec::new();
    match a.children() {
        Some(c) if a.label().is_none() => children.extend(c),
        _ => children.push(a),
    }
    match b.children() {
        Some(c) if b.label().is_none() => children.extend(c),
        _ => children.push(b),
    }
    Content::new("sequence")
        .with_field("children", Value::array(children.into_iter().map(Value::Content).collect()))
}
