//! Operators on values.

use std::cmp::Ordering;
use std::rc::Rc;

use super::content::{join_content, Content};
use super::repr::{format_float_unit, repr};
use super::value::{Dict, Dynamic, Relative, Symbol, Value};

/// A length with absolute and em parts.
#[derive(Clone, Copy, Debug, PartialEq, Default)]
pub struct Length {
    pub abs: f64,
    pub em: f64,
}

impl Length {
    pub const fn pt(abs: f64) -> Self {
        Length { abs, em: 0.0 }
    }
    pub const fn em(em: f64) -> Self {
        Length { abs: 0.0, em }
    }
    pub fn zero() -> Self {
        Length { abs: 0.0, em: 0.0 }
    }
    pub fn is_zero(&self) -> bool {
        self.abs == 0.0 && self.em == 0.0
    }
    pub fn neg(self) -> Self {
        Length { abs: -self.abs, em: -self.em }
    }
    pub fn add(self, o: Length) -> Self {
        Length { abs: self.abs + o.abs, em: self.em + o.em }
    }
    pub fn scale(self, f: f64) -> Self {
        Length { abs: self.abs * f, em: self.em * f }
    }
    pub fn repr(&self) -> String {
        match (self.abs != 0.0, self.em != 0.0) {
            (false, false) => "0pt".into(),
            (true, false) => format_float_unit(self.abs, "pt"),
            (false, true) => format_float_unit(self.em, "em"),
            (true, true) => {
                format!("{} + {}", format_float_unit(self.abs, "pt"), format_float_unit(self.em, "em"))
            }
        }
    }
    pub fn partial_cmp(&self, o: &Length) -> Option<Ordering> {
        if self.em == 0.0 && o.em == 0.0 {
            self.abs.partial_cmp(&o.abs)
        } else if self.abs == 0.0 && o.abs == 0.0 {
            self.em.partial_cmp(&o.em)
        } else if self.abs == o.abs {
            self.em.partial_cmp(&o.em)
        } else if self.em == o.em {
            self.abs.partial_cmp(&o.abs)
        } else {
            None
        }
    }
    /// Resolve with a given em size.
    pub fn resolve(&self, em: f64) -> f64 {
        self.abs + self.em * em
    }
}

impl Relative {
    pub fn new(rel: f64, abs: Length) -> Self {
        Relative { rel, abs }
    }
    pub fn from_length(l: Length) -> Self {
        Relative { rel: 0.0, abs: l }
    }
    pub fn from_ratio(r: f64) -> Self {
        Relative { rel: r, abs: Length::zero() }
    }
    pub fn repr(&self) -> String {
        format!("{} + {}", format_float_unit(self.rel * 100.0, "%"), self.abs.repr())
    }
    pub fn neg(self) -> Self {
        Relative { rel: -self.rel, abs: self.abs.neg() }
    }
}

pub type OpResult = Result<Value, String>;

pub fn pos(v: Value) -> OpResult {
    Ok(match v {
        Value::Int(_) | Value::Float(_) | Value::Length(_) | Value::Angle(_) | Value::Ratio(_)
        | Value::Relative(_) | Value::Fraction(_) => v,
        Value::Dyn(ref d) if matches!(**d, Dynamic::Decimal(_)) => v,
        Value::Duration(_) => v,
        v => return Err(format!("cannot apply unary '+' to {}", v.ty().long_name())),
    })
}

pub fn neg(v: Value) -> OpResult {
    Ok(match v {
        Value::Int(i) => Value::Int(i.checked_neg().ok_or("value is too large")?),
        Value::Float(f) => Value::Float(-f),
        Value::Length(l) => Value::Length(l.neg()),
        Value::Angle(a) => Value::Angle(-a),
        Value::Ratio(r) => Value::Ratio(-r),
        Value::Relative(r) => Value::Relative(r.neg()),
        Value::Fraction(f) => Value::Fraction(-f),
        Value::Duration(d) => Value::Duration(d.neg()),
        Value::Dyn(d) => match &*d {
            Dynamic::Decimal(dec) => Value::dynamic(Dynamic::Decimal(super::value::Decimal {
                mantissa: -dec.mantissa,
                scale: dec.scale,
            })),
            _ => return Err(format!("cannot apply '-' to {}", Value::Dyn(d.clone()).ty().long_name())),
        },
        v => return Err(format!("cannot apply '-' to {}", v.ty().long_name())),
    })
}

pub fn not(v: Value) -> OpResult {
    match v {
        Value::Bool(b) => Ok(Value::Bool(!b)),
        v => Err(format!("cannot apply 'not' to {}", v.ty().long_name())),
    }
}

fn mismatch(op: &str, a: &Value, b: &Value) -> String {
    format!("cannot {op} {} and {}", a.ty().long_name(), b.ty().long_name())
}

fn too_large() -> String {
    "value is too large".into()
}

pub fn join(a: Value, b: Value) -> OpResult {
    use Value::*;
    Ok(match (a, b) {
        (a, None) => a,
        (None, b) => b,
        (Str(a), Str(b)) => Value::str(format!("{a}{b}")),
        (Str(a), Symbol(b)) => Value::str(format!("{a}{}", b.text)),
        (Symbol(a), Str(b)) => Value::str(format!("{}{b}", a.text)),
        (Symbol(a), Symbol(b)) => Value::str(format!("{}{}", a.text, b.text)),
        (Bytes(a), Bytes(b)) => {
            let mut v = (*a).clone();
            v.extend_from_slice(&b);
            Bytes(Rc::new(v))
        }
        (Content(a), Content(b)) => Content(join_content(a, b)),
        (Content(a), Str(b)) => Content(join_content(a, super::content::Content::text(&b))),
        (Str(a), Content(b)) => Content(join_content(super::content::Content::text(&a), b)),
        (Content(a), Symbol(b)) => Content(join_content(a, super::content::Content::symbol(&b.text))),
        (Symbol(a), Content(b)) => Content(join_content(super::content::Content::symbol(&a.text), b)),
        (Array(a), Array(b)) => {
            let mut v = (*a).clone();
            v.extend(b.iter().cloned());
            Array(Rc::new(v))
        }
        (Dict(a), Dict(b)) => {
            let mut d = (*a).clone();
            for (k, v) in b.iter() {
                d.insert(k.clone(), v.clone());
            }
            Dict(Rc::new(d))
        }
        (Args(a), Args(b)) => {
            let mut x = (*a).clone();
            x.items.extend(b.items.iter().cloned());
            Args(Rc::new(x))
        }
        (a, b) => return Err(mismatch("join", &a, &b)),
    })
}

pub fn add(a: Value, b: Value) -> OpResult {
    use Value::*;
    Ok(match (a, b) {
        (a, None) => a,
        (None, b) => b,
        (Int(a), Int(b)) => Int(a.checked_add(b).ok_or_else(too_large)?),
        (Int(a), Float(b)) => Float(a as f64 + b),
        (Float(a), Int(b)) => Float(a + b as f64),
        (Float(a), Float(b)) => Float(a + b),
        (Angle(a), Angle(b)) => Angle(a + b),
        (Length(a), Length(b)) => Length(a.add(b)),
        (Length(a), Ratio(b)) => Relative(super::value::Relative::new(b, a)),
        (Length(a), Relative(b)) => Relative(super::value::Relative::new(b.rel, b.abs.add(a))),
        (Ratio(a), Length(b)) => Relative(super::value::Relative::new(a, b)),
        (Ratio(a), Ratio(b)) => Ratio(a + b),
        (Ratio(a), Relative(b)) => Relative(super::value::Relative::new(a + b.rel, b.abs)),
        (Relative(a), Length(b)) => Relative(super::value::Relative::new(a.rel, a.abs.add(b))),
        (Relative(a), Ratio(b)) => Relative(super::value::Relative::new(a.rel + b, a.abs)),
        (Relative(a), Relative(b)) => Relative(super::value::Relative::new(a.rel + b.rel, a.abs.add(b.abs))),
        (Fraction(a), Fraction(b)) => Fraction(a + b),
        (Str(a), Str(b)) => Value::str(format!("{a}{b}")),
        (Str(a), Symbol(b)) => Value::str(format!("{a}{}", b.text)),
        (Symbol(a), Str(b)) => Value::str(format!("{}{b}", a.text)),
        (Symbol(a), Symbol(b)) => Value::str(format!("{}{}", a.text, b.text)),
        (Bytes(a), Bytes(b)) => {
            let mut v = (*a).clone();
            v.extend_from_slice(&b);
            Bytes(Rc::new(v))
        }
        (Content(a), Content(b)) => Content(join_content(a, b)),
        (Content(a), Str(b)) => Content(join_content(a, super::content::Content::text(&b))),
        (Str(a), Content(b)) => Content(join_content(super::content::Content::text(&a), b)),
        (Content(a), Symbol(b)) => Content(join_content(a, super::content::Content::symbol(&b.text))),
        (Symbol(a), Content(b)) => Content(join_content(super::content::Content::symbol(&a.text), b)),
        (Array(a), Array(b)) => {
            let mut v = (*a).clone();
            v.extend(b.iter().cloned());
            Array(Rc::new(v))
        }
        (Dict(a), Dict(b)) => {
            let mut d: Dict = (*a).clone();
            for (k, v) in b.iter() {
                d.insert(k.clone(), v.clone());
            }
            Dict(Rc::new(d))
        }
        (Datetime(a), Duration(b)) => Datetime(a.add(b)?),
        (Duration(a), Datetime(b)) => Datetime(b.add(a)?),
        (Duration(a), Duration(b)) => Duration(a.add(b)),
        (Dyn(a), Dyn(b)) => match (&*a, &*b) {
            (Dynamic::Alignment(x), Dynamic::Alignment(y)) => {
                match (x.h, y.h, x.v, y.v) {
                    (Some(_), Some(_), _, _) => return Err("cannot add two horizontal alignments".into()),
                    (_, _, Some(_), Some(_)) => return Err("cannot add two vertical alignments".into()),
                    _ => {}
                }
                Value::dynamic(Dynamic::Alignment(super::value::Alignment {
                    h: x.h.or(y.h),
                    v: x.v.or(y.v),
                }))
            }
            (Dynamic::Decimal(x), Dynamic::Decimal(y)) => {
                Value::dynamic(Dynamic::Decimal(super::decimal::add(x, y)?))
            }
            (Dynamic::Stroke(_), Dynamic::Stroke(_)) => {
                return Err(mismatch("add", &Dyn(a.clone()), &Dyn(b.clone())))
            }
            _ => return Err(mismatch("add", &Dyn(a.clone()), &Dyn(b.clone()))),
        },
        (Dyn(a), Int(b)) if matches!(*a, Dynamic::Decimal(_)) => {
            if let Dynamic::Decimal(x) = &*a {
                Value::dynamic(Dynamic::Decimal(super::decimal::add(x, &super::decimal::from_int(b))?))
            } else {
                unreachable!()
            }
        }
        (Int(a), Dyn(b)) if matches!(*b, Dynamic::Decimal(_)) => {
            if let Dynamic::Decimal(y) = &*b {
                Value::dynamic(Dynamic::Decimal(super::decimal::add(&super::decimal::from_int(a), y)?))
            } else {
                unreachable!()
            }
        }
        (a, b) => return Err(mismatch("add", &a, &b)),
    })
}

pub fn sub(a: Value, b: Value) -> OpResult {
    use Value::*;
    Ok(match (a, b) {
        (Int(a), Int(b)) => Int(a.checked_sub(b).ok_or_else(too_large)?),
        (Int(a), Float(b)) => Float(a as f64 - b),
        (Float(a), Int(b)) => Float(a - b as f64),
        (Float(a), Float(b)) => Float(a - b),
        (Angle(a), Angle(b)) => Angle(a - b),
        (Length(a), Length(b)) => Length(a.add(b.neg())),
        (Length(a), Ratio(b)) => Relative(super::value::Relative::new(-b, a)),
        (Length(a), Relative(b)) => Relative(super::value::Relative::new(-b.rel, a.add(b.abs.neg()))),
        (Ratio(a), Length(b)) => Relative(super::value::Relative::new(a, b.neg())),
        (Ratio(a), Ratio(b)) => Ratio(a - b),
        (Ratio(a), Relative(b)) => Relative(super::value::Relative::new(a - b.rel, b.abs.neg())),
        (Relative(a), Length(b)) => Relative(super::value::Relative::new(a.rel, a.abs.add(b.neg()))),
        (Relative(a), Ratio(b)) => Relative(super::value::Relative::new(a.rel - b, a.abs)),
        (Relative(a), Relative(b)) => {
            Relative(super::value::Relative::new(a.rel - b.rel, a.abs.add(b.abs.neg())))
        }
        (Fraction(a), Fraction(b)) => Fraction(a - b),
        (Datetime(a), Duration(b)) => Datetime(a.sub(b)?),
        (Datetime(a), Datetime(b)) => Duration(a.diff(&b)),
        (Duration(a), Duration(b)) => Duration(a.sub(b)),
        (Dyn(a), Dyn(b)) => match (&*a, &*b) {
            (Dynamic::Decimal(x), Dynamic::Decimal(y)) => {
                Value::dynamic(Dynamic::Decimal(super::decimal::sub(x, y)?))
            }
            _ => return Err(mismatch("subtract", &Dyn(a.clone()), &Dyn(b.clone()))),
        },
        (Dyn(a), Int(b)) if matches!(*a, Dynamic::Decimal(_)) => {
            if let Dynamic::Decimal(x) = &*a {
                Value::dynamic(Dynamic::Decimal(super::decimal::sub(x, &super::decimal::from_int(b))?))
            } else {
                unreachable!()
            }
        }
        (Int(a), Dyn(b)) if matches!(*b, Dynamic::Decimal(_)) => {
            if let Dynamic::Decimal(y) = &*b {
                Value::dynamic(Dynamic::Decimal(super::decimal::sub(&super::decimal::from_int(a), y)?))
            } else {
                unreachable!()
            }
        }
        (a, b) => return Err(mismatch("subtract", &a, &b)),
    })
}

fn repeat_check(n: i64) -> Result<usize, String> {
    if n < 0 {
        return Err("number must be at least zero".into());
    }
    Ok(n as usize)
}

pub fn mul(a: Value, b: Value) -> OpResult {
    use Value::*;
    Ok(match (a, b) {
        (Int(a), Int(b)) => Int(a.checked_mul(b).ok_or_else(too_large)?),
        (Int(a), Float(b)) => Float(a as f64 * b),
        (Float(a), Int(b)) => Float(a * b as f64),
        (Float(a), Float(b)) => Float(a * b),
        (Length(a), Int(b)) => Length(a.scale(b as f64)),
        (Length(a), Float(b)) => Length(a.scale(b)),
        (Int(a), Length(b)) => Length(b.scale(a as f64)),
        (Float(a), Length(b)) => Length(b.scale(a)),
        (Length(a), Ratio(b)) => Length(a.scale(b)),
        (Ratio(a), Length(b)) => Length(b.scale(a)),
        (Angle(a), Int(b)) => Angle(a * b as f64),
        (Angle(a), Float(b)) => Angle(a * b),
        (Int(a), Angle(b)) => Angle(a as f64 * b),
        (Float(a), Angle(b)) => Angle(a * b),
        (Ratio(a), Int(b)) => Ratio(a * b as f64),
        (Ratio(a), Float(b)) => Ratio(a * b),
        (Ratio(a), Ratio(b)) => Ratio(a * b),
        (Int(a), Ratio(b)) => Ratio(a as f64 * b),
        (Float(a), Ratio(b)) => Ratio(a * b),
        (Relative(a), Int(b)) => Relative(super::value::Relative::new(a.rel * b as f64, a.abs.scale(b as f64))),
        (Relative(a), Float(b)) => Relative(super::value::Relative::new(a.rel * b, a.abs.scale(b))),
        (Relative(a), Ratio(b)) => Relative(super::value::Relative::new(a.rel * b, a.abs.scale(b))),
        (Int(a), Relative(b)) => Relative(super::value::Relative::new(b.rel * a as f64, b.abs.scale(a as f64))),
        (Float(a), Relative(b)) => Relative(super::value::Relative::new(b.rel * a, b.abs.scale(a))),
        (Ratio(a), Relative(b)) => Relative(super::value::Relative::new(b.rel * a, b.abs.scale(a))),
        (Fraction(a), Int(b)) => Fraction(a * b as f64),
        (Fraction(a), Float(b)) => Fraction(a * b),
        (Int(a), Fraction(b)) => Fraction(a as f64 * b),
        (Float(a), Fraction(b)) => Fraction(a * b),
        (Str(a), Int(b)) => Value::str(a.repeat(repeat_check(b)?)),
        (Int(a), Str(b)) => Value::str(b.repeat(repeat_check(a)?)),
        (Array(a), Int(b)) => {
            let n = repeat_check(b)?;
            let mut v = Vec::with_capacity(a.len() * n);
            for _ in 0..n {
                v.extend(a.iter().cloned());
            }
            Array(Rc::new(v))
        }
        (Int(a), Array(b)) => {
            let n = repeat_check(a)?;
            let mut v = Vec::with_capacity(b.len() * n);
            for _ in 0..n {
                v.extend(b.iter().cloned());
            }
            Array(Rc::new(v))
        }
        (Content(a), Int(b)) => Content(a.repeat(repeat_check(b)?)),
        (Int(a), Content(b)) => Content(b.repeat(repeat_check(a)?)),
        (Duration(a), Int(b)) => Duration(a.scale(b as f64)),
        (Duration(a), Float(b)) => Duration(a.scale(b)),
        (Int(a), Duration(b)) => Duration(b.scale(a as f64)),
        (Float(a), Duration(b)) => Duration(b.scale(a)),
        (Dyn(a), Dyn(b)) => match (&*a, &*b) {
            (Dynamic::Decimal(x), Dynamic::Decimal(y)) => {
                Value::dynamic(Dynamic::Decimal(super::decimal::mul(x, y)?))
            }
            _ => return Err(format!("cannot multiply {} with {}", Dyn(a.clone()).ty().long_name(), Dyn(b.clone()).ty().long_name())),
        },
        (Dyn(a), Int(b)) if matches!(*a, Dynamic::Decimal(_)) => {
            if let Dynamic::Decimal(x) = &*a {
                Value::dynamic(Dynamic::Decimal(super::decimal::mul(x, &super::decimal::from_int(b))?))
            } else {
                unreachable!()
            }
        }
        (Int(a), Dyn(b)) if matches!(*b, Dynamic::Decimal(_)) => {
            if let Dynamic::Decimal(y) = &*b {
                Value::dynamic(Dynamic::Decimal(super::decimal::mul(&super::decimal::from_int(a), y)?))
            } else {
                unreachable!()
            }
        }
        (a, b) => {
            return Err(format!("cannot multiply {} with {}", a.ty().long_name(), b.ty().long_name()))
        }
    })
}

fn div_zero() -> String {
    "cannot divide by zero".into()
}

pub fn div(a: Value, b: Value) -> OpResult {
    use Value::*;
    let is_zero = |v: &Value| match v {
        Int(0) => true,
        Float(f) => *f == 0.0,
        Length(l) => l.is_zero(),
        Angle(a) => *a == 0.0,
        Ratio(r) => *r == 0.0,
        Relative(r) => r.rel == 0.0 && r.abs.is_zero(),
        Fraction(f) => *f == 0.0,
        Duration(d) => d.is_zero(),
        _ => false,
    };
    if is_zero(&b) {
        return Err(div_zero());
    }
    Ok(match (a, b) {
        (Int(a), Int(b)) => Float(a as f64 / b as f64),
        (Int(a), Float(b)) => Float(a as f64 / b),
        (Float(a), Int(b)) => Float(a / b as f64),
        (Float(a), Float(b)) => Float(a / b),
        (Length(a), Int(b)) => Length(a.scale(1.0 / b as f64)),
        (Length(a), Float(b)) => Length(a.scale(1.0 / b)),
        (Length(a), Length(b)) => {
            Float(try_div_length(a, b).ok_or_else(|| format!("cannot divide these two lengths"))?)
        }
        (Angle(a), Int(b)) => Angle(a / b as f64),
        (Angle(a), Float(b)) => Angle(a / b),
        (Angle(a), Angle(b)) => Float(a / b),
        (Ratio(a), Int(b)) => Ratio(a / b as f64),
        (Ratio(a), Float(b)) => Ratio(a / b),
        (Ratio(a), Ratio(b)) => Float(a / b),
        (Relative(a), Int(b)) => Relative(super::value::Relative::new(a.rel / b as f64, a.abs.scale(1.0 / b as f64))),
        (Relative(a), Float(b)) => Relative(super::value::Relative::new(a.rel / b, a.abs.scale(1.0 / b))),
        (Relative(a), Relative(b)) => Float(
            try_div_relative(a, b).ok_or_else(|| format!("cannot divide these two relative lengths"))?,
        ),
        (Fraction(a), Int(b)) => Fraction(a / b as f64),
        (Fraction(a), Float(b)) => Fraction(a / b),
        (Fraction(a), Fraction(b)) => Float(a / b),
        (Duration(a), Int(b)) => Duration(a.scale(1.0 / b as f64)),
        (Duration(a), Float(b)) => Duration(a.scale(1.0 / b)),
        (Duration(a), Duration(b)) => Float(a.ratio(&b)),
        (Dyn(a), Dyn(b)) => match (&*a, &*b) {
            (Dynamic::Decimal(x), Dynamic::Decimal(y)) => {
                Value::dynamic(Dynamic::Decimal(super::decimal::div(x, y)?))
            }
            _ => return Err(format!("cannot divide {} by {}", Dyn(a.clone()).ty().long_name(), Dyn(b.clone()).ty().long_name())),
        },
        (Dyn(a), Int(b)) if matches!(*a, Dynamic::Decimal(_)) => {
            if let Dynamic::Decimal(x) = &*a {
                Value::dynamic(Dynamic::Decimal(super::decimal::div(x, &super::decimal::from_int(b))?))
            } else {
                unreachable!()
            }
        }
        (Int(a), Dyn(b)) if matches!(*b, Dynamic::Decimal(_)) => {
            if let Dynamic::Decimal(y) = &*b {
                Value::dynamic(Dynamic::Decimal(super::decimal::div(&super::decimal::from_int(a), y)?))
            } else {
                unreachable!()
            }
        }
        (a, b) => return Err(format!("cannot divide {} by {}", a.ty().long_name(), b.ty().long_name())),
    })
}

fn try_div_length(a: Length, b: Length) -> Option<f64> {
    if a.em == 0.0 && b.em == 0.0 {
        Some(a.abs / b.abs)
    } else if a.abs == 0.0 && b.abs == 0.0 {
        Some(a.em / b.em)
    } else {
        None
    }
}

fn try_div_relative(a: Relative, b: Relative) -> Option<f64> {
    if a.abs.is_zero() && b.abs.is_zero() {
        Some(a.rel / b.rel)
    } else if a.rel == 0.0 && b.rel == 0.0 {
        try_div_length(a.abs, b.abs)
    } else {
        None
    }
}

pub fn and(a: Value, b: Value) -> OpResult {
    match (a, b) {
        (Value::Bool(a), Value::Bool(b)) => Ok(Value::Bool(a && b)),
        (a, b) => Err(format!("cannot apply 'and' to {} and {}", a.ty().long_name(), b.ty().long_name())),
    }
}

pub fn or(a: Value, b: Value) -> OpResult {
    match (a, b) {
        (Value::Bool(a), Value::Bool(b)) => Ok(Value::Bool(a || b)),
        (a, b) => Err(format!("cannot apply 'or' to {} and {}", a.ty().long_name(), b.ty().long_name())),
    }
}

pub fn eq(a: &Value, b: &Value) -> bool {
    equal(a, b)
}

pub fn equal(a: &Value, b: &Value) -> bool {
    use Value::*;
    match (a, b) {
        (None, None) => true,
        (Auto, Auto) => true,
        (Bool(a), Bool(b)) => a == b,
        (Int(a), Int(b)) => a == b,
        (Float(a), Float(b)) => a == b,
        (Int(a), Float(b)) | (Float(b), Int(a)) => *a as f64 == *b,
        (Length(a), Length(b)) => a == b,
        (Angle(a), Angle(b)) => a == b,
        (Ratio(a), Ratio(b)) => a == b,
        (Relative(a), Relative(b)) => a == b,
        (Length(a), Relative(b)) | (Relative(b), Length(a)) => *a == b.abs && b.rel == 0.0,
        (Ratio(a), Relative(b)) | (Relative(b), Ratio(a)) => *a == b.rel && b.abs.is_zero(),
        (Fraction(a), Fraction(b)) => a == b,
        (Color(a), Color(b)) => a == b,
        (Gradient(a), Gradient(b)) => Rc::ptr_eq(a, b) || format!("{a:?}") == format!("{b:?}"),
        (Symbol(a), Symbol(b)) => a.text == b.text,
        (Version(a), Version(b)) => version_cmp(a, b) == Ordering::Equal,
        (Str(a), Str(b)) => a == b,
        (Bytes(a), Bytes(b)) => a == b,
        (Label(a), Label(b)) => a == b,
        (Datetime(a), Datetime(b)) => a == b,
        (Duration(a), Duration(b)) => a == b,
        (Content(a), Content(b)) => content_eq(a, b),
        (Styles(a), Styles(b)) => Rc::ptr_eq(a, b),
        (Array(a), Array(b)) => a.len() == b.len() && a.iter().zip(b.iter()).all(|(x, y)| equal(x, y)),
        (Dict(a), Dict(b)) => {
            a.len() == b.len() && a.iter().all(|(k, v)| b.get(k).is_some_and(|w| equal(v, w)))
        }
        (Func(a), Func(b)) => a.same(b),
        (Args(a), Args(b)) => {
            a.items.len() == b.items.len()
                && a.items.iter().zip(b.items.iter()).all(|(x, y)| x.name == y.name && equal(&x.value, &y.value))
        }
        (Type(a), Type(b)) => a == b,
        (Module(a), Module(b)) => Rc::ptr_eq(a, b) || a.name == b.name,
        (Dyn(a), Dyn(b)) => dyn_eq(a, b),
        _ => false,
    }
}

pub fn content_eq(a: &Content, b: &Content) -> bool {
    if a.elem() != b.elem() || a.label() != b.label() {
        return false;
    }
    let af = a.fields();
    let bf = b.fields();
    if af.len() != bf.len() {
        return false;
    }
    af.iter().all(|(k, v)| b.field(k).is_some_and(|w| equal(v, w)))
}

fn dyn_eq(a: &Dynamic, b: &Dynamic) -> bool {
    match (a, b) {
        (Dynamic::Regex(a), Dynamic::Regex(b)) => a.source == b.source,
        (Dynamic::Alignment(a), Dynamic::Alignment(b)) => a == b,
        (Dynamic::Direction(a), Dynamic::Direction(b)) => a == b,
        (Dynamic::Decimal(a), Dynamic::Decimal(b)) => super::decimal::cmp(a, b) == Ordering::Equal,
        (Dynamic::Location(a), Dynamic::Location(b)) => a == b,
        (Dynamic::Counter(a), Dynamic::Counter(b)) => equal(a, b),
        (Dynamic::State(a, _), Dynamic::State(b, _)) => a == b,
        (Dynamic::Selector(a), Dynamic::Selector(b)) => format!("{a:?}") == format!("{b:?}"),
        (Dynamic::Stroke(a), Dynamic::Stroke(b)) => format!("{a:?}") == format!("{b:?}"),
        _ => false,
    }
}

pub fn version_cmp(a: &[u32], b: &[u32]) -> Ordering {
    let n = a.len().max(b.len());
    for i in 0..n {
        let x = a.get(i).copied().unwrap_or(0);
        let y = b.get(i).copied().unwrap_or(0);
        match x.cmp(&y) {
            Ordering::Equal => continue,
            o => return o,
        }
    }
    Ordering::Equal
}

pub fn compare(a: &Value, b: &Value) -> Result<Ordering, String> {
    use Value::*;
    let res = match (a, b) {
        (Bool(a), Bool(b)) => a.partial_cmp(b),
        (Int(a), Int(b)) => a.partial_cmp(b),
        (Int(a), Float(b)) => (*a as f64).partial_cmp(b),
        (Float(a), Int(b)) => a.partial_cmp(&(*b as f64)),
        (Float(a), Float(b)) => a.partial_cmp(b),
        (Length(a), Length(b)) => {
            return a.partial_cmp(b).ok_or_else(|| format!("cannot compare {} with {}", a.repr(), b.repr()))
        }
        (Angle(a), Angle(b)) => a.partial_cmp(b),
        (Ratio(a), Ratio(b)) => a.partial_cmp(b),
        (Relative(a), Relative(b)) => {
            if a.abs.is_zero() && b.abs.is_zero() {
                a.rel.partial_cmp(&b.rel)
            } else if a.rel == 0.0 && b.rel == 0.0 {
                return a.abs.partial_cmp(&b.abs).ok_or_else(|| format!("cannot compare {} with {}", a.repr(), b.repr()));
            } else {
                return Err(format!("cannot compare {} with {}", a.repr(), b.repr()));
            }
        }
        (Fraction(a), Fraction(b)) => a.partial_cmp(b),
        (Str(a), Str(b)) => Some(a.cmp(b)),
        (Version(a), Version(b)) => Some(version_cmp(a, b)),
        (Datetime(a), Datetime(b)) => a.partial_cmp(b),
        (Duration(a), Duration(b)) => a.partial_cmp(b),
        (Array(a), Array(b)) => {
            for (x, y) in a.iter().zip(b.iter()) {
                match compare(x, y)? {
                    Ordering::Equal => continue,
                    o => return Ok(o),
                }
            }
            Some(a.len().cmp(&b.len()))
        }
        (Dyn(a), Dyn(b)) => match (&**a, &**b) {
            (Dynamic::Decimal(x), Dynamic::Decimal(y)) => Some(super::decimal::cmp(x, y)),
            _ => None,
        },
        (Dyn(x), Int(i)) if matches!(**x, Dynamic::Decimal(_)) => {
            if let Dynamic::Decimal(d) = &**x {
                Some(super::decimal::cmp(d, &super::decimal::from_int(*i)))
            } else {
                None
            }
        }
        (Int(i), Dyn(y)) if matches!(**y, Dynamic::Decimal(_)) => {
            if let Dynamic::Decimal(d) = &**y {
                Some(super::decimal::cmp(&super::decimal::from_int(*i), d))
            } else {
                None
            }
        }
        _ => None,
    };
    res.ok_or_else(|| format!("cannot compare {} and {}", a.ty().long_name(), b.ty().long_name()))
}

pub fn lt(a: &Value, b: &Value) -> OpResult {
    Ok(Value::Bool(compare(a, b)? == Ordering::Less))
}
pub fn leq(a: &Value, b: &Value) -> OpResult {
    Ok(Value::Bool(compare(a, b)? != Ordering::Greater))
}
pub fn gt(a: &Value, b: &Value) -> OpResult {
    Ok(Value::Bool(compare(a, b)? == Ordering::Greater))
}
pub fn geq(a: &Value, b: &Value) -> OpResult {
    Ok(Value::Bool(compare(a, b)? != Ordering::Less))
}

/// Test whether `a` is contained in `b`.
pub fn contains(a: &Value, b: &Value) -> Option<bool> {
    use Value::*;
    match (a, b) {
        (Str(a), Str(b)) => Some(b.contains(&**a)),
        (Dyn(d), Str(b)) => match &**d {
            Dynamic::Regex(r) => Some(r.regex.is_match(b)),
            _ => None,
        },
        (Str(a), Dict(b)) => Some(b.contains_key(&**a)),
        (a, Array(b)) => Some(b.iter().any(|x| equal(a, x))),
        _ => None,
    }
}

pub fn in_op(a: &Value, b: &Value) -> OpResult {
    match contains(a, b) {
        Some(r) => Ok(Value::Bool(r)),
        None => Err(format!("cannot apply 'in' to {} and {}", a.ty().long_name(), b.ty().long_name())),
    }
}

pub fn not_in_op(a: &Value, b: &Value) -> OpResult {
    match contains(a, b) {
        Some(r) => Ok(Value::Bool(!r)),
        None => Err(format!("cannot apply 'not in' to {} and {}", a.ty().long_name(), b.ty().long_name())),
    }
}

pub fn symbol_value(s: &str) -> Value {
    Value::Symbol(Rc::new(Symbol::single(s)))
}

#[allow(dead_code)]
pub fn repr_value(v: &Value) -> String {
    repr(v)
}
