//! Value representations.

use super::content::Content;
use super::value::{Dynamic, Func, Selector, Value};

/// Format a float with Rust's Display (never exponential), with Unicode minus.
pub fn display_float(v: f64) -> String {
    if v.is_nan() {
        return "NaN".into();
    }
    if v.is_infinite() {
        return if v < 0.0 { "\u{2212}\u{221E}".into() } else { "\u{221E}".into() };
    }
    if v < 0.0 {
        format!("\u{2212}{}", -v)
    } else {
        format!("{}", v)
    }
}

/// Format an integer for display with Unicode minus.
pub fn display_int(v: i64) -> String {
    if v < 0 {
        format!("\u{2212}{}", (v as i128).unsigned_abs())
    } else {
        format!("{v}")
    }
}

pub fn format_int_with_base(mut n: i64, base: i64) -> String {
    if n == 0 {
        return "0".into();
    }
    let negative = n < 0;
    let mut digits = Vec::new();
    let mut m: i128 = (n as i128).abs();
    let _ = &mut n;
    while m > 0 {
        let d = (m % base as i128) as u32;
        digits.push(std::char::from_digit(d, base as u32).unwrap());
        m /= base as i128;
    }
    let mut s = String::new();
    if negative {
        s.push('\u{2212}');
    }
    s.extend(digits.iter().rev());
    s
}

/// Rust's Debug formatting for floats, with special values.
pub fn repr_float(v: f64) -> String {
    if v.is_nan() {
        "float.nan".into()
    } else if v.is_infinite() {
        if v < 0.0 { "-float.inf".into() } else { "float.inf".into() }
    } else {
        format!("{v:?}")
    }
}

/// Format a float rounded to two decimals with a unit (for lengths etc.).
pub fn format_float_unit(value: f64, unit: &str) -> String {
    let offset = 100.0;
    let rounded = (value * offset).round() / offset;
    if rounded.is_nan() {
        return format!("NaN{unit}");
    }
    if rounded.is_infinite() {
        return if rounded < 0.0 { format!("-inf{unit}") } else { format!("inf{unit}") };
    }
    format!("{}{unit}", rounded)
}

/// Format a float rounded with precision for repr with a unit, forcing nothing.
pub fn format_float_prec(value: f64, precision: u8) -> String {
    let offset = 10f64.powi(precision as i32);
    let rounded = (value * offset).round() / offset;
    format!("{}", rounded)
}

pub fn pretty_comma_list(pieces: &[String], trailing_comma: bool) -> String {
    const MAX_WIDTH: usize = 50;
    let mut buf = String::new();
    let len = pieces.iter().map(|s| s.len()).sum::<usize>() + 2 * pieces.len().saturating_sub(1);
    let separator =
        if len >= MAX_WIDTH || pieces.iter().any(|p| p.contains('\n')) { ",\n" } else { ", " };
    for (i, piece) in pieces.iter().enumerate() {
        if i > 0 {
            buf.push_str(separator);
        }
        buf.push_str(piece);
    }
    if trailing_comma || separator == ",\n" {
        buf.push(',');
    }
    buf
}

pub fn pretty_array_like(parts: &[String], trailing_comma: bool) -> String {
    let list = pretty_comma_list(parts, trailing_comma);
    let mut buf = String::new();
    buf.push('(');
    if list.contains('\n') {
        buf.push('\n');
        for (i, line) in list.lines().enumerate() {
            if i > 0 {
                buf.push('\n');
            }
            buf.push_str("  ");
            buf.push_str(line);
        }
        buf.push('\n');
    } else {
        buf.push_str(&list);
    }
    buf.push(')');
    buf
}

pub fn repr_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() || c == '\u{7f}' => out.push_str(&format!("\\u{{{:x}}}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

pub fn is_ident(s: &str) -> bool {
    crate::syntax::lexer::is_ident(s)
}

pub fn repr_dict_key(k: &str) -> String {
    if is_ident(k) { k.to_string() } else { repr_str(k) }
}

pub fn repr_label(name: &str) -> String {
    if is_ident(name) || name.chars().all(|c| crate::syntax::lexer::is_id_continue(c) || c == ':' || c == '.') && !name.is_empty() && name.chars().next().is_some_and(crate::syntax::lexer::is_id_continue) {
        format!("<{name}>")
    } else {
        format!("label({})", repr_str(name))
    }
}

pub fn repr(v: &Value) -> String {
    match v {
        Value::None => "none".into(),
        Value::Auto => "auto".into(),
        Value::Bool(b) => b.to_string(),
        Value::Int(i) => i.to_string(),
        Value::Float(f) => repr_float(*f),
        Value::Length(l) => l.repr(),
        Value::Angle(a) => format_float_unit(a.to_degrees(), "deg"),
        Value::Ratio(r) => format_float_unit(r * 100.0, "%"),
        Value::Relative(r) => r.repr(),
        Value::Fraction(f) => format_float_unit(*f, "fr"),
        Value::Color(c) => c.repr(),
        Value::Gradient(g) => repr_gradient(g),
        Value::Symbol(s) => {
            if s.variants.len() <= 1 {
                format!("symbol({})", repr_str(&s.text))
            } else {
                let pieces: Vec<String> = s
                    .variants
                    .iter()
                    .map(|(k, v)| {
                        if k.is_empty() {
                            repr_str(v)
                        } else {
                            format!("({}, {})", repr_str(k), repr_str(v))
                        }
                    })
                    .collect();
                format!("symbol{}", pretty_array_like(&pieces, false))
            }
        }
        Value::Version(v) => {
            let parts: Vec<String> = v.iter().map(|n| n.to_string()).collect();
            format!("version({})", parts.join(", "))
        }
        Value::Str(s) => repr_str(s),
        Value::Bytes(b) => format!("bytes({})", b.len()),
        Value::Label(l) => repr_label(l),
        Value::Datetime(d) => d.repr(),
        Value::Duration(d) => d.repr(),
        Value::Content(c) => repr_content(c),
        Value::Styles(_) => "styles(..)".into(),
        Value::Array(a) => {
            let pieces: Vec<String> = a.iter().map(repr).collect();
            pretty_array_like(&pieces, a.len() == 1)
        }
        Value::Dict(d) => {
            if d.is_empty() {
                return "(:)".into();
            }
            let pieces: Vec<String> =
                d.iter().map(|(k, v)| format!("{}: {}", repr_dict_key(k), repr(v))).collect();
            pretty_array_like(&pieces, false)
        }
        Value::Func(f) => repr_func(f),
        Value::Args(a) => {
            let pieces: Vec<String> = a
                .items
                .iter()
                .map(|arg| match &arg.name {
                    Some(n) => format!("{}: {}", n, repr(&arg.value)),
                    None => repr(&arg.value),
                })
                .collect();
            format!("arguments{}", pretty_array_like(&pieces, false))
        }
        Value::Type(t) => t.repr(),
        Value::Module(m) => format!("<module {}>", m.name),
        Value::Dyn(d) => repr_dyn(d),
    }
}

pub fn repr_func(f: &Func) -> String {
    match f {
        Func::Native(n) => n.name.to_string(),
        Func::Elem(e) => e.to_string(),
        Func::Closure(c) => match &c.ast.name {
            Some(n) => n.name.clone(),
            None => "(..) => ..".into(),
        },
        Func::With(_) => "(..) => ..".into(),
    }
}

fn repr_gradient(g: &super::value::Gradient) -> String {
    let mut pieces: Vec<String> = Vec::new();
    for (k, v) in &g.extra {
        pieces.push(format!("{k}: {}", repr(v)));
    }
    if g.kind == "linear" && g.angle != 0.0 {
        pieces.push(format!("angle: {}", format_float_unit(g.angle.to_degrees(), "deg")));
    }
    for (c, pos) in &g.stops {
        pieces.push(format!("({}, {})", c.repr(), format_float_unit(pos * 100.0, "%")));
    }
    format!("gradient.{}{}", g.kind, pretty_array_like(&pieces, false))
}

pub fn repr_selector(s: &Selector) -> String {
    match s {
        Selector::Elem(name, None) => name.to_string(),
        Selector::Elem(name, Some(fields)) => {
            let pieces: Vec<String> =
                fields.iter().map(|(k, v)| format!("{}: {}", repr_dict_key(k), repr(v))).collect();
            format!("{name}.where{}", pretty_array_like(&pieces, false))
        }
        Selector::Label(l) => repr_label(l),
        Selector::Regex(r) => format!("regex({})", repr_str(&r.source)),
        Selector::Str(s) => format!("regex({})", repr_str(&regex::escape(s))),
        Selector::Or(items) => {
            let pieces: Vec<String> = items.iter().map(repr_selector).collect();
            format!("selector.or{}", pretty_array_like(&pieces, false))
        }
        Selector::And(items) => {
            let pieces: Vec<String> = items.iter().map(repr_selector).collect();
            format!("selector.and{}", pretty_array_like(&pieces, false))
        }
        Selector::Before { selector, end, inclusive } => {
            let mut pieces = vec![repr_selector(end)];
            if !inclusive {
                pieces.push("inclusive: false".into());
            }
            format!("{}.before{}", repr_selector(selector), pretty_array_like(&pieces, false))
        }
        Selector::After { selector, start, inclusive } => {
            let mut pieces = vec![repr_selector(start)];
            if !inclusive {
                pieces.push("inclusive: false".into());
            }
            format!("{}.after{}", repr_selector(selector), pretty_array_like(&pieces, false))
        }
        Selector::Location(_) => "location(..)".into(),
    }
}

fn repr_dyn(d: &Dynamic) -> String {
    match d {
        Dynamic::Regex(r) => format!("regex({})", repr_str(&r.source)),
        Dynamic::Selector(s) => repr_selector(s),
        Dynamic::Stroke(s) => repr_stroke(s),
        Dynamic::Alignment(a) => a.repr(),
        Dynamic::Direction(d) => d.repr().to_string(),
        Dynamic::Decimal(d) => format!("decimal({})", repr_str(&super::decimal::to_string(d))),
        Dynamic::Counter(key) => format!("counter({})", repr(key)),
        Dynamic::State(key, init) => format!("state({}, {})", repr_str(key), repr(init)),
        Dynamic::Location(_) => "location(..)".into(),
        Dynamic::Tiling => "tiling(..)".into(),
    }
}

pub fn repr_stroke(s: &super::value::Stroke) -> String {
    let set: Vec<(&str, &Value)> = [
        ("paint", &s.paint),
