//! Colors.

use super::repr::{format_float_unit, repr_str};

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Color {
    Luma(f32, f32),
    Oklab(f32, f32, f32, f32),
    Oklch(f32, f32, f32, f32),
    Rgb(f32, f32, f32, f32),
    LinearRgb(f32, f32, f32, f32),
    Cmyk(f32, f32, f32, f32),
    Hsl(f32, f32, f32, f32),
    Hsv(f32, f32, f32, f32),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Space {
    Luma,
    Oklab,
    Oklch,
    Rgb,
    LinearRgb,
    Cmyk,
    Hsl,
    Hsv,
}

impl Space {
    pub fn name(self) -> &'static str {
        match self {
            Space::Luma => "luma",
            Space::Oklab => "oklab",
            Space::Oklch => "oklch",
            Space::Rgb => "rgb",
            Space::LinearRgb => "color.linear-rgb",
            Space::Cmyk => "cmyk",
            Space::Hsl => "color.hsl",
            Space::Hsv => "color.hsv",
        }
    }
}

fn srgb_to_linear(c: f32) -> f32 {
    if c <= 0.04045 { c / 12.92 } else { ((c + 0.055) / 1.055).powf(2.4) }
}

fn linear_to_srgb(c: f32) -> f32 {
    if c <= 0.0031308 { c * 12.92 } else { 1.055 * c.powf(1.0 / 2.4) - 0.055 }
}

fn round2(v: f32) -> f32 {
    (v * 100.0).round() / 100.0
}

impl Color {
    pub const BLACK: Color = Color::Luma(0.0, 1.0);
    pub const WHITE: Color = Color::Luma(1.0, 1.0);

    pub fn from_u8(r: u8, g: u8, b: u8, a: u8) -> Color {
        Color::Rgb(r as f32 / 255.0, g as f32 / 255.0, b as f32 / 255.0, a as f32 / 255.0)
    }

    pub fn space(&self) -> Space {
        match self {
            Color::Luma(..) => Space::Luma,
            Color::Oklab(..) => Space::Oklab,
            Color::Oklch(..) => Space::Oklch,
            Color::Rgb(..) => Space::Rgb,
            Color::LinearRgb(..) => Space::LinearRgb,
            Color::Cmyk(..) => Space::Cmyk,
            Color::Hsl(..) => Space::Hsl,
            Color::Hsv(..) => Space::Hsv,
        }
    }

    pub fn alpha(&self) -> Option<f32> {
        match self {
            Color::Luma(_, a)
            | Color::Oklab(_, _, _, a)
            | Color::Oklch(_, _, _, a)
            | Color::Rgb(_, _, _, a)
            | Color::LinearRgb(_, _, _, a)
            | Color::Hsl(_, _, _, a)
            | Color::Hsv(_, _, _, a) => Some(*a),
            Color::Cmyk(..) => None,
        }
    }

    pub fn with_alpha(self, alpha: f32) -> Color {
        match self {
            Color::Luma(l, _) => Color::Luma(l, alpha),
            Color::Oklab(a, b, c, _) => Color::Oklab(a, b, c, alpha),
            Color::Oklch(a, b, c, _) => Color::Oklch(a, b, c, alpha),
            Color::Rgb(a, b, c, _) => Color::Rgb(a, b, c, alpha),
            Color::LinearRgb(a, b, c, _) => Color::LinearRgb(a, b, c, alpha),
            Color::Hsl(a, b, c, _) => Color::Hsl(a, b, c, alpha),
            Color::Hsv(a, b, c, _) => Color::Hsv(a, b, c, alpha),
            Color::Cmyk(..) => self,
        }
    }

    /// Convert to linear RGB (with alpha).
    pub fn to_linear_rgb(&self) -> (f32, f32, f32, f32) {
        match *self {
            Color::LinearRgb(r, g, b, a) => (r, g, b, a),
            Color::Rgb(r, g, b, a) => (srgb_to_linear(r), srgb_to_linear(g), srgb_to_linear(b), a),
            Color::Luma(l, a) => {
                let v = srgb_to_linear(l);
                (v, v, v, a)
            }
            Color::Cmyk(c, m, y, k) => {
                let r = (1.0 - c) * (1.0 - k);
                let g = (1.0 - m) * (1.0 - k);
                let b = (1.0 - y) * (1.0 - k);
                (srgb_to_linear(r), srgb_to_linear(g), srgb_to_linear(b), 1.0)
            }
            Color::Hsl(h, s, l, a) => {
                let (r, g, b) = hsl_to_rgb(h, s, l);
                (srgb_to_linear(r), srgb_to_linear(g), srgb_to_linear(b), a)
            }
            Color::Hsv(h, s, v, a) => {
                let (r, g, b) = hsv_to_rgb(h, s, v);
                (srgb_to_linear(r), srgb_to_linear(g), srgb_to_linear(b), a)
            }
            Color::Oklab(l, aa, bb, a) => {
                let (r, g, b) = oklab_to_linear(l, aa, bb);
                (r, g, b, a)
            }
            Color::Oklch(l, c, h, a) => {
                let hr = h.to_radians();
                let (r, g, b) = oklab_to_linear(l, c * hr.cos(), c * hr.sin());
                (r, g, b, a)
            }
        }
    }

    pub fn to_rgb_tuple(&self) -> (f32, f32, f32, f32) {
        match *self {
            Color::Rgb(r, g, b, a) => (r, g, b, a),
            Color::Luma(l, a) => (l, l, l, a),
            Color::Cmyk(c, m, y, k) => ((1.0 - c) * (1.0 - k), (1.0 - m) * (1.0 - k), (1.0 - y) * (1.0 - k), 1.0),
            Color::Hsl(h, s, l, a) => {
                let (r, g, b) = hsl_to_rgb(h, s, l);
                (r, g, b, a)
            }
            Color::Hsv(h, s, v, a) => {
                let (r, g, b) = hsv_to_rgb(h, s, v);
                (r, g, b, a)
            }
            _ => {
                let (r, g, b, a) = self.to_linear_rgb();
                (linear_to_srgb(r), linear_to_srgb(g), linear_to_srgb(b), a)
            }
        }
    }

    pub fn to_space(&self, space: Space) -> Color {
        if self.space() == space {
            return *self;
        }
        match space {
            Space::Rgb => {
                let (r, g, b, a) = self.to_rgb_tuple();
                Color::Rgb(r, g, b, a)
            }
            Space::LinearRgb => {
                let (r, g, b, a) = self.to_linear_rgb();
                Color::LinearRgb(r, g, b, a)
            }
            Space::Luma => {
                let (r, g, b, a) = self.to_linear_rgb();
                let y = 0.2126 * r + 0.7152 * g + 0.0722 * b;
                Color::Luma(linear_to_srgb(y), a)
            }
            Space::Cmyk => {
                let (r, g, b, _) = self.to_rgb_tuple();
                let k = 1.0 - r.max(g).max(b);
                if k >= 1.0 {
                    return Color::Cmyk(0.0, 0.0, 0.0, 1.0);
                }
                let c = (1.0 - r - k) / (1.0 - k);
                let m = (1.0 - g - k) / (1.0 - k);
                let y = (1.0 - b - k) / (1.0 - k);
                Color::Cmyk(c, m, y, k)
            }
            Space::Hsl => {
                let (r, g, b, a) = self.to_rgb_tuple();
                let (h, s, l) = rgb_to_hsl(r, g, b);
                Color::Hsl(h, s, l, a)
            }
            Space::Hsv => {
                let (r, g, b, a) = self.to_rgb_tuple();
                let (h, s, v) = rgb_to_hsv(r, g, b);
                Color::Hsv(h, s, v, a)
            }
            Space::Oklab => {
                if let Color::Oklch(l, c, h, a) = *self {
                    let hr = h.to_radians();
                    return Color::Oklab(l, c * hr.cos(), c * hr.sin(), a);
                }
                let (r, g, b, a) = self.to_linear_rgb();
                let (l, aa, bb) = linear_to_oklab(r, g, b);
                Color::Oklab(l, aa, bb, a)
            }
            Space::Oklch => {
                let (l, aa, bb, a) = match *self {
                    Color::Oklab(l, aa, bb, a) => (l, aa, bb, a),
                    _ => {
                        let (r, g, b, a) = self.to_linear_rgb();
                        let (l, aa, bb) = linear_to_oklab(r, g, b);
                        (l, aa, bb, a)
                    }
                };
                let c = (aa * aa + bb * bb).sqrt();
                let mut h = bb.atan2(aa).to_degrees();
                if h < 0.0 {
                    h += 360.0;
                }
                if c < 1e-6 {
                    h = 0.0;
                }
                Color::Oklch(l, c, h, a)
            }
        }
    }

    pub fn to_hex(&self) -> String {
        let (r, g, b, a) = self.to_rgb_tuple();
        let f = |v: f32| (v.clamp(0.0, 1.0) * 255.0).round() as u8;
        let (r, g, b, a) = (f(r), f(g), f(b), f(a));
        if a != 255 {
            format!("#{r:02x}{g:02x}{b:02x}{a:02x}")
        } else {
            format!("#{r:02x}{g:02x}{b:02x}")
        }
    }

    fn alpha_piece(a: f32) -> Option<String> {
        if a != 1.0 { Some(format_float_unit((a * 100.0) as f64, "%")) } else { None }
    }

    pub fn repr(&self) -> String {
        let pct = |v: f32| format_float_unit((v * 100.0) as f64, "%");
        let num = |v: f32| {
            let r = round2(v);
            format!("{}", if r == 0.0 { 0.0 } else { r })
        };
        let deg = |v: f32| format_float_unit(v as f64, "deg");
        match *self {
            Color::Luma(l, a) => match Color::alpha_piece(a) {
                Some(ap) => format!("luma({}, {})", pct(l), ap),
                None => format!("luma({})", pct(l)),
            },
            Color::Rgb(..) => format!("rgb({})", repr_str(&self.to_hex())),
            Color::LinearRgb(r, g, b, a) => {
                let mut s = format!("color.linear-rgb({}, {}, {}", pct(r), pct(g), pct(b));
                if let Some(ap) = Color::alpha_piece(a) {
                    s.push_str(&format!(", {ap}"));
                }
                s.push(')');
                s
            }
            Color::Cmyk(c, m, y, k) => format!("cmyk({}, {}, {}, {})", pct(c), pct(m), pct(y), pct(k)),
            Color::Oklab(l, aa, bb, a) => {
                let mut s = format!("oklab({}, {}, {}", pct(l), num3(aa), num3(bb));
                if let Some(ap) = Color::alpha_piece(a) {
                    s.push_str(&format!(", {ap}"));
                }
                s.push(')');
                let _ = num;
                s
            }
            Color::Oklch(l, c, h, a) => {
                let mut s = format!("oklch({}, {}, {}", pct(l), num3(c), deg(h));
                if let Some(ap) = Color::alpha_piece(a) {
                    s.push_str(&format!(", {ap}"));
                }
                s.push(')');
                s
            }
            Color::Hsl(h, sat, l, a) => {
                let mut s = format!("color.hsl({}, {}, {}", deg(h), pct(sat), pct(l));
                if let Some(ap) = Color::alpha_piece(a) {
                    s.push_str(&format!(", {ap}"));
                }
                s.push(')');
                s
            }
            Color::Hsv(h, sat, v, a) => {
                let mut s = format!("color.hsv({}, {}, {}", deg(h), pct(sat), pct(v));
                if let Some(ap) = Color::alpha_piece(a) {
                    s.push_str(&format!(", {ap}"));
                }
                s.push(')');
                s
            }
        }
    }

    /// Components as values (ratios / angles / floats).
    pub fn components(&self, alpha: bool) -> Vec<super::value::Value> {
        use super::value::Value;
        let ratio = |v: f32| Value::Ratio(v as f64);
        let angle = |v: f32| Value::Angle((v as f64).to_radians());
        let float = |v: f32| Value::Float(v as f64);
        let mut out = match *self {
            Color::Luma(l, a) => vec![ratio(l), ratio(a)],
            Color::Oklab(l, aa, bb, a) => vec![ratio(l), float(aa), float(bb), ratio(a)],
            Color::Oklch(l, c, h, a) => vec![ratio(l), float(c), angle(h), ratio(a)],
            Color::Rgb(r, g, b, a) => vec![ratio(r), ratio(g), ratio(b), ratio(a)],
            Color::LinearRgb(r, g, b, a) => vec![ratio(r), ratio(g), ratio(b), ratio(a)],
            Color::Cmyk(c, m, y, k) => vec![ratio(c), ratio(m), ratio(y), ratio(k)],
            Color::Hsl(h, s, l, a) => vec![angle(h), ratio(s), ratio(l), ratio(a)],
            Color::Hsv(h, s, v, a) => vec![angle(h), ratio(s), ratio(v), ratio(a)],
        };
        if !alpha && !matches!(self, Color::Cmyk(..)) {
            out.pop();
        }
        out
    }

    pub fn lighten(&self, factor: f32) -> Color {
        match *self {
            Color::Luma(l, a) => Color::Luma(l + (1.0 - l) * factor, a),
            Color::Oklab(l, aa, bb, a) => Color::Oklab(l + (1.0 - l) * factor, aa, bb, a),
            Color::Oklch(l, c, h, a) => Color::Oklch(l + (1.0 - l) * factor, c, h, a),
            Color::Hsl(h, s, l, a) => Color::Hsl(h, s, l + (1.0 - l) * factor, a),
            Color::Hsv(h, s, v, a) => Color::Hsv(h, s, v + (1.0 - v) * factor, a),
            Color::Rgb(r, g, b, a) => {
                Color::Rgb(r + (1.0 - r) * factor, g + (1.0 - g) * factor, b + (1.0 - b) * factor, a)
            }
            Color::LinearRgb(r, g, b, a) => {
                Color::LinearRgb(r + (1.0 - r) * factor, g + (1.0 - g) * factor, b + (1.0 - b) * factor, a)
            }
            Color::Cmyk(c, m, y, k) => {
                Color::Cmyk(c - c * factor, m - m * factor, y - y * factor, k - k * factor)
            }
        }
    }

    pub fn darken(&self, factor: f32) -> Color {
        match *self {
            Color::Luma(l, a) => Color::Luma(l - l * factor, a),
            Color::Oklab(l, aa, bb, a) => Color::Oklab(l - l * factor, aa, bb, a),
            Color::Oklch(l, c, h, a) => Color::Oklch(l - l * factor, c, h, a),
            Color::Hsl(h, s, l, a) => Color::Hsl(h, s, l - l * factor, a),
            Color::Hsv(h, s, v, a) => Color::Hsv(h, s, v - v * factor, a),
            Color::Rgb(r, g, b, a) => Color::Rgb(r - r * factor, g - g * factor, b - b * factor, a),
            Color::LinearRgb(r, g, b, a) => {
                Color::LinearRgb(r - r * factor, g - g * factor, b - b * factor, a)
            }
            Color::Cmyk(c, m, y, k) => Color::Cmyk(
                c + (1.0 - c) * factor,
                m + (1.0 - m) * factor,
                y + (1.0 - y) * factor,
                k + (1.0 - k) * factor,
            ),
        }
    }

    pub fn negate(&self, space: Space) -> Color {
        let c = self.to_space(space);
        let neg = match c {
            Color::Luma(l, a) => Color::Luma(1.0 - l, a),
            Color::Oklab(l, aa, bb, a) => Color::Oklab(1.0 - l, -aa, -bb, a),
            Color::Oklch(l, c, h, a) => Color::Oklch(1.0 - l, c, (h + 180.0) % 360.0, a),
            Color::Rgb(r, g, b, a) => Color::Rgb(1.0 - r, 1.0 - g, 1.0 - b, a),
            Color::LinearRgb(r, g, b, a) => Color::LinearRgb(1.0 - r, 1.0 - g, 1.0 - b, a),
            Color::Cmyk(c, m, y, k) => Color::Cmyk(1.0 - c, 1.0 - m, 1.0 - y, 1.0 - k),
            Color::Hsl(h, s, l, a) => Color::Hsl((h + 180.0) % 360.0, s, 1.0 - l, a),
            Color::Hsv(h, s, v, a) => Color::Hsv((h + 180.0) % 360.0, s, 1.0 - v, a),
        };
        neg.to_space(self.space())
    }

    pub fn rotate(&self, angle_deg: f32, space: Space) -> Color {
        let c = self.to_space(space);
        let rotated = match c {
            Color::Oklch(l, ch, h, a) => Color::Oklch(l, ch, (h + angle_deg).rem_euclid(360.0), a),
            Color::Hsl(h, s, l, a) => Color::Hsl((h + angle_deg).rem_euclid(360.0), s, l, a),
            Color::Hsv(h, s, v, a) => Color::Hsv((h + angle_deg).rem_euclid(360.0), s, v, a),
            other => other,
        };
        rotated.to_space(self.space())
    }

    pub fn saturate(&self, factor: f32, space: Space) -> Color {
        let c = self.to_space(space);
        let sat = match c {
            Color::Hsl(h, s, l, a) => Color::Hsl(h, s + (1.0 - s) * factor, l, a),
            Color::Hsv(h, s, v, a) => Color::Hsv(h, s + (1.0 - s) * factor, v, a),
            other => other,
        };
        sat.to_space(self.space())
    }

    pub fn desaturate(&self, factor: f32, space: Space) -> Color {
        let c = self.to_space(space);
        let sat = match c {
            Color::Hsl(h, s, l, a) => Color::Hsl(h, s - s * factor, l, a),
            Color::Hsv(h, s, v, a) => Color::Hsv(h, s - s * factor, v, a),
            other => other,
        };
        sat.to_space(self.space())
    }

    /// Mix colors with weights in the given space.
    pub fn mix(colors: &[(Color, f32)], space: Space) -> Color {
        let mut total = 0.0f32;
        let mut acc = [0.0f32; 4];
        for (color, weight) in colors {
            let c = color.to_space(space);
            let comps = c.raw_components();
            let w = *weight;
            if space == Space::Oklch || space == Space::Hsl || space == Space::Hsv {
                // Mix hue via vector.
                // Fallback: simple weighted average of components.
            }
            for i in 0..4 {
                acc[i] += comps[i] * w;
            }
            total += w;
        }
        if total == 0.0 {
            total = 1.0;
        }
        for v in &mut acc {
            *v /= total;
        }
        Color::from_raw(space, acc)
    }

    fn raw_components(&self) -> [f32; 4] {
        match *self {
            Color::Luma(l, a) => [l, a, 0.0, 0.0],
            Color::Oklab(l, aa, bb, a) => [l, aa, bb, a],
            Color::Oklch(l, c, h, a) => [l, c, h, a],
            Color::Rgb(r, g, b, a) => [r, g, b, a],
            Color::LinearRgb(r, g, b, a) => [r, g, b, a],
            Color::Cmyk(c, m, y, k) => [c, m, y, k],
            Color::Hsl(h, s, l, a) => [h, s, l, a],
            Color::Hsv(h, s, v, a) => [h, s, v, a],
        }
    }

    fn from_raw(space: Space, c: [f32; 4]) -> Color {
        match space {
            Space::Luma => Color::Luma(c[0], c[1]),
            Space::Oklab => Color::Oklab(c[0], c[1], c[2], c[3]),
            Space::Oklch => Color::Oklch(c[0], c[1], c[2], c[3]),
            Space::Rgb => Color::Rgb(c[0], c[1], c[2], c[3]),
            Space::LinearRgb => Color::LinearRgb(c[0], c[1], c[2], c[3]),
            Space::Cmyk => Color::Cmyk(c[0], c[1], c[2], c[3]),
            Space::Hsl => Color::Hsl(c[0], c[1], c[2], c[3]),
            Space::Hsv => Color::Hsv(c[0], c[1], c[2], c[3]),
        }
    }

    pub fn from_hex(s: &str) -> Result<Color, String> {
        let hex = s.trim_start_matches('#');
        if !hex.chars().all(|c| c.is_ascii_hexdigit()) {
            return Err("color string contains non-hexadecimal letters".into());
        }
        let len = hex.len();
        let long = len == 6 || len == 8;
        let short = len == 3 || len == 4;
        if !long && !short {
            return Err("color string has wrong length".into());
        }
        let alpha = len == 4 || len == 8;
        let mut values = [255u8; 4];
        for (i, slot) in values.iter_mut().enumerate() {
            if i == 3 && !alpha {
                break;
            }
            let v = if long {
                u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).unwrap()
            } else {
                let d = u8::from_str_radix(&hex[i..i + 1], 16).unwrap();
                d * 16 + d
            };
            *slot = v;
        }
        Ok(Color::from_u8(values[0], values[1], values[2], values[3]))
    }
}

fn num3(v: f32) -> String {
    let r = (v * 1000.0).round() / 1000.0;
    let r = if r == 0.0 { 0.0 } else { r };
    format!("{r}")
}

fn hsl_to_rgb(h: f32, s: f32, l: f32) -> (f32, f32, f32) {
    let h = h.rem_euclid(360.0);
    let c = (1.0 - (2.0 * l - 1.0).abs()) * s;
    let hp = h / 60.0;
    let x = c * (1.0 - (hp % 2.0 - 1.0).abs());
    let (r1, g1, b1) = if hp < 1.0 {
        (c, x, 0.0)
    } else if hp < 2.0 {
        (x, c, 0.0)
    } else if hp < 3.0 {
        (0.0, c, x)
    } else if hp < 4.0 {
        (0.0, x, c)
    } else if hp < 5.0 {
        (x, 0.0, c)
    } else {
        (c, 0.0, x)
    };
    let m = l - c / 2.0;
    (r1 + m, g1 + m, b1 + m)
}

fn hsv_to_rgb(h: f32, s: f32, v: f32) -> (f32, f32, f32) {
    let h = h.rem_euclid(360.0);
    let c = v * s;
    let hp = h / 60.0;
    let x = c * (1.0 - (hp % 2.0 - 1.0).abs());
    let (r1, g1, b1) = if hp < 1.0 {
        (c, x, 0.0)
    } else if hp < 2.0 {
        (x, c, 0.0)
    } else if hp < 3.0 {
        (0.0, c, x)
    } else if hp < 4.0 {
        (0.0, x, c)
    } else if hp < 5.0 {
        (x, 0.0, c)
    } else {
        (c, 0.0, x)
    };
    let m = v - c;
    (r1 + m, g1 + m, b1 + m)
}

fn rgb_to_hsl(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let l = (max + min) / 2.0;
    let d = max - min;
    if d.abs() < 1e-7 {
        return (0.0, 0.0, l);
    }
    let s = d / (1.0 - (2.0 * l - 1.0).abs());
    let h = hue(r, g, b, max, d);
    (h, s, l)
}

fn rgb_to_hsv(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let d = max - min;
    let v = max;
    if d.abs() < 1e-7 {
        return (0.0, 0.0, v);
    }
    let s = if max == 0.0 { 0.0 } else { d / max };
    let h = hue(r, g, b, max, d);
    (h, s, v)
}

fn hue(r: f32, g: f32, b: f32, max: f32, d: f32) -> f32 {
    let mut h = if max == r {
        (g - b) / d
    } else if max == g {
        (b - r) / d + 2.0
    } else {
        (r - g) / d + 4.0
    };
    h *= 60.0;
    if h < 0.0 {
        h += 360.0;
    }
    h
}

fn linear_to_oklab(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let l = 0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b;
    let m = 0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b;
    let s = 0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b;
    let l_ = l.cbrt();
    let m_ = m.cbrt();
    let s_ = s.cbrt();
    (
        0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_,
        1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_,
        0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_,
    )
}

fn oklab_to_linear(l: f32, a: f32, b: f32) -> (f32, f32, f32) {
    let l_ = l + 0.3963377774 * a + 0.2158037573 * b;
    let m_ = l - 0.1055613458 * a - 0.0638541728 * b;
    let s_ = l - 0.0894841775 * a - 1.2914855480 * b;
    let l3 = l_ * l_ * l_;
    let m3 = m_ * m_ * m_;
    let s3 = s_ * s_ * s_;
    (
        4.0767416621 * l3 - 3.3077115913 * m3 + 0.2309699292 * s3,
        -1.2684380046 * l3 + 2.6097574011 * m3 - 0.3413193965 * s3,
        -0.0041960863 * l3 - 0.7034186147 * m3 + 1.7076147010 * s3,
    )
}

/// Named colors.
