    }
    let mut frac = frac_part.to_string();
    if frac.len() > MAX_SCALE as usize {
        frac.truncate(MAX_SCALE as usize);
    }
    let digits = format!("{int_part}{frac}");
    let mantissa: i128 = if digits.is_empty() { 0 } else { digits.parse().ok()? };
    if mantissa > 79228162514264337593543950335 {
        return None;
    }
    Some(Decimal { mantissa: if neg { -mantissa } else { mantissa }, scale: frac.len() as u32 })
}

pub fn from_f64(f: f64) -> Option<Decimal> {
    if !f.is_finite() {
        return None;
    }
    let s = format!("{}", f);
    parse(&s)
}

pub fn to_string(d: &Decimal) -> String {
    let neg = d.mantissa < 0;
    let digits = d.mantissa.unsigned_abs().to_string();
    let scale = d.scale as usize;
    let mut s = String::new();
    if neg {
        s.push('-');
    }
    if scale == 0 {
        s.push_str(&digits);
    } else if digits.len() <= scale {
        s.push_str("0.");
        for _ in 0..(scale - digits.len()) {
            s.push('0');
        }
        s.push_str(&digits);
    } else {
        let (a, b) = digits.split_at(digits.len() - scale);
        s.push_str(a);
        s.push('.');
        s.push_str(b);
    }
    s
}

pub fn to_f64(d: &Decimal) -> f64 {
    d.mantissa as f64 / 10f64.powi(d.scale as i32)
}

fn align(a: &Decimal, b: &Decimal) -> (i128, i128, u32) {
    let scale = a.scale.max(b.scale);
    let ma = a.mantissa * 10i128.pow(scale - a.scale);
    let mb = b.mantissa * 10i128.pow(scale - b.scale);
    (ma, mb, scale)
}

pub fn cmp(a: &Decimal, b: &Decimal) -> Ordering {
    let (ma, mb, _) = align(a, b);
    ma.cmp(&mb)
}

fn check(m: i128) -> Result<i128, String> {
    if m.abs() > 79228162514264337593543950335 {
        Err("value is too large".into())
    } else {
        Ok(m)
    }
}

pub fn add(a: &Decimal, b: &Decimal) -> Result<Decimal, String> {
    let (ma, mb, scale) = align(a, b);
    Ok(Decimal { mantissa: check(ma + mb)?, scale })
}

pub fn sub(a: &Decimal, b: &Decimal) -> Result<Decimal, String> {
    let (ma, mb, scale) = align(a, b);
    Ok(Decimal { mantissa: check(ma - mb)?, scale })
}

pub fn mul(a: &Decimal, b: &Decimal) -> Result<Decimal, String> {
    let mut mantissa = a.mantissa.checked_mul(b.mantissa).ok_or("value is too large")?;
    let mut scale = a.scale + b.scale;
    while scale > MAX_SCALE {
        mantissa /= 10;
        scale -= 1;
    }
    Ok(Decimal { mantissa: check(mantissa)?, scale })
}

pub fn div(a: &Decimal, b: &Decimal) -> Result<Decimal, String> {
    if b.mantissa == 0 {
        return Err("cannot divide by zero".into());
    }
    // Scale the numerator up to get 28 fractional digits.
    let mut num = a.mantissa;
    let mut scale = a.scale as i64 - b.scale as i64;
    let mut extra = 0u32;
    while extra < MAX_SCALE && num.checked_mul(10).is_some() && (scale + extra as i64) < MAX_SCALE as i64 {
        num *= 10;
        extra += 1;
    }
    let mut mantissa = num / b.mantissa;
    let mut final_scale = scale + extra as i64;
    while final_scale < 0 {
        mantissa *= 10;
        final_scale += 1;
    }
    // Strip trailing zeros.
    while final_scale > 0 && mantissa % 10 == 0 {
        mantissa /= 10;
        final_scale -= 1;
    }
    let _ = &mut scale;
    Ok(Decimal { mantissa: check(mantissa)?, scale: final_scale as u32 })
}

pub fn normalize(d: &Decimal) -> Decimal {
    let mut m = d.mantissa;
    let mut s = d.scale;
    while s > 0 && m % 10 == 0 {
        m /= 10;
        s -= 1;
    }
    Decimal { mantissa: m, scale: s }
}
