//! Dates, times and durations.

use std::cmp::Ordering;

use super::repr::pretty_array_like;

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Datetime {
    pub date: Option<(i32, u8, u8)>,
    pub time: Option<(u8, u8, u8)>,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Duration {
    /// Total seconds (may be fractional).
    pub seconds: f64,
}

pub fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = (m as i64 + 9) % 12;
    let doy = (153 * mp + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

pub fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

pub fn is_leap(y: i32) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

pub fn days_in_month(y: i32, m: u8) -> u8 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if is_leap(y) {
                29
            } else {
                28
            }
        }
        _ => 0,
    }
}

impl Datetime {
    pub fn valid_date(y: i32, m: u8, d: u8) -> bool {
        (1..=12).contains(&m) && d >= 1 && d <= days_in_month(y, m)
    }

    pub fn repr(&self) -> String {
        let mut pieces = Vec::new();
        if let Some((y, m, d)) = self.date {
            pieces.push(format!("year: {y}"));
            pieces.push(format!("month: {m}"));
            pieces.push(format!("day: {d}"));
        }
        if let Some((h, mi, s)) = self.time {
            pieces.push(format!("hour: {h}"));
            pieces.push(format!("minute: {mi}"));
            pieces.push(format!("second: {s}"));
        }
        format!("datetime{}", pretty_array_like(&pieces, false))
    }

    fn to_seconds(&self) -> f64 {
        let days = self.date.map(|(y, m, d)| days_from_civil(y as i64, m as u32, d as u32)).unwrap_or(0);
        let secs = self.time.map(|(h, m, s)| h as i64 * 3600 + m as i64 * 60 + s as i64).unwrap_or(0);
        (days * 86400 + secs) as f64
    }

    fn from_seconds(secs: f64, has_date: bool, has_time: bool) -> Datetime {
        let total = secs.floor() as i64;
        let days = total.div_euclid(86400);
        let rem = total.rem_euclid(86400);
        let date = if has_date {
            let (y, m, d) = civil_from_days(days);
            Some((y as i32, m as u8, d as u8))
        } else {
            None
        };
        let time = if has_time {
            Some(((rem / 3600) as u8, ((rem % 3600) / 60) as u8, (rem % 60) as u8))
        } else {
            None
        };
        Datetime { date, time }
    }

    pub fn add(&self, d: Duration) -> Result<Datetime, String> {
        Ok(Datetime::from_seconds(self.to_seconds() + d.seconds, self.date.is_some(), self.time.is_some()))
    }

    pub fn sub(&self, d: Duration) -> Result<Datetime, String> {
        Ok(Datetime::from_seconds(self.to_seconds() - d.seconds, self.date.is_some(), self.time.is_some()))
    }

    pub fn diff(&self, other: &Datetime) -> Duration {
        Duration { seconds: self.to_seconds() - other.to_seconds() }
    }

    pub fn partial_cmp(&self, other: &Datetime) -> Option<Ordering> {
        if self.date.is_some() != other.date.is_some() || self.time.is_some() != other.time.is_some() {
            return None;
        }
        self.to_seconds().partial_cmp(&other.to_seconds())
    }

    pub fn weekday(&self) -> Option<u8> {
        let (y, m, d) = self.date?;
        let days = days_from_civil(y as i64, m as u32, d as u32);
        // 1970-01-01 was a Thursday (4). Monday = 1.
        Some((((days + 3).rem_euclid(7)) + 1) as u8)
    }

    pub fn ordinal(&self) -> Option<u16> {
        let (y, m, d) = self.date?;
