        for mm in 1..m {
            n += days_in_month(y, mm) as u16;
        }
        Some(n + d as u16)
    }

    /// Format with a strftime-like pattern as used by Typst.
    pub fn display(&self, pattern: Option<&str>) -> Result<String, String> {
        let pattern = match pattern {
            Some(p) => p.to_string(),
            None => match (self.date, self.time) {
                (Some(_), Some(_)) => "[year]-[month]-[day] [hour]:[minute]:[second]".into(),
                (Some(_), None) => "[year]-[month]-[day]".into(),
                (None, Some(_)) => "[hour]:[minute]:[second]".into(),
                (None, None) => String::new(),
            },
