            for p in parts {
                if let Some((k, v)) = p.split_once(':') {
                    modifiers.push((k, v));
                }
            }
            let get = |k: &str| modifiers.iter().find(|(kk, _)| *kk == k).map(|(_, v)| *v);
            match name {
                "year" => {
                    let (y, _, _) = self.date.ok_or("failed to format datetime in the requested format")?;
                    match get("repr") {
                        Some("last_two") => out.push_str(&format!("{:02}", y.rem_euclid(100))),
                        _ => out.push_str(&format!("{y:04}")),
                    }
                }
                "month" => {
                    let (_, m, _) = self.date.ok_or("failed to format datetime in the requested format")?;
                    match get("repr") {
                        Some("long") => out.push_str(MONTHS[m as usize - 1]),
                        Some("short") => out.push_str(&MONTHS[m as usize - 1][..3]),
                        _ => match get("padding") {
                            Some("none") => out.push_str(&format!("{m}")),
                            Some("space") => out.push_str(&format!("{m:>2}")),
                            _ => out.push_str(&format!("{m:02}")),
                        },
                    }
                }
                "day" => {
                    let (_, _, d) = self.date.ok_or("failed to format datetime in the requested format")?;
                    match get("padding") {
                        Some("none") => out.push_str(&format!("{d}")),
                        Some("space") => out.push_str(&format!("{d:>2}")),
                        _ => out.push_str(&format!("{d:02}")),
