const MONTHS: [&str; 12] = [
    "January", "February", "March", "April", "May", "June", "July", "August", "September",
    "October", "November", "December",
];

const WEEKDAYS: [&str; 7] =
    ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

impl Duration {
    pub fn new(seconds: f64) -> Self {
        Duration { seconds }
    }
    pub fn is_zero(&self) -> bool {
        self.seconds == 0.0
    }
    pub fn neg(self) -> Self {
        Duration { seconds: -self.seconds }
    }
    pub fn add(self, o: Duration) -> Self {
        Duration { seconds: self.seconds + o.seconds }
    }
    pub fn sub(self, o: Duration) -> Self {
        Duration { seconds: self.seconds - o.seconds }
    }
    pub fn scale(self, f: f64) -> Self {
        Duration { seconds: self.seconds * f }
    }
    pub fn ratio(&self, o: &Duration) -> f64 {
        self.seconds / o.seconds
    }
    pub fn partial_cmp(&self, o: &Duration) -> Option<Ordering> {
        self.seconds.partial_cmp(&o.seconds)
    }
    pub fn seconds(&self) -> f64 {
        self.seconds
    }
    pub fn minutes(&self) -> f64 {
        self.seconds / 60.0
    }
    pub fn hours(&self) -> f64 {
        self.seconds / 3600.0
    }
    pub fn days(&self) -> f64 {
        self.seconds / 86400.0
    }
    pub fn weeks(&self) -> f64 {
        self.seconds / (86400.0 * 7.0)
    }

    pub fn repr(&self) -> String {
        let mut pieces = Vec::new();
        let mut secs = self.seconds.trunc() as i64;
        let weeks = secs / (7 * 86400);
        secs %= 7 * 86400;
        let days = secs / 86400;
        secs %= 86400;
        let hours = secs / 3600;
        secs %= 3600;
        let minutes = secs / 60;
        secs %= 60;
        if weeks != 0 {
            pieces.push(format!("weeks: {weeks}"));
        }
        if days != 0 {
            pieces.push(format!("days: {days}"));
        }
        if hours != 0 {
            pieces.push(format!("hours: {hours}"));
        }
        if minutes != 0 {
            pieces.push(format!("minutes: {minutes}"));
        }
        if secs != 0 {
            pieces.push(format!("seconds: {secs}"));
        }
        format!("duration{}", pretty_array_like(&pieces, false))
    }
}

/// Current local date and time.
pub fn now(offset_hours: Option<i64>) -> Datetime {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let offset = match offset_hours {
        Some(h) => h * 3600,
        None => local_offset_seconds(secs),
    };
    let local = secs + offset;
    let days = local.div_euclid(86400);
    let rem = local.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    Datetime {
        date: Some((y as i32, m as u8, d as u8)),
        time: Some(((rem / 3600) as u8, ((rem % 3600) / 60) as u8, (rem % 60) as u8)),
    }
}

fn local_offset_seconds(secs: i64) -> i64 {
    unsafe {
        let t: libc::time_t = secs as libc::time_t;
        let mut tm: libc::tm = std::mem::zeroed();
        if libc::localtime_r(&t, &mut tm).is_null() {
            return 0;
        }
        tm.tm_gmtoff as i64
    }
}
