    ma.cmp(&mb)
}

fn check(m: i128) -> Result<i128, String> {
    if m.abs() > 79228162514264337593543950335 {
        Err("value is too large".into())
    } else {
        Ok(m)
    }
}

pub fn add(a: &Decimal, b: &Decimal) -> Result<Decimal, String> {
    let (ma, mb, scale) = align(a, b);
    Ok(Decimal { mantissa: check(ma + mb)?, scale })
}

pub fn sub(a: &Decimal, b: &Decimal) -> Result<Decimal, String> {
    let (ma, mb, scale) = align(a, b);
    Ok(Decimal { mantissa: check(ma - mb)?, scale })
}

pub fn mul(a: &Decimal, b: &Decimal) -> Result<Decimal, String> {
    let mut mantissa = a.mantissa.checked_mul(b.mantissa).ok_or("value is too large")?;
    let mut scale = a.scale + b.scale;
    while scale > MAX_SCALE {
        mantissa /= 10;
        scale -= 1;
    }
    Ok(Decimal { mantissa: check(mantissa)?, scale })
}

pub fn div(a: &Decimal, b: &Decimal) -> Result<Decimal, String> {
    if b.mantissa == 0 {
        return Err("cannot divide by zero".into());
    }
    // Scale the numerator up to get 28 fractional digits.
    let mut num = a.mantissa;
    let mut scale = a.scale as i64 - b.scale as i64;
    let mut extra = 0u32;
    while extra < MAX_SCALE && num.checked_mul(10).is_some() && (scale + extra as i64) < MAX_SCALE as i64 {
        num *= 10;
        extra += 1;
    }
    let mut mantissa = num / b.mantissa;
    let mut final_scale = scale + extra as i64;
    while final_scale < 0 {
        mantissa *= 10;
        final_scale += 1;
    }
    // Strip trailing zeros.
    while final_scale > 0 && mantissa % 10 == 0 {
        mantissa /= 10;
        final_scale -= 1;
    }
    let _ = &mut scale;
    Ok(Decimal { mantissa: check(mantissa)?, scale: final_scale as u32 })
}

pub fn normalize(d: &Decimal) -> Decimal {
    let mut m = d.mantissa;
    let mut s = d.scale;
    while s > 0 && m % 10 == 0 {
        m /= 10;
        s -= 1;
    }
    Decimal { mantissa: m, scale: s }
}
