        let days = secs / 86400;
        secs %= 86400;
        let hours = secs / 3600;
        secs %= 3600;
        let minutes = secs / 60;
        secs %= 60;
        if weeks != 0 {
            pieces.push(format!("weeks: {weeks}"));
        }
        if days != 0 {
            pieces.push(format!("days: {days}"));
        }
        if hours != 0 {
            pieces.push(format!("hours: {hours}"));
