#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Severity {
    Error,
    Warning,
}

#[derive(Debug, Clone)]
pub struct SourceDiagnostic {
    pub severity: Severity,
    pub span: Span,
    pub message: String,
    pub hints: Vec<String>,
    pub trace: Vec<(Span, String)>,
}

impl SourceDiagnostic {
    pub fn error(span: Span, message: impl Into<String>) -> Self {
        Self { severity: Severity::Error, span, message: message.into(), hints: vec![], trace: vec![] }
    }
    pub fn warning(span: Span, message: impl Into<String>) -> Self {
        Self { severity: Severity::Warning, span, message: message.into(), hints: vec![], trace: vec![] }
    }
    pub fn with_hint(mut self, hint: impl Into<String>) -> Self {
        self.hints.push(hint.into());
        self
    }
}

pub type Result<T> = std::result::Result<T, Vec<SourceDiagnostic>>;

pub fn bail<T>(span: Span, msg: impl Into<String>) -> Result<T> {
    Err(vec![SourceDiagnostic::error(span, msg)])
}

pub fn err(span: Span, msg: impl Into<String>) -> Vec<SourceDiagnostic> {
    vec![SourceDiagnostic::error(span, msg)]
}

/// Attach a span to a string error.
pub trait At<T> {
    fn at(self, span: Span) -> Result<T>;
}

impl<T> At<T> for std::result::Result<T, String> {
    fn at(self, span: Span) -> Result<T> {
        self.map_err(|e| {
            // Split off hints encoded with newlines prefixed by "\u{0}hint:".
            let mut parts = e.split("\u{0}hint:");
            let msg = parts.next().unwrap_or("").to_string();
            let mut d = SourceDiagnostic::error(span, msg);
            for h in parts {
                d.hints.push(h.to_string());
            }
            vec![d]
        })
    }
}

/// Encode a hint into a string error.
pub fn hinted(msg: impl Into<String>, hint: impl Into<String>) -> String {
    format!("{}\u{0}hint:{}", msg.into(), hint.into())
}

#[derive(Debug, Clone)]
pub enum FlowEvent {
    Break(Span),
    Continue(Span),
    Return(Span, Option<Value>),
}

impl FlowEvent {
    pub fn forbidden(&self) -> SourceDiagnostic {
        match self {
            FlowEvent::Break(span) => SourceDiagnostic::error(*span, "cannot break outside of loop"),
            FlowEvent::Continue(span) => {
                SourceDiagnostic::error(*span, "cannot continue outside of loop")
            }
            FlowEvent::Return(span, _) => {
                SourceDiagnostic::error(*span, "cannot return outside of function")
            }
        }
    }
}

/// The scope stack.
#[derive(Debug, Clone, Default)]
pub struct Scopes {
    pub top: Scope,
    pub scopes: Vec<Scope>,
    /// Whether the global library scope is visible.
    pub base: bool,
}

impl Scopes {
    pub fn new(base: bool) -> Self {
        Scopes { top: Scope::new(), scopes: vec![], base }
    }

    pub fn enter(&mut self) {
        self.scopes.push(std::mem::take(&mut self.top));
    }

    pub fn exit(&mut self) {
        self.top = self.scopes.pop().unwrap_or_default();
    }

    pub fn get(&self, name: &str) -> Option<Binding> {
        if let Some(b) = self.top.get(name) {
            return Some(b.clone());
        }
        for s in self.scopes.iter().rev() {
            if let Some(b) = s.get(name) {
                return Some(b.clone());
            }
        }
        if self.base {
            return crate::library::global_get(name);
        }
        None
    }

    pub fn get_in_math(&self, name: &str) -> Option<Binding> {
        if let Some(b) = self.get(name) {
            return Some(b);
        }
        if self.base {
            return crate::library::math_get(name);
        }
        None
    }

    /// Get a mutable reference; errors if constant or unknown.
    pub fn get_mut(&mut self, name: &str) -> std::result::Result<&mut Value, String> {
        if let Some(b) = self.top.get_mut(name) {
            return Ok(&mut b.value);
        }
        for s in self.scopes.iter_mut().rev() {
            if let Some(b) = s.get_mut(name) {
                return Ok(&mut b.value);
            }
        }
        if self.base && crate::library::global_get(name).is_some() {
            return Err(format!("cannot mutate a constant: {name}"));
        }
        Err(unknown_variable(name))
    }
}

pub fn unknown_variable(name: &str) -> String {
    let mut msg = format!("unknown variable: {name}");
    if name.contains('-') {
        let spaced = name.replace('-', " - ");
        msg = hinted(
            msg,
            format!("if you meant to use subtraction, try adding spaces around the minus sign: `{spaced}`"),
        );
    }
    msg
}

/// Evaluation context (styles / location availability).
#[derive(Clone, Debug, Default)]
pub struct Context {
    pub styles: bool,
    pub location: Option<Location>,
}

pub struct Vm<'w> {
    pub world: &'w mut crate::world::World,
    pub scopes: Scopes,
    pub flow: Option<FlowEvent>,
    pub file: u16,
    pub depth: usize,
