}

const MAX_CALL_DEPTH: usize = 256;

impl<'w> Vm<'w> {
    pub fn new(world: &'w mut crate::world::World, file: u16, scopes: Scopes) -> Self {
        Vm {
            world,
            scopes,
            flow: None,
