    pub fn eval_markup(&mut self, exprs: &[Expr]) -> Result<Content> {
        let flow = self.flow.take();
        let mut seq: Vec<Content> = Vec::with_capacity(exprs.len());
        let mut i = 0;
        while i < exprs.len() {
