                    }
                    let tail = self.eval_markup(&exprs[i..])?;
                    seq.push(self.apply_recipe(tail, recipe, expr.span)?);
                    break;
                }
                ExprKind::Label(label) => {
                    self.attach_label(&mut seq, label, expr.span);
                }
                _ => {
                    let value = self.eval_expr(expr)?;
                    if let Value::Label(label) = &value {
                        let l = label.to_string();
                        self.attach_label(&mut seq, &l, expr.span);
                    } else {
                        seq.push(display(value).with_span(self.span(expr.span)));
                    }
                }
            }
            if self.flow.is_some() {
                break;
            }
        }
        if flow.is_some() {
            self.flow = flow;
        }
        Ok(Content::sequence(seq))
    }

    fn attach_label(&mut self, seq: &mut Vec<Content>, label: &str, span: Span) {
        if let Some(elem) = seq.iter_mut().rev().find(|c| c.is_labellable()) {
            if elem.label().is_some() {
                self.warn(
                    SourceDiagnostic::warning(self.span(span), "content labelled multiple times")
                        .with_hint("only the last label is used, the rest are ignored"),
                );
            }
            elem.set_label(Rc::from(label));
        } else {
            self.warn(SourceDiagnostic::warning(
                self.span(span),
                format!("label `<{label}>` is not attached to anything"),
            ));
        }
    }

    // -------------------------------------------------------------- Code

    pub fn eval_code(&mut self, exprs: &[Expr]) -> Result<Value> {
        let flow = self.flow.take();
        let mut output = Value::None;
        let mut i = 0;
        while i < exprs.len() {
            let expr = &exprs[i];
            i += 1;
            let value = match &expr.kind {
                ExprKind::Set { .. } => {
                    let styles = self.eval_set(expr)?;
                    if self.flow.is_some() {
                        break;
                    }
                    let tail = display(self.eval_code(&exprs[i..])?);
                    i = exprs.len();
                    Value::Content(styled(tail, styles))
                }
                ExprKind::Show { .. } => {
                    let recipe = self.eval_show(expr)?;
                    if self.flow.is_some() {
                        break;
                    }
                    let tail = display(self.eval_code(&exprs[i..])?);
                    i = exprs.len();
                    Value::Content(self.apply_recipe(tail, recipe, expr.span)?)
                }
                _ => self.eval_expr(expr)?,
            };
            output = ops::join(output, value).at(self.span(expr.span))?;
            if self.flow.is_some() {
                break;
            }
        }
        if flow.is_some() {
            self.flow = flow;
        }
        Ok(output)
    }

    pub fn eval_math(&mut self, exprs: &[Expr]) -> Result<Content> {
        let mut seq = Vec::new();
        for expr in exprs {
            let was = self.in_math;
            self.in_math = true;
            let v = self.eval_expr(expr);
            self.in_math = was;
            let v = v?;
            seq.push(display_in_math(v).with_span(self.span(expr.span)));
        }
        Ok(Content::sequence(seq))
    }

    pub fn eval_expr(&mut self, expr: &Expr) -> Result<Value> {
        let span = expr.span;
        let sp = self.span(span);
        let v = match &expr.kind {
            ExprKind::Markup(exprs) => Value::Content(self.eval_markup(exprs)?),
            ExprKind::Text(t) => Value::Content(Content::text(t)),
            ExprKind::Space => Value::Content(Content::space()),
            ExprKind::Linebreak => Value::Content(Content::new("linebreak")),
            ExprKind::Parbreak => Value::Content(Content::new("parbreak")),
            ExprKind::Escape(c) => Value::Content(Content::symbol(&c.to_string())),
            ExprKind::Shorthand(c) => Value::Content(Content::symbol(&c.to_string())),
            ExprKind::SmartQuote { double } => {
                Value::Content(Content::new("smartquote").with_field("double", Value::Bool(*double)))
            }
            ExprKind::Strong(body) => {
                let body = self.eval_markup(body)?;
                Value::Content(Content::new("strong").with_field("body", body))
            }
            ExprKind::Emph(body) => {
                let body = self.eval_markup(body)?;
                Value::Content(Content::new("emph").with_field("body", body))
            }
            ExprKind::Raw { text, lang, block } => {
                let mut c = Content::new("raw")
                    .with_field("text", Value::str(text.clone()))
                    .with_field("block", Value::Bool(*block));
                if let Some(l) = lang {
                    c.set_field("lang", Value::str(l.clone()));
                }
                Value::Content(c)
            }
            ExprKind::Link(url) => Value::Content(
                Content::new("link")
                    .with_field("dest", Value::str(url.clone()))
                    .with_field("body", Content::text(url)),
            ),
            ExprKind::Label(l) => Value::Label(Rc::from(l.as_str())),
            ExprKind::Ref { target, supplement } => {
                let mut c =
                    Content::new("ref").with_field("target", Value::Label(Rc::from(target.as_str())));
                if let Some(s) = supplement {
                    let v = self.eval_expr(s)?;
                    c.set_field("supplement", v);
                }
                Value::Content(c)
            }
            ExprKind::Heading { depth, body } => {
                let body = self.eval_markup(body)?;
                Value::Content(
                    Content::new("heading")
                        .with_field("depth", Value::Int(*depth as i64))
                        .with_field("body", body),
                )
            }
            ExprKind::ListItem { body } => {
                let body = self.eval_markup(body)?;
                Value::Content(Content::new("list.item").with_field("body", body))
            }
            ExprKind::EnumItem { number, body } => {
                let body = self.eval_markup(body)?;
                let mut c = Content::new("enum.item");
                if let Some(n) = number {
                    c.set_field("number", Value::Int(*n as i64));
                }
                c.set_field("body", Value::Content(body));
                Value::Content(c)
            }
            ExprKind::TermItem { term, description } => {
                let term = self.eval_markup(term)?;
                let description = self.eval_markup(description)?;
                Value::Content(
                    Content::new("terms.item")
                        .with_field("term", term)
                        .with_field("description", description),
                )
            }
            ExprKind::Equation { block, body } => {
                let body = self.eval_math(body)?;
                Value::Content(
                    Content::new("equation")
                        .with_field("block", Value::Bool(*block))
                        .with_field("body", body),
                )
            }

            // Math
            ExprKind::Math(exprs) => Value::Content(self.eval_math(exprs)?),
            ExprKind::MathText(t) => {
                let mut chars = t.chars();
                let first = chars.next();
                if let (Some(c), None) = (first, chars.next()) {
                    if c.is_numeric() {
                        Value::Content(Content::text(t))
                    } else {
                        Value::Content(Content::symbol(t))
                    }
                } else {
                    Value::Content(Content::text(t))
                }
            }
            ExprKind::MathIdent(name) => {
                match self.scopes.get_in_math(name) {
                    Some(b) => b.value,
                    None => {
                        let mut d = SourceDiagnostic::error(sp, format!("unknown variable: {name}"));
                        if name.chars().all(|c| c.is_alphabetic()) && name.chars().count() > 1 {
                            let spaced: Vec<String> = name.chars().map(|c| c.to_string()).collect();
                            d = d.with_hint(format!(
                                "if you meant to display multiple letters as is, try adding spaces between each letter: `{}`",
                                spaced.join(" ")
                            ));
                            d = d.with_hint(format!(
                                "or if you meant to display this as text, try placing it in quotes: `\"{name}\"`"
                            ));
                        }
                        return Err(vec![d]);
                    }
                }
            }
            ExprKind::MathShorthand(c) => Value::Content(Content::symbol(&c.to_string())),
            ExprKind::MathAlignPoint => Value::Content(Content::new("align-point")),
            ExprKind::MathDelimited { open, body, close } => {
                let open = display_in_math(self.eval_expr(open)?);
                let body = self.eval_math(body)?;
                let close = display_in_math(self.eval_expr(close)?);
                let mut children = vec![open];
                match body.children() {
                    Some(c) if body.label().is_none() => children.extend(c),
                    _ => children.push(body),
                }
                children.push(close);
                let seq = Content::new("sequence")
                    .with_field("children", Value::array(children.into_iter().map(Value::Content).collect()));
                Value::Content(Content::new("lr").with_field("body", seq))
            }
            ExprKind::MathAttach { base, bottom, top, primes } => {
                let base = display_in_math(self.eval_expr(base)?);
                let mut c = Content::new("attach").with_field("base", base);
                if let Some(t) = top {
                    let v = display_in_math(self.eval_expr(t)?);
                    c.set_field("t", Value::Content(v));
                }
                if let Some(p) = primes {
                    let v = display_in_math(self.eval_expr(p)?);
                    if top.is_none() {
                        c.set_field("t", Value::Content(v));
                    } else {
                        c.set_field("tr", Value::Content(v));
                    }
                }
                if let Some(b) = bottom {
                    let v = display_in_math(self.eval_expr(b)?);
                    c.set_field("b", Value::Content(v));
                }
                Value::Content(c)
            }
            ExprKind::MathPrimes(n) => {
                Value::Content(Content::new("primes").with_field("count", Value::Int(*n as i64)))
            }
            ExprKind::MathFrac { num, denom } => {
                let num = display_in_math(self.eval_expr(num)?);
                let denom = display_in_math(self.eval_expr(denom)?);
                Value::Content(Content::new("frac").with_field("num", num).with_field("denom", denom))
            }
            ExprKind::MathRoot { index, radicand } => {
                let radicand = display_in_math(self.eval_expr(radicand)?);
                let mut c = Content::new("root");
                if let Some(i) = index {
                    c.set_field("index", Value::Content(Content::text(&i.to_string())));
                }
                c.set_field("radicand", Value::Content(radicand));
                Value::Content(c)
            }

            // Code
            ExprKind::Ident(name) => match self.scopes.get(name) {
                Some(b) => {
                    if let Some(dep) = b.deprecation {
                        self.warn(SourceDiagnostic::warning(sp, dep.to_string()));
                    }
                    b.value
                }
                None => {
                    if self.in_math {
                        if let Some(b) = self.scopes.get_in_math(name) {
                            return Ok(b.value);
                        }
                    }
                    return Err(unknown_variable(name)).at(sp);
                }
            },
            ExprKind::None => Value::None,
            ExprKind::Auto => Value::Auto,
            ExprKind::Bool(b) => Value::Bool(*b),
            ExprKind::Int(i) => Value::Int(*i),
            ExprKind::Float(f) => Value::Float(*f),
            ExprKind::Numeric(v, unit) => match unit {
                Unit::Pt => Value::Length(Length::pt(*v)),
                Unit::Mm => Value::Length(Length::pt(*v * 72.0 / 25.4)),
                Unit::Cm => Value::Length(Length::pt(*v * 72.0 / 2.54)),
                Unit::In => Value::Length(Length::pt(*v * 72.0)),
                Unit::Em => Value::Length(Length::em(*v)),
                Unit::Deg => Value::Angle(v.to_radians()),
                Unit::Rad => Value::Angle(*v),
                Unit::Percent => Value::Ratio(*v / 100.0),
                Unit::Fr => Value::Fraction(*v),
            },
            ExprKind::Str(s) => Value::str(s.clone()),
            ExprKind::CodeBlock(exprs) => {
                self.scopes.enter();
                let r = self.eval_code(exprs);
                self.scopes.exit();
                r?
            }
            ExprKind::ContentBlock(exprs) => {
                self.scopes.enter();
                let r = self.eval_markup(exprs);
                self.scopes.exit();
                Value::Content(r?)
            }
            ExprKind::Parenthesized(inner) => self.eval_expr(inner)?,
            ExprKind::Array(items) => {
                let mut out = Vec::with_capacity(items.len());
                for item in items {
                    match item {
                        ArrayItem::Pos(e) => out.push(self.eval_expr(e)?),
                        ArrayItem::Spread(e) => match self.eval_expr(e)? {
                            Value::None => {}
                            Value::Array(a) => out.extend(a.iter().cloned()),
                            v => {
                                return bail(
                                    self.span(e.span),
                                    format!("cannot spread {} into array", v.ty().long_name()),
                                )
                            }
                        },
                    }
                }
                Value::array(out)
            }
            ExprKind::Dict(items) => {
                let mut out: Dict = IndexMap::new();
                for item in items {
                    match item {
                        DictItem::Named(name, e) => {
                            let v = self.eval_expr(e)?;
                            out.insert(name.name.clone(), v);
                        }
                        DictItem::Keyed(k, e) => {
                            let key = self.eval_expr(k)?;
                            let key = match key {
                                Value::Str(s) => s.to_string(),
                                other => {
                                    return bail(
                                        self.span(k.span),
                                        format!("expected string, found {}", other.ty().long_name()),
                                    )
                                }
                            };
                            let v = self.eval_expr(e)?;
                            out.insert(key, v);
                        }
                        DictItem::Spread(e) => match self.eval_expr(e)? {
                            Value::None => {}
                            Value::Dict(d) => {
                                for (k, v) in d.iter() {
                                    out.insert(k.clone(), v.clone());
                                }
                            }
                            v => {
                                return bail(
                                    self.span(e.span),
                                    format!("cannot spread {} into dictionary", v.ty().long_name()),
                                )
                            }
                        },
                    }
                }
                Value::dict(out)
            }
            ExprKind::Unary { op, expr: inner } => {
                let v = self.eval_expr(inner)?;
                let r = match op {
                    UnOp::Pos => ops::pos(v),
                    UnOp::Neg => ops::neg(v),
                    UnOp::Not => ops::not(v),
                };
                r.at(sp)?
            }
            ExprKind::Binary { op, lhs, rhs } => self.eval_binary(*op, lhs, rhs, span)?,
            ExprKind::FieldAccess { target, field } => self.eval_field_access(target, field, span)?,
            ExprKind::FuncCall { callee, args } => self.eval_func_call(callee, args, span)?,
            ExprKind::Closure(closure) => self.eval_closure(closure, span)?,
            ExprKind::Let { pattern, init } => {
                let value = match init {
                    Some(e) => self.eval_expr(e)?,
                    None => Value::None,
                };
                if self.flow.is_some() {
                    return Ok(Value::None);
                }
                self.destructure(pattern, value)?;
                Value::None
            }
            ExprKind::DestructAssign { pattern, value } => {
                let value = self.eval_expr(value)?;
                self.destructure_assign(pattern, value)?;
                Value::None
            }
            ExprKind::Set { .. } => {
                return bail(sp, "set is only allowed directly in code and content blocks");
            }
            ExprKind::Show { .. } => {
                return bail(sp, "show is only allowed directly in code and content blocks");
            }
            ExprKind::Contextual(body) => {
                let closure = Rc::new(Closure { name: None, params: vec![], body: (**body).clone() });
                let func = self.make_closure(&closure)?;
                Value::Content(Content::new("context").with_field("func", Value::Func(func)))
            }
            ExprKind::Conditional { cond, if_body, else_body } => {
                let c = self.eval_expr(cond)?;
                let c = match c {
                    Value::Bool(b) => b,
                    other => {
                        return bail(
                            self.span(cond.span),
                            format!("expected boolean, found {}", other.ty().long_name()),
                        )
                    }
                };
                if c {
                    self.eval_expr(if_body)?
                } else if let Some(e) = else_body {
                    self.eval_expr(e)?
                } else {
                    Value::None
                }
            }
            ExprKind::While { cond, body } => self.eval_while(cond, body)?,
            ExprKind::For { pattern, iterable, body } => self.eval_for(pattern, iterable, body)?,
            ExprKind::Import { source, new_name, imports } => {
                self.eval_import(source, new_name.as_ref(), imports.as_ref(), span)?
            }
            ExprKind::Include(source) => self.eval_include(source, span)?,
            ExprKind::Break => {
                if self.flow.is_none() {
                    self.flow = Some(FlowEvent::Break(sp));
                }
                Value::None
            }
            ExprKind::Continue => {
                if self.flow.is_none() {
                    self.flow = Some(FlowEvent::Continue(sp));
                }
                Value::None
            }
            ExprKind::Return(value) => {
                let v = match value {
                    Some(e) => Some(self.eval_expr(e)?),
                    None => None,
                };
                if self.flow.is_none() {
                    self.flow = Some(FlowEvent::Return(sp, v));
                }
                Value::None
            }
        };
        Ok(v)
    }

    fn eval_binary(&mut self, op: BinOp, lhs: &Expr, rhs: &Expr, span: Span) -> Result<Value> {
        let sp = self.span(span);
        match op {
            BinOp::And => {
                let l = self.eval_expr(lhs)?;
                if let Value::Bool(false) = l {
                    return Ok(Value::Bool(false));
                }
                let r = self.eval_expr(rhs)?;
                ops::and(l, r).at(sp)
            }
            BinOp::Or => {
                let l = self.eval_expr(lhs)?;
                if let Value::Bool(true) = l {
                    return Ok(Value::Bool(true));
                }
                let r = self.eval_expr(rhs)?;
                ops::or(l, r).at(sp)
            }
            BinOp::Assign | BinOp::AddAssign | BinOp::SubAssign | BinOp::MulAssign | BinOp::DivAssign => {
                self.eval_assignment(op, lhs, rhs, span)
            }
            _ => {
                let l = self.eval_expr(lhs)?;
                let r = self.eval_expr(rhs)?;
                let res = match op {
                    BinOp::Add => ops::add(l, r),
                    BinOp::Sub => ops::sub(l, r),
                    BinOp::Mul => ops::mul(l, r),
                    BinOp::Div => ops::div(l, r),
                    BinOp::Eq => Ok(Value::Bool(ops::equal(&l, &r))),
                    BinOp::Neq => Ok(Value::Bool(!ops::equal(&l, &r))),
                    BinOp::Lt => ops::lt(&l, &r),
                    BinOp::Leq => ops::leq(&l, &r),
                    BinOp::Gt => ops::gt(&l, &r),
                    BinOp::Geq => ops::geq(&l, &r),
                    BinOp::In => ops::in_op(&l, &r),
                    BinOp::NotIn => ops::not_in_op(&l, &r),
                    _ => unreachable!(),
                };
                res.at(sp)
            }
        }
    }

    fn eval_assignment(&mut self, op: BinOp, lhs: &Expr, rhs: &Expr, span: Span) -> Result<Value> {
        let sp = self.span(span);
        let rhs_val = self.eval_expr(rhs)?;
        if op == BinOp::Assign {
            if let ExprKind::FieldAccess { target, field } = &lhs.kind {
                let dict = self.access_dict(target)?;
                dict.insert(field.name.clone(), rhs_val);
                return Ok(Value::None);
            }
        }
        let location = self.access(lhs)?;
        let lhs_val = std::mem::replace(location, Value::None);
        let result = match op {
            BinOp::Assign => Ok(rhs_val),
            BinOp::AddAssign => ops::add(lhs_val, rhs_val),
            BinOp::SubAssign => ops::sub(lhs_val, rhs_val),
            BinOp::MulAssign => ops::mul(lhs_val, rhs_val),
            BinOp::DivAssign => ops::div(lhs_val, rhs_val),
            _ => unreachable!(),
        };
        let new = result.at(sp)?;
        let location = self.access(lhs)?;
        *location = new;
        Ok(Value::None)
    }

    /// Get mutable access to the dictionary behind an expression.
    fn access_dict(&mut self, target: &Expr) -> Result<&mut Dict> {
        let sp = self.span(target.span);
        let value = self.access(target)?;
        match value {
            Value::Dict(d) => Ok(Rc::make_mut(d)),
            other => {
                let ty = other.ty();
                let msg = format!("{} does not have accessible fields", ty.long_name());
                bail(sp, msg)
            }
        }
    }

    /// Get mutable access to the location of an expression.
    pub fn access(&mut self, expr: &Expr) -> Result<&mut Value> {
        let sp = self.span(expr.span);
        match &expr.kind {
            ExprKind::Ident(name) => self.scopes.get_mut(name).map_err(|e| err(sp, e)),
            ExprKind::Parenthesized(inner) => self.access(inner),
            ExprKind::FieldAccess { target, field } => {
                let fsp = self.span(field.span);
                let dict = self.access_dict(target)?;
                match dict.get_mut(&field.name) {
                    Some(v) => Ok(v),
                    None => Err(vec![SourceDiagnostic::error(
                        fsp,
                        format!("dictionary does not contain key {}", super::repr::repr_str(&field.name)),
                    )
                    .with_hint("use `insert` to add or update values")]),
                }
            }
            ExprKind::FuncCall { callee, args } => {
                if let ExprKind::FieldAccess { target, field } = &callee.kind {
                    if field.name == "at" || field.name == "first" || field.name == "last" {
                        let args_val = self.eval_args(args)?;
                        let fsp = self.span(field.span);
                        let value = self.access(target)?;
                        return crate::library::access_method(value, &field.name, args_val, fsp, sp);
                    }
                }
                bail(sp, "cannot mutate a temporary value")
            }
            _ => bail(sp, "cannot mutate a temporary value"),
        }
    }

    // ------------------------------------------------------------- Fields

    fn eval_field_access(&mut self, target: &Expr, field: &Ident, span: Span) -> Result<Value> {
        let value = self.eval_expr(target)?;
        let fsp = self.span(field.span);
        let _ = span;
        match crate::library::field(self, &value, &field.name) {
            Ok(v) => Ok(v),
            Err(e) => {
                // Get-rule style access on element functions.
                if let Value::Func(func) = &value {
                    if let Some(elem) = func.elem() {
                        if self.context.styles {
                            if let Some(v) = crate::library::elements::style_field(elem, &field.name) {
                                return Ok(v);
                            }
                        }
                    }
                }
                Err(e).at(fsp)
            }
        }
    }

    // -------------------------------------------------------------- Calls

    pub fn eval_args(&mut self, args: &Args) -> Result<super::value::Args> {
        let mut out = super::value::Args { span: self.span(args.span), items: Vec::new() };
        for item in &args.items {
            match item {
                Arg::Pos(e) => {
                    let v = self.eval_expr(e)?;
                    out.items.push(super::value::Arg {
                        span: self.span(e.span),
                        name: None,
                        value: v,
                        value_span: self.span(e.span),
                    });
                }
                Arg::Named(name, e) => {
                    let v = self.eval_expr(e)?;
                    out.items.push(super::value::Arg {
                        span: self.span(name.span.join(e.span)),
                        name: Some(name.name.clone()),
                        value: v,
                        value_span: self.span(e.span),
                    });
                }
                Arg::Spread(e) => {
                    let v = self.eval_expr(e)?;
                    let sp = self.span(e.span);
                    match v {
                        Value::None => {}
                        Value::Array(a) => {
                            for item in a.iter() {
                                out.items.push(super::value::Arg {
                                    span: sp,
                                    name: None,
                                    value: item.clone(),
                                    value_span: sp,
                                });
                            }
                        }
                        Value::Dict(d) => {
                            for (k, v) in d.iter() {
                                out.items.push(super::value::Arg {
                                    span: sp,
                                    name: Some(k.clone()),
                                    value: v.clone(),
                                    value_span: sp,
                                });
                            }
                        }
                        Value::Args(a) => {
                            out.items.extend(a.items.iter().cloned());
                        }
                        other => {
                            return bail(
                                sp,
                                format!("cannot spread {} into arguments", other.ty().long_name()),
                            )
                        }
                    }
                }
            }
        }
        Ok(out)
    }

    fn eval_func_call(&mut self, callee: &Expr, args: &Args, span: Span) -> Result<Value> {
        let sp = self.span(span);
        let callee_span = self.span(callee.span);

        if self.depth >= MAX_CALL_DEPTH {
            return bail(sp, "maximum function call depth exceeded");
        }

        let in_math = self.in_math;

        // Method call on a field access.
        if let ExprKind::FieldAccess { target, field } = &callee.kind {
            let fsp = self.span(field.span);
            if crate::library::is_mutating_method(&field.name) {
                let args_val = self.eval_args(args)?;
                let target_val = self.access(target)?;
                if matches!(target_val, Value::Array(_) | Value::Dict(_)) {
                    return crate::library::call_method_mut(target_val, &field.name, args_val, fsp, sp);
                }
                let tv = target_val.clone();
                return self.call_method(tv, &field.name, args_val, fsp, sp);
            }
            let target_val = self.eval_expr(target)?;
            let args_val = self.eval_args(args)?;
            return self.call_method(target_val, &field.name, args_val, fsp, sp);
        }

        let callee_val = self.eval_expr(callee)?;
        let args_val = self.eval_args(args)?;

        let func = match callee_val {
            Value::Func(f) => f,
            Value::Type(t) => {
                return crate::library::construct_type(self, t, args_val, sp);
            }
            other => {
                if in_math {
                    // Symbol/content application in math: `f(x)` with f content.
                    let mut children = vec![display_in_math(other)];
                    let mut open = vec![Content::symbol("(")];
                    let mut first = true;
                    for arg in args_val.items {
                        if !first {
                            open.push(Content::symbol(","));
                        }
                        first = false;
                        open.push(display_in_math(arg.value));
                    }
                    open.push(Content::symbol(")"));
                    children.push(Content::new("lr").with_field(
                        "body",
                        Content::new("sequence").with_field(
                            "children",
                            Value::array(open.into_iter().map(Value::Content).collect()),
                        ),
                    ));
                    return Ok(Value::Content(Content::new("sequence").with_field(
                        "children",
                        Value::array(children.into_iter().map(Value::Content).collect()),
                    )));
                }
                return bail(
                    callee_span,
                    format!("expected function, found {}", other.ty().long_name()),
                );
            }
        };

        self.call_func(&func, args_val, sp)
    }

    pub fn call_method(
        &mut self,
        target: Value,
        method: &str,
        mut args: super::value::Args,
        field_span: Span,
        span: Span,
    ) -> Result<Value> {
        // Associated functions on modules / functions / types / symbols.
        match &target {
            Value::Module(_) | Value::Func(_) | Value::Type(_) | Value::Symbol(_) => {
                if let Value::Type(t) = &target {
                    if let Some(v) = crate::library::type_method(*t, method) {
                        // Methods on the type (e.g. `str.len`) - called as associated functions.
                        return self.call_value(v, args, span);
                    }
                }
                let callee = crate::library::field(self, &target, method).at(field_span)?;
                return self.call_value(callee, args, span);
            }
            _ => {}
        }

        if let Some(r) = crate::library::call_method(self, &target, method, &mut args, field_span, span) {
            return r;
        }

        // Content elements have a separate error message.
        if let Value::Content(c) = &target {
            return bail(field_span, format!("element {} has no method `{method}`", c.elem()));
        }

        let mut d = SourceDiagnostic::error(
            field_span,
            format!("type {} has no method `{method}`", target.ty().long_name()),
        );
        match &target {
            Value::Dict(dict) if matches!(dict.get(method), Some(Value::Func(_))) => {
                d = d.with_hint(format!(
                    "to call the function stored in the dictionary, surround the field access with parentheses, e.g. `(dict.{method})(..)`"
                ));
            }
            _ => {
                if crate::library::field(self, &target, method).is_ok() {
                    d = d.with_hint(format!("did you mean to access the field `{method}`?"));
                }
            }
        }
        Err(vec![d])
    }

    pub fn call_value(&mut self, callee: Value, args: super::value::Args, span: Span) -> Result<Value> {
        match callee {
            Value::Func(f) => self.call_func(&f, args, span),
            Value::Type(t) => crate::library::construct_type(self, t, args, span),
            other => bail(span, format!("expected function, found {}", other.ty().long_name())),
        }
    }

    pub fn call_func(&mut self, func: &Func, args: super::value::Args, span: Span) -> Result<Value> {
        self.depth += 1;
        if self.depth > MAX_CALL_DEPTH {
            self.depth -= 1;
            return bail(span, "maximum function call depth exceeded");
        }
        let result = match func {
            Func::Native(n) => {
                let mut args = args;
                let r = (n.func)(self, &mut args, span);
                match r {
                    Ok(v) => finish_args(&args).map(|_| v),
                    Err(e) => Err(e),
                }
            }
            Func::Elem(elem) => {
                let mut args = args;
                crate::library::elements::construct(self, elem, &mut args, span).map(Value::Content)
            }
            Func::Closure(c) => self.call_closure(c, func, args, span),
            Func::With(w) => {
                let (inner, bound) = &**w;
                let mut all = bound.clone();
                all.items.extend(args.items);
                all.span = args.span;
                self.call_func(inner, all, span)
            }
        };
        self.depth -= 1;
        // Add trace for closures.
        result.map_err(|mut errs| {
            if let Func::Closure(_) = func {
                for e in &mut errs {
                    if e.severity == Severity::Error && !e.span.is_detached() && e.span != span {
                        let name = func.name();
                        let point = match name {
                            Some(n) => format!("error occurred in this call of function `{n}`"),
                            None => "error occurred in this function call".to_string(),
                        };
                        if e.trace.last().map(|(s, _)| *s) != Some(span) {
                            e.trace.push((span, point));
                        }
                    }
                }
            }
            errs
        })
    }

    fn call_closure(
        &mut self,
        closure: &Rc<ClosureValue>,
        this: &Func,
        mut args: super::value::Args,
        span: Span,
    ) -> Result<Value> {
        let ast = &closure.ast;
        // Fresh scopes from captured variables.
        let mut scopes = Scopes::new(true);
        scopes.top = closure.captured.clone();
        scopes.enter();
        let saved_scopes = std::mem::replace(&mut self.scopes, scopes);
        let saved_flow = self.flow.take();
        let saved_file = self.file;
        let saved_math = self.in_math;
        self.file = closure.file;
        self.in_math = false;

        let result = (|| -> Result<Value> {
            if let Some(name) = &ast.name {
                self.define(&name.name, Value::Func(this.clone()), name.span);
            }

            let num_pos_params = ast.params.iter().filter(|p| matches!(p, Param::Pos(_))).count();
            let num_pos_args = args.remaining_pos();
            let sink_size = num_pos_args.checked_sub(num_pos_params);
            let mut sink: Option<Option<Ident>> = None;
            let mut sink_pos_values: Option<Vec<super::value::Arg>> = None;
            let mut defaults = closure.defaults.iter();

            for p in &ast.params {
                match p {
                    Param::Pos(pattern) => match pattern {
                        Pattern::Normal(Expr { kind: ExprKind::Ident(name), span: psp }) => {
                            let v = match args.eat_pos() {
                                Some(a) => a.value,
                                None => return bail(args.span, format!("missing argument: {name}")),
                            };
                            self.define(name, v, *psp);
                        }
                        pattern => {
                            let v = match args.eat_pos() {
                                Some(a) => a.value,
                                None => {
                                    return bail(args.span, "missing argument: pattern parameter")
                                }
                            };
                            self.destructure(pattern, v)?;
                        }
                    },
                    Param::Spread(name, _) => {
                        sink = Some(name.clone());
                        if let Some(n) = sink_size {
                            let mut taken = Vec::new();
                            for _ in 0..n {
                                if let Some(a) = args.eat_pos() {
                                    taken.push(a);
                                }
                            }
                            sink_pos_values = Some(taken);
                        }
                    }
                    Param::Named(name, _) => {
                        let default = defaults.next().cloned().unwrap_or(Value::None);
                        let v = match args.take_named(&name.name) {
                            Some(a) => a.value,
                            None => default,
                        };
                        self.define(&name.name, v, name.span);
                    }
                }
            }

            if let Some(sink) = sink {
                let mut remaining = std::mem::take(&mut args.items);
                if let Some(name) = sink {
                    if let Some(pos) = sink_pos_values {
                        remaining.extend(pos);
                    }
                    let a = super::value::Args { span: args.span, items: remaining };
                    self.define(&name.name, Value::Args(Rc::new(a)), name.span);
                }
            }

            finish_args(&args)?;

            let output = self.eval_expr(&ast.body)?;
            match self.flow.take() {
                Some(FlowEvent::Return(_, Some(explicit))) => Ok(explicit),
                Some(FlowEvent::Return(_, None)) => Ok(output),
                Some(flow) => Err(vec![flow.forbidden()]),
                None => Ok(output),
            }
        })();

        self.scopes = saved_scopes;
        self.flow = saved_flow;
        self.file = saved_file;
        self.in_math = saved_math;
        let _ = span;
        result
    }

    fn eval_closure(&mut self, closure: &Rc<Closure>, span: Span) -> Result<Value> {
        let _ = span;
        Ok(Value::Func(self.make_closure(closure)?))
    }

    fn make_closure(&mut self, closure: &Rc<Closure>) -> Result<Func> {
        // Evaluate default values of named parameters.
        let mut defaults = Vec::new();
        for p in &closure.params {
            if let Param::Named(_, default) = p {
                defaults.push(self.eval_expr(default)?);
            }
        }
        // Capture variables.
        let mut visitor = CapturesVisitor::new(&self.scopes, self.in_math);
        visitor.visit_closure(closure);
        let captured = visitor.finish();
        Ok(Func::Closure(Rc::new(ClosureValue {
            ast: closure.clone(),
            captured,
            defaults,
            file: self.file,
        })))
    }

    // ------------------------------------------------------- Destructuring

    pub fn destructure(&mut self, pattern: &Pattern, value: Value) -> Result<()> {
        self.destructure_impl(pattern, value, false)
    }

    fn destructure_assign(&mut self, pattern: &Pattern, value: Value) -> Result<()> {
        self.destructure_impl(pattern, value, true)
    }

    fn destructure_impl(&mut self, pattern: &Pattern, value: Value, assign: bool) -> Result<()> {
        match pattern {
            Pattern::Normal(expr) => {
                if assign {
                    let loc = self.access(expr)?;
                    *loc = value;
                } else if let ExprKind::Ident(name) = &expr.kind {
                    self.define(name, value, expr.span);
                } else {
                    return bail(self.span(expr.span), "expected pattern");
                }
                Ok(())
            }
            Pattern::Placeholder(_) => Ok(()),
            Pattern::Parenthesized(inner, _) => self.destructure_impl(inner, value, assign),
            Pattern::Destructuring(d) => match value {
                Value::Array(a) => self.destructure_array(d, &a, assign),
                Value::Dict(dict) => self.destructure_dict(d, &dict, assign),
                other => bail(
                    self.span(d.span),
                    format!("cannot destructure {}", other.ty().long_name()),
                ),
            },
        }
    }

    fn destructure_array(&mut self, d: &Destructuring, array: &[Value], assign: bool) -> Result<()> {
        let sp = self.span(d.span);
        let len = array.len();
        let mut i = 0;
        let count_pattern = d.items.iter().filter(|it| !matches!(it, DestructuringItem::Spread(..))).count();
        for item in &d.items {
            match item {
                DestructuringItem::Pattern(p) => {
                    let Some(v) = array.get(i) else {
                        return Err(vec![SourceDiagnostic::error(sp, "not enough elements to destructure")
                            .with_hint(format!(
                                "the provided array has a length of {len}, but the pattern expects {count_pattern} elements"
                            ))]);
                    };
                    self.destructure_impl(p, v.clone(), assign)?;
                    i += 1;
                }
                DestructuringItem::Spread(name, _) => {
                    let sink_size = (1 + len).checked_sub(d.items.len());
                    let sink = sink_size.and_then(|n| array.get(i..i + n));
                    if let (Some(sink_size), Some(sink)) = (sink_size, sink) {
                        if let Some(name) = name {
                            let v = Value::array(sink.to_vec());
                            if assign {
                                let loc = self
                                    .scopes
                                    .get_mut(&name.name)
                                    .map_err(|e| err(self.span(name.span), e))?;
                                *loc = v;
                            } else {
                                self.define(&name.name, v, name.span);
                            }
                        }
                        i += sink_size;
                    } else {
                        return Err(vec![SourceDiagnostic::error(sp, "not enough elements to destructure")
                            .with_hint(format!(
                                "the provided array has a length of {len}, but the pattern expects {count_pattern} elements"
                            ))]);
                    }
                }
                DestructuringItem::Named(name, _) => {
                    return bail(self.span(name.span), "cannot destructure named pattern from an array");
                }
            }
        }
        if i < len {
            return Err(vec![SourceDiagnostic::error(sp, "too many elements to destructure").with_hint(
                format!(
                    "the provided array has a length of {len}, but the pattern expects {count_pattern} elements"
                ),
            )]);
        }
        Ok(())
    }

    fn destructure_dict(&mut self, d: &Destructuring, dict: &Dict, assign: bool) -> Result<()> {
        let mut sink: Option<(Option<&Ident>, Span)> = None;
        let mut used: HashSet<String> = HashSet::new();
        for item in &d.items {
            match item {
                DestructuringItem::Pattern(Pattern::Normal(Expr { kind: ExprKind::Ident(name), span })) => {
                    let v = dict.get(name).cloned().ok_or_else(|| {
                        err(
                            self.span(*span),
                            format!("dictionary does not contain key {}", super::repr::repr_str(name)),
                        )
                    })?;
                    if assign {
                        let loc = self.scopes.get_mut(name).map_err(|e| err(self.span(*span), e))?;
                        *loc = v;
                    } else {
                        self.define(name, v, *span);
                    }
                    used.insert(name.clone());
                }
                DestructuringItem::Named(name, pattern) => {
                    let v = dict.get(&name.name).cloned().ok_or_else(|| {
                        err(
                            self.span(name.span),
                            format!("dictionary does not contain key {}", super::repr::repr_str(&name.name)),
                        )
                    })?;
                    self.destructure_impl(pattern, v, assign)?;
                    used.insert(name.name.clone());
                }
                DestructuringItem::Spread(name, span) => sink = Some((name.as_ref(), *span)),
                DestructuringItem::Pattern(p) => {
                    return bail(self.span(p.span()), "cannot destructure unnamed pattern from dictionary");
                }
            }
        }
        if let Some((Some(name), _)) = sink {
            let mut rest: Dict = IndexMap::new();
            for (k, v) in dict.iter() {
                if !used.contains(k) {
                    rest.insert(k.clone(), v.clone());
                }
            }
            let v = Value::dict(rest);
            if assign {
                let loc = self.scopes.get_mut(&name.name).map_err(|e| err(self.span(name.span), e))?;
                *loc = v;
            } else {
                self.define(&name.name, v, name.span);
            }
        }
        Ok(())
    }

    // -------------------------------------------------------------- Loops

    fn eval_while(&mut self, cond: &Expr, body: &Expr) -> Result<Value> {
        let flow = self.flow.take();
        let mut output = Value::None;
        let mut i = 0;
        loop {
            let c = self.eval_expr(cond)?;
            let c = match c {
                Value::Bool(b) => b,
                other => {
                    return bail(
                        self.span(cond.span),
                        format!("expected boolean, found {}", other.ty().long_name()),
                    )
                }
            };
            if !c {
                break;
            }
            let value = self.eval_expr(body)?;
            output = ops::join(output, value).at(self.span(body.span))?;
            match self.flow {
                Some(FlowEvent::Break(_)) => {
                    self.flow = None;
                    break;
                }
                Some(FlowEvent::Continue(_)) => self.flow = None,
                Some(FlowEvent::Return(..)) => break,
                None => {}
            }
            i += 1;
            if i >= 100_000_000 {
                return bail(self.span(cond.span), "loop seems to be infinite");
            }
        }
        if flow.is_some() {
            self.flow = flow;
        }
        Ok(output)
    }

    fn eval_for(&mut self, pattern: &Pattern, iterable: &Expr, body: &Expr) -> Result<Value> {
        let flow = self.flow.take();
        let mut output = Value::None;
        let iter_val = self.eval_expr(iterable)?;
        let items: Vec<Value> = match &iter_val {
            Value::Array(a) => a.iter().cloned().collect(),
            Value::Dict(d) => d
                .iter()
                .map(|(k, v)| Value::array(vec![Value::str(k.clone()), v.clone()]))
                .collect(),
            Value::Str(s) => {
                use unicode_segmentation::UnicodeSegmentation;
                s.graphemes(true).map(Value::str).collect()
            }
            Value::Bytes(b) => b.iter().map(|&x| Value::Int(x as i64)).collect(),
            other => {
                return bail(
                    self.span(iterable.span),
                    format!("cannot loop over {}", other.ty().long_name()),
                )
            }
        };
        self.scopes.enter();
        let result = (|| -> Result<()> {
            for item in items {
                self.destructure(pattern, item)?;
                let value = self.eval_expr(body)?;
                output = ops::join(std::mem::replace(&mut output, Value::None), value)
                    .at(self.span(body.span))?;
                match self.flow {
                    Some(FlowEvent::Break(_)) => {
                        self.flow = None;
                        break;
                    }
                    Some(FlowEvent::Continue(_)) => self.flow = None,
                    Some(FlowEvent::Return(..)) => break,
                    None => {}
                }
            }
            Ok(())
        })();
        self.scopes.exit();
        result?;
        if flow.is_some() {
            self.flow = flow;
        }
        Ok(output)
    }

    // ---------------------------------------------------------- Set/Show

    fn eval_set(&mut self, expr: &Expr) -> Result<Rc<Styles>> {
        let ExprKind::Set { target, args, condition } = &expr.kind else { unreachable!() };
        if let Some(cond) = condition {
            let c = self.eval_expr(cond)?;
            match c {
                Value::Bool(false) => return Ok(Rc::new(Styles::default())),
                Value::Bool(true) => {}
                other => {
                    return bail(
                        self.span(cond.span),
                        format!("expected boolean, found {}", other.ty().long_name()),
                    )
                }
            }
        }
        let target_val = self.eval_expr(target)?;
        let elem = match &target_val {
            Value::Func(f) => match f.elem() {
                Some(e) => e,
                None => {
                    return bail(self.span(target.span), "only element functions can be used in set rules")
                }
            },
            other => {
                return bail(
                    self.span(target.span),
                    format!("expected function, found {}", other.ty().long_name()),
                )
            }
        };
        let mut args_val = self.eval_args(args)?;
        let fields = crate::library::elements::set_fields(self, elem, &mut args_val, self.span(expr.span))?;
        Ok(Rc::new(Styles { rules: vec![StyleRule::Set { elem, fields }] }))
    }

    fn eval_show(&mut self, expr: &Expr) -> Result<Recipe> {
        let ExprKind::Show { selector, transform } = &expr.kind else { unreachable!() };
        let selector_val = match selector {
            Some(s) => {
                let v = self.eval_expr(s)?;
                Some(crate::library::cast_selector(&v, true).at(self.span(s.span))?)
            }
            None => None,
        };
        let transform_val = match &transform.kind {
            ExprKind::Set { .. } => Value::Styles(self.eval_set(transform)?),
            _ => self.eval_expr(transform)?,
        };
        match &transform_val {
            Value::Func(_) | Value::Content(_) | Value::Str(_) | Value::Styles(_) | Value::Symbol(_) | Value::None => {}
            other => {
                return bail(
                    self.span(transform.span),
                    format!("expected content, function, or string, found {}", other.ty().long_name()),
                )
            }
        }
        Ok(Recipe { selector: selector_val, transform: transform_val })
    }

    fn apply_recipe(&mut self, content: Content, recipe: Recipe, span: Span) -> Result<Content> {
        if recipe.selector.is_none() {
            // Apply the transformation directly.
            return match recipe.transform {
                Value::Func(f) => {
                    let args = super::value::Args::new(self.span(span), vec![Value::Content(content)]);
                    let v = self.call_func(&f, args, self.span(span))?;
                    Ok(display(v))
                }
                Value::Styles(styles) => Ok(styled(content, styles)),
                other => Ok(display(other)),
            };
        }
        let styles = Styles {
            rules: vec![StyleRule::Show { selector: recipe.selector, transform: recipe.transform }],
        };
        Ok(styled(content, Rc::new(styles)))
    }

    // ------------------------------------------------------------ Imports

    fn eval_import(
        &mut self,
        source: &Expr,
        new_name: Option<&Ident>,
        imports: Option<&Imports>,
        span: Span,
    ) -> Result<Value> {
        let source_val = self.eval_expr(source)?;
        let source_span = self.span(source.span);
        let module: Value = match &source_val {
            Value::Str(path) => {
                let m = self.import_file(path, source_span)?;
                Value::Module(m)
            }
            Value::Module(_) | Value::Func(_) | Value::Type(_) => source_val.clone(),
            other => {
                return bail(
                    source_span,
                    format!("expected path, module, function, or type, found {}", other.ty().long_name()),
                )
            }
        };

        if let Some(name) = new_name {
            self.define(&name.name, module.clone(), name.span);
        } else if imports.is_none() {
            // Bind by module name.
            match &module {
                Value::Module(m) => {
                    let n = m.name.clone();
                    self.define(&n, module.clone(), source.span);
                }
                Value::Func(f) => {
                    if let Some(n) = f.name() {
                        self.define(&n, module.clone(), source.span);
                    }
                }
                Value::Type(t) => {
                    let n = t.short_name().to_string();
                    self.define(&n, module.clone(), source.span);
                }
                _ => {}
            }
        }

        match imports {
            None => {}
            Some(Imports::Wildcard) => {
                let scope = crate::library::value_scope(&module);
                if let Some(scope) = scope {
                    for (k, b) in scope.map.iter() {
                        self.define(k, b.value.clone(), span);
                    }
                }
            }
            Some(Imports::Items(items)) => {
                for item in items {
                    let mut current = module.clone();
                    let mut path_iter = item.path.iter();
                    let first = path_iter.next().unwrap();
                    let mut value = match crate::library::field(self, &current, &first.name) {
                        Ok(v) => v,
                        Err(_) => return bail(self.span(first.span), "unresolved import"),
                    };
                    for seg in path_iter {
                        current = value;
                        value = match crate::library::field(self, &current, &seg.name) {
                            Ok(v) => v,
                            Err(_) => return bail(self.span(seg.span), "unresolved import"),
                        };
                    }
                    let bind = item.rename.as_ref().unwrap_or(item.path.last().unwrap());
                    self.define(&bind.name, value, bind.span);
                }
            }
        }
        Ok(Value::None)
    }

    fn import_file(&mut self, path: &str, span: Span) -> Result<Rc<Module>> {
        if path.starts_with('@') {
            return self.import_package(path, span);
        }
        let id = self.world.resolve(self.file, path, span)?;
        if self.route.contains(&id) {
            return bail(span, "cyclic import");
        }
        self.eval_module(id, span)
    }

    fn import_package(&mut self, spec: &str, span: Span) -> Result<Rc<Module>> {
        let id = self.world.resolve_package(spec, span)?;
        self.eval_module(id, span)
    }

    pub fn eval_module(&mut self, id: u16, span: Span) -> Result<Rc<Module>> {
        if let Some(m) = self.world.module_cache.get(&id) {
            return Ok(m.clone());
        }
        let text = self.world.source(id).text.clone();
        let (ast, errors) = crate::syntax::parser::parse_markup(&text);
        if !errors.is_empty() {
            return Err(errors
                .into_iter()
                .map(|e| {
                    let mut d = SourceDiagnostic::error(e.span.with_file(id), e.message);
                    d.hints = e.hints;
                    d
                })
                .collect());
        }
        let saved_scopes = std::mem::replace(&mut self.scopes, Scopes::new(true));
        let saved_file = self.file;
        let saved_flow = self.flow.take();
        self.file = id;
        self.route.push(id);
        let result = match &ast.kind {
            ExprKind::Markup(exprs) => self.eval_markup(exprs),
            _ => unreachable!(),
        };
        self.route.pop();
        let scopes = std::mem::replace(&mut self.scopes, saved_scopes);
        self.file = saved_file;
        self.flow = saved_flow;
        let content = result?;
        let _ = span;
        let name = self.world.source(id).module_name();
        let module = Rc::new(Module { name, scope: scopes.top, content: Some(content) });
        self.world.module_cache.insert(id, module.clone());
        Ok(module)
    }

    fn eval_include(&mut self, source: &Expr, span: Span) -> Result<Value> {
        let v = self.eval_expr(source)?;
        let sp = self.span(source.span);
        let path = match v {
            Value::Str(s) => s,
            other => return bail(sp, format!("expected path, found {}", other.ty().long_name())),
        };
        let _ = span;
        let module = self.import_file(&path, sp)?;
        Ok(Value::Content(module.content.clone().unwrap_or_else(Content::empty)))
    }
}

pub struct Recipe {
    pub selector: Option<Selector>,
    pub transform: Value,
}

pub fn finish_args(args: &super::value::Args) -> Result<()> {
    if let Some(arg) = args.items.first() {
        return match &arg.name {
            Some(n) => bail(arg.span, format!("unexpected argument: {n}")),
            None => bail(arg.span, "unexpected argument"),
        };
    }
    Ok(())
}

/// Wrap content with styles.
pub fn styled(content: Content, styles: Rc<Styles>) -> Content {
    if styles.rules.is_empty() {
        return content;
    }
    Content::new("styled")
        .with_field("child", content)
        .with_field("styles", Value::Styles(styles))
}

/// Display a value as content.
pub fn display(value: Value) -> Content {
    match value {
        Value::None => Content::empty(),
        Value::Int(i) => Content::text(&display_int(i)),
        Value::Float(f) => Content::text(&display_float(f)),
        Value::Str(s) => Content::text(&s),
        Value::Version(v) => {
            let parts: Vec<String> = v.iter().map(|n| n.to_string()).collect();
            Content::text(&parts.join("."))
        }
        Value::Symbol(s) => Content::symbol(&s.text),
        Value::Content(c) => c,
        Value::Module(m) => m.content.clone().unwrap_or_else(|| {
            Content::new("raw")
                .with_field("text", Value::str(format!("<module {}>", m.name)))
                .with_field("block", Value::Bool(false))
                .with_field("lang", Value::str("typc"))
        }),
        Value::Dyn(ref d) if matches!(**d, Dynamic::Decimal(_)) => {
            if let Dynamic::Decimal(dec) = &**d {
                let s = super::decimal::to_string(dec);
                Content::text(&s.replacen('-', "\u{2212}", 1))
            } else {
                unreachable!()
            }
        }
        other => Content::new("raw")
            .with_field("text", Value::str(repr(&other)))
            .with_field("block", Value::Bool(false))
            .with_field("lang", Value::str("typc")),
    }
}

/// Display a value in math.
pub fn display_in_math(value: Value) -> Content {
    match value {
        Value::Int(i) => Content::text(&display_int(i)),
        Value::Float(f) => Content::text(&display_float(f)),
        Value::Str(s) => Content::text(&s),
        Value::Symbol(s) => Content::symbol(&s.text),
        Value::Func(f) => Content::new("raw")
            .with_field("text", Value::str(super::repr::repr_func(&f)))
            .with_field("block", Value::Bool(false))
            .with_field("lang", Value::str("typc")),
        other => display(other),
    }
}

// --------------------------------------------------------------- Captures

struct CapturesVisitor<'a> {
    scopes: &'a Scopes,
    captures: Scope,
    internal: Vec<HashSet<String>>,
    in_math: bool,
}

impl<'a> CapturesVisitor<'a> {
    fn new(scopes: &'a Scopes, in_math: bool) -> Self {
        Self { scopes, captures: Scope::new(), internal: vec![HashSet::new()], in_math }
    }

    fn finish(self) -> Scope {
        self.captures
    }

    fn bind(&mut self, name: &str) {
        if let Some(last) = self.internal.last_mut() {
            last.insert(name.to_string());
        }
    }

    fn is_bound(&self, name: &str) -> bool {
        self.internal.iter().any(|s| s.contains(name))
    }

    fn capture(&mut self, name: &str, math: bool) {
        if self.is_bound(name) || self.captures.get(name).is_some() {
            return;
        }
        let binding = if math { self.scopes.get_in_math(name) } else { self.scopes.get(name) };
        if let Some(b) = binding {
            self.captures.map.insert(name.to_string(), b);
        }
    }

    fn visit_closure(&mut self, closure: &Closure) {
        // Defaults are evaluated outside.
        for p in &closure.params {
            if let Param::Named(_, default) = p {
                self.visit(default);
            }
        }
        self.internal.push(HashSet::new());
        if let Some(name) = &closure.name {
            self.bind(&name.name);
        }
        for p in &closure.params {
            match p {
                Param::Pos(pat) => self.bind_pattern(pat),
                Param::Named(name, _) => self.bind(&name.name),
                Param::Spread(Some(name), _) => self.bind(&name.name),
                Param::Spread(None, _) => {}
            }
        }
        self.visit(&closure.body);
        self.internal.pop();
    }

    fn bind_pattern(&mut self, pat: &Pattern) {
        for id in pat.bindings() {
            self.bind(&id.name);
        }
    }

    fn visit_all(&mut self, exprs: &[Expr]) {
        for e in exprs {
            self.visit(e);
        }
    }

    fn visit(&mut self, expr: &Expr) {
        match &expr.kind {
            ExprKind::Ident(name) => self.capture(name, self.in_math),
            ExprKind::MathIdent(name) => self.capture(name, true),
            ExprKind::Markup(exprs) | ExprKind::Math(exprs) => self.visit_all(exprs),
            ExprKind::Strong(b) | ExprKind::Emph(b) => self.visit_all(b),
            ExprKind::Heading { body, .. } | ExprKind::ListItem { body } | ExprKind::EnumItem { body, .. } => {
                self.visit_all(body)
            }
            ExprKind::TermItem { term, description } => {
                self.visit_all(term);
                self.visit_all(description);
            }
            ExprKind::Equation { body, .. } => {
                let was = self.in_math;
                self.in_math = true;
                self.visit_all(body);
                self.in_math = was;
            }
            ExprKind::Ref { supplement, .. } => {
                if let Some(s) = supplement {
                    self.visit(s);
                }
            }
            ExprKind::MathDelimited { open, body, close } => {
                self.visit(open);
                self.visit_all(body);
                self.visit(close);
            }
            ExprKind::MathAttach { base, bottom, top, primes } => {
                self.visit(base);
                for e in [bottom, top, primes].into_iter().flatten() {
                    self.visit(e);
                }
            }
            ExprKind::MathFrac { num, denom } => {
                self.visit(num);
                self.visit(denom);
            }
            ExprKind::MathRoot { radicand, .. } => self.visit(radicand),
            ExprKind::CodeBlock(exprs) => {
                self.internal.push(HashSet::new());
                self.visit_all(exprs);
                self.internal.pop();
            }
            ExprKind::ContentBlock(exprs) => {
                self.internal.push(HashSet::new());
                let was = self.in_math;
                self.in_math = false;
                self.visit_all(exprs);
                self.in_math = was;
                self.internal.pop();
            }
            ExprKind::Parenthesized(e) => self.visit(e),
            ExprKind::Array(items) => {
                for item in items {
                    match item {
                        ArrayItem::Pos(e) | ArrayItem::Spread(e) => self.visit(e),
                    }
                }
            }
            ExprKind::Dict(items) => {
                for item in items {
                    match item {
                        DictItem::Named(_, e) | DictItem::Spread(e) => self.visit(e),
                        DictItem::Keyed(k, e) => {
                            self.visit(k);
                            self.visit(e);
                        }
                    }
                }
            }
            ExprKind::Unary { expr, .. } => self.visit(expr),
            ExprKind::Binary { lhs, rhs, .. } => {
                self.visit(lhs);
                self.visit(rhs);
            }
            ExprKind::FieldAccess { target, .. } => self.visit(target),
            ExprKind::FuncCall { callee, args } => {
                self.visit(callee);
                self.visit_args(args);
            }
            ExprKind::Closure(c) => self.visit_closure(c),
            ExprKind::Let { pattern, init } => {
                if let Some(e) = init {
                    self.visit(e);
                }
                self.bind_pattern(pattern);
            }
            ExprKind::DestructAssign { pattern, value } => {
                self.visit(value);
                let _ = pattern;
            }
            ExprKind::Set { target, args, condition } => {
                self.visit(target);
                self.visit_args(args);
                if let Some(c) = condition {
                    self.visit(c);
                }
            }
            ExprKind::Show { selector, transform } => {
                if let Some(s) = selector {
                    self.visit(s);
                }
                self.visit(transform);
            }
            ExprKind::Contextual(body) => self.visit(body),
            ExprKind::Conditional { cond, if_body, else_body } => {
                self.visit(cond);
                self.visit(if_body);
                if let Some(e) = else_body {
                    self.visit(e);
                }
            }
            ExprKind::While { cond, body } => {
                self.visit(cond);
                self.visit(body);
            }
            ExprKind::For { pattern, iterable, body } => {
                self.visit(iterable);
                self.internal.push(HashSet::new());
                self.bind_pattern(pattern);
                self.visit(body);
                self.internal.pop();
            }
            ExprKind::Import { source, new_name, imports } => {
                self.visit(source);
                if let Some(n) = new_name {
                    self.bind(&n.name);
                }
                match imports {
                    Some(Imports::Items(items)) => {
                        for item in items {
                            let bind = item.rename.as_ref().unwrap_or(item.path.last().unwrap());
                            self.bind(&bind.name);
                        }
                    }
                    _ => {}
                }
            }
            ExprKind::Include(s) => self.visit(s),
            ExprKind::Return(Some(e)) => self.visit(e),
            _ => {}
        }
    }

    fn visit_args(&mut self, args: &Args) {
        for a in &args.items {
            match a {
                Arg::Pos(e) | Arg::Spread(e) => self.visit(e),
                Arg::Named(_, e) => self.visit(e),
            }
        }
    }
}

#[allow(dead_code)]
pub fn parse_mode(mode: &str) -> Option<LexMode> {
    match mode {
        "markup" => Some(LexMode::Markup),
        "code" => Some(LexMode::Code),
        "math" => Some(LexMode::Math),
        _ => None,
    }
}
