        s.trim_end_matches(['\n', '\r'])
    }

    pub fn lines(&self) -> usize {
        self.line_starts.len()
    }
}

fn compute_line_starts(text: &str) -> Vec<usize> {
    let mut starts = vec![0];
    let bytes = text.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        if b == b'\n' {
            starts.push(i + 1);
        } else if b == b'\r' {
            if bytes.get(i + 1) == Some(&b'\n') {
                i += 1;
            }
            starts.push(i + 1);
        } else if b == 0x0B || b == 0x0C {
            starts.push(i + 1);
        } else if b == 0xC2 && bytes.get(i + 1) == Some(&0x85) {
            i += 1;
            starts.push(i + 1);
        } else if b == 0xE2 && bytes.get(i + 1) == Some(&0x80) && matches!(bytes.get(i + 2), Some(0xA8) | Some(0xA9)) {
            i += 2;
            starts.push(i + 1);
        }
        i += 1;
    }
    starts
}

pub struct World {
    pub root: PathBuf,
    pub sources: Vec<Source>,
    pub module_cache: HashMap<u16, Rc<Module>>,
    pub warnings: Vec<SourceDiagnostic>,
    pub inputs: Vec<(String, String)>,
    /// Whether file system access is allowed (false for plain `eval`).
    pub fs_allowed: bool,
    pub package_path: Option<PathBuf>,
    pub package_cache_path: Option<PathBuf>,
    pub creation_timestamp: Option<i64>,
    pub features: Vec<String>,
    pub target: String,
}

impl World {
    pub fn new(root: PathBuf) -> Self {
        World {
            root,
            sources: Vec::new(),
            module_cache: HashMap::new(),
            warnings: Vec::new(),
            inputs: Vec::new(),
            fs_allowed: true,
            package_path: None,
            package_cache_path: None,
            creation_timestamp: None,
            features: Vec::new(),
            target: "paged".into(),
        }
    }

    pub fn add_source(&mut self, vpath: String, real: Option<PathBuf>, text: String) -> u16 {
        let id = self.sources.len() as u16;
        self.sources.push(Source::new(id, vpath, real, text));
        id
    }

    pub fn source(&self, id: u16) -> &Source {
        &self.sources[id as usize]
    }

    /// Resolve a path relative to a source file.
    pub fn resolve(&mut self, from: u16, path: &str, span: Span) -> Result<u16> {
        let real = self.resolve_path(from, path, span)?;
        // Already loaded?
        if let Some(s) = self.sources.iter().find(|s| s.real.as_deref() == Some(real.as_path())) {
            return Ok(s.id);
        }
        let text = match std::fs::read(&real) {
            Ok(bytes) => match String::from_utf8(bytes) {
                Ok(t) => t,
                Err(_) => return bail(span, "file is not valid utf-8"),
            },
            Err(e) => return bail(span, io_error_message(&e, &real)),
        };
        let vpath = self.vpath_of(&real);
        Ok(self.add_source(vpath, Some(real), text))
    }

    pub fn vpath_of(&self, real: &Path) -> String {
        match real.strip_prefix(&self.root) {
            Ok(rel) => format!("/{}", rel.display()),
            Err(_) => format!("/{}", real.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default()),
        }
    }

    /// Resolve a path to a real filesystem path, checking root containment.
    pub fn resolve_path(&self, from: u16, path: &str, span: Span) -> Result<PathBuf> {
        if !self.fs_allowed {
            return bail(span, "cannot access file system from here");
        }
        let base_vpath = &self.source(from).vpath;
        let joined = if path.starts_with('/') {
            normalize(&PathBuf::from(path.trim_start_matches('/')))
        } else {
            let parent = Path::new(base_vpath).parent().map(|p| p.to_path_buf()).unwrap_or_default();
            let parent = PathBuf::from(parent.to_string_lossy().trim_start_matches('/'));
            normalize(&parent.join(path))
        };
        if joined.starts_with("..") {
            let shown = self.root.join(path);
            let _ = shown;
            return bail(span, format!("file not found (searched at {})", self.root.join(&joined).display()))
                .map_err(|mut e: Vec<SourceDiagnostic>| {
                    e[0].message = "failed to load file (access denied)".into();
                    e
                });
        }
        Ok(self.root.join(joined))
    }

    /// Read a file's bytes relative to a source.
    pub fn read_file(&self, from: u16, path: &str, span: Span) -> Result<Vec<u8>> {
        let real = self.resolve_path(from, path, span)?;
        match std::fs::read(&real) {
            Ok(b) => Ok(b),
            Err(e) => bail(span, io_error_message(&e, &real)),
        }
    }

    pub fn resolve_package(&mut self, spec: &str, span: Span) -> Result<u16> {
        // Parse `@namespace/name:version`
        let rest = &spec[1..];
        let (ns, rest) = match rest.split_once('/') {
            Some(x) => x,
            None => return bail(span, "package specification is missing name"),
        };
        let (name, version) = match rest.split_once(':') {
            Some(x) => x,
            None => return bail(span, "package specification is missing version"),
        };
        let (name, subpath) = match name.split_once('/') {
            Some((n, p)) => (n, Some(p)),
            None => (name, None),
        };
        // Look in local package path and cache.
        let mut dirs = Vec::new();
        if let Some(p) = &self.package_path {
            dirs.push(p.clone());
        }
        if let Some(p) = &self.package_cache_path {
            dirs.push(p.clone());
        }
        for dir in dirs {
            let pkg = dir.join(ns).join(name).join(version);
            if pkg.is_dir() {
                // Read typst.toml for entrypoint.
                let manifest = std::fs::read_to_string(pkg.join("typst.toml")).unwrap_or_default();
                let entry = manifest
                    .lines()
                    .find_map(|l| {
                        let l = l.trim();
                        l.strip_prefix("entrypoint")
                            .and_then(|r| r.trim().strip_prefix('='))
                            .map(|v| v.trim().trim_matches('"').to_string())
                    })
                    .unwrap_or_else(|| "lib.typ".into());
                let file = match subpath {
                    Some(p) => pkg.join(p),
                    None => pkg.join(entry),
                };
                let text = match std::fs::read_to_string(&file) {
                    Ok(t) => t,
                    Err(e) => return bail(span, io_error_message(&e, &file)),
                };
                let vpath = format!("/{}", file.file_name().unwrap().to_string_lossy());
                return Ok(self.add_source(vpath, Some(file), text));
            }
        }
        if ns == "preview" {
            return bail(
                span,
                format!(
                    "failed to download package (https://packages.typst.org/preview/{name}-{version}.tar.gz: Dns Failed: resolve dns name 'packages.typst.org:443': failed to lookup address information: Temporary failure in name resolution)"
                ),
            );
        }
        bail(span, format!("package not found (searched for @{ns}/{name}:{version})"))
    }
}

pub fn io_error_message(e: &std::io::Error, path: &Path) -> String {
    match e.kind() {
        std::io::ErrorKind::NotFound => format!("file not found (searched at {})", path.display()),
        std::io::ErrorKind::PermissionDenied => "failed to load file (access denied)".into(),
        _ => {
            if path.is_dir() {
                "failed to load file (is a directory)".into()
            } else {
                format!("failed to load file ({e})")
            }
        }
    }
}

fn normalize(path: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for comp in path.components() {
        match comp {
            std::path::Component::ParentDir => {
                if !out.pop() {
                    out.push("..");
                }
            }
            std::path::Component::CurDir => {}
            c => out.push(c.as_os_str()),
        }
    }
    out
}
