/// A value with its span.
pub struct Spanned<T> {
    pub v: T,
    pub span: Span,
}

// ----------------------------------------------------------------- Args

impl Args {
    fn cast_arg<T: FromValue>(arg: Arg) -> Result<T> {
        let span = arg.value_span;
        T::from_value(arg.value).map_err(|e| {
            let mut parts = e.split("\u{0}hint:");
            let msg = parts.next().unwrap_or("").to_string();
            let mut d = SourceDiagnostic::error(span, msg);
            for h in parts {
                d.hints.push(h.to_string());
            }
            vec![d]
        })
    }

    /// Take the first positional argument and cast it.
    pub fn expect<T: FromValue>(&mut self, what: &str) -> Result<T> {
        match self.eat_pos() {
            Some(arg) => Self::cast_arg(arg),
            None => Err(vec![SourceDiagnostic::error(self.span, format!("missing argument: {what}"))]),
        }
    }

    /// Take the first positional argument with its span.
    pub fn expect_spanned<T: FromValue>(&mut self, what: &str) -> Result<Spanned<T>> {
        match self.eat_pos() {
            Some(arg) => {
                let span = arg.value_span;
                Self::cast_arg(arg).map(|v| Spanned { v, span })
            }
            None => Err(vec![SourceDiagnostic::error(self.span, format!("missing argument: {what}"))]),
        }
    }

    /// Take the first positional argument if present.
    pub fn eat<T: FromValue>(&mut self) -> Result<Option<T>> {
        match self.eat_pos() {
            Some(arg) => Self::cast_arg(arg).map(Some),
            None => Ok(None),
        }
    }

    pub fn eat_spanned<T: FromValue>(&mut self) -> Result<Option<Spanned<T>>> {
        match self.eat_pos() {
            Some(arg) => {
                let span = arg.value_span;
                Self::cast_arg(arg).map(|v| Some(Spanned { v, span }))
            }
            None => Ok(None),
        }
    }

    /// Take a named argument if present.
    pub fn named<T: FromValue>(&mut self, name: &str) -> Result<Option<T>> {
        match self.take_named(name) {
            Some(arg) => Self::cast_arg(arg).map(Some),
            None => Ok(None),
        }
