    }
    fn from_value(v: Value) -> std::result::Result<Self, String> {
        match v {
            Value::None => Ok(None),
            v => match T::from_value(v.clone()) {
                Ok(t) => Ok(Some(t)),
                Err(e) if e.starts_with("expected ") && !e.contains('\u{0}') => {
                    Err(format!("expected {}, found {}", Self::describe(), v.ty().long_name()))
                }
                Err(e) => Err(e),
            },
        }
    }
}

