pub fn symbol_value(variants: &[(&str, &str)]) -> Value {
    let vs: Vec<(String, String)> =
        variants.iter().map(|(m, c)| (m.to_string(), c.to_string())).collect();
    let text = best_variant(&vs, "").unwrap_or_default();
    Value::Symbol(Rc::new(Symbol { variants: vs, modifiers: vec![], text }))
}

pub fn best_variant(variants: &[(String, String)], modifiers: &str) -> Option<String> {
    let parts = |s: &str| s.split('.').filter(|p| !p.is_empty()).map(|s| s.to_string()).collect::<Vec<_>>();
    let wanted = parts(modifiers);
    let mut best: Option<(usize, std::cmp::Reverse<usize>, String)> = None;
    'outer: for (m, c) in variants {
        let have = parts(m);
        for w in &wanted {
            if !have.contains(w) {
                continue 'outer;
            }
        }
        let matching = have.iter().filter(|h| wanted.contains(h)).count();
        let total = have.len();
        let score = (matching, std::cmp::Reverse(total));
        if best.as_ref().is_none_or(|b| score > (b.0, b.1)) {
            best = Some((score.0, score.1, c.clone()));
        }
    }
    best.map(|b| b.2)
}

