/// Field access on a value.
pub fn field(vm: &mut Vm, value: &Value, name: &str) -> std::result::Result<Value, String> {
    match value {
        Value::Symbol(sym) => {
            let mods = if sym.modifiers.is_empty() {
                name.to_string()
            } else {
                format!("{}.{}", sym.modifiers.join("."), name)
            };
            match best_variant(&sym.variants, &mods) {
                Some(text) => {
                    let mut m = sym.modifiers.clone();
                    m.push(name.to_string());
                    Ok(Value::Symbol(Rc::new(Symbol { variants: sym.variants.clone(), modifiers: m, text })))
                }
                None => Err("unknown symbol modifier".into()),
            }
        }
        Value::Version(v) => {
            let idx = match name {
                "major" => 0,
                "minor" => 1,
                "patch" => 2,
                _ => return Err(format!("unknown version component")),
            };
            Ok(Value::Int(v.get(idx).copied().unwrap_or(0) as i64))
        }
        Value::Dict(d) => match d.get(name) {
            Some(v) => Ok(v.clone()),
            None => Err(format!("dictionary does not contain key {}", crate::eval::repr::repr_str(name))),
        },
        Value::Content(c) => content_field(c, name),
        Value::Type(t) => match type_scope_get(*t, name) {
            Some(v) => Ok(v),
            None => Err(format!("type {} does not contain field `{name}`", t.long_name())),
        },
        Value::Func(f) => match func_field(f, name) {
            Some(v) => Ok(v),
            None => Err(format!(
                "function `{}` does not contain field `{name}`",
                f.name().unwrap_or_else(|| "(..) => ..".into())
            )),
        },
        Value::Module(m) => match m.scope.get(name) {
            Some(b) => {
                if let Some(dep) = b.deprecation {
                    vm.warn(crate::eval::vm::SourceDiagnostic::warning(Span::detached(), dep.to_string()));
                }
                Ok(b.value.clone())
            }
            None => Err(format!("module `{}` does not contain `{name}`", m.name)),
        },
        Value::Length(l) => match name {
            "abs" => Ok(Value::Length(Length::pt(l.abs))),
            "em" => Ok(Value::Float(l.em)),
            _ => Err(format!("length does not contain field {}", crate::eval::repr::repr_str(name))),
        },
        Value::Relative(r) => match name {
            "ratio" => Ok(Value::Ratio(r.rel)),
            "length" => Ok(Value::Length(r.abs)),
            _ => Err(format!("relative length does not contain field {}", crate::eval::repr::repr_str(name))),
        },
        Value::Dyn(d) => match &**d {
            Dynamic::Alignment(a) => match name {
                "x" => Ok(match a.h {
                    Some(h) => Value::dynamic(Dynamic::Alignment(Alignment { h: Some(h), v: None })),
                    None => Value::None,
                }),
                "y" => Ok(match a.v {
                    Some(v) => Value::dynamic(Dynamic::Alignment(Alignment { h: None, v: Some(v) })),
                    None => Value::None,
                }),
                _ => Err(format!("alignment does not contain field {}", crate::eval::repr::repr_str(name))),
            },
            Dynamic::Stroke(s) => match name {
                "paint" => Ok(s.paint.clone().unwrap_or(Value::Auto)),
                "thickness" => Ok(s.thickness.clone().unwrap_or(Value::Auto)),
                "cap" => Ok(s.cap.clone().unwrap_or(Value::Auto)),
                "join" => Ok(s.join.clone().unwrap_or(Value::Auto)),
                "dash" => Ok(s.dash.clone().unwrap_or(Value::Auto)),
                "miter-limit" => Ok(s.miter_limit.clone().unwrap_or(Value::Auto)),
                _ => Err(format!("stroke does not contain field {}", crate::eval::repr::repr_str(name))),
            },
            _ => Err(format!("cannot access fields on type {}", value.ty().long_name())),
        },
        _ => Err(format!("cannot access fields on type {}", value.ty().long_name())),
    }
}

pub fn content_field(c: &Content, name: &str) -> std::result::Result<Value, String> {
    if let Some(v) = c.field(name) {
        return Ok(v.clone());
    }
    if name == "label" {
        if let Some(l) = c.label() {
            return Ok(Value::Label(l.clone()));
        }
    }
    let elem = c.elem_func_name();
    if elements::has_param(c.elem(), name) {
        return Err(format!("field \"{name}\" in {elem} is not known at this point"));
    }
    Err(format!("{elem} does not have field \"{name}\""))
}

/// Scope lookup on function values (e.g. `assert.eq`, `heading.where`).
pub fn func_field(f: &Func, name: &str) -> Option<Value> {
    match f {
        Func::Native(n) => n.scope.get(name).map(|b| b.value.clone()),
        Func::Elem(e) => elements::elem_scope_get(e, name),
        Func::With(w) => func_field(&w.0, name),
        Func::TypeCtor(t) => type_scope_get(*t, name),
        Func::Closure(_) => None,
    }
}

/// The scope of a value (for wildcard imports).
pub fn value_scope(v: &Value) -> Option<Scope> {
    match v {
        Value::Module(m) => Some(m.scope.clone()),
        Value::Func(Func::Native(n)) => Some(n.scope.clone()),
        Value::Func(Func::Elem(e)) => Some(elements::elem_scope(e)),
        Value::Type(t) => Some(type_scope(*t)),
        _ => None,
    }
}

pub fn type_scope_get(t: Type, name: &str) -> Option<Value> {
    type_scope(t).get(name).map(|b| b.value.clone())
}

pub fn type_method(t: Type, name: &str) -> Option<Value> {
    type_scope_get(t, name)
}

pub fn type_scope(t: Type) -> Scope {
    let mut s = Scope::new();
    match t {
        Type::Float => {
            s.define("inf", Value::Float(f64::INFINITY));
            s.define("nan", Value::Float(f64::NAN));
            s.define("is-nan", func("is-nan", foundations::float_is_nan));
            s.define("is-infinite", func("is-infinite", foundations::float_is_infinite));
            s.define("signum", func("signum", foundations::float_signum));
            s.define("from-bytes", func("from-bytes", foundations::float_from_bytes));
            s.define("to-bytes", func("to-bytes", foundations::float_to_bytes));
        }
        Type::Int => {
            s.define("signum", func("signum", foundations::int_signum));
            s.define("bit-not", func("bit-not", foundations::int_bit_not));
            s.define("bit-and", func("bit-and", foundations::int_bit_and));
            s.define("bit-or", func("bit-or", foundations::int_bit_or));
            s.define("bit-xor", func("bit-xor", foundations::int_bit_xor));
            s.define("bit-lshift", func("bit-lshift", foundations::int_bit_lshift));
            s.define("bit-rshift", func("bit-rshift", foundations::int_bit_rshift));
            s.define("from-bytes", func("from-bytes", foundations::int_from_bytes));
            s.define("to-bytes", func("to-bytes", foundations::int_to_bytes));
        }
        Type::Str => {
            s.define("from-unicode", func("from-unicode", strings::from_unicode));
            s.define("to-unicode", func("to-unicode", strings::to_unicode));
            for m in strings::METHODS {
                s.define(*m, func(m, strings::method_as_func));
            }
        }
        Type::Array => {
            for m in arrays::METHODS {
                s.define(*m, func(m, arrays::method_as_func));
            }
        }
        Type::Dict => {
            for m in dicts::METHODS {
                s.define(*m, func(m, dicts::method_as_func));
            }
        }
        Type::Datetime => {
            s.define("today", func("today", foundations::datetime_today));
        }
        Type::Color => colors::define_type_scope(&mut s),
        Type::Gradient => colors::define_gradient_scope(&mut s),
        Type::Func => {
            s.define("with", func("with", foundations::func_with));
            s.define("where", func("where", foundations::func_where));
        }
        Type::Selector => {
            s.define("or", func("or", introspection::selector_or));
            s.define("and", func("and", introspection::selector_and));
            s.define("before", func("before", introspection::selector_before));
            s.define("after", func("after", introspection::selector_after));
        }
        Type::Angle | Type::Length | Type::Ratio | Type::Relative | Type::Fraction => {}
        Type::Symbol => {}
        Type::Decimal => {}
        _ => {}
    }
    s
}

pub fn is_mutating_method(name: &str) -> bool {
    matches!(name, "push" | "pop" | "insert" | "remove")
}

/// Call a method on a value. Returns `None` if the method does not exist.
pub fn call_method(
    vm: &mut Vm,
    target: &Value,
    method: &str,
    args: &mut Args,
    field_span: Span,
    span: Span,
) -> Option<Result<Value>> {
    let r = match target {
        Value::Str(s) => strings::call(vm, s, method, args, span),
        Value::Array(a) => arrays::call(vm, a, method, args, span),
        Value::Dict(d) => dicts::call(vm, d, method, args, span),
        Value::Content(c) => foundations::content_method(vm, c, method, args, span),
        Value::Func(f) => foundations::func_method(vm, f, method, args, span),
        Value::Color(c) => colors::method(vm, *c, method, args, span),
        Value::Gradient(g) => colors::gradient_method(vm, g, method, args, span),
        Value::Length(l) => foundations::length_method(vm, *l, method, args, span),
        Value::Angle(a) => foundations::angle_method(vm, *a, method, args, span),
        Value::Datetime(d) => foundations::datetime_method(vm, *d, method, args, span),
        Value::Duration(d) => foundations::duration_method(vm, *d, method, args, span),
        Value::Version(v) => foundations::version_method(vm, v, method, args, span),
        Value::Bytes(b) => foundations::bytes_method(vm, b, method, args, span),
        Value::Args(a) => foundations::args_method(vm, a, method, args, span),
        Value::Int(i) => foundations::int_method(vm, *i, method, args, span),
        Value::Float(f) => foundations::float_method(vm, *f, method, args, span),
        Value::Dyn(d) => match &**d {
            Dynamic::Alignment(a) => foundations::alignment_method(vm, *a, method, args, span),
            Dynamic::Direction(d) => foundations::direction_method(vm, *d, method, args, span),
            Dynamic::Selector(s) => introspection::selector_method(vm, s, method, args, span),
            Dynamic::Counter(k) => introspection::counter_method(vm, k, method, args, span),
            Dynamic::State(k, init) => introspection::state_method(vm, k, init, method, args, span),
            Dynamic::Location(l) => introspection::location_method(vm, *l, method, args, span),
            Dynamic::Decimal(_) => None,
            _ => None,
        },
        _ => None,
    };
    let _ = field_span;
    r.map(|r| r.and_then(|v| args.finish().map(|_| v)))
}

/// Call a mutating method.
pub fn call_method_mut(
    target: &mut Value,
    method: &str,
    mut args: Args,
    field_span: Span,
    span: Span,
) -> Result<Value> {
    let r = match target {
        Value::Array(a) => arrays::call_mut(Rc::make_mut(a), method, &mut args, span)?,
        Value::Dict(d) => dicts::call_mut(Rc::make_mut(d), method, &mut args, span)?,
        other => {
            return bail(
                field_span,
                format!("type {} has no method `{method}`", other.ty().long_name()),
            )
        }
    };
    args.finish()?;
    Ok(r)
}

/// Mutable access via `at`/`first`/`last`.
pub fn access_method<'a>(
    value: &'a mut Value,
    method: &str,
    mut args: Args,
    field_span: Span,
    span: Span,
) -> Result<&'a mut Value> {
    match value {
        Value::Array(a) => {
            let arr = Rc::make_mut(a);
            let r = match method {
                "at" => {
                    let idx: i64 = args.expect("index")?;
                    args.finish()?;
                    let len = arr.len();
                    let i = if idx < 0 { idx + len as i64 } else { idx };
                    if i < 0 || i as usize >= len {
                        return bail(
                            span,
                            format!("array index out of bounds (index: {idx}, len: {len})"),
                        );
                    }
                    &mut arr[i as usize]
                }
                "first" => {
                    args.finish()?;
                    match arr.first_mut() {
                        Some(v) => v,
                        None => return bail(span, "array is empty"),
                    }
                }
                "last" => {
                    args.finish()?;
                    match arr.last_mut() {
                        Some(v) => v,
                        None => return bail(span, "array is empty"),
                    }
                }
                _ => unreachable!(),
            };
            Ok(r)
        }
        Value::Dict(d) => {
            if method != "at" {
                return bail(field_span, format!("type dictionary has no method `{method}`"));
            }
            let key: String = args.expect("key")?;
            args.finish()?;
            let dict = Rc::make_mut(d);
            match dict.get_mut(&key) {
                Some(v) => Ok(v),
                None => bail(
                    span,
                    format!("dictionary does not contain key {}", crate::eval::repr::repr_str(&key)),
                ),
            }
        }
        other => bail(field_span, format!("type {} has no method `{method}`", other.ty().long_name())),
    }
}

/// Construct a value of a type (`str(1)`, `int("2")`, ...).
pub fn construct_type(vm: &mut Vm, t: Type, mut args: Args, span: Span) -> Result<Value> {
    let r = match t {
        Type::Int => foundations::int_ctor(vm, &mut args, span),
        Type::Float => foundations::float_ctor(vm, &mut args, span),
        Type::Str => foundations::str_ctor(vm, &mut args, span),
        Type::Bytes => foundations::bytes_ctor(vm, &mut args, span),
        Type::Label => foundations::label_ctor(vm, &mut args, span),
        Type::Array => foundations::array_ctor(vm, &mut args, span),
        Type::Dict => foundations::dict_ctor(vm, &mut args, span),
        Type::Regex => foundations::regex_ctor(vm, &mut args, span),
        Type::Symbol => foundations::symbol_ctor(vm, &mut args, span),
        Type::Version => foundations::version_ctor(vm, &mut args, span),
        Type::Datetime => foundations::datetime_ctor(vm, &mut args, span),
        Type::Duration => foundations::duration_ctor(vm, &mut args, span),
        Type::Decimal => foundations::decimal_ctor(vm, &mut args, span),
        Type::Args => foundations::arguments_ctor(vm, &mut args, span),
        Type::Type => foundations::type_ctor(vm, &mut args, span),
        Type::Selector => introspection::selector_ctor(vm, &mut args, span),
        Type::Counter => introspection::counter_ctor(vm, &mut args, span),
        Type::State => introspection::state_ctor(vm, &mut args, span),
        Type::Stroke => foundations::stroke_ctor(vm, &mut args, span),
        Type::Color => colors::color_ctor(vm, &mut args, span),
        Type::Gradient => return bail(span, "type gradient does not have a constructor"),
        Type::Tiling => colors::tiling_ctor(vm, &mut args, span),
        _ => return bail(span, format!("type {} does not have a constructor", t.long_name())),
    };
    let v = r?;
    args.finish()?;
    Ok(v)
}

/// Cast a value to a selector.
pub fn cast_selector(v: &Value, allow_show: bool) -> std::result::Result<Selector, String> {
    match v {
        Value::Dyn(d) => match &**d {
            Dynamic::Selector(s) => Ok(s.clone()),
            Dynamic::Regex(r) => Ok(Selector::Regex(r.clone())),
            Dynamic::Location(l) => Ok(Selector::Location(*l)),
            _ => Err(format!(
                "expected {}, found {}",
                selector_describe(allow_show),
                v.ty().long_name()
            )),
        },
        Value::Func(f) => match f.elem() {
            Some(e) => Ok(Selector::Elem(e, None)),
            None => Err("only element functions can be used as selectors".into()),
        },
        Value::Label(l) => Ok(Selector::Label(l.clone())),
        Value::Str(s) => Ok(Selector::Str(s.clone())),
        _ => Err(format!(
            "expected {}, found {}",
            selector_describe(allow_show),
            v.ty().long_name()
        )),
    }
}

fn selector_describe(allow_show: bool) -> &'static str {
    if allow_show {
        "function, label, string, regular expression, selector, or location"
    } else {
        "label, string, regular expression, selector, location, or function"
    }
}

/// Helper to get a typed value with a span.
pub fn cast_value<T: FromValue>(v: Value, span: Span) -> Result<T> {
    T::from_value(v).map_err(|e| {
        let mut parts = e.split("\u{0}hint:");
        let msg = parts.next().unwrap_or("").to_string();
        let mut d = crate::eval::vm::SourceDiagnostic::error(span, msg);
        for h in parts {
            d.hints.push(h.to_string());
        }
        vec![d]
    })
}
