use cast::FromValue;

thread_local! {
    static GLOBAL: RefCell<Option<Rc<Scope>>> = RefCell::new(None);
    static MATH: RefCell<Option<Rc<Scope>>> = RefCell::new(None);
}

pub fn global_scope() -> Rc<Scope> {
    GLOBAL.with(|g| {
        if g.borrow().is_none() {
            *g.borrow_mut() = Some(Rc::new(build_global()));
        }
        g.borrow().as_ref().unwrap().clone()
    })
}

pub fn math_scope() -> Rc<Scope> {
    MATH.with(|g| {
        if g.borrow().is_none() {
            *g.borrow_mut() = Some(Rc::new(build_math()));
        }
        g.borrow().as_ref().unwrap().clone()
    })
}

pub fn global_get(name: &str) -> Option<Binding> {
    global_scope().get(name).cloned()
}

pub fn math_get(name: &str) -> Option<Binding> {
    math_scope().get(name).cloned()
}

pub fn func(name: &'static str, f: NativeFn) -> Value {
    Value::Func(Func::native(name, f))
}

pub fn func_scoped(name: &'static str, f: NativeFn, scope: Scope) -> Value {
    Value::Func(Func::native_with_scope(name, f, scope))
}

pub fn module(name: &str, scope: Scope) -> Value {
    Value::Module(Rc::new(Module { name: name.to_string(), scope, content: None }))
}

pub fn symbol_value(variants: &[(&str, &str)]) -> Value {
    let vs: Vec<(String, String)> =
        variants.iter().map(|(m, c)| (m.to_string(), c.to_string())).collect();
    let text = best_variant(&vs, "").unwrap_or_default();
    Value::Symbol(Rc::new(Symbol { variants: vs, modifiers: vec![], text }))
}

pub fn best_variant(variants: &[(String, String)], modifiers: &str) -> Option<String> {
    let parts = |s: &str| s.split('.').filter(|p| !p.is_empty()).map(|s| s.to_string()).collect::<Vec<_>>();
    let wanted = parts(modifiers);
    let mut best: Option<(usize, std::cmp::Reverse<usize>, String)> = None;
    'outer: for (m, c) in variants {
        let have = parts(m);
        for w in &wanted {
            if !have.contains(w) {
                continue 'outer;
            }
        }
        let matching = have.iter().filter(|h| wanted.contains(h)).count();
        let total = have.len();
        let score = (matching, std::cmp::Reverse(total));
        if best.as_ref().is_none_or(|b| score > (b.0, b.1)) {
            best = Some((score.0, score.1, c.clone()));
        }
    }
    best.map(|b| b.2)
}

fn build_global() -> Scope {
    let mut s = Scope::new();
    foundations::define(&mut s);
    calc::define(&mut s);
    colors::define(&mut s);
    data::define(&mut s);
    introspection::define(&mut s);
    elements::define(&mut s);

    // Symbol modules.
    let mut sym = Scope::new();
    for (name, variants) in symbols::SYM {
        sym.define(*name, symbol_value(variants));
    }
    let mut gender = Scope::new();
    for (name, variants) in symbols::GENDER {
        gender.define(*name, symbol_value(variants));
    }
    sym.define("gender", module("gender", gender));
    s.define("sym", module("sym", sym));

    let mut emoji = Scope::new();
    for (name, variants) in symbols::EMOJI {
        emoji.define(*name, symbol_value(variants));
    }
    s.define("emoji", module("emoji", emoji));

    s.define("math", module("math", build_math()));

    // Directions and alignments.
    s.define("ltr", Value::dynamic(Dynamic::Direction(Direction::Ltr)));
    s.define("rtl", Value::dynamic(Dynamic::Direction(Direction::Rtl)));
    s.define("ttb", Value::dynamic(Dynamic::Direction(Direction::Ttb)));
    s.define("btt", Value::dynamic(Dynamic::Direction(Direction::Btt)));
    let h = |a: HAlign| Value::dynamic(Dynamic::Alignment(Alignment { h: Some(a), v: None }));
    let v = |a: VAlign| Value::dynamic(Dynamic::Alignment(Alignment { h: None, v: Some(a) }));
    s.define("start", h(HAlign::Start));
    s.define("left", h(HAlign::Left));
    s.define("center", h(HAlign::Center));
    s.define("right", h(HAlign::Right));
    s.define("end", h(HAlign::End));
    s.define("top", v(VAlign::Top));
    s.define("horizon", v(VAlign::Horizon));
    s.define("bottom", v(VAlign::Bottom));

    // Types.
    for t in [
        Type::Bool, Type::Int, Type::Float, Type::Str, Type::Label, Type::Bytes, Type::Content,
        Type::Array, Type::Dict, Type::Func, Type::Args, Type::Type, Type::Module, Type::Regex,
        Type::Selector, Type::Datetime, Type::Decimal, Type::Symbol, Type::Duration, Type::Version,
        Type::Length, Type::Angle, Type::Ratio, Type::Relative, Type::Fraction, Type::Direction,
        Type::Alignment, Type::Color, Type::Gradient, Type::Tiling, Type::Stroke, Type::Location,
        Type::Counter, Type::State,
    ] {
        s.define(t.short_name(), Value::Type(t));
    }

    // `std` module referencing the global scope itself.
    let std_scope = s.clone();
    s.define("std", module("std", std_scope));
    s
}

fn build_math() -> Scope {
    let mut s = Scope::new();
    for (name, variants) in symbols::SYM {
        s.define(*name, symbol_value(variants));
    }
    let mut gender = Scope::new();
    for (name, variants) in symbols::GENDER {
        gender.define(*name, symbol_value(variants));
    }
    s.define("gender", module("gender", gender));
    elements::define_math(&mut s);
    s
}

