    s.define("pdf", module("pdf", pdf));
}

fn pdf_embed(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let path: String = args.expect("path")?;
    let _ = span;
    let mut c = Content::new("pdf.attach").with_field("path", Value::str(path));
    if let Some(v) = args.named::<Value>("relationship")? {
        c.set_field("relationship", v);
    }
    if let Some(v) = args.named::<Value>("mime-type")? {
        c.set_field("mime-type", v);
    }
    if let Some(v) = args.named::<Value>("description")? {
        c.set_field("description", v);
    }
    Ok(Value::Content(c))
}

fn pdf_artifact(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let body: Content = args.expect("body")?;
    let mut c = Content::new("pdf.artifact");
    if let Some(v) = args.named::<Value>("kind")? {
        c.set_field("kind", v);
    }
    c.set_field("body", Value::Content(body));
    Ok(Value::Content(c))
}

fn repr_fn(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: Value = args.expect("value")?;
    Ok(Value::str(repr(&v)))
}

fn panic(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let values: Vec<Value> = args.all()?;
    let mut msg = String::from("panicked");
    if !values.is_empty() {
        msg.push_str(" with: ");
        let parts: Vec<String> = values.iter().map(repr).collect();
        msg.push_str(&parts.join(", "));
    }
    bail(span, msg)
}

fn assert(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let cond: bool = args.expect("condition")?;
    let message: Option<String> = args.named("message")?;
    if !cond {
        return match message {
            Some(m) => bail(span, format!("assertion failed: {m}")),
            None => bail(span, "assertion failed"),
        };
    }
    Ok(Value::None)
}

fn assert_eq(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let a: Value = args.expect("left")?;
    let b: Value = args.expect("right")?;
    let message: Option<String> = args.named("message")?;
    if !ops::equal(&a, &b) {
        return match message {
            Some(m) => bail(span, format!("equality assertion failed: {m}")),
            None => bail(
                span,
                format!("equality assertion failed: value {} was not equal to {}", repr(&a), repr(&b)),
            ),
        };
    }
    Ok(Value::None)
}

fn assert_ne(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let a: Value = args.expect("left")?;
    let b: Value = args.expect("right")?;
    let message: Option<String> = args.named("message")?;
    if ops::equal(&a, &b) {
        return match message {
            Some(m) => bail(span, format!("inequality assertion failed: {m}")),
            None => bail(
                span,
                format!("inequality assertion failed: value {} was equal to {}", repr(&a), repr(&b)),
            ),
        };
    }
    Ok(Value::None)
}

fn eval(vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let source: Spanned<String> = args.expect_spanned("source")?;
    let mode: Option<Spanned<String>> = args.named_spanned("mode")?;
    let scope: Option<Dict> = args.named("scope")?;
    let mode = match mode {
        None => "code".to_string(),
        Some(m) => {
            if !matches!(m.v.as_str(), "code" | "markup" | "math") {
                return bail(m.span, "expected \"markup\", \"math\", or \"code\"");
            }
            m.v
        }
    };
    crate::compile::eval_string(vm, &source.v, &mode, scope, span)
}

fn range(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let first: i64 = args.expect("end")?;
    let second: Option<i64> = args.eat()?;
    let step: Option<Spanned<i64>> = args.named_spanned("step")?;
    let (start, end) = match second {
        Some(e) => (first, e),
        None => (0, first),
    };
    let step = match step {
        Some(s) => {
            if s.v == 0 {
                return bail(s.span, "number must not be zero");
            }
            s.v
        }
        None => 1,
    };
    let _ = span;
    let mut out = Vec::new();
    let mut x = start;
    while (step > 0 && x < end) || (step < 0 && x > end) {
        out.push(Value::Int(x));
        x = match x.checked_add(step) {
            Some(v) => v,
            None => break,
        };
    }
    Ok(Value::array(out))
}

pub enum StrOrContent {
    Str(String),
    Content(Content),
}

impl FromValue for StrOrContent {
    fn describe() -> String {
        "string or content".into()
    }
    fn from_value(v: Value) -> std::result::Result<Self, String> {
        match v {
            Value::Str(s) => Ok(StrOrContent::Str(s.to_string())),
            Value::Symbol(s) => Ok(StrOrContent::Str(s.text.clone())),
            Value::Content(c) => Ok(StrOrContent::Content(c)),
            v => Err(mismatch::<Self>(&v)),
        }
    }
}

fn lower(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: StrOrContent = args.expect("text")?;
    Ok(match v {
        StrOrContent::Str(s) => Value::str(s.to_lowercase()),
        StrOrContent::Content(c) => Value::Content(crate::eval::vm::styled(
            c,
            Rc::new(Styles {
                rules: vec![StyleRule::Set {
                    elem: "text",
                    fields: vec![("case".into(), Value::str("lower"))],
                }],
            }),
        )),
    })
}

fn upper(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: StrOrContent = args.expect("text")?;
    Ok(match v {
        StrOrContent::Str(s) => Value::str(s.to_uppercase()),
        StrOrContent::Content(c) => Value::Content(crate::eval::vm::styled(
            c,
            Rc::new(Styles {
                rules: vec![StyleRule::Set {
                    elem: "text",
                    fields: vec![("case".into(), Value::str("upper"))],
                }],
            }),
        )),
    })
}

const LOREM: &str = "Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.";

fn lorem(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let n: NonNeg = args.expect("words")?;
    let n = n.0 as usize;
    if n == 0 {
        return Ok(Value::str(""));
    }
    let words: Vec<&str> = LOREM.split(' ').collect();
    let mut out = Vec::with_capacity(n);
    for i in 0..n {
        out.push(words[i % words.len()]);
    }
    let mut s = out.join(" ");
    // Ensure it ends with a period.
    let trimmed = s.trim_end_matches(|c: char| c == ',' || c == '.');
    s = format!("{trimmed}.");
    Ok(Value::str(s))
}

/// Numbering patterns.
pub fn numbering_fn(vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let pattern: Value = args.expect("numbering")?;
    let numbers: Vec<Spanned<i64>> = args.all_spanned()?;
    for n in &numbers {
        if n.v < 0 {
            return bail(n.span, "number must be at least zero");
        }
    }
    let nums: Vec<i64> = numbers.iter().map(|n| n.v).collect();
    match pattern {
        Value::Str(p) => Ok(Value::str(apply_numbering(&p, &nums).at(span)?)),
        Value::Func(f) => {
            let a = Args::new(span, nums.into_iter().map(Value::Int).collect());
            vm.call_func(&f, a, span)
        }
        other => bail(span, format!("expected string or function, found {}", other.ty().long_name())),
    }
}

pub fn apply_numbering(pattern: &str, numbers: &[i64]) -> std::result::Result<String, String> {
    // Parse pattern into pieces: (prefix, kind) and suffix.
    let mut pieces: Vec<(String, char)> = Vec::new();
    let mut prefix = String::new();
    let mut chars = pattern.chars().peekable();
    while let Some(c) = chars.next() {
        if numbering_kind(c).is_some() {
            pieces.push((std::mem::take(&mut prefix), c));
        } else {
            prefix.push(c);
        }
    }
    let suffix = prefix;
    if pieces.is_empty() {
        return Err("invalid numbering pattern".into());
    }
    let mut out = String::new();
    for (i, &n) in numbers.iter().enumerate() {
        let (pre, kind) = if i < pieces.len() { &pieces[i] } else { pieces.last().unwrap() };
        if i > 0 && i >= pieces.len() {
            // Reuse the last piece's prefix.
            out.push_str(&pieces.last().unwrap().0);
        } else {
            out.push_str(pre);
        }
        out.push_str(&format_number(*kind, n));
    }
    out.push_str(&suffix);
    Ok(out)
}

fn numbering_kind(c: char) -> Option<char> {
    match c {
        '1' | 'a' | 'A' | 'i' | 'I' | 'α' | 'Α' | '*' | '①' | '⓵' | '一' | '壹' | 'א' | 'あ' | 'い' | 'ア' | 'イ' | 'ㄱ' | '가' | '١' | '۱' | '१' | '১' | 'ক' | '〇' | '零' | '¹' | '₁' => Some(c),
        _ => None,
    }
}

fn format_number(kind: char, n: i64) -> String {
    match kind {
        '1' => n.to_string(),
        'a' => zeroless(n, |n| letters(n, b'a')),
        'A' => zeroless(n, |n| letters(n, b'A')),
        'i' => {
            if n == 0 {
                "n".into()
            } else {
                roman(n).to_lowercase()
            }
        }
        'I' => {
            if n == 0 {
                "N".into()
            } else {
                roman(n)
            }
        }
        'α' => zeroless(n, |n| greek(n, false)),
        'Α' => zeroless(n, |n| greek(n, true)),
        '*' => zeroless(n, symbols),
        '①' => {
            if (1..=50).contains(&n) {
                circled(n)
            } else {
                n.to_string()
            }
        }
        '一' => chinese(n, false),
        '壹' => chinese(n, true),
        'א' => zeroless(n, hebrew),
        'あ' => zeroless(n, |n| fixed(n, HIRAGANA)),
        'い' => zeroless(n, |n| fixed(n, HIRAGANA_IROHA)),
        'ア' => zeroless(n, |n| fixed(n, KATAKANA)),
        'イ' => zeroless(n, |n| fixed(n, KATAKANA_IROHA)),
        'ㄱ' => zeroless(n, |n| fixed(n, KOREAN_JAMO)),
        '가' => zeroless(n, |n| fixed(n, KOREAN_SYLLABLE)),
        '١' => digits(n, '٠'),
        '۱' => digits(n, '۰'),
        '१' => digits(n, '०'),
        '১' => digits(n, '০'),
        'ক' => zeroless(n, |n| fixed(n, BENGALI_LETTERS)),
        '〇' => digits_from(n, &['〇', '一', '二', '三', '四', '五', '六', '七', '八', '九']),
        '零' => digits_from(n, &['零', '壹', '贰', '叁', '肆', '伍', '陆', '柒', '捌', '玖']),
        '¹' => digits_from(n, &['⁰', '¹', '²', '³', '⁴', '⁵', '⁶', '⁷', '⁸', '⁹']),
        '₁' => digits_from(n, &['₀', '₁', '₂', '₃', '₄', '₅', '₆', '₇', '₈', '₉']),
        _ => n.to_string(),
    }
}

fn zeroless(n: i64, f: impl Fn(i64) -> String) -> String {
    if n == 0 { "-".into() } else { f(n) }
}

fn letters(mut n: i64, base: u8) -> String {
    let mut out = Vec::new();
    while n > 0 {
        n -= 1;
        out.push((base + (n % 26) as u8) as char);
        n /= 26;
    }
    out.iter().rev().collect()
}

fn roman(mut n: i64) -> String {
    const PAIRS: &[(i64, &str)] = &[
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"), (50, "L"),
        (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    ];
    if n > 3999 {
        // Vinculum notation for thousands.
        let thousands = n / 1000;
        n %= 1000;
        let mut out = String::new();
        for c in roman(thousands).chars() {
            out.push(c);
            out.push('\u{0305}');
        }
        if n > 0 {
            out.push_str(&roman(n));
        }
        return out;
    }
    let mut out = String::new();
    for (v, s) in PAIRS {
        while n >= *v {
            out.push_str(s);
            n -= v;
        }
    }
    out
}

fn greek(n: i64, upper: bool) -> String {
    let lower = ['α', 'β', 'γ', 'δ', 'ε', 'ζ', 'η', 'θ', 'ι', 'κ', 'λ', 'μ', 'ν', 'ξ', 'ο', 'π', 'ρ', 'σ', 'τ', 'υ', 'φ', 'χ', 'ψ', 'ω'];
    let up = ['Α', 'Β', 'Γ', 'Δ', 'Ε', 'Ζ', 'Η', 'Θ', 'Ι', 'Κ', 'Λ', 'Μ', 'Ν', 'Ξ', 'Ο', 'Π', 'Ρ', 'Σ', 'Τ', 'Υ', 'Φ', 'Χ', 'Ψ', 'Ω'];
    let table: &[char] = if upper { &up } else { &lower };
    fixed(n, table)
}

fn fixed(mut n: i64, table: &[char]) -> String {
    let len = table.len() as i64;
    let mut out = Vec::new();
    while n > 0 {
        n -= 1;
        out.push(table[(n % len) as usize]);
        n /= len;
    }
    out.iter().rev().collect()
}

fn symbols(n: i64) -> String {
    let table = ['*', '†', '‡', '§', '¶', '‖'];
    let idx = ((n - 1) % 6) as usize;
    let count = ((n - 1) / 6 + 1) as usize;
    std::iter::repeat(table[idx]).take(count).collect()
}

fn circled(n: i64) -> String {
    let c = match n {
        1..=20 => char::from_u32(0x2460 + (n - 1) as u32),
        21..=35 => char::from_u32(0x3251 + (n - 21) as u32),
        36..=50 => char::from_u32(0x32B1 + (n - 36) as u32),
        _ => None,
    };
    c.map(|c| c.to_string()).unwrap_or_else(|| n.to_string())
}

fn hebrew(n: i64) -> String {
    const ONES: [&str; 9] = ["א", "ב", "ג", "ד", "ה", "ו", "ז", "ח", "ט"];
    const TENS: [&str; 9] = ["י", "כ", "ל", "מ", "נ", "ס", "ע", "פ", "צ"];
    const HUNDREDS: [&str; 4] = ["ק", "ר", "ש", "ת"];
    let mut n = n;
    let mut out = String::new();
    while n >= 400 {
        out.push_str("ת");
        n -= 400;
    }
    if n >= 100 {
        out.push_str(HUNDREDS[(n / 100 - 1) as usize]);
        n %= 100;
    }
    if n == 15 {
        out.push_str("טו");
        n = 0;
    } else if n == 16 {
        out.push_str("טז");
        n = 0;
    }
    if n >= 10 {
        out.push_str(TENS[(n / 10 - 1) as usize]);
        n %= 10;
    }
    if n > 0 {
        out.push_str(ONES[(n - 1) as usize]);
    }
    out
}

fn digits(n: i64, zero: char) -> String {
    n.to_string()
        .chars()
        .map(|c| char::from_u32(zero as u32 + (c as u32 - '0' as u32)).unwrap_or(c))
        .collect()
}

fn digits_from(n: i64, table: &[char; 10]) -> String {
    n.to_string().chars().map(|c| table[(c as u32 - '0' as u32) as usize]).collect()
}

fn chinese(n: i64, formal: bool) -> String {
    let digits: [&str; 10] = if formal {
        ["零", "壹", "贰", "叁", "肆", "伍", "陆", "柒", "捌", "玖"]
    } else {
        ["零", "一", "二", "三", "四", "五", "六", "七", "八", "九"]
    };
    let units: [&str; 4] = if formal { ["", "拾", "佰", "仟"] } else { ["", "十", "百", "千"] };
    if n == 0 {
        return digits[0].to_string();
    }
    let mut out = String::new();
    let wan = n / 10000;
    let rest = n % 10000;
    if wan > 0 {
        out.push_str(&chinese_small(wan, &digits, &units, formal));
        out.push_str(if formal { "萬" } else { "万" });
        if rest > 0 && rest < 1000 {
            out.push_str(digits[0]);
        }
    }
    if rest > 0 || wan == 0 {
        let s = chinese_small(rest, &digits, &units, formal);
        out.push_str(&s);
    }
    out
}

fn chinese_small(n: i64, digits: &[&str; 10], units: &[&str; 4], _formal: bool) -> String {
    let mut out = String::new();
    let s = n.to_string();
    let len = s.len();
    let mut zero_pending = false;
    for (i, c) in s.chars().enumerate() {
        let d = (c as u32 - '0' as u32) as usize;
        let pos = len - 1 - i;
        if d == 0 {
            zero_pending = true;
            continue;
        }
        if zero_pending && !out.is_empty() {
            out.push_str(digits[0]);
        }
        zero_pending = false;
        if !(d == 1 && pos == 1 && len == 2) {
            out.push_str(digits[d]);
        }
        out.push_str(units[pos]);
    }
    out
}

