pub fn stroke_ctor(vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    stroke_fn(vm, args, span)
}

fn stroke_fn(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: Option<Spanned<Value>> = args.eat_spanned()?;
    let mut stroke = match v {
        Some(v) => cast_stroke(&v.v).at(v.span)?,
        None => Stroke::default(),
    };
    if let Some(p) = args.named::<Value>("paint")? {
        stroke.paint = Some(p);
    }
    if let Some(t) = args.named::<Value>("thickness")? {
        stroke.thickness = Some(t);
    }
    if let Some(c) = args.named::<Value>("cap")? {
        stroke.cap = Some(c);
    }
    if let Some(j) = args.named::<Value>("join")? {
        stroke.join = Some(j);
    }
    if let Some(d) = args.named::<Value>("dash")? {
        stroke.dash = Some(d);
    }
    if let Some(m) = args.named::<Value>("miter-limit")? {
        stroke.miter_limit = Some(m);
    }
    Ok(Value::dynamic(Dynamic::Stroke(stroke)))
}

pub fn cast_stroke(v: &Value) -> std::result::Result<Stroke, String> {
    match v {
        Value::Length(_) => Ok(Stroke { thickness: Some(v.clone()), ..Default::default() }),
        Value::Color(_) | Value::Gradient(_) => Ok(Stroke { paint: Some(v.clone()), ..Default::default() }),
        Value::Dict(d) => {
            let mut s = Stroke::default();
            for (k, val) in d.iter() {
                match k.as_str() {
                    "paint" => s.paint = Some(val.clone()),
                    "thickness" => s.thickness = Some(val.clone()),
                    "cap" => s.cap = Some(val.clone()),
                    "join" => s.join = Some(val.clone()),
                    "dash" => s.dash = Some(dash_value(val)),
                    "miter-limit" => s.miter_limit = Some(val.clone()),
                    other => return Err(format!("unexpected key {}", crate::eval::repr::repr_str(other))),
                }
            }
            Ok(s)
        }
        Value::Dyn(d) => match &**d {
            Dynamic::Stroke(s) => Ok(s.clone()),
            Dynamic::Tiling => Ok(Stroke { paint: Some(v.clone()), ..Default::default() }),
            _ => Err(format!(
                "expected length, color, gradient, tiling, dictionary, or stroke, found {}",
                v.ty().long_name()
            )),
        },
        _ => Err(format!(
            "expected length, color, gradient, tiling, dictionary, or stroke, found {}",
            v.ty().long_name()
        )),
    }
}

fn dash_value(v: &Value) -> Value {
    match v {
        Value::Str(s) => {
            let pattern: Option<Vec<Value>> = match &**s {
                "solid" => Some(vec![]),
                "dotted" => Some(vec![Value::Length(Length::pt(0.0)), Value::Length(Length::pt(2.0))]),
                "densely-dotted" => Some(vec![Value::Length(Length::pt(0.0)), Value::Length(Length::pt(1.0))]),
                "loosely-dotted" => Some(vec![Value::Length(Length::pt(0.0)), Value::Length(Length::pt(4.0))]),
                "dashed" => Some(vec![Value::Length(Length::pt(3.0)), Value::Length(Length::pt(3.0))]),
                "densely-dashed" => Some(vec![Value::Length(Length::pt(3.0)), Value::Length(Length::pt(1.0))]),
                "loosely-dashed" => Some(vec![Value::Length(Length::pt(3.0)), Value::Length(Length::pt(6.0))]),
                "dash-dotted" => Some(vec![Value::Length(Length::pt(3.0)), Value::Length(Length::pt(2.0)), Value::Length(Length::pt(0.0)), Value::Length(Length::pt(2.0))]),
                "densely-dash-dotted" => Some(vec![Value::Length(Length::pt(3.0)), Value::Length(Length::pt(1.0)), Value::Length(Length::pt(0.0)), Value::Length(Length::pt(1.0))]),
                "loosely-dash-dotted" => Some(vec![Value::Length(Length::pt(3.0)), Value::Length(Length::pt(4.0)), Value::Length(Length::pt(0.0)), Value::Length(Length::pt(4.0))]),
                _ => None,
            };
            match pattern {
                Some(p) if p.is_empty() => Value::None,
                Some(p) => {
                    let mut d: Dict = IndexMap::new();
                    d.insert("array".into(), Value::array(p));
                    d.insert("phase".into(), Value::Length(Length::pt(0.0)));
                    Value::dict(d)
                }
                None => v.clone(),
            }
        }
        _ => v.clone(),
    }
}

// --------------------------------------------------------------- Methods

pub fn func_with(vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let f: Func = args.expect("self")?;
    let _ = vm;
    let _ = span;
    let rest = std::mem::take(args);
    Ok(Value::Func(Func::With(Rc::new((f, rest)))))
}

pub fn func_where(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let f: Func = args.expect("self")?;
    let elem = match f.elem() {
        Some(e) => e,
        None => return bail(span, "only element functions can be used as selectors"),
    };
    let mut fields: Dict = IndexMap::new();
    let taken = std::mem::take(args);
    for arg in taken.items {
        match arg.name {
            Some(n) => {
                fields.insert(n, arg.value);
            }
            None => return bail(arg.span, "unexpected argument"),
        }
    }
    Ok(Value::dynamic(Dynamic::Selector(Selector::Elem(elem, Some(Rc::new(fields))))))
}

pub fn func_method(vm: &mut Vm, f: &Func, method: &str, args: &mut Args, span: Span) -> Option<Result<Value>> {
    Some(match method {
        "with" => {
            let rest = std::mem::take(args);
            Ok(Value::Func(Func::With(Rc::new((f.clone(), rest)))))
        }
        "where" => {
            let mut a = std::mem::take(args);
            a.items.insert(0, Arg { span, name: None, value: Value::Func(f.clone()), value_span: span });
            func_where(vm, &mut a, span)
        }
        _ => return None,
    })
}

pub fn content_method(_vm: &mut Vm, c: &Content, method: &str, args: &mut Args, span: Span) -> Option<Result<Value>> {
    Some((|| match method {
        "func" => Ok(Value::Func(Func::Elem(c.elem()))),
        "fields" => {
            let mut d: Dict = IndexMap::new();
            for (k, v) in c.fields() {
                d.insert(k.clone(), v.clone());
            }
            if let Some(l) = c.label() {
                d.insert("label".into(), Value::Label(l.clone()));
            }
            Ok(Value::dict(d))
        }
        "has" => {
            let name: String = args.expect("field")?;
            Ok(Value::Bool(c.has_field(&name) || (name == "label" && c.label().is_some())))
        }
        "at" => {
            let name: Spanned<String> = args.expect_spanned("field")?;
            let default: Option<Value> = args.named("default")?;
            match super::content_field(c, &name.v) {
                Ok(v) => Ok(v),
                Err(_) => match default {
                    Some(d) => Ok(d),
                    None => bail(
                        span,
                        format!("{} does not have field \"{}\" and no default was specified", c.elem_func_name(), name.v),
                    ),
                },
            }
        }
        "location" => Ok(match c.location() {
            Some(l) => Value::dynamic(Dynamic::Location(l)),
            None => Value::None,
        }),
        _ => Err(vec![]),
    })())
    .filter(|r| !matches!(r, Err(e) if e.is_empty()))
}

pub fn length_method(_vm: &mut Vm, l: Length, method: &str, args: &mut Args, span: Span) -> Option<Result<Value>> {
    let check = |unit: &str| -> Result<()> {
        if l.em != 0.0 {
            return Err(vec![SourceDiagnostic::error(
                span,
                format!("cannot convert a length with non-zero em units (`{}`) to {unit}", l.repr()),
            )
            .with_hint("use `length.to-absolute()` to resolve its em component (requires context)")
            .with_hint("or use `length.abs.{unit}()` instead to ignore its em component")]);
        }
        Ok(())
    };
    let _ = args;
    Some(match method {
        "pt" => check("pt").map(|_| Value::Float(l.abs)),
        "mm" => check("mm").map(|_| Value::Float(l.abs / 72.0 * 25.4)),
        "cm" => check("cm").map(|_| Value::Float(l.abs / 72.0 * 2.54)),
        "inches" => check("inches").map(|_| Value::Float(l.abs / 72.0)),
        "to-absolute" => Ok(Value::Length(Length::pt(l.abs + l.em * 11.0))),
        _ => return None,
    })
}

pub fn angle_method(_vm: &mut Vm, a: f64, method: &str, _args: &mut Args, _span: Span) -> Option<Result<Value>> {
    Some(match method {
        "rad" => Ok(Value::Float(a)),
        "deg" => Ok(Value::Float(a.to_degrees())),
        _ => return None,
    })
}

pub fn datetime_method(_vm: &mut Vm, d: Datetime, method: &str, args: &mut Args, span: Span) -> Option<Result<Value>> {
    let opt = |v: Option<i64>| v.map(Value::Int).unwrap_or(Value::None);
    Some(match method {
        "year" => Ok(opt(d.date.map(|x| x.0 as i64))),
        "month" => Ok(opt(d.date.map(|x| x.1 as i64))),
        "day" => Ok(opt(d.date.map(|x| x.2 as i64))),
        "hour" => Ok(opt(d.time.map(|x| x.0 as i64))),
        "minute" => Ok(opt(d.time.map(|x| x.1 as i64))),
        "second" => Ok(opt(d.time.map(|x| x.2 as i64))),
        "weekday" => Ok(opt(d.weekday().map(|x| x as i64))),
        "ordinal" => Ok(opt(d.ordinal().map(|x| x as i64))),
        "display" => {
            let pattern: Option<Spanned<String>> = args.eat_spanned().unwrap_or(None);
            let r = d.display(pattern.as_ref().map(|p| p.v.as_str()));
            match r {
                Ok(s) => Ok(Value::str(s)),
                Err(e) => bail(pattern.map(|p| p.span).unwrap_or(span), e),
            }
        }
        _ => return None,
    })
}

