pub fn version_method(_vm: &mut Vm, v: &Rc<Vec<u32>>, method: &str, args: &mut Args, span: Span) -> Option<Result<Value>> {
    Some(match method {
        "at" => {
            let idx: Spanned<Value> = match args.expect_spanned("index") {
                Ok(i) => i,
                Err(e) => return Some(Err(e)),
            };
            match idx.v {
                Value::Int(i) => {
                    if i < 0 {
                        return Some(bail(span, format!("version component index out of bounds (index: {i})")));
                    }
                    Ok(Value::Int(v.get(i as usize).copied().unwrap_or(0) as i64))
                }
                Value::Str(s) => {
                    let i = match &*s {
                        "major" => 0,
                        "minor" => 1,
                        "patch" => 2,
                        _ => return Some(bail(idx.span, format!("unknown version component"))),
                    };
                    Ok(Value::Int(v.get(i).copied().unwrap_or(0) as i64))
                }
                o => bail(idx.span, format!("expected integer or string, found {}", o.ty().long_name())),
            }
        }
        _ => return None,
    })
}

pub fn bytes_method(_vm: &mut Vm, b: &Rc<Vec<u8>>, method: &str, args: &mut Args, span: Span) -> Option<Result<Value>> {
    Some((|| match method {
        "len" => Ok(Value::Int(b.len() as i64)),
        "at" => {
            let idx: i64 = args.expect("index")?;
            let default: Option<Value> = args.named("default")?;
            let len = b.len() as i64;
            let i = if idx < 0 { idx + len } else { idx };
            if i >= 0 && i < len {
                Ok(Value::Int(b[i as usize] as i64))
            } else {
                match default {
                    Some(d) => Ok(d),
                    None => bail(
                        span,
                        format!("byte index out of bounds (index: {idx}, len: {len}) and no default value was specified"),
                    ),
                }
            }
        }
        "slice" => {
            let start: i64 = args.expect("start")?;
            let end: Option<i64> = args.eat()?;
            let count: Option<i64> = args.named("count")?;
            let len = b.len() as i64;
            let s = if start < 0 { start + len } else { start };
            let e = match (end, count) {
                (Some(e), _) => e,
                (None, Some(c)) => s + c,
                (None, None) => len,
            };
            let e = if e < 0 { e + len } else { e };
            if s < 0 || s > len {
                return bail(span, format!("byte index out of bounds (index: {start}, len: {len})"));
            }
            if e < s || e > len {
                return bail(span, format!("byte index out of bounds (index: {e}, len: {len})"));
            }
            Ok(Value::Bytes(Rc::new(b[s as usize..e as usize].to_vec())))
        }
        _ => Err(vec![]),
    })())
    .filter(|r| !matches!(r, Err(e) if e.is_empty()))
}

pub fn args_method(_vm: &mut Vm, a: &Rc<Args>, method: &str, args: &mut Args, span: Span) -> Option<Result<Value>> {
    Some((|| match method {
        "pos" => Ok(Value::array(a.items.iter().filter(|x| x.name.is_none()).map(|x| x.value.clone()).collect())),
        "named" => {
            let mut d: Dict = IndexMap::new();
            for x in &a.items {
                if let Some(n) = &x.name {
                    d.insert(n.clone(), x.value.clone());
                }
            }
            Ok(Value::dict(d))
        }
        "at" => {
            let key: Spanned<Value> = args.expect_spanned("key")?;
            let default: Option<Value> = args.named("default")?;
            let found = match &key.v {
                Value::Int(i) => {
                    let pos: Vec<&Arg> = a.items.iter().filter(|x| x.name.is_none()).collect();
                    let len = pos.len() as i64;
                    let idx = if *i < 0 { i + len } else { *i };
                    if idx >= 0 && idx < len { Some(pos[idx as usize].value.clone()) } else { None }
                }
                Value::Str(s) => a.items.iter().find(|x| x.name.as_deref() == Some(&**s)).map(|x| x.value.clone()),
                o => return bail(key.span, format!("expected integer or string, found {}", o.ty().long_name())),
            };
            match found {
                Some(v) => Ok(v),
                None => match default {
                    Some(d) => Ok(d),
                    None => bail(
                        span,
                        format!("arguments do not contain key {} and no default value was specified", repr(&key.v)),
                    ),
                },
            }
        }
        _ => Err(vec![]),
    })())
    .filter(|r| !matches!(r, Err(e) if e.is_empty()))
}

pub fn int_method(_vm: &mut Vm, i: i64, method: &str, args: &mut Args, span: Span) -> Option<Result<Value>> {
    let mut a = std::mem::take(args);
    a.items.insert(0, Arg { span, name: None, value: Value::Int(i), value_span: span });
    let f = match method {
        "signum" => int_signum,
        "bit-not" => int_bit_not,
        "bit-and" => int_bit_and,
        "bit-or" => int_bit_or,
        "bit-xor" => int_bit_xor,
        "bit-lshift" => int_bit_lshift,
        "bit-rshift" => int_bit_rshift,
        "to-bytes" => int_to_bytes,
        _ => {
            *args = a;
            args.items.remove(0);
            return None;
        }
    };
    let r = f(_vm, &mut a, span);
    *args = a;
    Some(r)
}

pub fn float_method(_vm: &mut Vm, f: f64, method: &str, args: &mut Args, span: Span) -> Option<Result<Value>> {
    let mut a = std::mem::take(args);
    a.items.insert(0, Arg { span, name: None, value: Value::Float(f), value_span: span });
    let func = match method {
        "is-nan" => float_is_nan,
        "is-infinite" => float_is_infinite,
        "signum" => float_signum,
        "to-bytes" => float_to_bytes,
        _ => {
            *args = a;
            args.items.remove(0);
            return None;
        }
    };
    let r = func(_vm, &mut a, span);
    *args = a;
    Some(r)
}

pub fn float_is_nan(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let f: f64 = args.expect("self")?;
    Ok(Value::Bool(f.is_nan()))
}
pub fn float_is_infinite(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let f: f64 = args.expect("self")?;
    Ok(Value::Bool(f.is_infinite()))
}
pub fn float_signum(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let f: f64 = args.expect("self")?;
    Ok(Value::Float(if f == 0.0 { f } else { f.signum() }))
}
pub fn float_from_bytes(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let b: Rc<Vec<u8>> = args.expect("bytes")?;
    let endian: Option<String> = args.named("endian")?;
    let little = endian.as_deref() != Some("big");
    match b.len() {
        8 => {
            let arr: [u8; 8] = b[..].try_into().unwrap();
            Ok(Value::Float(if little { f64::from_le_bytes(arr) } else { f64::from_be_bytes(arr) }))
        }
        4 => {
            let arr: [u8; 4] = b[..].try_into().unwrap();
            Ok(Value::Float(if little { f32::from_le_bytes(arr) } else { f32::from_be_bytes(arr) } as f64))
        }
        _ => bail(span, "bytes must have a length of 4 or 8"),
    }
}
pub fn float_to_bytes(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let f: f64 = args.expect("self")?;
    let endian: Option<String> = args.named("endian")?;
    let size: Option<i64> = args.named("size")?;
    let little = endian.as_deref() != Some("big");
    let bytes = match size.unwrap_or(8) {
        8 => if little { f.to_le_bytes().to_vec() } else { f.to_be_bytes().to_vec() },
        4 => if little { (f as f32).to_le_bytes().to_vec() } else { (f as f32).to_be_bytes().to_vec() },
        _ => return bail(span, "size must be either 4 or 8"),
    };
    Ok(Value::Bytes(Rc::new(bytes)))
}
pub fn int_signum(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let i: i64 = args.expect("self")?;
    Ok(Value::Int(i.signum()))
}
pub fn int_bit_not(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let i: i64 = args.expect("self")?;
    Ok(Value::Int(!i))
}
pub fn int_bit_and(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let a: i64 = args.expect("self")?;
    let b: i64 = args.expect("rhs")?;
    Ok(Value::Int(a & b))
}
pub fn int_bit_or(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let a: i64 = args.expect("self")?;
    let b: i64 = args.expect("rhs")?;
    Ok(Value::Int(a | b))
}
pub fn int_bit_xor(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let a: i64 = args.expect("self")?;
    let b: i64 = args.expect("rhs")?;
    Ok(Value::Int(a ^ b))
}
pub fn int_bit_lshift(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let a: i64 = args.expect("self")?;
    let b: i64 = args.expect("shift")?;
    if !(0..64).contains(&b) {
        return bail(span, "the result is too large");
    }
    match a.checked_shl(b as u32) {
        Some(v) if (v >> b) == a => Ok(Value::Int(v)),
        _ => bail(span, "the result is too large"),
    }
}
pub fn int_bit_rshift(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let a: i64 = args.expect("self")?;
    let b: i64 = args.expect("shift")?;
    let logical: bool = args.named("logical")?.unwrap_or(false);
    if b < 0 {
        return bail(span, "number must be at least zero");
    }
    if b >= 64 {
        return Ok(Value::Int(if logical || a >= 0 { 0 } else { -1 }));
    }
    Ok(Value::Int(if logical { ((a as u64) >> b) as i64 } else { a >> b }))
}
pub fn int_from_bytes(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let b: Rc<Vec<u8>> = args.expect("bytes")?;
    let endian: Option<String> = args.named("endian")?;
    let signed: bool = args.named("signed")?.unwrap_or(true);
    let little = endian.as_deref() != Some("big");
    if b.len() > 8 {
        return bail(span, "too many bytes to convert to a 64 bit number");
    }
    let mut arr = [0u8; 8];
    let mut bytes = (*b).clone();
    if !little {
        bytes.reverse();
    }
    let negative = signed && bytes.last().is_some_and(|&x| x & 0x80 != 0);
    if negative {
        arr = [0xff; 8];
    }
    arr[..bytes.len()].copy_from_slice(&bytes);
    Ok(Value::Int(i64::from_le_bytes(arr)))
}
pub fn int_to_bytes(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let i: i64 = args.expect("self")?;
    let endian: Option<String> = args.named("endian")?;
    let size: Option<i64> = args.named("size")?;
    let little = endian.as_deref() != Some("big");
    let size = size.unwrap_or(8);
    if !(1..=8).contains(&size) {
        return bail(span, "size must be between 1 and 8");
    }
    let mut bytes = i.to_le_bytes()[..size as usize].to_vec();
    if !little {
        bytes.reverse();
    }
    Ok(Value::Bytes(Rc::new(bytes)))
}

pub fn alignment_method(_vm: &mut Vm, a: Alignment, method: &str, _args: &mut Args, span: Span) -> Option<Result<Value>> {
    Some(match method {
        "axis" => match (a.h, a.v) {
            (Some(_), None) => Ok(Value::str("horizontal")),
            (None, Some(_)) => Ok(Value::str("vertical")),
            _ => Ok(Value::None),
        },
        "inv" => {
            let h = a.h.map(|h| match h {
                HAlign::Start => HAlign::End,
                HAlign::Left => HAlign::Right,
                HAlign::Center => HAlign::Center,
                HAlign::Right => HAlign::Left,
                HAlign::End => HAlign::Start,
            });
            let v = a.v.map(|v| match v {
                VAlign::Top => VAlign::Bottom,
                VAlign::Horizon => VAlign::Horizon,
                VAlign::Bottom => VAlign::Top,
            });
            Ok(Value::dynamic(Dynamic::Alignment(Alignment { h, v })))
        }
        _ => {
            let _ = span;
            return None;
        }
    })
}

pub fn direction_method(_vm: &mut Vm, d: Direction, method: &str, _args: &mut Args, _span: Span) -> Option<Result<Value>> {
    let h = |a: HAlign| Value::dynamic(Dynamic::Alignment(Alignment { h: Some(a), v: None }));
    let v = |a: VAlign| Value::dynamic(Dynamic::Alignment(Alignment { h: None, v: Some(a) }));
    Some(match method {
        "axis" => Ok(Value::str(match d {
            Direction::Ltr | Direction::Rtl => "horizontal",
            _ => "vertical",
        })),
        "sign" => Ok(Value::Int(match d {
            Direction::Ltr | Direction::Ttb => 1,
            _ => -1,
        })),
        "start" => Ok(match d {
            Direction::Ltr => h(HAlign::Left),
            Direction::Rtl => h(HAlign::Right),
            Direction::Ttb => v(VAlign::Top),
            Direction::Btt => v(VAlign::Bottom),
        }),
        "end" => Ok(match d {
            Direction::Ltr => h(HAlign::Right),
            Direction::Rtl => h(HAlign::Left),
            Direction::Ttb => v(VAlign::Bottom),
            Direction::Btt => v(VAlign::Top),
        }),
        "inv" => Ok(Value::dynamic(Dynamic::Direction(match d {
            Direction::Ltr => Direction::Rtl,
            Direction::Rtl => Direction::Ltr,
            Direction::Ttb => Direction::Btt,
            Direction::Btt => Direction::Ttb,
        }))),
        _ => return None,
    })
}

