// ------------------------------------------------------------ Type ctors

pub fn int_ctor(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: Spanned<Value> = args.expect_spanned("value")?;
    let sp = v.span;
    let r = match v.v {
        Value::Int(i) => Ok(i),
        Value::Bool(b) => Ok(b as i64),
        Value::Float(f) => {
            if f.is_nan() {
                Ok(0)
            } else if f.is_infinite() || f.abs() >= 9223372036854775808.0 {
                Err("number too large".to_string())
            } else {
                Ok(f.trunc() as i64)
            }
        }
        Value::Str(s) => parse_int(&s),
        Value::Dyn(d) => match &*d {
            Dynamic::Decimal(dec) => {
                let f = decimal::to_f64(dec);
                Ok(f.trunc() as i64)
            }
            _ => Err(format!(
                "expected integer, boolean, float, decimal, or string, found {}",
                Value::Dyn(d.clone()).ty().long_name()
            )),
        },
        other => Err(format!(
            "expected integer, boolean, float, decimal, or string, found {}",
            other.ty().long_name()
        )),
    };
    r.map(Value::Int).at(sp)
}

fn parse_int(s: &str) -> std::result::Result<i64, String> {
    let t = s.strip_prefix('+').unwrap_or(s);
    let t = t.replace('\u{2212}', "-");
    match t.parse::<i64>() {
        Ok(i) => Ok(i),
        Err(e) => {
            if t.is_empty() || !t.trim_start_matches('-').chars().all(|c| c.is_ascii_digit()) || t.trim_start_matches('-').is_empty() {
                Err("string contains invalid digits".into())
            } else {
                let _ = e;
                Err("number too large".into())
            }
        }
    }
}

pub fn float_ctor(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: Spanned<Value> = args.expect_spanned("value")?;
    let sp = v.span;
    let r = match v.v {
        Value::Int(i) => Ok(i as f64),
        Value::Float(f) => Ok(f),
        Value::Bool(b) => Ok(b as i64 as f64),
        Value::Ratio(r) => Ok(r),
        Value::Str(s) => {
            let t = s.replace('\u{2212}', "-");
            match t.trim().parse::<f64>() {
                Ok(f) if !t.trim().is_empty() && !t.contains("inf") && !t.to_lowercase().contains("nan") || t.trim() == "inf" || t.trim() == "-inf" || t.trim().eq_ignore_ascii_case("nan") => Ok(f),
                _ => {
                    // Accept forms like "inf", "NaN", "-inf".
                    match t.trim() {
                        "inf" | "+inf" | "infinity" => Ok(f64::INFINITY),
                        "-inf" | "-infinity" => Ok(f64::NEG_INFINITY),
                        x if x.eq_ignore_ascii_case("nan") => Ok(f64::NAN),
                        _ => Err(format!("invalid float: {s}")),
                    }
                }
            }
        }
        Value::Dyn(d) => match &*d {
            Dynamic::Decimal(dec) => Ok(decimal::to_f64(dec)),
            _ => Err(format!(
                "expected float, boolean, integer, decimal, ratio, or string, found {}",
                Value::Dyn(d.clone()).ty().long_name()
            )),
        },
        other => Err(format!(
            "expected float, boolean, integer, decimal, ratio, or string, found {}",
            other.ty().long_name()
        )),
    };
    r.map(Value::Float).at(sp)
}

pub fn str_ctor(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: Spanned<Value> = args.expect_spanned("value")?;
    let base: Option<Spanned<i64>> = args.named_spanned("base")?;
    let sp = v.span;
    if let Some(b) = &base {
        if !(2..=36).contains(&b.v) {
            let mut d = SourceDiagnostic::error(b.span, "base must be between 2 and 36");
            if b.v == 1 {
                d = d.with_hint("generate a unary representation with `\"1\" * 1`");
            }
            return Err(vec![d]);
        }
        if !matches!(v.v, Value::Int(_)) {
            return bail(b.span, "base is only supported for integers");
        }
    }
    let r: std::result::Result<String, String> = match v.v {
        Value::Int(i) => Ok(match base {
            Some(b) if b.v != 10 => format_int_with_base(i, b.v),
            _ => display_int(i),
        }),
        Value::Float(f) => Ok(display_float(f)),
        Value::Str(s) => Ok(s.to_string()),
        Value::Bytes(b) => match String::from_utf8((*b).clone()) {
            Ok(s) => Ok(s),
            Err(_) => Err("bytes are not valid utf-8".into()),
        },
        Value::Label(l) => Ok(l.to_string()),
        Value::Type(t) => Ok(t.long_name().to_string()),
        Value::Version(v) => Ok(v.iter().map(|n| n.to_string()).collect::<Vec<_>>().join(".")),
        Value::Dyn(d) => match &*d {
            Dynamic::Decimal(dec) => Ok(decimal::to_string(dec).replacen('-', "\u{2212}", 1)),
            _ => Err(format!(
                "expected integer, float, decimal, version, bytes, label, type, or string, found {}",
                Value::Dyn(d.clone()).ty().long_name()
            )),
        },
        other => Err(format!(
            "expected integer, float, decimal, version, bytes, label, type, or string, found {}",
            other.ty().long_name()
        )),
    };
    r.map(Value::str).at(sp)
}

pub fn bytes_ctor(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: Spanned<Value> = args.expect_spanned("value")?;
    let sp = v.span;
    match v.v {
        Value::Str(s) => Ok(Value::Bytes(Rc::new(s.as_bytes().to_vec()))),
        Value::Bytes(b) => Ok(Value::Bytes(b)),
        Value::Array(a) => {
            let mut out = Vec::with_capacity(a.len());
            for item in a.iter() {
                match item {
                    Value::Int(i) if (0..=255).contains(i) => out.push(*i as u8),
                    Value::Int(_) => return bail(sp, "number must be between 0 and 255"),
                    other => {
                        return bail(sp, format!("expected integer, found {}", other.ty().long_name()))
                    }
                }
            }
            Ok(Value::Bytes(Rc::new(out)))
        }
        other => bail(sp, format!("expected string, array, or bytes, found {}", other.ty().long_name())),
    }
}

pub fn label_ctor(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let s: String = args.expect("name")?;
    Ok(Value::Label(Rc::from(s.as_str())))
}

pub fn array_ctor(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: Spanned<Value> = args.expect_spanned("value")?;
    match v.v {
        Value::Array(a) => Ok(Value::Array(a)),
        Value::Bytes(b) => Ok(Value::array(b.iter().map(|&x| Value::Int(x as i64)).collect())),
        Value::Version(ver) => Ok(Value::array(ver.iter().map(|&x| Value::Int(x as i64)).collect())),
        other => bail(v.span, format!("expected array, bytes, or version, found {}", other.ty().long_name())),
    }
}

pub fn dict_ctor(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: Spanned<Value> = args.expect_spanned("value")?;
    match v.v {
        Value::Dict(d) => Ok(Value::Dict(d)),
        Value::Module(m) => {
            let mut d: Dict = IndexMap::new();
            for (k, b) in m.scope.map.iter() {
                d.insert(k.clone(), b.value.clone());
            }
            Ok(Value::dict(d))
        }
        other => bail(v.span, format!("expected module, found {}", other.ty().long_name())),
    }
}

pub fn make_regex(source: &str) -> std::result::Result<RegexValue, String> {
    match regex::Regex::new(source) {
        Ok(r) => Ok(RegexValue { source: source.to_string(), regex: r }),
        Err(e) => Err(format!("{e}")),
    }
}

pub fn regex_ctor(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let s: Spanned<String> = args.expect_spanned("regex")?;
    let r = make_regex(&s.v).at(s.span)?;
    Ok(Value::dynamic(Dynamic::Regex(r)))
}

pub fn symbol_ctor(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let variants: Vec<Spanned<Value>> = args.all_spanned()?;
    if variants.is_empty() {
        return bail(span, "expected at least one variant");
    }
    let mut vs: Vec<(String, String)> = Vec::new();
    for v in variants {
        let (m, c) = match v.v {
            Value::Str(s) => (String::new(), s.to_string()),
            Value::Array(a) => {
                if a.len() != 2 {
                    return bail(v.span, "variant array must have exactly two elements");
                }
                let m = match &a[0] {
                    Value::Str(s) => s.to_string(),
                    o => return bail(v.span, format!("expected string, found {}", o.ty().long_name())),
                };
                let c = match &a[1] {
                    Value::Str(s) => s.to_string(),
                    o => return bail(v.span, format!("expected string, found {}", o.ty().long_name())),
                };
                (m, c)
            }
            other => {
                return bail(v.span, format!("expected string or array, found {}", other.ty().long_name()))
            }
        };
        use unicode_segmentation::UnicodeSegmentation;
        if c.graphemes(true).count() != 1 {
            return Err(vec![SourceDiagnostic::error(
                v.span,
                format!("invalid variant value: {}", crate::eval::repr::repr_str(&c)),
            )
            .with_hint("variant value must be exactly one grapheme cluster")]);
        }
        vs.push((m, c));
    }
    let text = super::best_variant(&vs, "").unwrap_or_default();
    Ok(Value::Symbol(Rc::new(Symbol { variants: vs, modifiers: vec![], text })))
}

pub fn version_ctor(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let parts: Vec<Spanned<Value>> = args.all_spanned()?;
    let mut out = Vec::new();
    for p in parts {
        match p.v {
            Value::Int(i) => {
                if i < 0 {
                    return bail(p.span, "number must be at least zero");
                }
                out.push(i as u32);
            }
            Value::Array(a) => {
                for item in a.iter() {
                    match item {
                        Value::Int(i) if *i >= 0 => out.push(*i as u32),
                        Value::Int(_) => return bail(p.span, "number must be at least zero"),
                        o => return bail(p.span, format!("expected integer, found {}", o.ty().long_name())),
                    }
                }
            }
            other => {
                return bail(p.span, format!("expected integer or array, found {}", other.ty().long_name()))
            }
        }
    }
    Ok(Value::Version(Rc::new(out)))
}

pub fn datetime_ctor(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let year: Option<i64> = args.named("year")?;
    let month: Option<i64> = args.named("month")?;
    let day: Option<i64> = args.named("day")?;
    let hour: Option<i64> = args.named("hour")?;
    let minute: Option<i64> = args.named("minute")?;
    let second: Option<i64> = args.named("second")?;

    let date = match (year, month, day) {
        (Some(y), Some(m), Some(d)) => {
            if !(1..=12).contains(&m) {
                return bail(span, "month is invalid");
            }
            if !Datetime::valid_date(y as i32, m as u8, d as u8) {
                return bail(span, "date is invalid");
            }
            Some((y as i32, m as u8, d as u8))
        }
        (None, None, None) => None,
        (y, m, d) => {
            let mut missing = Vec::new();
            if y.is_none() {
                missing.push("`year`");
            }
            if m.is_none() {
                missing.push("`month`");
            }
            if d.is_none() {
                missing.push("`day`");
            }
            let hint = format!("add the {} to get a valid date", join_args(&missing));
            return Err(vec![SourceDiagnostic::error(span, "date is incomplete").with_hint(hint)]);
        }
    };
    let time = match (hour, minute, second) {
        (Some(h), Some(m), Some(s)) => {
            if !(0..24).contains(&h) {
                return bail(span, "hour is invalid");
            }
            if !(0..60).contains(&m) {
                return bail(span, "minute is invalid");
            }
            if !(0..60).contains(&s) {
                return bail(span, "second is invalid");
            }
            Some((h as u8, m as u8, s as u8))
        }
        (None, None, None) => None,
        (h, m, s) => {
            let mut missing = Vec::new();
            if h.is_none() {
                missing.push("`hour`");
            }
            if m.is_none() {
                missing.push("`minute`");
            }
            if s.is_none() {
                missing.push("`second`");
            }
            let hint = format!("add the {} to get a valid time", join_args(&missing));
            return Err(vec![SourceDiagnostic::error(span, "time is incomplete").with_hint(hint)]);
        }
    };
    if date.is_none() && time.is_none() {
        return Err(vec![SourceDiagnostic::error(
            span,
            "at least one of date or time must be fully specified",
        )
        .with_hint("add the `hour`, `minute`, and `second` arguments to get a valid time")
        .with_hint("add the `year`, `month`, and `day` arguments to get a valid date")]);
    }
    Ok(Value::Datetime(Datetime { date, time }))
}

fn join_args(items: &[&str]) -> String {
    match items.len() {
        0 => String::new(),
        1 => format!("{} argument", items[0]),
        2 => format!("{} and {} arguments", items[0], items[1]),
        _ => {
            let (last, rest) = items.split_last().unwrap();
            format!("{}, and {} arguments", rest.join(", "), last)
        }
    }
}

pub fn datetime_today(vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let offset: Option<Spanned<Value>> = args.named_spanned("offset")?;
    let offset = match offset {
        None | Some(Spanned { v: Value::Auto, .. }) => None,
        Some(Spanned { v: Value::Int(i), .. }) => Some(i),
        Some(o) => {
            return bail(o.span, format!("expected integer or auto, found {}", o.v.ty().long_name()))
        }
    };
    if let Some(ts) = vm.world.creation_timestamp {
        let secs = ts + offset.unwrap_or(0) * 3600;
        let days = secs.div_euclid(86400);
        let rem = secs.rem_euclid(86400);
        let (y, m, d) = crate::eval::datetime::civil_from_days(days);
        return Ok(Value::Datetime(Datetime {
            date: Some((y as i32, m as u8, d as u8)),
            time: Some(((rem / 3600) as u8, ((rem % 3600) / 60) as u8, (rem % 60) as u8)),
        }));
    }
    Ok(Value::Datetime(crate::eval::datetime::now(offset)))
}

pub fn duration_ctor(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let seconds: Option<i64> = args.named("seconds")?;
    let minutes: Option<i64> = args.named("minutes")?;
    let hours: Option<i64> = args.named("hours")?;
    let days: Option<i64> = args.named("days")?;
    let weeks: Option<i64> = args.named("weeks")?;
    let total = seconds.unwrap_or(0) as f64
        + minutes.unwrap_or(0) as f64 * 60.0
        + hours.unwrap_or(0) as f64 * 3600.0
        + days.unwrap_or(0) as f64 * 86400.0
        + weeks.unwrap_or(0) as f64 * 604800.0;
    Ok(Value::Duration(Duration::new(total)))
}

pub fn decimal_ctor(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: Spanned<Value> = args.expect_spanned("value")?;
    let d = match &v.v {
        Value::Int(i) => decimal::from_int(*i),
        Value::Float(f) => match decimal::from_f64(*f) {
            Some(d) => {
                // Mimic rust_decimal's conversion from f64 (uses full precision).
                if f.fract() == 0.0 || d.scale == 0 {
                    d
                } else {
                    let exact = format!("{:.28}", f);
                    let trimmed = exact.trim_end_matches('0');
                    decimal::parse(trimmed).unwrap_or(d)
                }
            }
            None => {
                return bail(
                    v.span,
                    format!("float is not a valid decimal: {}", crate::eval::repr::repr_float(*f)),
                )
            }
        },
        Value::Str(s) => match decimal::parse(s) {
            Some(d) => d,
            None => return bail(v.span, format!("invalid decimal: {s}")),
        },
        Value::Dyn(dy) => match &**dy {
            Dynamic::Decimal(d) => d.clone(),
            _ => return bail(v.span, format!("expected integer, float, or string, found {}", v.v.ty().long_name())),
        },
        other => {
            return bail(v.span, format!("expected integer, float, or string, found {}", other.ty().long_name()))
        }
    };
    Ok(Value::dynamic(Dynamic::Decimal(d)))
}

