        "inv" => Ok(Value::dynamic(Dynamic::Direction(match d {
            Direction::Ltr => Direction::Rtl,
            Direction::Rtl => Direction::Ltr,
            Direction::Ttb => Direction::Btt,
            Direction::Btt => Direction::Ttb,
        }))),
        _ => return None,
    })
}

