fn log(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let v: Spanned<Num> = args.expect_spanned("value")?;
    let base: Option<Spanned<f64>> = args.named_spanned("base")?;
    let f = v.v.as_f64();
    if f <= 0.0 {
        return bail(v.span, "value must be strictly positive");
    }
    let (b, bspan) = match base {
        Some(b) => (b.v, b.span),
        None => (10.0, span),
    };
    if b.is_nan() || b.is_infinite() || b == 0.0 || !b.is_normal() {
        return bail(bspan, "base may not be zero, NaN, infinite, or subnormal");
    }
    let r = if b == 2.0 {
        f.log2()
    } else if b == 10.0 {
        f.log10()
    } else {
        f.ln() / b.ln()
    };
    if r.is_infinite() || r.is_nan() {
        return bail(span, "the result is not a real number");
    }
    Ok(Value::Float(r))
}

fn ln(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let v: Spanned<Num> = args.expect_spanned("value")?;
    let f = v.v.as_f64();
    if f <= 0.0 {
        return bail(v.span, "value must be strictly positive");
    }
    let r = f.ln();
    if r.is_infinite() {
        return bail(span, "the result is not a real number");
    }
    Ok(Value::Float(r))
}

fn fact(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let n: NonNeg = args.expect("number")?;
    let mut r: i64 = 1;
    for i in 1..=n.0 {
        r = r.checked_mul(i).ok_or_else(too_large).at(span)?;
    }
    Ok(Value::Int(r))
}

fn perm(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let n: NonNeg = args.expect("base")?;
    let k: NonNeg = args.expect("numbers")?;
    if k.0 > n.0 {
        return Ok(Value::Int(0));
    }
    let mut r: i64 = 1;
    for i in (n.0 - k.0 + 1)..=n.0 {
        r = r.checked_mul(i).ok_or_else(too_large).at(span)?;
    }
    Ok(Value::Int(r))
}

fn binom(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let n: NonNeg = args.expect("n")?;
    let k: NonNeg = args.expect("k")?;
    if k.0 > n.0 {
        return Ok(Value::Int(0));
    }
    let k = k.0.min(n.0 - k.0);
    let mut r: i64 = 1;
    for i in 0..k {
        r = r.checked_mul(n.0 - i).ok_or_else(too_large).at(span)?;
        r /= i + 1;
    }
    Ok(Value::Int(r))
}

fn gcd_i(a: i64, b: i64) -> i64 {
    let (mut a, mut b) = (a.unsigned_abs(), b.unsigned_abs());
    while b != 0 {
        let t = a % b;
        a = b;
        b = t;
    }
    a as i64
}

fn gcd(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let a: i64 = args.expect("a")?;
    let b: i64 = args.expect("b")?;
    Ok(Value::Int(gcd_i(a, b)))
}

fn lcm(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let a: i64 = args.expect("a")?;
    let b: i64 = args.expect("b")?;
    if a == 0 || b == 0 {
        return Ok(Value::Int(0));
    }
    let g = gcd_i(a, b);
    let r = (a / g).checked_mul(b).ok_or_else(too_large).at(span)?;
    Ok(Value::Int(r.abs()))
}

fn float_to_int(f: f64, span: Span) -> Result<i64> {
    if f.is_nan() {
        return Ok(0);
    }
    if f.is_infinite() || f.abs() >= 9223372036854775808.0 {
        return bail(span, too_large());
    }
    Ok(f as i64)
}

fn floor(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let v: DecNum = args.expect("value")?;
    Ok(Value::Int(match v {
        DecNum::Int(i) => i,
        DecNum::Float(f) => float_to_int(f.floor(), span)?,
        DecNum::Decimal(d) => float_to_int(decimal::to_f64(&d).floor(), span)?,
    }))
}

fn ceil(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let v: DecNum = args.expect("value")?;
    Ok(Value::Int(match v {
        DecNum::Int(i) => i,
        DecNum::Float(f) => float_to_int(f.ceil(), span)?,
        DecNum::Decimal(d) => float_to_int(decimal::to_f64(&d).ceil(), span)?,
    }))
}

fn trunc(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let v: DecNum = args.expect("value")?;
    Ok(Value::Int(match v {
        DecNum::Int(i) => i,
        DecNum::Float(f) => float_to_int(f.trunc(), span)?,
        DecNum::Decimal(d) => float_to_int(decimal::to_f64(&d).trunc(), span)?,
    }))
}

fn fract(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: DecNum = args.expect("value")?;
    Ok(match v {
        DecNum::Int(_) => Value::Int(0),
        DecNum::Float(f) => Value::Float(f.fract()),
        DecNum::Decimal(d) => {
            let int = decimal::to_f64(&d).trunc();
            let whole = decimal::from_f64(int).unwrap_or(decimal::from_int(0));
            Value::dynamic(Dynamic::Decimal(decimal::sub(&d, &whole).unwrap_or(decimal::from_int(0))))
        }
    })
}

fn round(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let v: DecNum = args.expect("value")?;
    let digits: Option<i64> = args.named("digits")?;
    let digits = digits.unwrap_or(0);
    Ok(match v {
        DecNum::Int(i) => {
            if digits >= 0 {
                Value::Int(i)
            } else {
                let factor = 10i64.checked_pow((-digits).min(18) as u32).unwrap_or(i64::MAX);
                if (-digits) > 18 {
                    Value::Int(0)
                } else {
                    let r = (i as f64 / factor as f64).round() * factor as f64;
                    Value::Int(float_to_int(r, span)?)
                }
            }
        }
        DecNum::Float(f) => {
            let d = digits.clamp(-308, 308) as i32;
            let factor = 10f64.powi(d);
            let r = (f * factor).round() / factor;
            if !f.is_finite() {
                Value::Float(f)
            } else if r.is_finite() {
                Value::Float(r)
            } else {
                Value::Float(f)
            }
        }
        DecNum::Decimal(d) => {
            let f = decimal::to_f64(&d);
            let digits = digits.max(0) as u32;
            // Round half away from zero at the given scale.
            let scaled = decimal::mul(&d, &Decimal { mantissa: 10i128.pow(digits.min(28)), scale: 0 }).at(span)?;
            let m = scaled.mantissa;
            let sc = scaled.scale;
            let div = 10i128.pow(sc);
            let q = m / div;
            let r = m % div;
            let q = if (r.abs() * 2) >= div && r != 0 { q + m.signum() } else { q };
            let _ = f;
            Value::dynamic(Dynamic::Decimal(Decimal { mantissa: q, scale: digits.min(28) }))
        }
    })
}

fn clamp(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let v: DecNum = args.expect("value")?;
    let min: DecNum = args.expect("min")?;
    let max: Spanned<DecNum> = args.expect_spanned("max")?;
    let vv = v.to_value();
    let minv = min.to_value();
    let maxv = max.v.to_value();
    if ops::compare(&maxv, &minv).at(span)? == std::cmp::Ordering::Less {
        return bail(max.span, "max must be greater than or equal to min");
    }
    if ops::compare(&vv, &minv).at(span)? == std::cmp::Ordering::Less {
        return Ok(minv);
    }
    if ops::compare(&vv, &maxv).at(span)? == std::cmp::Ordering::Greater {
        return Ok(maxv);
    }
    Ok(vv)
}

fn minmax(args: &mut Args, span: Span, want: std::cmp::Ordering) -> Result<Value> {
    let values: Vec<Spanned<Value>> = args.all_spanned()?;
    let mut iter = values.into_iter();
    let Some(first) = iter.next() else {
        return bail(span, "expected at least one value");
    };
    let mut best = first.v;
    for v in iter {
        let ord = ops::compare(&v.v, &best).at(v.span)?;
        if ord == want {
            best = v.v;
        }
    }
    Ok(best)
}

fn min(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    minmax(args, span, std::cmp::Ordering::Less)
}

fn max(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    minmax(args, span, std::cmp::Ordering::Greater)
}

fn even(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: i64 = args.expect("value")?;
    Ok(Value::Bool(v % 2 == 0))
}

fn odd(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: i64 = args.expect("value")?;
    Ok(Value::Bool(v % 2 != 0))
}

fn check_divisor(d: &DecNum, span: Span) -> Result<()> {
    let zero = match d {
        DecNum::Int(0) => true,
        DecNum::Float(f) => *f == 0.0,
        DecNum::Decimal(dec) => dec.mantissa == 0,
        _ => false,
    };
    if zero {
        return bail(span, "divisor must not be zero");
    }
    Ok(())
}

fn rem(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let a: DecNum = args.expect("dividend")?;
    let b: Spanned<DecNum> = args.expect_spanned("divisor")?;
    check_divisor(&b.v, b.span)?;
    Ok(match (a, b.v) {
        (DecNum::Int(a), DecNum::Int(b)) => Value::Int(a.wrapping_rem(b)),
        (DecNum::Decimal(a), DecNum::Decimal(b)) => {
            let q = decimal::div(&a, &b).at(b_span(&b))?;
            let qf = decimal::to_f64(&q).trunc();
            let qd = decimal::from_f64(qf).unwrap_or(decimal::from_int(0));
            let prod = decimal::mul(&qd, &b).at(b_span(&b))?;
            Value::dynamic(Dynamic::Decimal(decimal::normalize(&decimal::sub(&a, &prod).at(b_span(&b))?)))
        }
        (DecNum::Decimal(a), DecNum::Int(b)) => {
            let bd = decimal::from_int(b);
            let q = decimal::to_f64(&a) / b as f64;
            let qd = decimal::from_f64(q.trunc()).unwrap_or(decimal::from_int(0));
            let prod = decimal::mul(&qd, &bd).unwrap();
            Value::dynamic(Dynamic::Decimal(decimal::normalize(&decimal::sub(&a, &prod).unwrap())))
        }
        (DecNum::Int(a), DecNum::Decimal(b)) => {
            let ad = decimal::from_int(a);
            let q = a as f64 / decimal::to_f64(&b);
            let qd = decimal::from_f64(q.trunc()).unwrap_or(decimal::from_int(0));
            let prod = decimal::mul(&qd, &b).unwrap();
            Value::dynamic(Dynamic::Decimal(decimal::normalize(&decimal::sub(&ad, &prod).unwrap())))
        }
        (a, b) => Value::Float(a.as_f64() % b.as_f64()),
    })
}

fn b_span(_d: &Decimal) -> Span {
    Span::detached()
}

fn div_euclid(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let a: DecNum = args.expect("dividend")?;
    let b: Spanned<DecNum> = args.expect_spanned("divisor")?;
    check_divisor(&b.v, b.span)?;
    Ok(match (a, b.v) {
        (DecNum::Int(a), DecNum::Int(b)) => Value::Int(a.wrapping_div_euclid(b)),
        (a, b) => Value::Float(a.as_f64().div_euclid(b.as_f64())),
    })
}

fn rem_euclid(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let a: DecNum = args.expect("dividend")?;
    let b: Spanned<DecNum> = args.expect_spanned("divisor")?;
    check_divisor(&b.v, b.span)?;
    Ok(match (a, b.v) {
        (DecNum::Int(a), DecNum::Int(b)) => Value::Int(a.wrapping_rem_euclid(b)),
        (a, b) => Value::Float(a.as_f64().rem_euclid(b.as_f64())),
    })
}

fn quo(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let a: DecNum = args.expect("dividend")?;
    let b: Spanned<DecNum> = args.expect_spanned("divisor")?;
    check_divisor(&b.v, b.span)?;
    Ok(match (a, b.v) {
        (DecNum::Int(a), DecNum::Int(b)) => Value::Int(a.wrapping_div(b).wrapping_sub(if (a % b != 0) && ((a < 0) != (b < 0)) { 1 } else { 0 })),
        (a, b) => Value::Int(float_to_int((a.as_f64() / b.as_f64()).floor(), span)?),
    })
}

fn norm(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let p: Option<Spanned<f64>> = args.named_spanned("p")?;
    let values: Vec<f64> = args.all()?;
    let p = match p {
        Some(p) => {
            if p.v <= 0.0 {
                return bail(p.span, "p must be greater than zero");
            }
            p.v
        }
        None => 2.0,
    };
    if values.is_empty() {
        return Ok(Value::Float(0.0));
    }
    let max = values.iter().fold(0.0f64, |m, v| m.max(v.abs()));
    if max == 0.0 {
        return Ok(Value::Float(0.0));
    }
    let sum: f64 = values.iter().map(|v| (v.abs() / max).powf(p)).sum();
    Ok(Value::Float(max * sum.powf(1.0 / p)))
}

