/// Int, float or decimal.
pub enum DecNum {
    Int(i64),
    Float(f64),
    Decimal(Decimal),
}

impl FromValue for DecNum {
    fn describe() -> String {
        "integer, float, or decimal".into()
    }
    fn from_value(v: Value) -> std::result::Result<Self, String> {
        match v {
            Value::Int(i) => Ok(DecNum::Int(i)),
            Value::Float(f) => Ok(DecNum::Float(f)),
            Value::Dyn(d) => match &*d {
                Dynamic::Decimal(dec) => Ok(DecNum::Decimal(dec.clone())),
                _ => Err(mismatch::<Self>(&Value::Dyn(d.clone()))),
            },
            v => Err(mismatch::<Self>(&v)),
        }
    }
}

impl DecNum {
    fn to_value(self) -> Value {
        match self {
            DecNum::Int(i) => Value::Int(i),
            DecNum::Float(f) => Value::Float(f),
            DecNum::Decimal(d) => Value::dynamic(Dynamic::Decimal(d)),
        }
    }
    fn as_f64(&self) -> f64 {
        match self {
            DecNum::Int(i) => *i as f64,
            DecNum::Float(f) => *f,
            DecNum::Decimal(d) => decimal::to_f64(d),
        }
    }
}

/// Int or float, rejecting decimals with a hint.
pub struct StrictNum(pub Num);

impl FromValue for StrictNum {
    fn describe() -> String {
        "integer or float".into()
    }
    fn from_value(v: Value) -> std::result::Result<Self, String> {
        match v {
            Value::Int(i) => Ok(StrictNum(Num::Int(i))),
            Value::Float(f) => Ok(StrictNum(Num::Float(f))),
            Value::Dyn(d) if matches!(&*d, Dynamic::Decimal(_)) => Err(hinted(
                "expected integer or float, found decimal",
                "if loss of precision is acceptable, explicitly cast the decimal to a float with `float(value)`",
            )),
            v => Err(mismatch::<Self>(&v)),
        }
    }
}

/// Angle-like: int/float (radians) or angle.
pub struct AngleLike(pub f64);

impl FromValue for AngleLike {
