            Value::Float(f) => Ok(AngleLike(f)),
            Value::Angle(a) => Ok(AngleLike(a)),
            v => Err(mismatch::<Self>(&v)),
        }
    }
}

fn too_large() -> String {
    "the result is too large".into()
}

fn abs(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: Spanned<Value> = args.expect_spanned("value")?;
    Ok(match v.v {
        Value::Int(i) => Value::Int(i.checked_abs().ok_or_else(too_large).at(v.span)?),
        Value::Float(f) => Value::Float(f.abs()),
        Value::Length(l) => Value::Length(Length { abs: l.abs.abs(), em: l.em.abs() }),
        Value::Angle(a) => Value::Angle(a.abs()),
        Value::Ratio(r) => Value::Ratio(r.abs()),
        Value::Fraction(f) => Value::Fraction(f.abs()),
        Value::Dyn(d) if matches!(&*d, Dynamic::Decimal(_)) => {
            if let Dynamic::Decimal(dec) = &*d {
                Value::dynamic(Dynamic::Decimal(Decimal { mantissa: dec.mantissa.abs(), scale: dec.scale }))
            } else {
                unreachable!()
            }
        }
        other => {
            return bail(
                v.span,
                format!(
                    "expected integer, float, length, angle, ratio, fraction, or decimal, found {}",
                    other.ty().long_name()
                ),
            )
        }
    })
}

fn pow(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let base: Spanned<DecNum> = args.expect_spanned("base")?;
    let exponent: Spanned<StrictNum> = args.expect_spanned("exponent")?;
    match &exponent.v.0 {
        Num::Int(0) if matches!(base.v, DecNum::Int(0)) => {
            return bail(span, "zero to the power of zero is undefined");
        }
        Num::Float(f) if *f == 0.0 && base.v.as_f64() == 0.0 => {
            return bail(span, "zero to the power of zero is undefined");
        }
        Num::Float(f) if f.is_nan() || f.is_infinite() => {
            return bail(exponent.span, "exponent may not be NaN or infinite");
        }
        _ => {}
    }
    match (base.v, exponent.v.0) {
        (DecNum::Int(b), Num::Int(e)) if e >= 0 => {
            let r = b.checked_pow(e as u32).ok_or_else(too_large).at(span)?;
            if e > u32::MAX as i64 {
                return bail(span, too_large());
            }
            Ok(Value::Int(r))
        }
        (DecNum::Decimal(d), Num::Int(e)) => {
            let mut result = decimal::from_int(1);
            let n = e.unsigned_abs();
            for _ in 0..n.min(10_000) {
                result = decimal::mul(&result, &d).at(span)?;
            }
            if e < 0 {
                result = decimal::div(&decimal::from_int(1), &result).at(span)?;
            }
            Ok(Value::dynamic(Dynamic::Decimal(decimal::normalize(&result))))
        }
        (b, e) => {
            let b = b.as_f64();
            let e = e.as_f64();
            let r = if e.fract() == 0.0 { b.powi(e as i32) } else { b.powf(e) };
            if r.is_nan() {
                return bail(span, "the result is not a real number");
            }
            Ok(Value::Float(r))
        }
    }
