    if ops::compare(&maxv, &minv).at(span)? == std::cmp::Ordering::Less {
        return bail(max.span, "max must be greater than or equal to min");
    }
    if ops::compare(&vv, &minv).at(span)? == std::cmp::Ordering::Less {
        return Ok(minv);
    }
    if ops::compare(&vv, &maxv).at(span)? == std::cmp::Ordering::Greater {
