            Value::dynamic(Dynamic::Decimal(decimal::normalize(&decimal::sub(&a, &prod).unwrap())))
        }
        (DecNum::Int(a), DecNum::Decimal(b)) => {
            let ad = decimal::from_int(a);
            let q = a as f64 / decimal::to_f64(&b);
            let qd = decimal::from_f64(q.trunc()).unwrap_or(decimal::from_int(0));
            let prod = decimal::mul(&qd, &b).unwrap();
            Value::dynamic(Dynamic::Decimal(decimal::normalize(&decimal::sub(&ad, &prod).unwrap())))
        }
        (a, b) => Value::Float(a.as_f64() % b.as_f64()),
    })
}

