/// Resolve a (possibly negative) index into a byte offset with boundary checks.
fn locate(s: &str, index: i64, span: Span) -> Result<usize> {
    let len = s.len() as i64;
    let wrapped = if index < 0 { index + len } else { index };
    if wrapped < 0 || wrapped > len {
