fn not_boundary(index: i64) -> String {
    format!("string index {index} is not a character boundary")
}

/// Resolve a (possibly negative) index into a byte offset with boundary checks.
fn locate(s: &str, index: i64, span: Span) -> Result<usize> {
    let len = s.len() as i64;
    let wrapped = if index < 0 { index + len } else { index };
    if wrapped < 0 || wrapped > len {
        return bail(span, out_of_bounds(index, s.len()));
    }
    let i = wrapped as usize;
    if !s.is_char_boundary(i) {
        return bail(span, not_boundary(index));
    }
    Ok(i)
}

fn locate_opt(s: &str, index: i64) -> Option<usize> {
    let len = s.len() as i64;
    let wrapped = if index < 0 { index + len } else { index };
    if wrapped < 0 || wrapped > len {
        return None;
    }
    let i = wrapped as usize;
    if !s.is_char_boundary(i) {
        return None;
    }
    Some(i)
}

pub fn match_dict(start: usize, end: usize, text: &str, captures: Vec<Value>) -> Value {
    let mut d: Dict = IndexMap::new();
    d.insert("start".into(), Value::Int(start as i64));
    d.insert("end".into(), Value::Int(end as i64));
    d.insert("text".into(), Value::str(text));
    d.insert("captures".into(), Value::array(captures));
    Value::dict(d)
}

fn captures_of(c: &regex::Captures) -> Vec<Value> {
    (1..c.len())
        .map(|i| match c.get(i) {
            Some(m) => Value::str(m.as_str()),
            None => Value::None,
        })
        .collect()
}

