                        _ => return bail(a.span, "expected either `start` or `end`"),
                    },
                    None => {
                        return bail(a.span, format!("expected alignment, found {}", a.v.ty().long_name()))
                    }
                },
            };
            Ok(Value::str(trim(s, pat, start, end, repeat)))
        })(),
        "split" => (|| {
            let pat: Option<StrPattern> = args.eat()?;
            Ok(Value::array(match pat {
                None => s.split_whitespace().map(Value::str).collect(),
                Some(StrPattern::Str(p)) => s.split(&*p).map(Value::str).collect(),
                Some(StrPattern::Regex(r)) => r.regex.split(s).map(Value::str).collect(),
            }))
        })(),
        "rev" => Ok(Value::str(s.graphemes(true).rev().collect::<String>())),
        _ => return None,
    };
    Some(r)
}

enum Replacement {
    Str(String),
    Func(Func),
}

fn trim(s: &str, pat: Option<StrPattern>, start: bool, end: bool, repeat: bool) -> String {
    match pat {
        None => {
            let mut r = s;
            if start {
                r = r.trim_start();
            }
            if end {
                r = r.trim_end();
            }
            r.to_string()
        }
        Some(StrPattern::Str(p)) => {
            if p.is_empty() {
                return s.to_string();
            }
            let mut r = s;
            if start {
                if repeat {
                    while let Some(x) = r.strip_prefix(&*p) {
                        r = x;
                    }
                } else if let Some(x) = r.strip_prefix(&*p) {
                    r = x;
                }
            }
            if end {
                if repeat {
                    while let Some(x) = r.strip_suffix(&*p) {
                        r = x;
                    }
                } else if let Some(x) = r.strip_suffix(&*p) {
                    r = x;
                }
            }
            r.to_string()
        }
        Some(StrPattern::Regex(re)) => {
            let mut r = s.to_string();
            if start {
                loop {
                    let mut changed = false;
                    if let Some(m) = re.regex.find(&r) {
                        if m.start() == 0 && m.end() > 0 {
                            r = r[m.end()..].to_string();
                            changed = true;
                        }
                    }
                    if !changed || !repeat {
                        break;
                    }
                }
            }
            if end {
                loop {
                    let mut changed = false;
                    let mut last_end = None;
                    for m in re.regex.find_iter(&r) {
                        if m.end() == r.len() && m.start() < m.end() {
                            last_end = Some(m.start());
                        }
                    }
                    if let Some(st) = last_end {
                        r = r[..st].to_string();
                        changed = true;
                    }
                    if !changed || !repeat {
                        break;
                    }
                }
            }
            r
        }
    }
}

pub fn from_unicode(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: Spanned<NonNeg> = args.expect_spanned("value")?;
    match char::from_u32(v.v.0 as u32) {
        Some(c) if v.v.0 <= u32::MAX as i64 => Ok(Value::str(c.to_string())),
        _ => bail(v.span, format!("{:#x} is not a valid codepoint", v.v.0)),
    }
}

pub fn to_unicode(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: Spanned<String> = args.expect_spanned("value")?;
    let mut chars = v.v.chars();
    match (chars.next(), chars.next()) {
        (Some(c), None) => Ok(Value::Int(c as i64)),
        _ => bail(v.span, "expected exactly one character"),
    }
}
