                        result = ops::join(result, last.clone().unwrap()).at(span)?;
                    } else if let Some(s) = &sep {
                        result = ops::join(result, s.clone()).at(span)?;
                    }
                }
                result = ops::join(result, item.clone()).at(span)?;
            }
            Ok(result)
        })(),
        "sorted" => (|| {
            let key: Option<Func> = args.named("key")?;
            let by: Option<Func> = args.named("by")?;
            let mut items: Vec<(Value, Value)> = Vec::with_capacity(a.len());
            for item in a {
                let k = match &key {
                    Some(f) => vm.call_func(f, Args::new(span, vec![item.clone()]), span)?,
                    None => item.clone(),
                };
                items.push((k, item.clone()));
            }
            let mut err: Option<Vec<SourceDiagnostic>> = None;
            // Stable insertion/merge sort with error capture.
            let mut sorted: Vec<(Value, Value)> = Vec::with_capacity(items.len());
            for item in items {
                let mut pos = sorted.len();
                for (i, existing) in sorted.iter().enumerate() {
                    let less = match &by {
                        Some(f) => {
                            match vm.call_func(f, Args::new(span, vec![item.0.clone(), existing.0.clone()]), span) {
                                Ok(Value::Bool(b)) => b,
                                Ok(other) => {
                                    err = Some(vec![SourceDiagnostic::error(
                                        span,
                                        format!("expected boolean, found {}", other.ty().long_name()),
                                    )]);
                                    false
                                }
                                Err(e) => {
                                    err = Some(e);
                                    false
                                }
                            }
                        }
                        None => match ops::compare(&item.0, &existing.0) {
                            Ok(o) => o == std::cmp::Ordering::Less,
                            Err(e) => {
                                err = Some(vec![SourceDiagnostic::error(span, e)
                                    .with_hint("consider choosing a `key` or defining the comparison with `by`")]);
                                false
                            }
                        },
                    };
                    if err.is_some() {
                        return Err(err.unwrap());
                    }
                    if less {
                        pos = i;
                        break;
                    }
                }
                sorted.insert(pos, item);
            }
            Ok(Value::array(sorted.into_iter().map(|(_, v)| v).collect()))
        })(),
        "dedup" => (|| {
            let key: Option<Func> = args.named("key")?;
            let mut out: Vec<Value> = Vec::new();
            let mut keys: Vec<Value> = Vec::new();
            for item in a {
                let k = match &key {
                    Some(f) => vm.call_func(f, Args::new(span, vec![item.clone()]), span)?,
                    None => item.clone(),
                };
                if !keys.iter().any(|x| ops::equal(x, &k)) {
                    keys.push(k);
                    out.push(item.clone());
                }
            }
            Ok(Value::array(out))
        })(),
        "intersperse" => (|| {
            let sep: Value = args.expect("separator")?;
            let mut out = Vec::new();
            for (i, item) in a.iter().enumerate() {
                if i > 0 {
                    out.push(sep.clone());
                }
                out.push(item.clone());
            }
            Ok(Value::array(out))
        })(),
        "chunks" => (|| {
            let size: Spanned<i64> = args.expect_spanned("chunk-size")?;
            let exact: bool = args.named("exact")?.unwrap_or(false);
            if size.v <= 0 {
                return bail(size.span, "number must be positive");
            }
            let n = size.v as usize;
            let mut out = Vec::new();
            for chunk in a.chunks(n) {
                if exact && chunk.len() < n {
                    break;
                }
                out.push(Value::array(chunk.to_vec()));
            }
            Ok(Value::array(out))
        })(),
        "windows" => (|| {
            let size: Spanned<i64> = args.expect_spanned("window-size")?;
            if size.v <= 0 {
                return bail(size.span, "number must be positive");
            }
            let n = size.v as usize;
            let out: Vec<Value> = if n > a.len() {
                vec![]
            } else {
                a.windows(n).map(|w| Value::array(w.to_vec())).collect()
            };
            Ok(Value::array(out))
        })(),
        "reduce" => (|| {
            let f: Func = args.expect("reducer")?;
            let mut iter = a.iter();
            let mut acc = match iter.next() {
                Some(v) => v.clone(),
                None => return Ok(Value::None),
            };
            for item in iter {
                acc = vm.call_func(&f, Args::new(span, vec![acc, item.clone()]), span)?;
            }
            Ok(acc)
        })(),
        "to-dict" => (|| {
            let mut d: Dict = IndexMap::new();
            for item in a {
                match item {
                    Value::Array(pair) if pair.len() == 2 => match &pair[0] {
                        Value::Str(k) => {
                            d.insert(k.to_string(), pair[1].clone());
                        }
                        other => {
                            return bail(
                                span,
                                format!("expected key of type str, found {}", other.ty().long_name()),
                            )
                        }
                    },
                    Value::Array(pair) => {
                        return bail(
                            span,
                            format!("expected pair of key and value, found array of length {}", pair.len()),
                        )
                    }
                    other => {
                        return bail(
                            span,
                            format!("expected (str, any) pairs, found {}", other.ty().long_name()),
                        )
                    }
                }
            }
            Ok(Value::dict(d))
        })(),
        "split" => (|| {
            let at: Value = args.expect("at")?;
            let mut out = Vec::new();
            let mut cur = Vec::new();
            for item in a {
                if ops::equal(item, &at) {
                    out.push(Value::array(std::mem::take(&mut cur)));
                } else {
                    cur.push(item.clone());
                }
            }
            out.push(Value::array(cur));
            Ok(Value::array(out))
        })(),
        _ => return None,
    };
    Some(r)
}

fn call_bool(vm: &mut Vm, f: &Func, args: Vec<Value>, span: Span) -> Result<bool> {
    match vm.call_func(f, Args::new(span, args), span)? {
        Value::Bool(b) => Ok(b),
        other => bail(span, format!("expected boolean, found {}", other.ty().long_name())),
    }
}

pub fn call_mut(a: &mut Vec<Value>, method: &str, args: &mut Args, span: Span) -> Result<Value> {
    match method {
        "push" => {
            let v: Value = args.expect("value")?;
            a.push(v);
            Ok(Value::None)
        }
        "pop" => match a.pop() {
            Some(v) => Ok(v),
            None => bail(span, "array is empty"),
        },
        "insert" => {
            let index: i64 = args.expect("index")?;
            let v: Value = args.expect("value")?;
            match locate(a.len(), index, true) {
                Some(i) => {
                    a.insert(i, v);
                    Ok(Value::None)
                }
                None => bail(span, out_of_bounds(index, a.len())),
            }
        }
        "remove" => {
            let index: i64 = args.expect("index")?;
            let default: Option<Value> = args.named("default")?;
            match locate(a.len(), index, false) {
                Some(i) => Ok(a.remove(i)),
                None => match default {
                    Some(d) => Ok(d),
                    None => bail(span, out_of_bounds_no_default(index, a.len())),
                },
            }
        }
        _ => bail(span, format!("type array has no method `{method}`")),
    }
}
