//! Dictionary methods.

use std::rc::Rc;

use crate::eval::repr::repr_str;
use crate::eval::value::*;
use crate::eval::vm::{bail, Result, SourceDiagnostic, Vm};
use crate::syntax::ast::Span;

pub const METHODS: &[&str] = &["len", "at", "keys", "values", "pairs"];

pub fn method_as_func(_vm: &mut Vm, _args: &mut Args, span: Span) -> Result<Value> {
    bail(span, "cannot call dictionary method without a receiver")
}

pub fn missing_key(key: &str) -> String {
    format!("dictionary does not contain key {}", repr_str(key))
}

pub fn missing_key_no_default(key: &str) -> String {
    format!("dictionary does not contain key {} and no default value was specified", repr_str(key))
}

pub fn call(_vm: &mut Vm, d: &Rc<Dict>, method: &str, args: &mut Args, span: Span) -> Option<Result<Value>> {
    let r: Result<Value> = match method {
        "len" => Ok(Value::Int(d.len() as i64)),
        "at" => (|| {
            let key: String = args.expect("key")?;
            let default: Option<Value> = args.named("default")?;
            match d.get(&key) {
                Some(v) => Ok(v.clone()),
                None => match default {
                    Some(v) => Ok(v),
                    None => bail(span, missing_key_no_default(&key)),
                },
            }
        })(),
        "keys" => Ok(Value::array(d.keys().map(|k| Value::str(k.clone())).collect())),
        "values" => Ok(Value::array(d.values().cloned().collect())),
        "pairs" => Ok(Value::array(
            d.iter().map(|(k, v)| Value::array(vec![Value::str(k.clone()), v.clone()])).collect(),
        )),
        _ => return None,
    };
    Some(r)
}

pub fn call_mut(d: &mut Dict, method: &str, args: &mut Args, span: Span) -> Result<Value> {
    match method {
        "insert" => {
            let key: String = args.expect("key")?;
            let v: Value = args.expect("value")?;
            d.insert(key, v);
            Ok(Value::None)
        }
        "remove" => {
            let key: String = args.expect("key")?;
            let default: Option<Value> = args.named("default")?;
            match d.shift_remove(&key) {
                Some(v) => Ok(v),
                None => match default {
                    Some(v) => Ok(v),
                    None => Err(vec![SourceDiagnostic::error(span, missing_key(&key))]),
                },
            }
        }
        _ => bail(span, format!("type dictionary has no method `{method}`")),
    }
}
