    Some(wrapped as usize)
}

pub fn call(vm: &mut Vm, a: &Rc<Vec<Value>>, method: &str, args: &mut Args, span: Span) -> Option<Result<Value>> {
    let a: &Vec<Value> = a;
    let r: Result<Value> = match method {
        "len" => Ok(Value::Int(a.len() as i64)),
        "first" => (|| {
            let default: Option<Value> = args.named("default")?;
            match a.first() {
                Some(v) => Ok(v.clone()),
                None => match default {
                    Some(d) => Ok(d),
                    None => bail(span, "array is empty"),
                },
            }
        })(),
        "last" => (|| {
            let default: Option<Value> = args.named("default")?;
            match a.last() {
                Some(v) => Ok(v.clone()),
                None => match default {
                    Some(d) => Ok(d),
                    None => bail(span, "array is empty"),
                },
            }
        })(),
        "at" => (|| {
            let index: i64 = args.expect("index")?;
            let default: Option<Value> = args.named("default")?;
            match locate(a.len(), index, false) {
                Some(i) => Ok(a[i].clone()),
                None => match default {
                    Some(d) => Ok(d),
                    None => bail(span, out_of_bounds_no_default(index, a.len())),
                },
            }
        })(),
        "slice" => (|| {
            let start: i64 = args.expect("start")?;
            let end: Option<Option<i64>> = args.eat()?;
            let count: Option<Spanned<i64>> = args.named_spanned("count")?;
            let end_v = end.flatten();
            if end_v.is_some() && count.is_some() {
                return bail(count.unwrap().span, "`end` and `count` are mutually exclusive");
            }
            let end_idx = match (end_v, &count) {
                (Some(e), _) => e,
                (None, Some(c)) => start + c.v,
                (None, None) => a.len() as i64,
            };
            let s = locate(a.len(), start, true).ok_or_else(|| out_of_bounds(start, a.len())).at(span)?;
            let e = locate(a.len(), end_idx, true).ok_or_else(|| out_of_bounds(end_idx, a.len())).at(span)?;
            if e < s {
                return Ok(Value::array(vec![]));
            }
            Ok(Value::array(a[s..e].to_vec()))
        })(),
        "contains" => (|| {
            let v: Value = args.expect("value")?;
            Ok(Value::Bool(a.iter().any(|x| ops::equal(x, &v))))
        })(),
        "find" => (|| {
            let f: Func = args.expect("searcher")?;
            for item in a {
                if call_bool(vm, &f, vec![item.clone()], span)? {
                    return Ok(item.clone());
                }
            }
            Ok(Value::None)
        })(),
        "position" => (|| {
            let f: Func = args.expect("searcher")?;
            for (i, item) in a.iter().enumerate() {
                if call_bool(vm, &f, vec![item.clone()], span)? {
                    return Ok(Value::Int(i as i64));
                }
            }
            Ok(Value::None)
        })(),
        "filter" => (|| {
            let f: Func = args.expect("test")?;
            let mut out = Vec::new();
            for item in a {
                if call_bool(vm, &f, vec![item.clone()], span)? {
                    out.push(item.clone());
                }
            }
            Ok(Value::array(out))
        })(),
        "map" => (|| {
            let f: Func = args.expect("mapper")?;
            let mut out = Vec::with_capacity(a.len());
            for item in a {
                out.push(vm.call_func(&f, Args::new(span, vec![item.clone()]), span)?);
            }
            Ok(Value::array(out))
        })(),
        "enumerate" => (|| {
            let start: i64 = args.named("start")?.unwrap_or(0);
            Ok(Value::array(
                a.iter()
                    .enumerate()
                    .map(|(i, v)| Value::array(vec![Value::Int(start + i as i64), v.clone()]))
                    .collect(),
            ))
        })(),
        "zip" => (|| {
            let exact: bool = args.named("exact")?.unwrap_or(false);
            let others: Vec<Spanned<Vec<Value>>> = args.all_spanned()?;
            if exact {
                for o in &others {
                    if o.v.len() != a.len() {
                        return bail(
                            o.span,
                            format!("second array has different length ({}) from first array ({})", o.v.len(), a.len()),
                        );
                    }
                }
            }
            let mut len = a.len();
            for o in &others {
                len = len.min(o.v.len());
            }
            let mut out = Vec::with_capacity(len);
            for i in 0..len {
                let mut row = vec![a[i].clone()];
                for o in &others {
                    row.push(o.v[i].clone());
                }
                out.push(Value::array(row));
            }
            Ok(Value::array(out))
        })(),
        "fold" => (|| {
            let init: Value = args.expect("init")?;
            let f: Func = args.expect("folder")?;
            let mut acc = init;
            for item in a {
                acc = vm.call_func(&f, Args::new(span, vec![acc, item.clone()]), span)?;
            }
            Ok(acc)
        })(),
        "sum" => (|| {
            let default: Option<Value> = args.named("default")?;
            let mut iter = a.iter();
            let mut acc = match iter.next() {
                Some(v) => v.clone(),
                None => {
                    return match default {
                        Some(d) => Ok(d),
                        None => bail(span, "cannot calculate sum of empty array with no default"),
                    }
                }
            };
            for item in iter {
                acc = ops::add(acc, item.clone()).at(span)?;
            }
            Ok(acc)
        })(),
        "product" => (|| {
            let default: Option<Value> = args.named("default")?;
            let mut iter = a.iter();
            let mut acc = match iter.next() {
                Some(v) => v.clone(),
                None => {
                    return match default {
                        Some(d) => Ok(d),
                        None => bail(span, "cannot calculate product of empty array with no default"),
                    }
                }
            };
            for item in iter {
                acc = ops::mul(acc, item.clone()).at(span)?;
            }
            Ok(acc)
        })(),
        "any" => (|| {
            let f: Func = args.expect("test")?;
            for item in a {
                if call_bool(vm, &f, vec![item.clone()], span)? {
                    return Ok(Value::Bool(true));
                }
            }
            Ok(Value::Bool(false))
        })(),
        "all" => (|| {
            let f: Func = args.expect("test")?;
            for item in a {
                if !call_bool(vm, &f, vec![item.clone()], span)? {
                    return Ok(Value::Bool(false));
                }
            }
            Ok(Value::Bool(true))
        })(),
        "flatten" => {
            fn flat(v: &[Value], out: &mut Vec<Value>) {
                for item in v {
                    match item {
                        Value::Array(inner) => flat(inner, out),
                        other => out.push(other.clone()),
                    }
                }
            }
            let mut out = Vec::new();
            flat(a, &mut out);
            Ok(Value::array(out))
        }
        "rev" => Ok(Value::array(a.iter().rev().cloned().collect())),
        "join" => (|| {
            let sep: Option<Value> = args.eat()?;
            let last: Option<Value> = args.named("last")?;
            let len = a.len();
            let mut result = Value::None;
            for (i, item) in a.iter().enumerate() {
                if i > 0 {
                    if i + 1 == len && last.is_some() {
                        result = ops::join(result, last.clone().unwrap()).at(span)?;
                    } else if let Some(s) = &sep {
                        result = ops::join(result, s.clone()).at(span)?;
                    }
                }
                result = ops::join(result, item.clone()).at(span)?;
            }
            Ok(result)
        })(),
        "sorted" => (|| {
            let key: Option<Func> = args.named("key")?;
            let by: Option<Func> = args.named("by")?;
            let mut items: Vec<(Value, Value)> = Vec::with_capacity(a.len());
            for item in a {
                let k = match &key {
                    Some(f) => vm.call_func(f, Args::new(span, vec![item.clone()]), span)?,
                    None => item.clone(),
                };
                items.push((k, item.clone()));
            }
            let mut err: Option<Vec<SourceDiagnostic>> = None;
            // Stable insertion/merge sort with error capture.
            let mut sorted: Vec<(Value, Value)> = Vec::with_capacity(items.len());
            for item in items {
                let mut pos = sorted.len();
                for (i, existing) in sorted.iter().enumerate() {
                    let less = match &by {
                        Some(f) => {
                            match vm.call_func(f, Args::new(span, vec![item.0.clone(), existing.0.clone()]), span) {
                                Ok(Value::Bool(b)) => b,
                                Ok(other) => {
                                    err = Some(vec![SourceDiagnostic::error(
                                        span,
                                        format!("expected boolean, found {}", other.ty().long_name()),
                                    )]);
                                    false
                                }
                                Err(e) => {
                                    err = Some(e);
                                    false
                                }
                            }
                        }
                        None => match ops::compare(&item.0, &existing.0) {
                            Ok(o) => o == std::cmp::Ordering::Less,
                            Err(e) => {
                                err = Some(vec![SourceDiagnostic::error(span, e)
                                    .with_hint("consider choosing a `key` or defining the comparison with `by`")]);
                                false
                            }
                        },
                    };
                    if err.is_some() {
                        return Err(err.unwrap());
                    }
                    if less {
                        pos = i;
                        break;
                    }
                }
                sorted.insert(pos, item);
            }
            Ok(Value::array(sorted.into_iter().map(|(_, v)| v).collect()))
        })(),
        "dedup" => (|| {
            let key: Option<Func> = args.named("key")?;
            let mut out: Vec<Value> = Vec::new();
            let mut keys: Vec<Value> = Vec::new();
            for item in a {
                let k = match &key {
                    Some(f) => vm.call_func(f, Args::new(span, vec![item.clone()]), span)?,
                    None => item.clone(),
                };
                if !keys.iter().any(|x| ops::equal(x, &k)) {
                    keys.push(k);
                    out.push(item.clone());
                }
            }
            Ok(Value::array(out))
        })(),
        "intersperse" => (|| {
            let sep: Value = args.expect("separator")?;
            let mut out = Vec::new();
            for (i, item) in a.iter().enumerate() {
                if i > 0 {
                    out.push(sep.clone());
                }
                out.push(item.clone());
            }
            Ok(Value::array(out))
        })(),
        "chunks" => (|| {
            let size: Spanned<i64> = args.expect_spanned("chunk-size")?;
            let exact: bool = args.named("exact")?.unwrap_or(false);
            if size.v <= 0 {
                return bail(size.span, "number must be positive");
            }
            let n = size.v as usize;
            let mut out = Vec::new();
            for chunk in a.chunks(n) {
                if exact && chunk.len() < n {
                    break;
                }
                out.push(Value::array(chunk.to_vec()));
            }
            Ok(Value::array(out))
        })(),
        "windows" => (|| {
            let size: Spanned<i64> = args.expect_spanned("window-size")?;
            if size.v <= 0 {
                return bail(size.span, "number must be positive");
            }
            let n = size.v as usize;
            let out: Vec<Value> = if n > a.len() {
                vec![]
            } else {
                a.windows(n).map(|w| Value::array(w.to_vec())).collect()
            };
            Ok(Value::array(out))
        })(),
        "reduce" => (|| {
            let f: Func = args.expect("reducer")?;
            let mut iter = a.iter();
            let mut acc = match iter.next() {
                Some(v) => v.clone(),
                None => return Ok(Value::None),
            };
            for item in iter {
                acc = vm.call_func(&f, Args::new(span, vec![acc, item.clone()]), span)?;
            }
            Ok(acc)
        })(),
        "to-dict" => (|| {
            let mut d: Dict = IndexMap::new();
            for item in a {
                match item {
                    Value::Array(pair) if pair.len() == 2 => match &pair[0] {
                        Value::Str(k) => {
                            d.insert(k.to_string(), pair[1].clone());
                        }
                        other => {
                            return bail(
                                span,
                                format!("expected key of type str, found {}", other.ty().long_name()),
                            )
                        }
                    },
                    Value::Array(pair) => {
                        return bail(
                            span,
                            format!("expected pair of key and value, found array of length {}", pair.len()),
                        )
                    }
                    other => {
                        return bail(
                            span,
                            format!("expected (str, any) pairs, found {}", other.ty().long_name()),
                        )
                    }
                }
            }
            Ok(Value::dict(d))
        })(),
        "split" => (|| {
            let at: Value = args.expect("at")?;
            let mut out = Vec::new();
            let mut cur = Vec::new();
            for item in a {
                if ops::equal(item, &at) {
                    out.push(Value::array(std::mem::take(&mut cur)));
                } else {
                    cur.push(item.clone());
                }
            }
            out.push(Value::array(cur));
            Ok(Value::array(out))
        })(),
        _ => return None,
    };
    Some(r)
}

fn call_bool(vm: &mut Vm, f: &Func, args: Vec<Value>, span: Span) -> Result<bool> {
    match vm.call_func(f, Args::new(span, args), span)? {
        Value::Bool(b) => Ok(b),
        other => bail(span, format!("expected boolean, found {}", other.ty().long_name())),
    }
}

pub fn call_mut(a: &mut Vec<Value>, method: &str, args: &mut Args, span: Span) -> Result<Value> {
    match method {
        "push" => {
            let v: Value = args.expect("value")?;
            a.push(v);
            Ok(Value::None)
        }
        "pop" => match a.pop() {
            Some(v) => Ok(v),
            None => bail(span, "array is empty"),
        },
        "insert" => {
            let index: i64 = args.expect("index")?;
            let v: Value = args.expect("value")?;
            match locate(a.len(), index, true) {
                Some(i) => {
                    a.insert(i, v);
                    Ok(Value::None)
                }
                None => bail(span, out_of_bounds(index, a.len())),
            }
        }
        "remove" => {
            let index: i64 = args.expect("index")?;
            let default: Option<Value> = args.named("default")?;
            match locate(a.len(), index, false) {
                Some(i) => Ok(a.remove(i)),
                None => match default {
                    Some(d) => Ok(d),
                    None => bail(span, out_of_bounds_no_default(index, a.len())),
                },
            }
        }
        _ => bail(span, format!("type array has no method `{method}`")),
    }
}
