/// Component: integer 0..255 or ratio.
pub struct Component(pub f32);
impl FromValue for Component {
    fn describe() -> String {
        "integer or ratio".into()
    }
    fn from_value(v: Value) -> std::result::Result<Self, String> {
        match v {
            Value::Int(i) => {
                if !(0..=255).contains(&i) {
                    return Err("number must be between 0 and 255".into());
                }
                Ok(Component(i as f32 / 255.0))
            }
            Value::Ratio(r) => {
                if !(0.0..=1.0).contains(&r) {
                    return Err("ratio must be between 0% and 100%".into());
                }
                Ok(Component(r as f32))
            }
            v => Err(mismatch::<Self>(&v)),
        }
    }
}

/// Ratio component (0% - 100%).
pub struct RatioComponent(pub f32);
impl FromValue for RatioComponent {
    fn describe() -> String {
        "ratio".into()
    }
    fn from_value(v: Value) -> std::result::Result<Self, String> {
        match v {
            Value::Ratio(r) => {
                if !(0.0..=1.0).contains(&r) {
                    return Err("ratio must be between 0% and 100%".into());
                }
                Ok(RatioComponent(r as f32))
            }
            v => Err(mismatch::<Self>(&v)),
        }
    }
}

/// Float or ratio (for oklab a/b and chroma).
pub struct ChromaComponent(pub f32);
impl FromValue for ChromaComponent {
    fn describe() -> String {
        "float or ratio".into()
    }
    fn from_value(v: Value) -> std::result::Result<Self, String> {
        match v {
            Value::Int(i) => Ok(ChromaComponent(i as f32)),
            Value::Float(f) => Ok(ChromaComponent(f as f32)),
            Value::Ratio(r) => Ok(ChromaComponent(r as f32 * 0.4)),
            v => Err(mismatch::<Self>(&v)),
        }
    }
}

fn luma(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let l: Component = args.expect("gray")?;
    let a: Option<Component> = args.eat()?;
    Ok(Value::Color(Color::Luma(l.0, a.map(|a| a.0).unwrap_or(1.0))))
}

fn oklab(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let l: RatioComponent = args.expect("lightness")?;
    let a: ChromaComponent = args.expect("a")?;
    let b: ChromaComponent = args.expect("b")?;
    let alpha: Option<Component> = args.eat()?;
    Ok(Value::Color(Color::Oklab(l.0, a.0, b.0, alpha.map(|a| a.0).unwrap_or(1.0))))
}

fn oklch(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let l: RatioComponent = args.expect("lightness")?;
    let c: ChromaComponent = args.expect("chroma")?;
    let h: Angle = args.expect("hue")?;
    let alpha: Option<Component> = args.eat()?;
    Ok(Value::Color(Color::Oklch(l.0, c.0, h.0.to_degrees() as f32, alpha.map(|a| a.0).unwrap_or(1.0))))
}

fn rgb(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    // Either a hex string or components.
    if let Some(first) = args.items.iter().position(|a| a.name.is_none()) {
        if let Value::Str(_) = &args.items[first].value {
            let s: Spanned<String> = args.expect_spanned("hex")?;
            let c = Color::from_hex(&s.v).map_err(|e| vec![crate::eval::vm::SourceDiagnostic::error(s.span, e)])?;
            return Ok(Value::Color(c));
        }
    }
    let r: Component = args.expect("red component")?;
    let g: Component = args.expect("green component")?;
    let b: Component = args.expect("blue component")?;
    let a: Option<Component> = args.eat()?;
    Ok(Value::Color(Color::Rgb(r.0, g.0, b.0, a.map(|a| a.0).unwrap_or(1.0))))
}

fn linear_rgb(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let r: Component = args.expect("red component")?;
    let g: Component = args.expect("green component")?;
    let b: Component = args.expect("blue component")?;
    let a: Option<Component> = args.eat()?;
    Ok(Value::Color(Color::LinearRgb(r.0, g.0, b.0, a.map(|a| a.0).unwrap_or(1.0))))
}

fn cmyk(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let c: RatioComponent = args.expect("cyan component")?;
    let m: RatioComponent = args.expect("magenta component")?;
    let y: RatioComponent = args.expect("yellow component")?;
    let k: RatioComponent = args.expect("key component")?;
    Ok(Value::Color(Color::Cmyk(c.0, m.0, y.0, k.0)))
}

fn hsl(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let h: Angle = args.expect("hue")?;
    let s: Component = args.expect("saturation")?;
    let l: Component = args.expect("lightness")?;
    let a: Option<Component> = args.eat()?;
    Ok(Value::Color(Color::Hsl(h.0.to_degrees() as f32, s.0, l.0, a.map(|a| a.0).unwrap_or(1.0))))
}

fn hsv(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let h: Angle = args.expect("hue")?;
    let s: Component = args.expect("saturation")?;
    let v: Component = args.expect("value")?;
    let a: Option<Component> = args.eat()?;
    Ok(Value::Color(Color::Hsv(h.0.to_degrees() as f32, s.0, v.0, a.map(|a| a.0).unwrap_or(1.0))))
}

pub fn cast_space(v: &Value) -> std::result::Result<Space, String> {
    match v {
        Value::Func(f) => match f.name().as_deref() {
            Some("luma") => Ok(Space::Luma),
            Some("oklab") => Ok(Space::Oklab),
            Some("oklch") => Ok(Space::Oklch),
            Some("rgb") => Ok(Space::Rgb),
            Some("linear-rgb") => Ok(Space::LinearRgb),
            Some("cmyk") => Ok(Space::Cmyk),
            Some("hsl") => Ok(Space::Hsl),
            Some("hsv") => Ok(Space::Hsv),
            _ => Err("expected `rgb`, `luma`, `cmyk`, `oklab`, `oklch`, `color.linear-rgb`, `color.hsl`, or `color.hsv`".into()),
        },
        _ => Err(format!("expected `rgb`, `luma`, `cmyk`, `oklab`, `oklch`, `color.linear-rgb`, `color.hsl`, or `color.hsv`, found {}", v.ty().long_name())),
    }
}

fn space_arg(args: &mut Args, default: Space) -> Result<Space> {
    match args.take_named("space") {
        Some(a) => cast_space(&a.value).map_err(|e| vec![crate::eval::vm::SourceDiagnostic::error(a.value_span, e)]),
        None => Ok(default),
    }
}

/// Weighted color for mixing.
fn weighted(v: &Value, span: Span) -> Result<(Color, f32)> {
    match v {
        Value::Color(c) => Ok((*c, 1.0)),
        Value::Array(a) if a.len() == 2 => {
            let c = match &a[0] {
                Value::Color(c) => *c,
                o => return bail(span, format!("expected color, found {}", o.ty().long_name())),
            };
            let w = match &a[1] {
                Value::Int(i) => *i as f32,
                Value::Float(f) => *f as f32,
                Value::Ratio(r) => *r as f32,
                o => return bail(span, format!("expected integer, float, or ratio, found {}", o.ty().long_name())),
            };
            Ok((c, w))
        }
        o => bail(span, format!("expected color or array, found {}", o.ty().long_name())),
    }
}

fn mix(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let space = space_arg(args, Space::Oklab)?;
    let colors: Vec<Spanned<Value>> = args.all_spanned()?;
    let mut ws = Vec::new();
    for c in colors {
        ws.push(weighted(&c.v, c.span)?);
    }
    Ok(Value::Color(Color::mix(&ws, space)))
}

pub fn color_ctor(_vm: &mut Vm, _args: &mut Args, span: Span) -> Result<Value> {
    bail(span, "type color does not have a constructor")
}

pub fn tiling_ctor(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let _: Value = args.expect("body")?;
    let _ = args.named::<Value>("size")?;
    let _ = args.named::<Value>("spacing")?;
    let _ = args.named::<Value>("relative")?;
    Ok(Value::dynamic(Dynamic::Tiling))
}

pub fn method(_vm: &mut Vm, c: Color, method: &str, args: &mut Args, span: Span) -> Option<Result<Value>> {
    let r: Result<Value> = match method {
        "space" => Ok(Value::Func(Func::native(c.space().name_short(), noop))),
        "to-hex" => Ok(Value::str(c.to_hex())),
        "components" => (|| {
            let alpha: bool = args.named("alpha")?.unwrap_or(true);
            Ok(Value::array(c.components(alpha)))
        })(),
        "luma" => Ok(Value::Color(c.to_space(Space::Luma))),
        "oklab" => Ok(Value::Color(c.to_space(Space::Oklab))),
        "oklch" => Ok(Value::Color(c.to_space(Space::Oklch))),
        "rgb" => Ok(Value::Color(c.to_space(Space::Rgb))),
        "linear-rgb" => Ok(Value::Color(c.to_space(Space::LinearRgb))),
        "cmyk" => Ok(Value::Color(c.to_space(Space::Cmyk))),
        "hsl" => Ok(Value::Color(c.to_space(Space::Hsl))),
        "hsv" => Ok(Value::Color(c.to_space(Space::Hsv))),
        "lighten" => (|| {
            let f: Ratio = args.expect("factor")?;
            Ok(Value::Color(c.lighten(f.0 as f32)))
        })(),
        "darken" => (|| {
            let f: Ratio = args.expect("factor")?;
            Ok(Value::Color(c.darken(f.0 as f32)))
        })(),
        "saturate" => (|| {
            let f: Ratio = args.expect("factor")?;
            let space = if matches!(c.space(), Space::Hsl | Space::Hsv) { c.space() } else { Space::Hsv };
            Ok(Value::Color(c.saturate(f.0 as f32, space)))
        })(),
        "desaturate" => (|| {
            let f: Ratio = args.expect("factor")?;
            let space = if matches!(c.space(), Space::Hsl | Space::Hsv) { c.space() } else { Space::Hsv };
            Ok(Value::Color(c.desaturate(f.0 as f32, space)))
        })(),
        "negate" => (|| {
            let space = space_arg(args, c.space())?;
            Ok(Value::Color(c.negate(space)))
        })(),
        "rotate" => (|| {
            let a: Angle = args.expect("angle")?;
            let space = space_arg(args, Space::Oklch)?;
            Ok(Value::Color(c.rotate(a.0.to_degrees() as f32, space)))
        })(),
        "mix" => (|| {
            let space = space_arg(args, Space::Oklab)?;
            let others: Vec<Spanned<Value>> = args.all_spanned()?;
            let mut ws = vec![(c, 1.0)];
            for o in others {
                ws.push(weighted(&o.v, o.span)?);
            }
            Ok(Value::Color(Color::mix(&ws, space)))
        })(),
        "transparentize" => (|| {
            let f: Ratio = args.expect("scale")?;
            let a = c.alpha().unwrap_or(1.0);
            Ok(Value::Color(c.with_alpha((a - a * f.0 as f32).clamp(0.0, 1.0))))
        })(),
        "opacify" => (|| {
            let f: Ratio = args.expect("scale")?;
            let a = c.alpha().unwrap_or(1.0);
            Ok(Value::Color(c.with_alpha((a + (1.0 - a) * f.0 as f32).clamp(0.0, 1.0))))
        })(),
        _ => {
            let _ = span;
            return None;
        }
    };
    Some(r)
}

fn noop(_vm: &mut Vm, _args: &mut Args, span: Span) -> Result<Value> {
    bail(span, "cannot call this function")
}

impl Space {
    pub fn name_short(self) -> &'static str {
        match self {
            Space::Luma => "luma",
            Space::Oklab => "oklab",
            Space::Oklch => "oklch",
            Space::Rgb => "rgb",
            Space::LinearRgb => "linear-rgb",
            Space::Cmyk => "cmyk",
            Space::Hsl => "hsl",
            Space::Hsv => "hsv",
        }
    }
}

fn stops(args: &mut Args) -> Result<Vec<(Color, f64)>> {
    let items: Vec<Spanned<Value>> = args.all_spanned()?;
    let mut raw: Vec<(Color, Option<f64>)> = Vec::new();
    for item in items {
        match &item.v {
            Value::Color(c) => raw.push((*c, None)),
            Value::Array(a) if a.len() == 2 => {
                let c = match &a[0] {
                    Value::Color(c) => *c,
                    o => return bail(item.span, format!("expected color, found {}", o.ty().long_name())),
                };
                let r = match &a[1] {
                    Value::Ratio(r) => *r,
                    o => return bail(item.span, format!("expected ratio, found {}", o.ty().long_name())),
                };
                raw.push((c, Some(r)));
            }
            o => return bail(item.span, format!("expected color or array, found {}", o.ty().long_name())),
        }
    }
    if raw.len() < 2 {
        return bail(args.span, "a gradient must have at least two stops");
    }
    let n = raw.len();
    let out: Vec<(Color, f64)> = raw
        .into_iter()
        .enumerate()
        .map(|(i, (c, r))| (c, r.unwrap_or(i as f64 / (n - 1) as f64)))
        .collect();
    Ok(out)
}

fn gradient_common(args: &mut Args, kind: &'static str) -> Result<(Vec<(Color, f64)>, &'static str, Value)> {
    let space = space_arg(args, Space::Oklab)?;
    let relative: Value = args.named("relative")?.unwrap_or(Value::Auto);
    let stops = stops(args)?;
    let _ = kind;
    Ok((stops, space.name(), relative))
}

fn gradient_linear(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let angle: Option<Value> = args.named("angle")?;
    let dir: Option<Value> = args.named("dir")?;
    let (stops, space, relative) = gradient_common(args, "linear")?;
    let angle = match (angle, dir) {
        (Some(Value::Angle(a)), _) => a,
        (_, Some(Value::Dyn(d))) => match &*d {
            Dynamic::Direction(Direction::Ltr) => 0.0,
            Dynamic::Direction(Direction::Rtl) => std::f64::consts::PI,
            Dynamic::Direction(Direction::Ttb) => std::f64::consts::FRAC_PI_2,
            Dynamic::Direction(Direction::Btt) => -std::f64::consts::FRAC_PI_2,
            _ => 0.0,
        },
        _ => 0.0,
    };
    Ok(Value::Gradient(Rc::new(Gradient { kind: "linear", stops, space, relative, angle, extra: vec![] })))
}

fn gradient_radial(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let mut extra = Vec::new();
    for name in ["center", "radius", "focal-center", "focal-radius"] {
        if let Some(v) = args.named::<Value>(name)? {
            extra.push((name.to_string(), v));
        }
    }
    let (stops, space, relative) = gradient_common(args, "radial")?;
    Ok(Value::Gradient(Rc::new(Gradient { kind: "radial", stops, space, relative, angle: 0.0, extra })))
}

fn gradient_conic(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let mut extra = Vec::new();
    if let Some(v) = args.named::<Value>("angle")? {
        extra.push(("angle".to_string(), v));
    }
    if let Some(v) = args.named::<Value>("center")? {
        extra.push(("center".to_string(), v));
    }
    let (stops, space, relative) = gradient_common(args, "conic")?;
    Ok(Value::Gradient(Rc::new(Gradient { kind: "conic", stops, space, relative, angle: 0.0, extra })))
}

pub fn gradient_method(_vm: &mut Vm, g: &Rc<Gradient>, method: &str, args: &mut Args, _span: Span) -> Option<Result<Value>> {
    let r: Result<Value> = match method {
        "kind" => Ok(Value::Func(Func::native(g.kind, noop))),
        "stops" => Ok(Value::array(
            g.stops.iter().map(|(c, r)| Value::array(vec![Value::Color(*c), Value::Ratio(*r)])).collect(),
        )),
        "space" => Ok(Value::Func(Func::native(g.space.rsplit('.').next().unwrap_or(g.space), noop))),
        "relative" => Ok(g.relative.clone()),
        "angle" => Ok(if g.kind == "linear" { Value::Angle(g.angle) } else { Value::None }),
        "sample" => (|| {
            let t: Value = args.expect("t")?;
            let t = match t {
                Value::Ratio(r) => r,
                Value::Angle(a) => a / std::f64::consts::TAU,
                o => return bail(args.span, format!("expected ratio or angle, found {}", o.ty().long_name())),
            };
            Ok(Value::Color(sample(g, t)))
        })(),
        "samples" => (|| {
            let ts: Vec<Value> = args.all()?;
            let mut out = Vec::new();
            for t in ts {
                let t = match t {
                    Value::Ratio(r) => r,
                    Value::Angle(a) => a / std::f64::consts::TAU,
                    o => return bail(args.span, format!("expected ratio or angle, found {}", o.ty().long_name())),
                };
                out.push(Value::Color(sample(g, t)));
            }
            Ok(Value::array(out))
        })(),
        "sharp" => (|| {
            let steps: i64 = args.expect("steps")?;
            let smoothness: Option<Ratio> = args.named("smoothness")?;
            let _ = smoothness;
            let n = steps.max(1) as usize;
            let mut stops = Vec::new();
            for i in 0..n {
                let t = (i as f64 + 0.5) / n as f64;
                let c = sample(g, t);
                stops.push((c, i as f64 / n as f64));
                stops.push((c, (i + 1) as f64 / n as f64));
            }
            Ok(Value::Gradient(Rc::new(Gradient { stops, ..(**g).clone() })))
        })(),
        "repeat" => (|| {
            let repetitions: i64 = args.expect("repetitions")?;
            let mirror: bool = args.named("mirror")?.unwrap_or(false);
            let n = repetitions.max(1) as usize;
            let mut stops = Vec::new();
            for i in 0..n {
                let mut part = g.stops.clone();
                if mirror && i % 2 == 1 {
                    part.reverse();
                    for s in &mut part {
                        s.1 = 1.0 - s.1;
                    }
                }
                for (c, r) in part {
                    stops.push((c, (i as f64 + r) / n as f64));
                }
            }
            Ok(Value::Gradient(Rc::new(Gradient { stops, ..(**g).clone() })))
        })(),
        _ => return None,
    };
    Some(r)
}

fn sample(g: &Gradient, t: f64) -> Color {
    let t = t.clamp(0.0, 1.0);
    let space = match g.space {
        "luma" => Space::Luma,
        "oklab" => Space::Oklab,
        "oklch" => Space::Oklch,
        "rgb" => Space::Rgb,
        "color.linear-rgb" => Space::LinearRgb,
        "cmyk" => Space::Cmyk,
        "color.hsl" => Space::Hsl,
        "color.hsv" => Space::Hsv,
        _ => Space::Oklab,
    };
    let mut prev = &g.stops[0];
    for stop in &g.stops {
        if stop.1 >= t {
            if stop.1 == prev.1 {
                return stop.0.to_space(space);
            }
            let f = ((t - prev.1) / (stop.1 - prev.1)) as f32;
            return Color::mix(&[(prev.0, 1.0 - f), (stop.0, f)], space);
        }
        prev = stop;
    }
    g.stops.last().unwrap().0.to_space(space)
}

#[allow(dead_code)]
fn unused() -> Value {
    func_scoped("x", noop, Scope::new())
}
