pub fn method(_vm: &mut Vm, c: Color, method: &str, args: &mut Args, span: Span) -> Option<Result<Value>> {
    let r: Result<Value> = match method {
        "space" => Ok(Value::Func(Func::native(c.space().name_short(), noop))),
        "to-hex" => Ok(Value::str(c.to_hex())),
        "components" => (|| {
            let alpha: bool = args.named("alpha")?.unwrap_or(true);
            Ok(Value::array(c.components(alpha)))
        })(),
        "luma" => Ok(Value::Color(c.to_space(Space::Luma))),
        "oklab" => Ok(Value::Color(c.to_space(Space::Oklab))),
        "oklch" => Ok(Value::Color(c.to_space(Space::Oklch))),
        "rgb" => Ok(Value::Color(c.to_space(Space::Rgb))),
        "linear-rgb" => Ok(Value::Color(c.to_space(Space::LinearRgb))),
        "cmyk" => Ok(Value::Color(c.to_space(Space::Cmyk))),
        "hsl" => Ok(Value::Color(c.to_space(Space::Hsl))),
        "hsv" => Ok(Value::Color(c.to_space(Space::Hsv))),
        "lighten" => (|| {
            let f: Ratio = args.expect("factor")?;
            Ok(Value::Color(c.lighten(f.0 as f32)))
        })(),
        "darken" => (|| {
            let f: Ratio = args.expect("factor")?;
            Ok(Value::Color(c.darken(f.0 as f32)))
        })(),
        "saturate" => (|| {
            let f: Ratio = args.expect("factor")?;
            let space = if matches!(c.space(), Space::Hsl | Space::Hsv) { c.space() } else { Space::Hsv };
            Ok(Value::Color(c.saturate(f.0 as f32, space)))
        })(),
        "desaturate" => (|| {
            let f: Ratio = args.expect("factor")?;
            let space = if matches!(c.space(), Space::Hsl | Space::Hsv) { c.space() } else { Space::Hsv };
            Ok(Value::Color(c.desaturate(f.0 as f32, space)))
        })(),
        "negate" => (|| {
            let space = space_arg(args, c.space())?;
            Ok(Value::Color(c.negate(space)))
        })(),
        "rotate" => (|| {
            let a: Angle = args.expect("angle")?;
            let space = space_arg(args, Space::Oklch)?;
            Ok(Value::Color(c.rotate(a.0.to_degrees() as f32, space)))
        })(),
        "mix" => (|| {
            let space = space_arg(args, Space::Oklab)?;
            let others: Vec<Spanned<Value>> = args.all_spanned()?;
            let mut ws = vec![(c, 1.0)];
            for o in others {
                ws.push(weighted(&o.v, o.span)?);
            }
            Ok(Value::Color(Color::mix(&ws, space)))
        })(),
        "transparentize" => (|| {
            let f: Ratio = args.expect("scale")?;
            let a = c.alpha().unwrap_or(1.0);
            Ok(Value::Color(c.with_alpha((a - a * f.0 as f32).clamp(0.0, 1.0))))
        })(),
        "opacify" => (|| {
            let f: Ratio = args.expect("scale")?;
            let a = c.alpha().unwrap_or(1.0);
            Ok(Value::Color(c.with_alpha((a + (1.0 - a) * f.0 as f32).clamp(0.0, 1.0))))
        })(),
        _ => {
            let _ = span;
            return None;
        }
    };
    Some(r)
}

fn noop(_vm: &mut Vm, _args: &mut Args, span: Span) -> Result<Value> {
    bail(span, "cannot call this function")
}

impl Space {
    pub fn name_short(self) -> &'static str {
        match self {
            Space::Luma => "luma",
            Space::Oklab => "oklab",
            Space::Oklch => "oklch",
            Space::Rgb => "rgb",
            Space::LinearRgb => "linear-rgb",
            Space::Cmyk => "cmyk",
            Space::Hsl => "hsl",
            Space::Hsv => "hsv",
        }
    }
}

fn stops(args: &mut Args) -> Result<Vec<(Color, f64)>> {
    let items: Vec<Spanned<Value>> = args.all_spanned()?;
    let mut raw: Vec<(Color, Option<f64>)> = Vec::new();
    for item in items {
        match &item.v {
            Value::Color(c) => raw.push((*c, None)),
            Value::Array(a) if a.len() == 2 => {
                let c = match &a[0] {
                    Value::Color(c) => *c,
                    o => return bail(item.span, format!("expected color, found {}", o.ty().long_name())),
                };
                let r = match &a[1] {
                    Value::Ratio(r) => *r,
                    o => return bail(item.span, format!("expected ratio, found {}", o.ty().long_name())),
                };
                raw.push((c, Some(r)));
            }
            o => return bail(item.span, format!("expected color or array, found {}", o.ty().long_name())),
        }
    }
    if raw.len() < 2 {
        return bail(args.span, "a gradient must have at least two stops");
    }
    let n = raw.len();
    let out: Vec<(Color, f64)> = raw
        .into_iter()
        .enumerate()
        .map(|(i, (c, r))| (c, r.unwrap_or(i as f64 / (n - 1) as f64)))
        .collect();
    Ok(out)
}

fn gradient_common(args: &mut Args, kind: &'static str) -> Result<(Vec<(Color, f64)>, &'static str, Value)> {
    let space = space_arg(args, Space::Oklab)?;
    let relative: Value = args.named("relative")?.unwrap_or(Value::Auto);
    let stops = stops(args)?;
    let _ = kind;
    Ok((stops, space.name(), relative))
}

fn gradient_linear(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let angle: Option<Value> = args.named("angle")?;
    let dir: Option<Value> = args.named("dir")?;
    let (stops, space, relative) = gradient_common(args, "linear")?;
    let angle = match (angle, dir) {
        (Some(Value::Angle(a)), _) => a,
        (_, Some(Value::Dyn(d))) => match &*d {
            Dynamic::Direction(Direction::Ltr) => 0.0,
            Dynamic::Direction(Direction::Rtl) => std::f64::consts::PI,
            Dynamic::Direction(Direction::Ttb) => std::f64::consts::FRAC_PI_2,
            Dynamic::Direction(Direction::Btt) => -std::f64::consts::FRAC_PI_2,
            _ => 0.0,
        },
        _ => 0.0,
    };
    Ok(Value::Gradient(Rc::new(Gradient { kind: "linear", stops, space, relative, angle, extra: vec![] })))
}

fn gradient_radial(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let mut extra = Vec::new();
    for name in ["center", "radius", "focal-center", "focal-radius"] {
        if let Some(v) = args.named::<Value>(name)? {
            extra.push((name.to_string(), v));
        }
    }
    let (stops, space, relative) = gradient_common(args, "radial")?;
    Ok(Value::Gradient(Rc::new(Gradient { kind: "radial", stops, space, relative, angle: 0.0, extra })))
}

fn gradient_conic(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let mut extra = Vec::new();
    if let Some(v) = args.named::<Value>("angle")? {
        extra.push(("angle".to_string(), v));
    }
    if let Some(v) = args.named::<Value>("center")? {
        extra.push(("center".to_string(), v));
    }
    let (stops, space, relative) = gradient_common(args, "conic")?;
    Ok(Value::Gradient(Rc::new(Gradient { kind: "conic", stops, space, relative, angle: 0.0, extra })))
}

pub fn gradient_method(_vm: &mut Vm, g: &Rc<Gradient>, method: &str, args: &mut Args, _span: Span) -> Option<Result<Value>> {
    let r: Result<Value> = match method {
        "kind" => Ok(Value::Func(Func::native(g.kind, noop))),
        "stops" => Ok(Value::array(
            g.stops.iter().map(|(c, r)| Value::array(vec![Value::Color(*c), Value::Ratio(*r)])).collect(),
        )),
        "space" => Ok(Value::Func(Func::native(g.space.rsplit('.').next().unwrap_or(g.space), noop))),
        "relative" => Ok(g.relative.clone()),
        "angle" => Ok(if g.kind == "linear" { Value::Angle(g.angle) } else { Value::None }),
        "sample" => (|| {
            let t: Value = args.expect("t")?;
            let t = match t {
                Value::Ratio(r) => r,
                Value::Angle(a) => a / std::f64::consts::TAU,
                o => return bail(args.span, format!("expected ratio or angle, found {}", o.ty().long_name())),
            };
            Ok(Value::Color(sample(g, t)))
        })(),
        "samples" => (|| {
            let ts: Vec<Value> = args.all()?;
            let mut out = Vec::new();
            for t in ts {
                let t = match t {
                    Value::Ratio(r) => r,
                    Value::Angle(a) => a / std::f64::consts::TAU,
                    o => return bail(args.span, format!("expected ratio or angle, found {}", o.ty().long_name())),
                };
                out.push(Value::Color(sample(g, t)));
            }
            Ok(Value::array(out))
        })(),
        "sharp" => (|| {
            let steps: i64 = args.expect("steps")?;
            let smoothness: Option<Ratio> = args.named("smoothness")?;
            let _ = smoothness;
            let n = steps.max(1) as usize;
            let mut stops = Vec::new();
            for i in 0..n {
                let t = (i as f64 + 0.5) / n as f64;
                let c = sample(g, t);
                stops.push((c, i as f64 / n as f64));
                stops.push((c, (i + 1) as f64 / n as f64));
            }
            Ok(Value::Gradient(Rc::new(Gradient { stops, ..(**g).clone() })))
        })(),
        "repeat" => (|| {
            let repetitions: i64 = args.expect("repetitions")?;
            let mirror: bool = args.named("mirror")?.unwrap_or(false);
            let n = repetitions.max(1) as usize;
            let mut stops = Vec::new();
            for i in 0..n {
                let mut part = g.stops.clone();
                if mirror && i % 2 == 1 {
                    part.reverse();
                    for s in &mut part {
                        s.1 = 1.0 - s.1;
                    }
                }
                for (c, r) in part {
                    stops.push((c, (i as f64 + r) / n as f64));
                }
            }
            Ok(Value::Gradient(Rc::new(Gradient { stops, ..(**g).clone() })))
        })(),
        _ => return None,
    };
    Some(r)
}

fn sample(g: &Gradient, t: f64) -> Color {
    let t = t.clamp(0.0, 1.0);
    let space = match g.space {
        "luma" => Space::Luma,
        "oklab" => Space::Oklab,
        "oklch" => Space::Oklch,
        "rgb" => Space::Rgb,
        "color.linear-rgb" => Space::LinearRgb,
        "cmyk" => Space::Cmyk,
        "color.hsl" => Space::Hsl,
        "color.hsv" => Space::Hsv,
        _ => Space::Oklab,
    };
    let mut prev = &g.stops[0];
    for stop in &g.stops {
        if stop.1 >= t {
            if stop.1 == prev.1 {
                return stop.0.to_space(space);
            }
            let f = ((t - prev.1) / (stop.1 - prev.1)) as f32;
            return Color::mix(&[(prev.0, 1.0 - f), (stop.0, f)], space);
        }
        prev = stop;
    }
    g.stops.last().unwrap().0.to_space(space)
}

