    let mut toml_scope = Scope::new();
    toml_scope.define("decode", deprecated_func("decode", toml_decode, "`toml.decode` is deprecated, directly pass bytes to `toml` instead"));
    toml_scope.define("encode", func("encode", toml_encode));
    s.define("toml", func_scoped("toml", toml_fn, toml_scope));

    let mut csv_scope = Scope::new();
    csv_scope.define("decode", deprecated_func("decode", csv_decode, "`csv.decode` is deprecated, directly pass bytes to `csv` instead"));
    s.define("csv", func_scoped("csv", csv, csv_scope));

    let mut xml_scope = Scope::new();
    xml_scope.define("decode", deprecated_func("decode", xml_decode, "`xml.decode` is deprecated, directly pass bytes to `xml` instead"));
    s.define("xml", func_scoped("xml", xml, xml_scope));

    let mut cbor_scope = Scope::new();
    cbor_scope.define("decode", deprecated_func("decode", cbor_decode, "`cbor.decode` is deprecated, directly pass bytes to `cbor` instead"));
    cbor_scope.define("encode", func("encode", cbor_encode));
    s.define("cbor", func_scoped("cbor", cbor, cbor_scope));

    s.define("read", func("read", read));
}

fn deprecated_func(name: &'static str, f: NativeFn, msg: &'static str) -> Value {
    Value::Func(Func::Native(Rc::new(NativeFunc {
        name,
        func: f,
        scope: Scope::new(),
        contextual: false,
        deprecation: Some(msg),
    })))
}

/// Data source: path string or bytes.
pub enum DataSource {
    Path(String),
    Bytes(Rc<Vec<u8>>),
}

impl FromValue for DataSource {
    fn describe() -> String {
        "path or bytes".into()
    }
    fn from_value(v: Value) -> std::result::Result<Self, String> {
        match v {
            Value::Str(s) => Ok(DataSource::Path(s.to_string())),
            Value::Bytes(b) => Ok(DataSource::Bytes(b)),
            v => Err(mismatch::<Self>(&v)),
        }
    }
}

fn load(vm: &mut Vm, source: Spanned<DataSource>) -> Result<Vec<u8>> {
    match source.v {
        DataSource::Bytes(b) => Ok((*b).clone()),
        DataSource::Path(p) => vm.world.read_file(vm.file, &p, source.span),
    }
}

fn load_str(vm: &mut Vm, args: &mut Args, what: &str) -> Result<(String, Span)> {
    let source: Spanned<DataSource> = args.expect_spanned(what)?;
    let span = source.span;
    let bytes = load(vm, source)?;
    match String::from_utf8(bytes) {
        Ok(s) => Ok((s, span)),
        Err(_) => bail(span, "file is not valid utf-8"),
    }
}

// --------------------------------------------------------------- JSON

pub fn json_to_value(v: &serde_json::Value) -> Value {
    match v {
        serde_json::Value::Null => Value::None,
        serde_json::Value::Bool(b) => Value::Bool(*b),
        serde_json::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Value::Int(i)
            } else {
                Value::Float(n.as_f64().unwrap_or(0.0))
            }
        }
        serde_json::Value::String(s) => Value::str(s.clone()),
        serde_json::Value::Array(a) => Value::array(a.iter().map(json_to_value).collect()),
        serde_json::Value::Object(o) => {
            let mut d: Dict = IndexMap::new();
            for (k, v) in o {
                d.insert(k.clone(), json_to_value(v));
            }
            Value::dict(d)
        }
    }
}

fn parse_json(text: &str, span: Span) -> Result<Value> {
    match serde_json::from_str::<serde_json::Value>(text) {
        Ok(v) => Ok(json_to_value(&v)),
        Err(e) => bail(
            span,
            format!("failed to parse JSON ({} at {}:{})", e.to_string(), e.line(), e.column()),
        ),
    }
}

fn json(vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let (text, span) = load_str(vm, args, "source")?;
    parse_json(&text, span)
}

fn json_decode(vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let (text, span) = load_str(vm, args, "data")?;
    parse_json(&text, span)
}

fn json_encode(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: Value = args.expect("value")?;
    let pretty: bool = args.named("pretty")?.unwrap_or(true);
    let s = if pretty {
        serde_json::to_string_pretty(&v).unwrap_or_default()
    } else {
        serde_json::to_string(&v).unwrap_or_default()
    };
    Ok(Value::str(s))
}

// --------------------------------------------------------------- YAML

fn yaml_to_value(v: &serde_yaml::Value) -> Value {
    match v {
        serde_yaml::Value::Null => Value::None,
        serde_yaml::Value::Bool(b) => Value::Bool(*b),
        serde_yaml::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Value::Int(i)
            } else {
                Value::Float(n.as_f64().unwrap_or(0.0))
            }
        }
        serde_yaml::Value::String(s) => Value::str(s.clone()),
        serde_yaml::Value::Sequence(a) => Value::array(a.iter().map(yaml_to_value).collect()),
        serde_yaml::Value::Mapping(m) => {
            let mut d: Dict = IndexMap::new();
            for (k, v) in m {
                let key = match k {
                    serde_yaml::Value::String(s) => s.clone(),
                    serde_yaml::Value::Number(n) => n.to_string(),
                    serde_yaml::Value::Bool(b) => b.to_string(),
                    serde_yaml::Value::Null => "null".into(),
                    other => format!("{other:?}"),
                };
                d.insert(key, yaml_to_value(v));
            }
            Value::dict(d)
        }
        serde_yaml::Value::Tagged(t) => yaml_to_value(&t.value),
    }
}

fn parse_yaml(text: &str, span: Span) -> Result<Value> {
    match serde_yaml::from_str::<serde_yaml::Value>(text) {
        Ok(v) => Ok(yaml_to_value(&v)),
        Err(e) => bail(span, format!("failed to parse YAML ({e})")),
    }
}

fn yaml(vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let (text, span) = load_str(vm, args, "source")?;
    parse_yaml(&text, span)
}

fn yaml_decode(vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let (text, span) = load_str(vm, args, "data")?;
    parse_yaml(&text, span)
}

fn yaml_encode(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let v: Value = args.expect("value")?;
    Ok(Value::str(serde_yaml::to_string(&v).unwrap_or_default()))
}

// --------------------------------------------------------------- TOML

fn toml_to_value(v: &toml::Value) -> Value {
    match v {
        toml::Value::String(s) => Value::str(s.clone()),
        toml::Value::Integer(i) => Value::Int(*i),
        toml::Value::Float(f) => Value::Float(*f),
        toml::Value::Boolean(b) => Value::Bool(*b),
        toml::Value::Datetime(d) => {
            let date = d.date.map(|d| (d.year as i32, d.month, d.day));
            let time = d.time.map(|t| (t.hour, t.minute, t.second));
            if date.is_none() && time.is_none() {
                Value::str(d.to_string())
            } else {
                Value::Datetime(crate::eval::datetime::Datetime { date, time })
            }
        }
        toml::Value::Array(a) => Value::array(a.iter().map(toml_to_value).collect()),
        toml::Value::Table(t) => {
            let mut d: Dict = IndexMap::new();
            for (k, v) in t {
                d.insert(k.clone(), toml_to_value(v));
            }
            Value::dict(d)
        }
    }
}

fn parse_toml(text: &str, span: Span) -> Result<Value> {
    match text.parse::<toml::Value>() {
        Ok(v) => Ok(toml_to_value(&v)),
        Err(e) => {
            let msg = e.message().to_string();
            match e.span() {
                Some(r) => {
                    let line = text[..r.start.min(text.len())].matches('\n').count() + 1;
                    let col = text[..r.start.min(text.len())].rsplit('\n').next().map(|l| l.chars().count()).unwrap_or(0) + 1;
                    bail(span, format!("failed to parse TOML ({msg} at {line}:{col})"))
                }
                None => bail(span, format!("failed to parse TOML ({msg})")),
            }
        }
    }
}

fn toml_fn(vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let (text, span) = load_str(vm, args, "source")?;
    parse_toml(&text, span)
}

fn toml_decode(vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let (text, span) = load_str(vm, args, "data")?;
    parse_toml(&text, span)
}

fn value_to_toml(v: &Value) -> std::result::Result<toml::Value, String> {
    Ok(match v {
        Value::None => return Err("cannot convert none to TOML".into()),
        Value::Bool(b) => toml::Value::Boolean(*b),
        Value::Int(i) => toml::Value::Integer(*i),
        Value::Float(f) => toml::Value::Float(*f),
        Value::Str(s) => toml::Value::String(s.to_string()),
        Value::Array(a) => toml::Value::Array(a.iter().map(value_to_toml).collect::<std::result::Result<_, _>>()?),
        Value::Dict(d) => {
            let mut t = toml::map::Map::new();
            for (k, v) in d.iter() {
                t.insert(k.clone(), value_to_toml(v)?);
            }
            toml::Value::Table(t)
        }
        other => toml::Value::String(crate::eval::repr::repr(other)),
    })
}

fn toml_encode(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let v: Value = args.expect("value")?;
    let pretty: bool = args.named("pretty")?.unwrap_or(true);
    let t = value_to_toml(&v).map_err(|e| vec![SourceDiagnostic::error(span, format!("failed to encode value as TOML ({e})"))])?;
    let s = if pretty { toml::to_string_pretty(&t) } else { toml::to_string(&t) };
    match s {
        Ok(s) => Ok(Value::str(s)),
        Err(e) => bail(span, format!("failed to encode value as TOML ({e})")),
    }
}

// ---------------------------------------------------------------- CSV

fn parse_csv(text: &str, delimiter: char, row_type: &str, span: Span) -> Result<Value> {
    let mut rows: Vec<Vec<String>> = Vec::new();
    let mut row: Vec<String> = Vec::new();
    let mut field = String::new();
    let mut in_quotes = false;
    let mut chars = text.chars().peekable();
    let mut any = false;
    while let Some(c) = chars.next() {
        any = true;
        if in_quotes {
            if c == '"' {
                if chars.peek() == Some(&'"') {
                    chars.next();
                    field.push('"');
                } else {
                    in_quotes = false;
                }
            } else {
                field.push(c);
            }
        } else if c == '"' {
            in_quotes = true;
        } else if c == delimiter {
            row.push(std::mem::take(&mut field));
        } else if c == '\n' || c == '\r' {
            if c == '\r' && chars.peek() == Some(&'\n') {
                chars.next();
            }
            row.push(std::mem::take(&mut field));
            rows.push(std::mem::take(&mut row));
        } else {
            field.push(c);
        }
    }
    if !field.is_empty() || !row.is_empty() {
        row.push(field);
        rows.push(row);
    }
    let _ = any;
    if row_type == "dictionary" {
        let mut iter = rows.into_iter();
        let header = iter.next().unwrap_or_default();
        let mut out = Vec::new();
        for (i, r) in iter.enumerate() {
            if r.len() != header.len() {
                return bail(
                    span,
                    format!("failed to parse CSV (found record with {} fields, but the previous record has {} fields at line {})", r.len(), header.len(), i + 2),
                );
            }
            let mut d: Dict = IndexMap::new();
            for (k, v) in header.iter().zip(r) {
                d.insert(k.clone(), Value::str(v));
            }
            out.push(Value::dict(d));
        }
        Ok(Value::array(out))
    } else {
        let mut width = None;
        let mut out = Vec::new();
        for (i, r) in rows.into_iter().enumerate() {
            if let Some(w) = width {
                if r.len() != w {
                    return bail(
                        span,
                        format!("failed to parse CSV (found record with {} fields, but the previous record has {} fields at line {})", r.len(), w, i + 1),
                    );
                }
            }
            width = Some(r.len());
            out.push(Value::array(r.into_iter().map(Value::str).collect()));
        }
        Ok(Value::array(out))
    }
}

fn csv_common(vm: &mut Vm, args: &mut Args, what: &str) -> Result<Value> {
    let (text, span) = load_str(vm, args, what)?;
    let delimiter: Option<Spanned<String>> = args.named_spanned("delimiter")?;
    let delimiter = match delimiter {
        Some(d) => {
            let mut cs = d.v.chars();
            match (cs.next(), cs.next()) {
                (Some(c), None) if c.is_ascii() => c,
                _ => return bail(d.span, "delimiter must be an ASCII character"),
            }
        }
        None => ',',
    };
    let row_type: Option<Spanned<Value>> = args.named_spanned("row-type")?;
    let row_type = match row_type {
        None => "array",
        Some(Spanned { v: Value::Type(Type::Array), .. }) => "array",
        Some(Spanned { v: Value::Type(Type::Dict), .. }) => "dictionary",
        Some(o) => return bail(o.span, format!("expected `array` or `dictionary`, found {}", crate::eval::repr::repr(&o.v))),
    };
    parse_csv(&text, delimiter, row_type, span)
}

fn csv(vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    csv_common(vm, args, "source")
}

fn csv_decode(vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    csv_common(vm, args, "data")
}

// ---------------------------------------------------------------- XML

struct XmlParser<'a> {
    s: &'a str,
    pos: usize,
}

impl<'a> XmlParser<'a> {
    fn peek(&self) -> Option<char> {
        self.s[self.pos..].chars().next()
    }
    fn starts(&self, p: &str) -> bool {
        self.s[self.pos..].starts_with(p)
    }
    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.pos += c.len_utf8();
            } else {
                break;
            }
        }
    }
    fn name(&mut self) -> String {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_alphanumeric() || matches!(c, '_' | '-' | ':' | '.') {
                self.pos += c.len_utf8();
            } else {
                break;
            }
        }
        self.s[start..self.pos].to_string()
    }
    fn parse_nodes(&mut self, close: Option<&str>) -> std::result::Result<Vec<Value>, String> {
        let mut out = Vec::new();
        let mut text = String::new();
        loop {
            if self.pos >= self.s.len() {
                if close.is_some() {
                    return Err("unexpected end of stream".into());
                }
                break;
            }
            if self.starts("</") {
                if !text.is_empty() {
                    out.push(Value::str(std::mem::take(&mut text)));
                }
                let save = self.pos;
                self.pos += 2;
                let n = self.name();
                self.skip_ws();
                if !self.starts(">") {
                    return Err("expected '>'".into());
                }
                self.pos += 1;
                if Some(n.as_str()) != close {
                    self.pos = save;
                    return Err(format!("unexpected closing tag"));
                }
                return Ok(out);
            } else if self.starts("<!--") {
                match self.s[self.pos..].find("-->") {
                    Some(i) => self.pos += i + 3,
                    None => return Err("unclosed comment".into()),
                }
            } else if self.starts("<?") {
                match self.s[self.pos..].find("?>") {
                    Some(i) => self.pos += i + 2,
                    None => return Err("unclosed processing instruction".into()),
                }
            } else if self.starts("<![CDATA[") {
                match self.s[self.pos..].find("]]>") {
                    Some(i) => {
                        text.push_str(&self.s[self.pos + 9..self.pos + i]);
                        self.pos += i + 3;
                    }
                    None => return Err("unclosed CDATA".into()),
                }
            } else if self.starts("<!") {
                match self.s[self.pos..].find('>') {
                    Some(i) => self.pos += i + 1,
                    None => return Err("unclosed declaration".into()),
                }
            } else if self.starts("<") {
                if !text.is_empty() {
                    out.push(Value::str(std::mem::take(&mut text)));
                }
                self.pos += 1;
                let tag = self.name();
                if tag.is_empty() {
                    return Err("expected element name".into());
                }
                let mut attrs: Dict = IndexMap::new();
                loop {
                    self.skip_ws();
                    if self.starts("/>") {
                        self.pos += 2;
                        out.push(element(&tag, attrs, vec![]));
                        break;
                    }
                    if self.starts(">") {
                        self.pos += 1;
                        let children = self.parse_nodes(Some(&tag))?;
                        out.push(element(&tag, attrs, children));
                        break;
                    }
                    let an = self.name();
                    if an.is_empty() {
                        return Err("expected attribute name".into());
                    }
                    self.skip_ws();
                    if !self.starts("=") {
                        return Err("expected '='".into());
                    }
                    self.pos += 1;
                    self.skip_ws();
                    let q = match self.peek() {
                        Some(q @ ('"' | '\'')) => q,
                        _ => return Err("expected quote".into()),
                    };
                    self.pos += 1;
                    let start = self.pos;
                    match self.s[self.pos..].find(q) {
                        Some(i) => {
                            let v = &self.s[start..start + i];
                            attrs.insert(an, Value::str(unescape(v)));
                            self.pos = start + i + 1;
                        }
                        None => return Err("unclosed attribute value".into()),
                    }
                }
            } else {
                let c = self.peek().unwrap();
                if c == '&' {
                    match self.s[self.pos..].find(';') {
                        Some(i) => {
                            let ent = &self.s[self.pos..self.pos + i + 1];
                            text.push_str(&unescape(ent));
                            self.pos += i + 1;
                        }
                        None => return Err("unclosed entity".into()),
                    }
                } else {
                    text.push(c);
                    self.pos += c.len_utf8();
                }
            }
        }
        if !text.is_empty() {
            out.push(Value::str(text));
        }
        Ok(out)
    }
}

fn unescape(s: &str) -> String {
    s.replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&quot;", "\"")
        .replace("&apos;", "'")
        .replace("&amp;", "&")
}

fn element(tag: &str, attrs: Dict, children: Vec<Value>) -> Value {
    let mut d: Dict = IndexMap::new();
    d.insert("tag".into(), Value::str(tag));
    d.insert("attrs".into(), Value::dict(attrs));
    d.insert("children".into(), Value::array(children));
    Value::dict(d)
}

fn parse_xml(text: &str, span: Span) -> Result<Value> {
    let mut p = XmlParser { s: text, pos: 0 };
    match p.parse_nodes(None) {
        Ok(nodes) => {
            let elems: Vec<Value> = nodes.into_iter().filter(|n| matches!(n, Value::Dict(_))).collect();
            Ok(Value::array(elems))
        }
        Err(e) => bail(span, format!("failed to parse XML ({e})")),
    }
}

fn xml(vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let (text, span) = load_str(vm, args, "source")?;
    parse_xml(&text, span)
}

fn xml_decode(vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let (text, span) = load_str(vm, args, "data")?;
    parse_xml(&text, span)
}

// --------------------------------------------------------------- CBOR

fn cbor_to_value(v: &ciborium::Value) -> Value {
    match v {
        ciborium::Value::Integer(i) => {
            let i: i128 = (*i).into();
            Value::Int(i as i64)
        }
        ciborium::Value::Bytes(b) => Value::Bytes(Rc::new(b.clone())),
        ciborium::Value::Float(f) => Value::Float(*f),
        ciborium::Value::Text(s) => Value::str(s.clone()),
        ciborium::Value::Bool(b) => Value::Bool(*b),
        ciborium::Value::Null => Value::None,
        ciborium::Value::Array(a) => Value::array(a.iter().map(cbor_to_value).collect()),
        ciborium::Value::Map(m) => {
            let mut d: Dict = IndexMap::new();
            for (k, v) in m {
                let key = match k {
                    ciborium::Value::Text(s) => s.clone(),
                    other => format!("{other:?}"),
                };
                d.insert(key, cbor_to_value(v));
            }
            Value::dict(d)
        }
        ciborium::Value::Tag(_, inner) => cbor_to_value(inner),
        _ => Value::None,
    }
}

fn value_to_cbor(v: &Value) -> ciborium::Value {
    match v {
        Value::None => ciborium::Value::Null,
        Value::Bool(b) => ciborium::Value::Bool(*b),
        Value::Int(i) => ciborium::Value::Integer((*i).into()),
        Value::Float(f) => ciborium::Value::Float(*f),
        Value::Str(s) => ciborium::Value::Text(s.to_string()),
        Value::Bytes(b) => ciborium::Value::Bytes((**b).clone()),
        Value::Array(a) => ciborium::Value::Array(a.iter().map(value_to_cbor).collect()),
        Value::Dict(d) => ciborium::Value::Map(
            d.iter().map(|(k, v)| (ciborium::Value::Text(k.clone()), value_to_cbor(v))).collect(),
        ),
        other => ciborium::Value::Text(crate::eval::repr::repr(other)),
    }
}

fn parse_cbor(bytes: &[u8], span: Span) -> Result<Value> {
    match ciborium::from_reader::<ciborium::Value, _>(bytes) {
        Ok(v) => Ok(cbor_to_value(&v)),
        Err(e) => bail(span, format!("failed to parse CBOR ({e})")),
    }
}

fn cbor(vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let source: Spanned<DataSource> = args.expect_spanned("source")?;
    let span = source.span;
    let bytes = load(vm, source)?;
    parse_cbor(&bytes, span)
}

fn cbor_decode(vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let source: Spanned<DataSource> = args.expect_spanned("data")?;
    let span = source.span;
    let bytes = load(vm, source)?;
    parse_cbor(&bytes, span)
}

fn cbor_encode(_vm: &mut Vm, args: &mut Args, span: Span) -> Result<Value> {
    let v: Value = args.expect("value")?;
    let mut out = Vec::new();
    match ciborium::into_writer(&value_to_cbor(&v), &mut out) {
        Ok(()) => Ok(Value::Bytes(Rc::new(out))),
        Err(e) => bail(span, format!("failed to encode value as CBOR ({e})")),
    }
}

// --------------------------------------------------------------- read

fn read(vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let path: Spanned<String> = args.expect_spanned("path")?;
    let encoding: Option<Spanned<Value>> = args.named_spanned("encoding")?;
