#[derive(Clone, Debug)]
pub enum Ty {
    Any,
    Bool,
    Int,
    PosInt,
    NonNegInt,
    Float,
    Str,
    Content,
    Length,
    Angle,
    Ratio,
    Relative,
    Fraction,
