    Direction,
    Stroke,
    Numbering,
    Selector,
    Location,
    Bytes,
    Location2,
    Smart(Box<Ty>),
    Opt(Box<Ty>),
    Or(Vec<Ty>),
    Enum(Vec<&'static str>),
    Sides(Box<Ty>),
