    }

    /// The description pieces (for "expected X, Y, or Z").
    fn describe(&self) -> Vec<String> {
        match self {
            Ty::Any => vec!["value".into()],
            Ty::Bool => vec!["boolean".into()],
            Ty::Int | Ty::PosInt | Ty::NonNegInt => vec!["integer".into()],
            Ty::Float => vec!["float".into()],
            Ty::Str => vec!["string".into()],
            Ty::Content => vec!["content".into()],
            Ty::Length => vec!["length".into()],
            Ty::Angle => vec!["angle".into()],
            Ty::Ratio => vec!["ratio".into()],
            Ty::Relative => vec!["relative length".into()],
            Ty::Fraction => vec!["fraction".into()],
            Ty::Spacing => vec!["relative length".into(), "fraction".into()],
            Ty::Paint => vec!["color".into(), "gradient".into(), "tiling".into()],
            Ty::Color => vec!["color".into()],
            Ty::Label => vec!["label".into()],
            Ty::Func => vec!["function".into()],
            Ty::Array => vec!["array".into()],
            Ty::Dict => vec!["dictionary".into()],
            Ty::Alignment | Ty::HAlignment | Ty::VAlignment => vec!["alignment".into()],
            Ty::Direction => vec!["direction".into()],
            Ty::Stroke => vec![
                "length".into(), "color".into(), "gradient".into(), "tiling".into(),
                "dictionary".into(), "stroke".into(),
            ],
            Ty::Numbering => vec!["string".into(), "function".into()],
            Ty::Selector => vec!["selector".into()],
            Ty::Location | Ty::Location2 => vec!["location".into()],
            Ty::Bytes => vec!["bytes".into()],
            Ty::Smart(t) => {
                let mut v = t.describe();
                v.push("auto".into());
                v
            }
            Ty::Opt(t) => {
                let mut v = t.describe();
                v.push("none".into());
                v
            }
            Ty::Or(ts) => ts.iter().flat_map(|t| t.describe()).collect(),
            Ty::Enum(names) => names.iter().map(|n| format!("\"{n}\"")).collect(),
            Ty::Sides(t) | Ty::Corners(t) => {
                let mut v = t.describe();
                v.push("dictionary".into());
                v
            }
            Ty::ArrayOf(_) => vec!["array".into()],
            Ty::Tracks => vec!["auto".into(), "relative length".into(), "fraction".into(), "integer".into(), "array".into()],
            Ty::Font => vec!["string".into(), "dictionary".into(), "array".into()],
            Ty::Weight => vec![
                "integer".into(), "\"thin\"".into(), "\"extralight\"".into(), "\"light\"".into(),
                "\"regular\"".into(), "\"medium\"".into(), "\"semibold\"".into(), "\"bold\"".into(),
                "\"extrabold\"".into(), "\"black\"".into(),
            ],
            Ty::TextEdge => vec![
                "\"ascender\"".into(), "\"cap-height\"".into(), "\"x-height\"".into(),
                "\"baseline\"".into(), "\"bounds\"".into(), "length".into(),
            ],
            Ty::Linkable => vec!["string".into(), "dictionary".into(), "location".into(), "label".into()],
            Ty::FigureKind => vec!["function".into(), "string".into(), "auto".into()],
            Ty::ElemOrContentArray(_) => vec!["content".into(), "array".into()],
        }
    }

    fn expected(&self, v: &Value) -> String {
        let parts = self.describe();
        let joined = join_or(&parts);
        if parts.iter().any(|p| p.starts_with('"')) {
            format!("expected {joined}")
        } else {
            format!("expected {joined}, found {}", v.ty().long_name())
        }
    }

    /// Cast and normalize a value.
    pub fn cast(&self, v: Value) -> std::result::Result<Value, String> {
        match self {
            Ty::Any => Ok(v),
            Ty::Bool => match v {
                Value::Bool(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Int => match v {
                Value::Int(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::PosInt => match v {
                Value::Int(i) if i > 0 => Ok(v),
                Value::Int(_) => Err("number must be positive".into()),
                _ => Err(self.expected(&v)),
            },
            Ty::NonNegInt => match v {
                Value::Int(i) if i >= 0 => Ok(v),
                Value::Int(_) => Err("number must be at least zero".into()),
                _ => Err(self.expected(&v)),
            },
            Ty::Float => match v {
                Value::Int(i) => Ok(Value::Float(i as f64)),
                Value::Float(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Str => match v {
                Value::Str(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Content => match v {
                Value::Content(_) => Ok(v),
                Value::Str(s) => Ok(Value::Content(Content::text(&s))),
                Value::Symbol(s) => Ok(Value::Content(Content::symbol(&s.text))),
                _ => Err(self.expected(&v)),
            },
            Ty::Length => match v {
                Value::Length(_) => Ok(v),
                Value::Int(i) => Err(hinted(self.expected(&v), format!("a length needs a unit - did you mean {i}pt?"))),
                Value::Float(f) => Err(hinted(
                    self.expected(&v),
                    format!("a length needs a unit - did you mean {}pt?", crate::eval::repr::repr_float(f)),
                )),
                _ => Err(self.expected(&v)),
            },
            Ty::Angle => match v {
                Value::Angle(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Ratio => match v {
                Value::Ratio(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Relative => match v {
                Value::Length(l) => Ok(Value::Relative(Relative::from_length(l))),
                Value::Ratio(r) => Ok(Value::Relative(Relative::from_ratio(r))),
                Value::Relative(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Fraction => match v {
                Value::Fraction(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Spacing => match v {
                Value::Length(l) => Ok(Value::Relative(Relative::from_length(l))),
                Value::Ratio(r) => Ok(Value::Relative(Relative::from_ratio(r))),
                Value::Relative(_) | Value::Fraction(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Paint => match v {
                Value::Color(_) | Value::Gradient(_) => Ok(v),
                Value::Dyn(ref d) if matches!(**d, Dynamic::Tiling) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Color => match v {
                Value::Color(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Label => match v {
                Value::Label(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Func => match v {
                Value::Func(_) => Ok(v),
                Value::Type(t) => Ok(Value::Func(Func::TypeCtor(t))),
                _ => Err(self.expected(&v)),
            },
            Ty::Array => match v {
                Value::Array(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Dict => match v {
                Value::Dict(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Alignment => match v.as_alignment() {
                Some(_) => Ok(v),
                None => Err(self.expected(&v)),
            },
            Ty::HAlignment => match v.as_alignment() {
                Some(a) if a.v.is_none() => Ok(v),
                Some(_) => Err("expected horizontal alignment".into()),
                None => Err(self.expected(&v)),
            },
            Ty::VAlignment => match v.as_alignment() {
                Some(a) if a.h.is_none() => Ok(v),
                Some(_) => Err("expected vertical alignment".into()),
                None => Err(self.expected(&v)),
            },
            Ty::Direction => match &v {
                Value::Dyn(d) if matches!(**d, Dynamic::Direction(_)) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Stroke => {
                let s = super::foundations::cast_stroke(&v).map_err(|e| {
                    if e.starts_with("expected") { self.expected(&v) } else { e }
                })?;
                // Simple strokes are represented by their defining value.
                Ok(stroke_value(s))
            }
            Ty::Numbering => match v {
                Value::Str(_) | Value::Func(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Selector => super::cast_selector(&v, false)
                .map(|s| Value::dynamic(Dynamic::Selector(s)))
                .map_err(|_| self.expected(&v)),
            Ty::Location | Ty::Location2 => match &v {
                Value::Dyn(d) if matches!(**d, Dynamic::Location(_)) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Bytes => match v {
                Value::Bytes(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Smart(t) => match v {
                Value::Auto => Ok(v),
                _ => t.cast(v.clone()).map_err(|e| {
                    if e.starts_with("expected") && !e.contains('\u{0}') { self.expected(&v) } else { e }
                }),
            },
            Ty::Opt(t) => match v {
                Value::None => Ok(v),
                _ => t.cast(v.clone()).map_err(|e| {
                    if e.starts_with("expected") && !e.contains('\u{0}') { self.expected(&v) } else { e }
                }),
            },
            Ty::Or(ts) => {
                for t in ts {
                    match t.cast(v.clone()) {
                        Ok(r) => return Ok(r),
                        Err(e) if !e.starts_with("expected") => return Err(e),
                        Err(_) => {}
                    }
                }
                Err(self.expected(&v))
            }
            Ty::Enum(names) => match &v {
                Value::Str(s) if names.contains(&&**s) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Sides(t) => match &v {
                Value::Dict(d) => {
                    let mut out: Dict = IndexMap::new();
                    let keys = ["left", "top", "right", "bottom", "x", "y", "rest"];
                    for k in d.keys() {
                        if !keys.contains(&k.as_str()) {
                            return Err(format!("unexpected key {}", repr_str(k)));
                        }
                    }
                    let get = |k: &str| d.get(k).cloned();
                    let rest = get("rest");
                    let x = get("x").or(rest.clone());
                    let y = get("y").or(rest.clone());
                    let left = get("left").or(x.clone());
                    let right = get("right").or(x);
                    let top = get("top").or(y.clone());
                    let bottom = get("bottom").or(y);
                    let sides = [("left", left), ("top", top), ("right", right), ("bottom", bottom)];
                    let mut all_same = true;
                    let mut first: Option<Value> = None;
                    for (k, val) in &sides {
                        if let Some(val) = val {
                            let c = t.cast(val.clone())?;
                            if let Some(f) = &first {
                                if !crate::eval::ops::equal(f, &c) {
                                    all_same = false;
                                }
                            } else {
                                first = Some(c.clone());
                            }
                            out.insert(k.to_string(), c);
                        } else {
                            all_same = false;
                        }
                    }
                    if all_same && out.len() == 4 {
                        return Ok(first.unwrap());
                    }
                    Ok(Value::dict(out))
                }
                _ => t.cast(v.clone()).map_err(|e| if e.starts_with("expected") { self.expected(&v) } else { e }),
            },
            Ty::Corners(t) => match &v {
                Value::Dict(d) => {
                    let mut out: Dict = IndexMap::new();
                    let keys = ["top-left", "top-right", "bottom-right", "bottom-left", "left", "top", "right", "bottom", "rest"];
                    for k in d.keys() {
                        if !keys.contains(&k.as_str()) {
                            return Err(format!("unexpected key {}", repr_str(k)));
                        }
                    }
                    let get = |k: &str| d.get(k).cloned();
                    let rest = get("rest");
                    let left = get("left").or(rest.clone());
                    let top = get("top").or(rest.clone());
                    let right = get("right").or(rest.clone());
                    let bottom = get("bottom").or(rest.clone());
                    let tl = get("top-left").or(top.clone()).or(left.clone());
                    let tr = get("top-right").or(top).or(right.clone());
                    let br = get("bottom-right").or(bottom.clone()).or(right);
                    let bl = get("bottom-left").or(bottom).or(left);
                    let corners = [("top-left", tl), ("top-right", tr), ("bottom-right", br), ("bottom-left", bl)];
                    let mut all_same = true;
                    let mut first: Option<Value> = None;
                    for (k, val) in &corners {
                        if let Some(val) = val {
                            let c = t.cast(val.clone())?;
                            if let Some(f) = &first {
                                if !crate::eval::ops::equal(f, &c) {
                                    all_same = false;
                                }
                            } else {
                                first = Some(c.clone());
                            }
                            out.insert(k.to_string(), c);
                        } else {
                            all_same = false;
                        }
                    }
                    if all_same && out.len() == 4 {
                        return Ok(first.unwrap());
                    }
                    Ok(Value::dict(out))
                }
                _ => t.cast(v.clone()).map_err(|e| if e.starts_with("expected") { self.expected(&v) } else { e }),
            },
            Ty::ArrayOf(t) => match &v {
                Value::Array(a) => {
                    let mut out = Vec::new();
                    for item in a.iter() {
                        out.push(t.cast(item.clone())?);
                    }
                    Ok(Value::array(out))
                }
                _ => Err(self.expected(&v)),
            },
            Ty::Tracks => match &v {
                Value::Auto => Ok(Value::array(vec![Value::Auto])),
                Value::Int(i) => {
                    if *i <= 0 {
                        return Err("number must be positive".into());
                    }
                    Ok(Value::array(vec![Value::Auto; *i as usize]))
                }
                Value::Length(_) | Value::Ratio(_) | Value::Relative(_) => {
                    Ok(Value::array(vec![Ty::Relative.cast(v.clone())?]))
                }
                Value::Fraction(_) => Ok(Value::array(vec![v.clone()])),
                Value::Array(a) => {
                    let mut out = Vec::new();
                    for item in a.iter() {
                        let c = match item {
                            Value::Auto | Value::Fraction(_) => item.clone(),
                            Value::Length(_) | Value::Ratio(_) | Value::Relative(_) => Ty::Relative.cast(item.clone())?,
                            other => return Err(format!("expected auto, relative length, or fraction, found {}", other.ty().long_name())),
                        };
                        out.push(c);
                    }
                    Ok(Value::array(out))
                }
                _ => Err(self.expected(&v)),
            },
            Ty::Font => match &v {
                Value::Str(_) | Value::Dict(_) => Ok(v),
                Value::Array(_) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Weight => match &v {
                Value::Int(_) => Ok(v),
                Value::Str(s) if matches!(&**s, "thin" | "extralight" | "light" | "regular" | "medium" | "semibold" | "bold" | "extrabold" | "black") => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::TextEdge => match &v {
                Value::Length(_) => Ok(v),
                Value::Str(s) if matches!(&**s, "ascender" | "cap-height" | "x-height" | "baseline" | "bounds" | "descender") => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::Linkable => match &v {
                Value::Str(_) | Value::Dict(_) | Value::Label(_) => Ok(v),
                Value::Dyn(d) if matches!(**d, Dynamic::Location(_)) => Ok(v),
                _ => Err(self.expected(&v)),
            },
            Ty::FigureKind => match &v {
                Value::Auto | Value::Str(_) => Ok(v),
                Value::Func(f) if f.elem().is_some() => Ok(v),
                Value::Func(_) => Err("expected element function".into()),
                _ => Err(self.expected(&v)),
            },
            Ty::ElemOrContentArray(_) => Ok(v),
        }
    }
}

fn join_or(parts: &[String]) -> String {
    match parts.len() {
        0 => String::new(),
        1 => parts[0].clone(),
        2 => format!("{} or {}", parts[0], parts[1]),
        _ => {
            let (last, rest) = parts.split_last().unwrap();
            format!("{}, or {}", rest.join(", "), last)
        }
    }
}

/// Convert a stroke to its value representation (simple strokes are plain values).
pub fn stroke_value(s: Stroke) -> Value {
    let simple = s.cap.is_none() && s.join.is_none() && s.dash.is_none() && s.miter_limit.is_none();
    match (&s.paint, &s.thickness, simple) {
        (Some(p), None, true) => p.clone(),
        (None, Some(t), true) => t.clone(),
        _ => Value::dynamic(Dynamic::Stroke(s)),
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Kind {
    /// Required positional (also accepted by name? no).
    Required,
    /// Optional positional found by type.
    Positional,
    /// Named only.
    Named,
    /// Variadic positional.
    Variadic,
    /// Named, but also externally provided (`internal`).
    Internal,
}

#[derive(Clone, Debug)]
pub struct ParamDef {
    pub name: &'static str,
    pub ty: Ty,
    pub kind: Kind,
    pub settable: bool,
    pub default: Option<Value>,
}

#[derive(Clone, Debug)]
pub struct ElemDef {
    pub name: &'static str,
    pub params: Vec<ParamDef>,
    /// Whether the element can only be used in set rules.
    pub set_only: bool,
}

fn named(name: &'static str, ty: Ty) -> ParamDef {
    ParamDef { name, ty, kind: Kind::Named, settable: true, default: None }
}
fn req(name: &'static str, ty: Ty) -> ParamDef {
    ParamDef { name, ty, kind: Kind::Required, settable: false, default: None }
}
fn pos(name: &'static str, ty: Ty) -> ParamDef {
    ParamDef { name, ty, kind: Kind::Positional, settable: true, default: None }
}
fn variadic(name: &'static str, ty: Ty) -> ParamDef {
    ParamDef { name, ty, kind: Kind::Variadic, settable: false, default: None }
}
fn internal(name: &'static str, ty: Ty) -> ParamDef {
    ParamDef { name, ty, kind: Kind::Internal, settable: false, default: None }
}

impl ParamDef {
    fn def(mut self, v: Value) -> Self {
        self.default = Some(v);
        self
    }
    fn noset(mut self) -> Self {
        self.settable = false;
        self
    }
}

fn pt(v: f64) -> Value {
    Value::Length(Length::pt(v))
}
fn em(v: f64) -> Value {
    Value::Length(Length::em(v))
}
fn s(v: &str) -> Value {
    Value::str(v)
}
fn rel_pt(v: f64) -> Value {
    Value::Relative(Relative::from_length(Length::pt(v)))
}
fn rel_em(v: f64) -> Value {
    Value::Relative(Relative::from_length(Length::em(v)))
}
fn align_h(h: HAlign) -> Value {
    Value::dynamic(Dynamic::Alignment(Alignment { h: Some(h), v: None }))
}
fn align_v(v: VAlign) -> Value {
    Value::dynamic(Dynamic::Alignment(Alignment { h: None, v: Some(v) }))
}

thread_local! {
    static ELEMS: RefCell<Option<Rc<HashMap<&'static str, Rc<ElemDef>>>>> = RefCell::new(None);
}

fn elems() -> Rc<HashMap<&'static str, Rc<ElemDef>>> {
    ELEMS.with(|e| {
        if e.borrow().is_none() {
            *e.borrow_mut() = Some(Rc::new(build_elems()));
        }
        e.borrow().as_ref().unwrap().clone()
    })
}

pub fn get(name: &str) -> Option<Rc<ElemDef>> {
    elems().get(name).cloned()
}

fn build_elems() -> HashMap<&'static str, Rc<ElemDef>> {
    let mut m: HashMap<&'static str, Rc<ElemDef>> = HashMap::new();
    let mut add = |name: &'static str, params: Vec<ParamDef>| {
        m.insert(name, Rc::new(ElemDef { name, params, set_only: false }));
    };

    let body = || req("body", Ty::Content);
    let numbering = || Ty::opt(Ty::Numbering);
    let smart_len = || Ty::smart(Ty::Length);
    let smart_rel = || Ty::smart(Ty::Relative);
    let opt_paint = || Ty::opt(Ty::Paint);
    let opt_stroke = || Ty::opt(Ty::Stroke);
    let sides_rel = || Ty::Sides(Box::new(Ty::Relative));
    let sides_stroke = || Ty::Sides(Box::new(Ty::opt(Ty::Stroke)));
    let corners_rel = || Ty::Corners(Box::new(Ty::Relative));

    // ---- Text
    add("text", vec![
        named("font", Ty::Font).def(s("libertinus serif")),
        named("fallback", Ty::Bool).def(Value::Bool(true)),
        named("style", Ty::Enum(vec!["normal", "italic", "oblique"])).def(s("normal")),
        named("weight", Ty::Weight).def(s("regular")),
        named("stretch", Ty::Ratio).def(Value::Ratio(1.0)),
        pos("size", Ty::Length).def(pt(11.0)),
        pos("fill", Ty::Paint).def(Value::Color(crate::eval::color::Color::Luma(0.0, 1.0))),
        named("stroke", Ty::opt(Ty::Stroke)).def(Value::None),
        named("tracking", Ty::Length).def(pt(0.0)),
        named("spacing", Ty::Relative).def(Value::Relative(Relative::new(1.0, Length::zero()))),
        named("cjk-latin-spacing", Ty::smart(Ty::opt(Ty::Bool))).def(Value::Auto),
        named("baseline", Ty::Length).def(pt(0.0)),
        named("overhang", Ty::Bool).def(Value::Bool(true)),
        named("top-edge", Ty::TextEdge).def(s("cap-height")),
        named("bottom-edge", Ty::TextEdge).def(s("baseline")),
        named("lang", Ty::Str).def(s("en")),
        named("region", Ty::opt(Ty::Str)).def(Value::None),
        named("script", Ty::smart(Ty::Str)).def(Value::Auto),
        named("dir", Ty::smart(Ty::Direction)).def(Value::Auto),
        named("hyphenate", Ty::smart(Ty::Bool)).def(Value::Auto),
        named("costs", Ty::Dict),
        named("kerning", Ty::Bool).def(Value::Bool(true)),
        named("alternates", Ty::Bool).def(Value::Bool(false)),
        named("stylistic-set", Ty::opt(Ty::Or(vec![Ty::Int, Ty::Array]))).def(Value::None),
        named("ligatures", Ty::Bool).def(Value::Bool(true)),
        named("discretionary-ligatures", Ty::Bool).def(Value::Bool(false)),
        named("historical-ligatures", Ty::Bool).def(Value::Bool(false)),
        named("number-type", Ty::smart(Ty::Enum(vec!["lining", "old-style"]))).def(Value::Auto),
        named("number-width", Ty::smart(Ty::Enum(vec!["proportional", "tabular"]))).def(Value::Auto),
        named("slashed-zero", Ty::Bool).def(Value::Bool(false)),
        named("fractions", Ty::Bool).def(Value::Bool(false)),
        named("features", Ty::Or(vec![Ty::Array, Ty::Dict])).def(Value::dict(IndexMap::new())),
        named("case", Ty::Any).noset(),
        body(),
    ]);
    add("linebreak", vec![named("justify", Ty::Bool).def(Value::Bool(false))]);
    add("smartquote", vec![
        named("double", Ty::Bool).def(Value::Bool(true)),
        named("enabled", Ty::Bool).def(Value::Bool(true)),
        named("alternative", Ty::Bool).def(Value::Bool(false)),
        named("quotes", Ty::Any).def(Value::Auto),
    ]);
    add("sub", vec![
        named("typographic", Ty::Bool).def(Value::Bool(true)),
        named("baseline", Ty::smart(Ty::Length)).def(Value::Auto),
        named("size", Ty::smart(Ty::Length)).def(Value::Auto),
        body(),
    ]);
    add("super", vec![
        named("typographic", Ty::Bool).def(Value::Bool(true)),
        named("baseline", Ty::smart(Ty::Length)).def(Value::Auto),
        named("size", Ty::smart(Ty::Length)).def(Value::Auto),
        body(),
    ]);
    add("underline", vec![
        named("stroke", Ty::smart(Ty::Stroke)).def(Value::Auto),
        named("offset", Ty::smart(Ty::Length)).def(Value::Auto),
        named("extent", Ty::Length).def(pt(0.0)),
        named("evade", Ty::Bool).def(Value::Bool(true)),
        named("background", Ty::Bool).def(Value::Bool(false)),
        body(),
    ]);
    add("overline", vec![
        named("stroke", Ty::smart(Ty::Stroke)).def(Value::Auto),
        named("offset", Ty::smart(Ty::Length)).def(Value::Auto),
        named("extent", Ty::Length).def(pt(0.0)),
        named("evade", Ty::Bool).def(Value::Bool(true)),
        named("background", Ty::Bool).def(Value::Bool(false)),
        body(),
    ]);
    add("strike", vec![
