fn cast_quotes(v: Value, span: Span) -> Result<Value> {
    fn pair(v: &Value, span: Span) -> Result<Value> {
        match v {
            Value::Auto => Ok(Value::Auto),
            Value::Str(s) => {
                let n = s.chars().count();
                if n != 2 {
                    return bail(span, format!("expected 2 characters, found {n} character{}", if n == 1 { "" } else { "s" }));
                }
                let cs: Vec<Value> = s.chars().map(|c| Value::str(c.to_string())).collect();
                Ok(Value::array(cs))
            }
            Value::Array(a) => {
                if a.len() != 2 {
                    return bail(span, format!("expected 2 quotes, found {} quote{}", a.len(), if a.len() == 1 { "" } else { "s" }));
                }
                for item in a.iter() {
                    if !matches!(item, Value::Str(_)) {
                        return bail(span, format!("expected string, found {}", item.ty().long_name()));
                    }
                }
                Ok(Value::Array(a.clone()))
            }
            other => bail(span, format!("expected string, array, dictionary, or auto, found {}", other.ty().long_name())),
        }
    }
    match &v {
        Value::Dict(d) => {
            for k in d.keys() {
                if k != "double" && k != "single" {
                    return bail(span, format!("unexpected key {}, valid keys are \"double\" and \"single\"", repr_str(k)));
                }
            }
            let mut out: Dict = IndexMap::new();
            out.insert("double".into(), match d.get("double") { Some(x) => pair(x, span)?, None => Value::Auto });
            out.insert("single".into(), match d.get("single") { Some(x) => pair(x, span)?, None => Value::Auto });
            Ok(Value::dict(out))
        }
        other => {
            let p = pair(other, span)?;
            let mut out: Dict = IndexMap::new();
            out.insert("double".into(), p.clone());
            out.insert("single".into(), p);
            Ok(Value::dict(out))
        }
    }
}

fn check_fonts(vm: &mut Vm, fields: &[(String, Value)], span: Span) {
    let Some(font) = get_field(fields, "font") else { return };
    let names: Vec<String> = match &font {
        Value::Str(s) => vec![s.to_string()],
        Value::Array(a) => a
            .iter()
            .filter_map(|v| match v {
                Value::Str(s) => Some(s.to_string()),
                Value::Dict(d) => d.get("name").and_then(|n| n.as_str().map(|s| s.to_string())),
                _ => None,
            })
            .collect(),
        Value::Dict(d) => d.get("name").and_then(|n| n.as_str().map(|s| vec![s.to_string()])).unwrap_or_default(),
        _ => vec![],
    };
    for name in names {
        let lower = name.to_lowercase();
        if !vm.world.has_font(&lower) {
            vm.warn(SourceDiagnostic::warning(span, format!("unknown font family: {lower}")));
        }
    }
}

/// Parse the arguments of a set rule.
pub fn set_fields(vm: &mut Vm, elem: &'static str, args: &mut Args, span: Span) -> Result<Vec<(String, Value)>> {
    let def = match get(elem) {
        Some(d) => d,
        None => {
            let mut fields = Vec::new();
            for arg in std::mem::take(args).items {
                match arg.name {
                    Some(n) => fields.push((n, arg.value)),
                    None => return bail(arg.span, "unexpected argument"),
                }
            }
            return Ok(fields);
        }
    };
    let fields = parse_params(&def, args, span, false)?;
    if elem == "text" {
        check_fonts(vm, &fields, span);
    }
    args.finish()?;
    Ok(fields)
}
