/// Elements whose `func` is referenced as an element function in the global scope.
const GLOBAL_ELEMS: &[&str] = &[
    "text", "linebreak", "smartquote", "sub", "super", "underline", "overline", "strike",
    "highlight", "smallcaps", "raw", "document", "par", "parbreak", "strong", "emph", "list",
    "enum", "terms", "link", "title", "heading", "figure", "quote", "footnote", "outline", "ref",
    "cite", "bibliography", "table", "grid", "page", "pagebreak", "v", "h", "box", "block",
    "stack", "columns", "colbreak", "place", "align", "pad", "repeat", "move", "scale", "rotate",
    "skew", "hide", "layout", "image", "line", "rect", "square", "ellipse", "circle", "polygon",
    "curve", "path",
];

pub fn define(s: &mut Scope) {
    for name in GLOBAL_ELEMS {
        s.define(*name, Value::Func(Func::Elem(name)));
    }
}

pub fn define_math(s: &mut Scope) {
    s.define("equation", Value::Func(Func::Elem("equation")));
    for name in [
        "lr", "mid", "attach", "stretch", "scripts", "limits", "accent", "underline", "overline",
        "underbrace", "overbrace", "underbracket", "overbracket", "underparen", "overparen",
        "undershell", "overshell", "cancel", "frac", "binom", "vec", "mat", "cases", "root",
        "class", "op", "primes", "upright", "bold", "italic", "serif", "sans", "scr", "cal",
        "frak", "mono", "bb", "display", "inline", "script", "sscript", "text",
    ] {
        let full: &'static str = Box::leak(format!("math.{name}").into_boxed_str());
        s.define(name, Value::Func(Func::Elem(full)));
    }
    s.define("abs", Value::Func(Func::native("abs", math_abs)));
    s.define("norm", Value::Func(Func::native("norm", math_norm)));
    s.define("round", Value::Func(Func::native("round", math_round)));
    s.define("sqrt", Value::Func(Func::native("sqrt", math_sqrt)));

    // Predefined operators.
    for (name, limits) in [
        ("arccos", false), ("arcsin", false), ("arctan", false), ("arg", false), ("cos", false),
        ("cosh", false), ("cot", false), ("coth", false), ("csc", false), ("csch", false),
        ("ctg", false), ("deg", false), ("det", true), ("dim", false), ("exp", false),
        ("gcd", true), ("lcm", true), ("hom", false), ("id", false), ("im", false), ("inf", true),
        ("ker", false), ("lg", false), ("lim", true), ("liminf", true), ("limsup", true),
        ("ln", false), ("log", false), ("max", true), ("min", true), ("mod", false), ("Pr", true),
        ("sec", false), ("sech", false), ("sin", false), ("sinc", false), ("sinh", false),
        ("sup", true), ("tan", false), ("tanh", false), ("tg", false), ("tr", false),
    ] {
        let c = Content::new("math.op")
            .with_field("text", Content::text(name))
            .with_field("limits", Value::Bool(limits));
        s.define(name, Value::Content(c));
    }
    s.define("dif", Value::Content(Content::new("math.upright").with_field("body", Content::text("d"))));
    s.define("Dif", Value::Content(Content::new("math.upright").with_field("body", Content::text("D"))));
    let spacing = |amount: f64| {
        Value::Content(Content::new("h").with_field("amount", Value::Relative(Relative::from_length(Length::em(amount)))))
    };
    s.define("thin", spacing(1.0 / 6.0));
    s.define("med", spacing(2.0 / 9.0));
    s.define("thick", spacing(5.0 / 18.0));
    s.define("quad", spacing(1.0));
    s.define("wide", spacing(2.0));
}

fn math_abs(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let body: Content = args.expect("body")?;
    let size: Option<Value> = args.named("size")?;
    let mut c = Content::new("math.lr");
    if let Some(sz) = size {
        c.set_field("size", sz);
    }
    let seq = Content::new("sequence").with_field(
        "children",
        Value::array(vec![Value::Content(Content::symbol("|")), Value::Content(body), Value::Content(Content::symbol("|"))]),
    );
    c.set_field("body", Value::Content(seq));
    Ok(Value::Content(c))
}

fn math_norm(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let body: Content = args.expect("body")?;
    let size: Option<Value> = args.named("size")?;
    let mut c = Content::new("math.lr");
    if let Some(sz) = size {
        c.set_field("size", sz);
    }
    let seq = Content::new("sequence").with_field(
        "children",
        Value::array(vec![Value::Content(Content::symbol("‖")), Value::Content(body), Value::Content(Content::symbol("‖"))]),
    );
    c.set_field("body", Value::Content(seq));
    Ok(Value::Content(c))
}

fn math_round(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let body: Content = args.expect("body")?;
    let size: Option<Value> = args.named("size")?;
    let mut c = Content::new("math.lr");
    if let Some(sz) = size {
        c.set_field("size", sz);
    }
    let seq = Content::new("sequence").with_field(
        "children",
        Value::array(vec![Value::Content(Content::symbol("⌊")), Value::Content(body), Value::Content(Content::symbol("⌉"))]),
    );
    c.set_field("body", Value::Content(seq));
    Ok(Value::Content(c))
}

fn math_sqrt(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let radicand: Content = args.expect("radicand")?;
    Ok(Value::Content(Content::new("math.root").with_field("radicand", radicand)))
}

pub fn has_param(elem: &str, name: &str) -> bool {
    get(elem).is_some_and(|d| d.params.iter().any(|p| p.name == name))
}

pub fn style_field(elem: &str, name: &str) -> Option<Value> {
    let def = get(elem)?;
    let p = def.params.iter().find(|p| p.name == name)?;
    if p.kind == Kind::Required || p.kind == Kind::Variadic {
        return None;
    }
    p.default.clone()
}

pub fn elem_scope(elem: &str) -> Scope {
    let mut s = Scope::new();
    let subs: &[&str] = match elem {
        "list" => &["item"],
        "enum" => &["item"],
        "terms" => &["item"],
        "table" => &["cell", "hline", "vline", "header", "footer"],
        "grid" => &["cell", "hline", "vline", "header", "footer"],
        "figure" => &["caption"],
        "outline" => &["entry"],
        "footnote" => &["entry"],
        "raw" => &["line"],
        "curve" => &["move", "line", "quad", "cubic", "close"],
        "place" => &["flush"],
        "math.equation" | "equation" => &[],
        _ => &[],
    };
    for sub in subs {
        let full: &'static str = Box::leak(format!("{elem}.{sub}").into_boxed_str());
        s.define(*sub, Value::Func(Func::Elem(full)));
    }
    if elem == "polygon" {
        s.define("regular", Value::Func(Func::native("regular", polygon_regular)));
    }
    s
}

pub fn elem_scope_get(elem: &str, name: &str) -> Option<Value> {
    elem_scope(elem).get(name).map(|b| b.value.clone())
}

fn polygon_regular(_vm: &mut Vm, args: &mut Args, _span: Span) -> Result<Value> {
    let fill: Option<Value> = args.named("fill")?;
    let stroke: Option<Value> = args.named("stroke")?;
    let size: Length = args.named::<Length>("size")?.unwrap_or(Length::em(1.0));
    let vertices: i64 = args.named("vertices")?.unwrap_or(3);
    let mut c = Content::new("polygon");
    if let Some(f) = fill {
        c.set_field("fill", f);
    }
    if let Some(s) = stroke {
        c.set_field("stroke", s);
    }
    let n = vertices.max(0) as usize;
    let radius = size.abs / 2.0;
    let mut pts = Vec::new();
    for i in 0..=n {
        let angle = std::f64::consts::TAU * i as f64 / n as f64 + std::f64::consts::FRAC_PI_2 * 3.0;
        let x = radius + radius * angle.cos();
        let y = radius + radius * angle.sin();
        pts.push(Value::array(vec![
            Value::Relative(Relative::from_length(Length::pt(x))),
            Value::Relative(Relative::from_length(Length::pt(y))),
        ]));
    }
    c.set_field("vertices", Value::array(pts));
    Ok(Value::Content(c))
}

fn cast_arg(ty: &Ty, arg: Arg) -> Result<Value> {
    let span = arg.value_span;
    ty.cast(arg.value).map_err(|e| {
        let mut parts = e.split("\u{0}hint:");
        let msg = parts.next().unwrap_or("").to_string();
        let mut d = SourceDiagnostic::error(span, msg);
        for h in parts {
            d.hints.push(h.to_string());
        }
        vec![d]
    })
}

/// Parse arguments according to the element definition.
fn parse_params(
    def: &ElemDef,
    args: &mut Args,
    span: Span,
    allow_pos: bool,
) -> Result<Vec<(String, Value)>> {
    let mut fields: Vec<(String, Value)> = Vec::new();
    // Named arguments first.
    for p in &def.params {
        if matches!(p.kind, Kind::Required | Kind::Variadic) && !allow_pos {
            continue;
        }
        if p.kind == Kind::Internal {
            continue;
        }
        if let Some(arg) = args.take_named(p.name) {
            if !allow_pos && !p.settable {
                return bail(arg.span, format!("unexpected argument: {}", p.name));
            }
            let v = cast_arg(&p.ty, arg)?;
            fields.push((p.name.to_string(), v));
        }
    }
    if allow_pos {
        // Optional positional (found by type).
        for p in &def.params {
            if p.kind == Kind::Positional && !fields.iter().any(|(n, _)| n == p.name) {
                let idx = args.items.iter().position(|a| a.name.is_none() && p.ty.cast(a.value.clone()).is_ok());
                if let Some(i) = idx {
                    let arg = args.items.remove(i);
                    let v = cast_arg(&p.ty, arg)?;
                    fields.push((p.name.to_string(), v));
                }
            }
        }
        // Required positional in order.
        for p in &def.params {
            if p.kind == Kind::Required && !fields.iter().any(|(n, _)| n == p.name) {
                match args.eat_pos() {
                    Some(arg) => {
                        let v = cast_arg(&p.ty, arg)?;
                        fields.push((p.name.to_string(), v));
                    }
                    None => return bail(span, format!("missing argument: {}", p.name)),
                }
            }
        }
        // Variadic.
        for p in &def.params {
            if p.kind == Kind::Variadic {
                let mut items = Vec::new();
                while let Some(arg) = args.eat_pos() {
                    items.push(cast_arg(&p.ty, arg)?);
                }
                fields.push((p.name.to_string(), Value::array(items)));
            }
        }
    }
    Ok(fields)
}

fn order_fields(def: &ElemDef, fields: &mut Vec<(String, Value)>) {
    fields.sort_by_key(|(n, _)| def.params.iter().position(|p| p.name == n).unwrap_or(usize::MAX));
}

fn get_field(fields: &[(String, Value)], name: &str) -> Option<Value> {
    fields.iter().find(|(n, _)| n == name).map(|(_, v)| v.clone())
}

fn remove_field(fields: &mut Vec<(String, Value)>, name: &str) -> Option<Value> {
    let idx = fields.iter().position(|(n, _)| n == name)?;
    Some(fields.remove(idx).1)
}

fn set_field(fields: &mut Vec<(String, Value)>, name: &str, v: Value) {
    if let Some(slot) = fields.iter_mut().find(|(n, _)| n == name) {
        slot.1 = v;
    } else {
        fields.push((name.to_string(), v));
    }
}

/// Convert children to the given element kind.
fn convert_children(vm: &mut Vm, items: Vec<Value>, target: &str, span: Span) -> Result<Vec<Value>> {
    let mut out = Vec::new();
    for item in items {
        let v = match (&item, target) {
            (Value::Content(c), _) if c.elem() == target => item,
            (Value::Content(c), "table.cell") if c.elem() == "table.hline" || c.elem() == "table.vline" || c.elem() == "table.header" || c.elem() == "table.footer" => item,
            (Value::Content(c), "grid.cell") if c.elem() == "grid.hline" || c.elem() == "grid.vline" || c.elem() == "grid.header" || c.elem() == "grid.footer" => item,
            (Value::Content(c), "terms.item") => {
                let _ = c;
                return bail(span, "expected term item or array");
            }
            (Value::Array(a), "terms.item") => {
                vm.warn(
                    SourceDiagnostic::warning(span, "implicit conversion from array to `terms.item` is deprecated")
                        .with_hint("use `terms.item(term, description)` instead")
                        .with_hint("this conversion was never documented and is being phased out"),
                );
                if a.len() != 2 {
                    return bail(span, "array must contain exactly two entries");
                }
                let term = Ty::Content.cast(a[0].clone()).map_err(|e| vec![SourceDiagnostic::error(span, e)])?;
                let desc = Ty::Content.cast(a[1].clone()).map_err(|e| vec![SourceDiagnostic::error(span, e)])?;
                Value::Content(Content::new("terms.item").with_field("term", term).with_field("description", desc))
            }
            (_, "terms.item") => return bail(span, "expected term item or array"),
            (Value::Content(_) | Value::Str(_) | Value::Symbol(_), _) => {
                let body = Ty::Content.cast(item).map_err(|e| vec![SourceDiagnostic::error(span, e)])?;
                let target_static: &'static str = Box::leak(target.to_string().into_boxed_str());
                Value::Content(Content::new(target_static).with_field("body", body))
            }
            (other, _) => {
                return bail(span, format!("expected content, found {}", other.ty().long_name()));
            }
        };
        out.push(v);
    }
    Ok(out)
}

fn finish_children(children: Vec<Value>) -> Value {
    Value::array(children)
}

/// Construct an element from arguments.
pub fn construct(vm: &mut Vm, elem: &'static str, args: &mut Args, span: Span) -> Result<Content> {
    let def = match get(elem) {
        Some(d) => d,
        None => {
            // Unknown element: generic construction.
            let mut c = Content::new(elem);
            let taken = std::mem::take(args);
            for arg in taken.items {
                match arg.name {
                    Some(n) => c.set_field(&n, arg.value),
                    None => c.set_field("body", arg.value),
                }
            }
            return Ok(c.with_span(span));
        }
    };
    if def.set_only {
        return bail(span, "can only be used in set rules");
    }

    // Special handling for `text`: style args become styles.
    if elem == "text" {
        let mut fields = parse_params(&def, args, span, true)?;
        check_fonts(vm, &fields, span);
        let body = match remove_field(&mut fields, "body") {
            Some(Value::Content(c)) => c,
            _ => Content::empty(),
        };
        args.finish()?;
        if fields.is_empty() {
            return Ok(body);
        }
        let styles = Styles { rules: vec![StyleRule::Set { elem: "text", fields }] };
        return Ok(styled(body, Rc::new(styles)));
    }

    // Variadic content children get special conversions.
    let mut fields = parse_params(&def, args, span, true)?;
    args.finish()?;

    // Post-processing per element.
    match elem {
        "page" => {
            let body = match remove_field(&mut fields, "body") {
                Some(Value::Content(c)) => c,
                _ => Content::empty(),
            };
            let seq = Content::new("sequence").with_field(
                "children",
                Value::array(vec![
                    Value::Content(Content::new("pagebreak").with_field("weak", Value::Bool(true))),
                    Value::Content(Content::new("place.flush")),
                    Value::Content(body),
                    Value::Content(Content::new("pagebreak").with_field("weak", Value::Bool(true))),
                ]),
            );
            if fields.is_empty() {
                return Ok(seq);
            }
            let styles = Styles { rules: vec![StyleRule::Set { elem: "page", fields }] };
            return Ok(styled(seq, Rc::new(styles)));
        }
        "list" | "enum" | "terms" | "table" | "grid" | "table.header" | "table.footer" | "grid.header" | "grid.footer" => {
            let target = match elem {
                "list" => "list.item",
                "enum" => "enum.item",
                "terms" => "terms.item",
                "table" | "table.header" | "table.footer" => "table.cell",
                _ => "grid.cell",
            };
            if let Some(Value::Array(children)) = remove_field(&mut fields, "children") {
                let converted = convert_children(vm, (*children).clone(), target, span)?;
                set_field(&mut fields, "children", finish_children(converted));
            }
            if let Some(g) = remove_field(&mut fields, "gutter") {
                if get_field(&fields, "column-gutter").is_none() {
                    set_field(&mut fields, "column-gutter", g.clone());
                }
                if get_field(&fields, "row-gutter").is_none() {
                    set_field(&mut fields, "row-gutter", g);
                }
            }
        }
        "figure" => {
            if let Some(Value::Content(c)) = get_field(&fields, "caption") {
                if c.elem() != "figure.caption" {
                    set_field(&mut fields, "caption", Value::Content(Content::new("figure.caption").with_field("body", c)));
                }
            }
            if let Some(Value::Func(f)) = get_field(&fields, "kind") {
                if let Some(e) = f.elem() {
                    set_field(&mut fields, "kind", Value::Func(Func::Elem(e)));
                }
            }
        }
        "link" => {
            if get_field(&fields, "body").is_none() {
                match get_field(&fields, "dest") {
                    Some(Value::Str(s)) => {
                        let text = s.strip_prefix("mailto:").or_else(|| s.strip_prefix("tel:")).unwrap_or(&s).to_string();
                        set_field(&mut fields, "body", Value::Content(Content::text(&text)));
                    }
                    _ => return bail(span, "missing argument: body"),
                }
            }
        }
        "pad" => {
            let rest = remove_field(&mut fields, "rest");
            let x = remove_field(&mut fields, "x").or(rest.clone());
            let y = remove_field(&mut fields, "y").or(rest);
            for (side, axis) in [("left", &x), ("right", &x), ("top", &y), ("bottom", &y)] {
                if get_field(&fields, side).is_none() {
                    if let Some(v) = axis {
                        set_field(&mut fields, side, v.clone());
                    }
                }
            }
        }
        "square" => {
            if let Some(size) = remove_field(&mut fields, "size") {
                if get_field(&fields, "width").is_some() {
                    return bail(span, "unexpected argument: width");
                }
                if get_field(&fields, "height").is_some() {
                    return bail(span, "unexpected argument: height");
                }
                let rel = Ty::smart(Ty::Relative).cast(size).unwrap_or(Value::Auto);
                set_field(&mut fields, "width", rel.clone());
                set_field(&mut fields, "height", rel);
            }
        }
        "circle" => {
            if let Some(Value::Length(r)) = remove_field(&mut fields, "radius") {
                if get_field(&fields, "width").is_some() {
                    return bail(span, "unexpected argument: width");
                }
                if get_field(&fields, "height").is_some() {
                    return bail(span, "unexpected argument: height");
                }
                let d = Value::Relative(Relative::from_length(r.scale(2.0)));
                set_field(&mut fields, "width", d.clone());
                set_field(&mut fields, "height", d);
            }
        }
        "scale" => {
            if let Some(f) = remove_field(&mut fields, "factor") {
                if get_field(&fields, "x").is_none() {
                    set_field(&mut fields, "x", f.clone());
                }
                if get_field(&fields, "y").is_none() {
                    set_field(&mut fields, "y", f);
                }
            }
        }
        "block" => {
            if let Some(sp) = remove_field(&mut fields, "spacing") {
                if get_field(&fields, "above").is_none() {
                    set_field(&mut fields, "above", sp.clone());
                }
                if get_field(&fields, "below").is_none() {
                    set_field(&mut fields, "below", sp);
                }
            }
        }
        "par" => {
            if let Some(v) = get_field(&fields, "first-line-indent") {
                let converted = match v {
                    Value::Length(l) => {
                        let mut d: Dict = IndexMap::new();
                        d.insert("amount".into(), Value::Length(l));
                        Value::dict(d)
                    }
                    Value::Dict(d) => {
                        let mut out: Dict = IndexMap::new();
                        if let Some(a) = d.get("amount") {
                            out.insert("amount".into(), Ty::Length.cast(a.clone()).map_err(|e| vec![SourceDiagnostic::error(span, e)])?);
                        } else {
                            out.insert("amount".into(), pt(0.0));
                        }
                        if let Some(a) = d.get("all") {
                            out.insert("all".into(), Ty::Bool.cast(a.clone()).map_err(|e| vec![SourceDiagnostic::error(span, e)])?);
                        }
                        Value::dict(out)
                    }
                    other => return bail(span, format!("expected length or dictionary, found {}", other.ty().long_name())),
                };
                set_field(&mut fields, "first-line-indent", converted);
            }
        }
        "smartquote" => {
            if let Some(v) = get_field(&fields, "quotes") {
                set_field(&mut fields, "quotes", cast_quotes(v, span)?);
            }
        }
        "cite" => {
            if let Some(Value::Str(st)) = get_field(&fields, "style") {
                if !KNOWN_CSL.contains(&&*st) && !st.ends_with(".csl") {
                    return bail(span, format!("unknown style: {st}"));
                }
            }
        }
        "raw" => {
            if let Some(Value::Str(_)) = get_field(&fields, "theme") {
                return bail(span, "cannot access file system from here");
            }
            if let Some(Value::Str(_)) = get_field(&fields, "syntaxes") {
                return bail(span, "cannot access file system from here");
            }
            if let Some(Value::Array(a)) = get_field(&fields, "syntaxes") {
                if !a.is_empty() {
                    return bail(span, "cannot access file system from here");
                }
            }
        }
        "image" => {
            if let Some(Value::Str(_)) = get_field(&fields, "source") {
                return bail(span, "cannot access file system from here");
            }
        }
        "bibliography" => {
            return bail(span, "cannot access file system from here");
        }
        _ => {}
    }

    // Remove `none` positional optionals for `title`.
    if elem == "title" {
        if let Some(Value::None) = get_field(&fields, "body") {
            remove_field(&mut fields, "body");
        }
    }

    order_fields(&def, &mut fields);
    let mut c = Content::new(elem);
    for (k, v) in fields {
        c.set_field(&k, v);
    }
    Ok(c.with_span(span))
}

