/// Path of a source relative to the current directory, as displayed by Typst.
pub fn display_path(world: &World, file: u16) -> String {
    let source = world.source(file);
    match &source.real {
        Some(real) => {
            let cwd = std::env::current_dir().unwrap_or_default();
            let real = if real.is_absolute() { real.clone() } else { cwd.join(real) };
            match path_relative_from(&real, &cwd) {
                Some(rel) => rel.display().to_string(),
                None => real.display().to_string(),
            }
        }
        None => source.vpath.trim_start_matches('/').to_string(),
    }
}

fn path_relative_from(path: &std::path::Path, base: &std::path::Path) -> Option<std::path::PathBuf> {
    use std::path::Component;
    if path.is_absolute() != base.is_absolute() {
        return if path.is_absolute() { Some(path.to_path_buf()) } else { None };
    }
    let mut ita = path.components();
    let mut itb = base.components();
    let mut comps: Vec<Component> = vec![];
    loop {
        match (ita.next(), itb.next()) {
            (None, None) => break,
            (Some(a), None) => {
                comps.push(a);
                comps.extend(ita.by_ref());
                break;
            }
            (None, _) => comps.push(Component::ParentDir),
            (Some(a), Some(b)) if comps.is_empty() && a == b => (),
            (Some(a), Some(Component::CurDir)) => comps.push(a),
            (Some(_), Some(Component::ParentDir)) => return None,
            (Some(a), Some(_)) => {
                comps.push(Component::ParentDir);
                for _ in itb {
                    comps.push(Component::ParentDir);
                }
                comps.push(a);
                comps.extend(ita.by_ref());
                break;
            }
        }
    }
