}

fn render_rich(world: &World, d: &SourceDiagnostic, colors: bool, out: &mut String) {
    let blue = |s: &str| Style::new().fg(Color::Blue).paint(s, colors);
    let label_color = match d.severity {
        Severity::Error => Color::Red,
        Severity::Warning => Color::Yellow,
    };
    out.push_str(&message(d.severity, &d.message, colors));
    out.push('\n');

    let has_span = !d.span.is_detached() && (d.span.file as usize) < world.sources.len();
    if has_span {
        let source = world.source(d.span.file);
        let start = (d.span.start as usize).min(source.text.len());
        let end = (d.span.end as usize).min(source.text.len()).max(start);
