        out.push_str(&format!("{pad} {}\n", blue("│")));

        if start_line == end_line {
            let line_text = source.line_text(start_line);
            let line_start = source.line_starts[start_line];
            let before = &source.text[line_start..start];
            let marked = &source.text[start..end];
            let after_end = (line_start + line_text.len()).max(end);
            let after = &source.text[end..after_end];
