                if line == start_line {
                    let before = &source.text[line_start..start];
                    let marked = &source.text[start..line_start + line_text.len()];
                    let caret_offset: usize = before.chars().map(char_width).sum();
                    out.push_str(&format!(
                        "{lineno} {}   {}{}\n",
                        blue("│"),
                        before,
                        Style::new().fg(label_color).paint(marked, colors)
                    ));
                    out.push_str(&format!(
                        "{pad} {} {}\n",
                        blue("│"),
                        Style::new().fg(label_color).paint(&format!(" {}^", "_".repeat(caret_offset + 2)), colors)
                    ));
                } else if line == end_line {
                    let marked_end = end.min(line_start + line_text.len());
                    let marked = &source.text[line_start..marked_end];
                    let after = &source.text[marked_end..line_start + line_text.len()];
                    out.push_str(&format!(
                        "{lineno} {} {} {}{}\n",
                        blue("│"),
                        Style::new().fg(label_color).paint("│", colors),
                        Style::new().fg(label_color).paint(marked, colors),
                        after
                    ));
                    let w: usize = marked.chars().map(char_width).sum::<usize>().max(1);
                    out.push_str(&format!(
                        "{pad} {} {}\n",
                        blue("│"),
                        Style::new().fg(label_color).paint(&format!("│{}^", "_".repeat(w)), colors)
                    ));
                } else {
                    out.push_str(&format!(
                        "{lineno} {} {} {}\n",
                        blue("│"),
                        Style::new().fg(label_color).paint("│", colors),
                        Style::new().fg(label_color).paint(line_text, colors)
                    ));
                }
            }
        }
        if !d.hints.is_empty() {
            out.push_str(&format!("{pad} {}\n", blue("│")));
            for h in &d.hints {
                out.push_str(&format!("{pad} {} hint: {h}\n", blue("=")));
            }
        }
        out.push('\n');
        // Trace.
        for (span, point) in &d.trace {
            if span.is_detached() || (span.file as usize) >= world.sources.len() {
                continue;
            }
            let tsrc = world.source(span.file);
            let s = (span.start as usize).min(tsrc.text.len());
            let e = (span.end as usize).min(tsrc.text.len()).max(s);
            let line = tsrc.byte_to_line(s);
            let eline = tsrc.byte_to_line(e);
            let gw = (eline + 1).to_string().len();
            let tp = " ".repeat(gw);
            let path = display_path(world, span.file);
            let c = tsrc.byte_to_column(s) + 1;
            out.push_str(&message_with_label("help", point, colors));
            out.push('\n');
            out.push_str(&format!("{tp} {} {path}:{}:{}\n", blue("┌─"), line + 1, c));
            out.push_str(&format!("{tp} {}\n", blue("│")));
            if line == eline {
                let line_text = tsrc.line_text(line);
                let ls = tsrc.line_starts[line];
                let before = &tsrc.text[ls..s];
                let marked = &tsrc.text[s..e];
                let after = &tsrc.text[e..(ls + line_text.len()).max(e)];
                let lineno = blue(&format!("{:>width$}", line + 1, width = gw));
                out.push_str(&format!(
                    "{lineno} {} {}{}{}\n",
                    blue("│"),
                    before,
                    Style::new().fg(Color::Cyan).paint(marked, colors),
                    after
                ));
                let off: usize = before.chars().map(char_width).sum();
                let len: usize = marked.chars().map(char_width).sum::<usize>().max(1);
                out.push_str(&format!(
                    "{tp} {} {}{}\n",
                    blue("│"),
                    " ".repeat(off),
                    Style::new().fg(Color::Cyan).paint(&"^".repeat(len), colors)
                ));
            }
            out.push('\n');
        }
    } else {
        for h in &d.hints {
            out.push_str(&format!(" {} hint: {h}\n", blue("=")));
        }
        out.push('\n');
    }
}

fn message_with_label(label: &str, msg: &str, colors: bool) -> String {
    let l = Style::new().bold().fg(Color::Cyan).paint(label, colors);
    if colors {
        format!("{l}{}", Style::new().bold().paint(&format!(": {msg}"), true))
    } else {
        format!("{l}: {msg}")
    }
}

fn char_width(c: char) -> usize {
    if c == '\t' {
        4
    } else {
        unicode_width::UnicodeWidthChar::width(c).unwrap_or(0)
    }
}
