//! The `eval`, `compile` and `query` commands.

use std::path::{Path, PathBuf};
use std::rc::Rc;

use crate::eval::content::Content;
use crate::eval::value::*;
use crate::eval::vm::{bail, Result, Scopes, Severity, SourceDiagnostic, Vm};
use crate::syntax::ast::{ExprKind, Span};
use crate::syntax::lexer::LexMode;
use crate::syntax::parser;
use crate::world::World;

pub struct WorldArgs {
    pub root: Option<PathBuf>,
    pub inputs: Vec<(String, String)>,
    pub font_paths: Vec<PathBuf>,
    pub ignore_system_fonts: bool,
    pub ignore_embedded_fonts: bool,
    pub package_path: Option<PathBuf>,
    pub package_cache_path: Option<PathBuf>,
    pub creation_timestamp: Option<i64>,
    pub features: Vec<String>,
    pub diagnostic_format: String,
    pub target: String,
}

fn parse_errors_to_diags(errors: Vec<parser::SyntaxError>, file: u16) -> Vec<SourceDiagnostic> {
    errors
        .into_iter()
        .map(|e| {
            let mut d = SourceDiagnostic::error(e.span.with_file(file), e.message);
            d.hints = e.hints;
            d
        })
        .collect()
}

/// Evaluate a string of code (used by the `eval` function).
pub fn eval_string(vm: &mut Vm, text: &str, mode: &str, scope: Option<Dict>, span: Span) -> Result<Value> {
    let file = vm.world.add_source(format!("/<eval-{}>", vm.world.sources.len()), None, text.to_string());
    let lex_mode = match mode {
        "markup" => LexMode::Markup,
        "math" => LexMode::Math,
        _ => LexMode::Code,
    };
    let (exprs, errors) = match lex_mode {
        LexMode::Code => parser::parse_code(text),
        LexMode::Markup => {
            let (e, errs) = parser::parse_markup(text);
            (vec![e], errs)
        }
        LexMode::Math => {
            let (e, errs) = parser::parse_math(text);
            (vec![e], errs)
        }
    };
    if !errors.is_empty() {
        // Errors inside evaluated strings are reported at the call site.
        let _ = span;
        return Err(errors
            .into_iter()
            .map(|e| {
                let mut d = SourceDiagnostic::error(e.span.with_file(file), e.message);
                d.hints = e.hints;
                d
            })
            .collect());
    }

    let saved_scopes = std::mem::replace(&mut vm.scopes, Scopes::new(true));
    let saved_file = vm.file;
    let saved_flow = vm.flow.take();
    vm.file = file;
    if let Some(scope) = scope {
        for (k, v) in scope {
            vm.scopes.top.define(k, v);
        }
    }
    let result = match lex_mode {
        LexMode::Code => vm.eval_code(&exprs),
        LexMode::Markup => vm.eval_expr(&exprs[0]),
        LexMode::Math => match &exprs[0].kind {
            ExprKind::Math(items) => {
                let was = vm.in_math;
                vm.in_math = true;
                let r = vm.eval_math(items);
                vm.in_math = was;
                r.map(|body| {
                    Value::Content(
                        Content::new("equation")
                            .with_field("block", Value::Bool(false))
                            .with_field("body", body),
                    )
                })
            }
            _ => unreachable!(),
        },
    };
    let flow = vm.flow.take();
    vm.scopes = saved_scopes;
    vm.file = saved_file;
    vm.flow = saved_flow;
    let value = result?;
    if let Some(f) = flow {
        return Err(vec![f.forbidden()]);
    }
    Ok(value)
}

pub fn make_world(args: &WorldArgs, main_dir: &Path) -> World {
    let root = match &args.root {
        Some(r) => r.clone(),
        None => main_dir.to_path_buf(),
    };
    let root = if root.is_absolute() { root } else { std::env::current_dir().unwrap_or_default().join(root) };
    let mut world = World::new(root);
    world.inputs = args.inputs.clone();
    world.package_path = args.package_path.clone().or_else(crate::info::package_path);
    world.package_cache_path = args.package_cache_path.clone().or_else(crate::info::package_cache_path);
    world.creation_timestamp = args.creation_timestamp;
    world.features = args.features.clone();
    world.target = args.target.clone();
    world.font_paths = args.font_paths.clone();
    world.ignore_system_fonts = args.ignore_system_fonts;
    world.ignore_embedded_fonts = args.ignore_embedded_fonts;
    world
}

fn read_input(path: &Path) -> std::result::Result<String, String> {
    if path.as_os_str() == "-" {
        let mut s = String::new();
        std::io::Read::read_to_string(&mut std::io::stdin(), &mut s)
            .map_err(|e| format!("failed to read from stdin ({e})"))?;
        return Ok(s);
    }
    match std::fs::read(path) {
        Ok(bytes) => String::from_utf8(bytes).map_err(|_| format!("input file is not valid utf-8")),
        Err(e) => match e.kind() {
            std::io::ErrorKind::NotFound => Err(format!("input file not found (searched at {})", path.display())),
            std::io::ErrorKind::PermissionDenied => Err("failed to load input file (access denied)".into()),
            _ => {
                if path.is_dir() {
                    Err("failed to load input file (is a directory)".into())
                } else {
                    Err(format!("failed to load input file ({e})"))
                }
            }
        },
    }
}

/// Load the main source into the world.
fn load_main(world: &mut World, input: &Path) -> std::result::Result<u16, String> {
    let text = read_input(input)?;
    if input.as_os_str() == "-" {
        Ok(world.add_source("/<stdin>".into(), None, text))
    } else {
        let real = if input.is_absolute() { input.to_path_buf() } else { std::env::current_dir().unwrap_or_default().join(input) };
        let vpath = world.vpath_of(&real);
        if real.strip_prefix(&world.root).is_err() {
            return Err("source file must be contained in project root".into());
        }
        Ok(world.add_source(vpath, Some(real), text))
    }
}

fn print_diags(world: &World, diags: &[SourceDiagnostic], format: &str) {
    crate::diag::print_diagnostics(world, diags, format == "short");
}

fn serialize(v: &Value, format: &str, pretty: bool) -> String {
    match format {
        "yaml" => serde_yaml::to_string(v).unwrap_or_default(),
        _ => {
            if pretty {
                serde_json::to_string_pretty(v).unwrap_or_default()
            } else {
                serde_json::to_string(v).unwrap_or_default()
            }
        }
    }
}

/// Evaluate the document of a file, producing content and setting up the
/// introspector.
fn compile_document(world: &mut World, main: u16) -> Result<Content> {
    let text = world.source(main).text.clone();
    let (ast, errors) = parser::parse_markup(&text);
    if !errors.is_empty() {
        return Err(parse_errors_to_diags(errors, main));
    }
    let mut vm = Vm::new(world, main, Scopes::new(true));
    let content = match &ast.kind {
        ExprKind::Markup(exprs) => vm.eval_markup(exprs)?,
        _ => unreachable!(),
    };
    if let Some(flow) = vm.flow.take() {
        return Err(vec![flow.forbidden()]);
    }
    let _ = &mut vm;
    world.set_document(content.clone());
    Ok(content)
}

pub fn run_eval(
    expression: &str,
    input: Option<&Path>,
    format: &str,
    pretty: bool,
    wargs: &WorldArgs,
) -> i32 {
    let main_dir = match input {
        Some(p) if p.as_os_str() != "-" => {
            let abs = if p.is_absolute() { p.to_path_buf() } else { std::env::current_dir().unwrap_or_default().join(p) };
            abs.parent().map(|d| d.to_path_buf()).unwrap_or_default()
        }
        _ => std::env::current_dir().unwrap_or_default(),
    };
    let mut world = make_world(wargs, &main_dir);
    world.fs_allowed = input.is_some();

    // Load and compile the document if given.
    let main = match input {
        Some(p) => match load_main(&mut world, p) {
            Ok(id) => Some(id),
            Err(e) => {
                crate::term::print_error(&e);
                return 1;
            }
        },
        None => None,
    };

    if let Some(main) = main {
        if let Err(diags) = compile_document(&mut world, main) {
            print_diags(&world, &diags, &wargs.diagnostic_format);
            print_diags(&world, &world.warnings.clone(), &wargs.diagnostic_format);
            return 1;
        }
    }

    // Parse the expression.
    let file = world.add_source("/<eval>".into(), None, expression.to_string());
    let (exprs, errors) = parser::parse_code(expression);
    if !errors.is_empty() {
        let diags = parse_errors_to_diags(errors, file);
        print_diags(&world, &diags, &wargs.diagnostic_format);
        return 0;
    }

    let mut vm = Vm::new(&mut world, file, Scopes::new(true));
    if let Some(main) = main {
        // Make the document's module available? Not in typst; keep plain.
        let _ = main;
    }
    let result = vm.eval_code(&exprs);
    let flow = vm.flow.take();
    let result = match (result, flow) {
        (Ok(_), Some(f)) => Err(vec![f.forbidden()]),
        (r, _) => r,
    };
    match result {
        Ok(value) => {
            let s = serialize(&value, format, pretty);
            println!("{s}");
            let warnings = world.warnings.clone();
            print_diags(&world, &warnings, &wargs.diagnostic_format);
            0
        }
        Err(diags) => {
            print_diags(&world, &diags, &wargs.diagnostic_format);
            let warnings = world.warnings.clone();
            print_diags(&world, &warnings, &wargs.diagnostic_format);
            0
        }
    }
}

pub struct CompileArgs<'a> {
    pub input: &'a Path,
    pub output: Option<&'a Path>,
    pub format: Option<&'a str>,
    pub pages: Option<Vec<(usize, Option<usize>)>>,
    pub pdf_standards: Vec<String>,
    pub no_pdf_tags: bool,
    pub ppi: f32,
    pub deps: Option<&'a Path>,
    pub deps_format: &'a str,
    pub make_deps: Option<&'a Path>,
}

fn infer_format(path: &Path) -> Option<&'static str> {
    let ext = path.extension()?.to_str()?.to_lowercase();
    match ext.as_str() {
        "pdf" => Some("pdf"),
        "png" => Some("png"),
        "svg" => Some("svg"),
        "html" => Some("html"),
        _ => None,
    }
}

pub fn run_compile(args: &CompileArgs, wargs: &WorldArgs) -> i32 {
    let input = args.input;
    let stdin = input.as_os_str() == "-";
    let main_dir = if stdin {
        std::env::current_dir().unwrap_or_default()
    } else {
        let abs = if input.is_absolute() { input.to_path_buf() } else { std::env::current_dir().unwrap_or_default().join(input) };
        abs.parent().map(|d| d.to_path_buf()).unwrap_or_default()
    };

    // Determine output path and format.
    let (output, format): (PathBuf, &str) = match (args.output, args.format) {
        (Some(o), Some(f)) => (o.to_path_buf(), f),
        (Some(o), None) => {
            if o.as_os_str() == "-" {
                (o.to_path_buf(), "pdf")
            } else {
                match infer_format(o) {
                    Some(f) => (o.to_path_buf(), f),
                    None => {
                        crate::term::print_error(&format!(
                            "could not infer output format for path {}.\nconsider providing the format manually with `--format/-f`",
                            o.display()
                        ));
                        return 1;
                    }
                }
            }
        }
        (None, f) => {
            let f = f.unwrap_or("pdf");
            if stdin {
                (PathBuf::from("-"), f)
            } else {
                (input.with_extension(f), f)
            }
        }
    };

    if format == "html" && !wargs.features.iter().any(|f| f == "html") {
        let world = make_world(wargs, &main_dir);
        let d = SourceDiagnostic::error(Span::detached(), "html export is only available when `--features html` is passed")
            .with_hint("html export is under active development and incomplete")
            .with_hint("see https://github.com/typst/typst/issues/5512 for more information");
        print_diags(&world, &[d], &wargs.diagnostic_format);
        return 1;
    }

    let mut world = make_world(wargs, &main_dir);
    if format == "html" {
        world.target = "html".into();
    }
    let main = match load_main(&mut world, input) {
        Ok(id) => id,
        Err(e) => {
            crate::term::print_error(&e);
            return 1;
        }
    };

    if format == "html" {
        world.warnings.push(
            SourceDiagnostic::warning(Span::detached(), "html export is under active development and incomplete")
                .with_hint("its behaviour may change at any time")
                .with_hint("do not rely on this feature for production use cases")
                .with_hint("see https://github.com/typst/typst/issues/5512 for more information"),
        );
    }
    if args.pages.is_some() && format == "pdf" && !args.no_pdf_tags {
        world.warnings.push(
            SourceDiagnostic::warning(Span::detached(), "using --pages implies --no-pdf-tags")
                .with_hint("the resulting PDF will be inaccessible")
                .with_hint("add --no-pdf-tags to silence this warning"),
        );
    }

    let content = match compile_document(&mut world, main) {
        Ok(c) => c,
        Err(diags) => {
            let mut all = diags;
            all.extend(world.warnings.clone());
            print_diags(&world, &all, &wargs.diagnostic_format);
            return 1;
        }
    };

    // Export.
    let page_count = world.page_count();
    let selected: Vec<usize> = match &args.pages {
        None => (1..=page_count).collect(),
        Some(ranges) => {
            let mut v = Vec::new();
            for p in 1..=page_count {
                if ranges.iter().any(|(s, e)| p >= *s && e.is_none_or(|e| p <= e)) {
                    v.push(p);
                }
            }
            v
        }
    };

    let result: std::result::Result<Vec<PathBuf>, String> = match format {
        "pdf" => {
            let bytes = crate::export::pdf(&world, &content, &selected);
            write_output(&output, &bytes).map(|_| vec![output.clone()])
        }
        "html" => {
            let s = crate::export::html(&world, &content);
            write_output(&output, s.as_bytes()).map(|_| vec![output.clone()])
        }
        "svg" | "png" => {
            let out_str = output.to_string_lossy().to_string();
            let has_template = out_str.contains("{p}") || out_str.contains("{0p}") || out_str.contains("{t}");
            if selected.len() > 1 && !has_template && output.as_os_str() != "-" {
                Err("cannot export multiple images without a page number template ({p}, {0p}) in the output path".into())
            } else {
                let mut outputs = Vec::new();
                let width = page_count.to_string().len();
                let mut err = None;
                for (i, p) in selected.iter().enumerate() {
                    let path = if has_template {
                        PathBuf::from(
                            out_str
                                .replace("{p}", &p.to_string())
                                .replace("{0p}", &format!("{:0width$}", p, width = width))
                                .replace("{t}", &page_count.to_string()),
                        )
                    } else {
                        output.clone()
                    };
                    let bytes = if format == "svg" {
                        crate::export::svg(&world, &content, *p).into_bytes()
                    } else {
                        crate::export::png(&world, &content, *p, args.ppi)
                    };
                    if let Err(e) = write_output(&path, &bytes) {
                        err = Some(e);
                        break;
                    }
                    outputs.push(path);
                    if output.as_os_str() == "-" && i + 1 < selected.len() {
                        // Only the first page is written to stdout.
                        break;
                    }
                }
                match err {
                    Some(e) => Err(e),
                    None => Ok(outputs),
                }
            }
        }
        _ => Err(format!("unsupported format {format}")),
    };

    let outputs = match result {
        Ok(o) => o,
        Err(e) => {
            let d = SourceDiagnostic::error(Span::detached(), e);
            print_diags(&world, &[d], &wargs.diagnostic_format);
            return 1;
        }
    };

    // Dependencies.
    if let Some(deps) = args.deps {
        let inputs: Vec<String> = world
            .sources
            .iter()
            .filter_map(|s| s.real.as_ref())
            .map(|p| relative_display(p))
            .collect();
        let outs: Vec<String> = outputs.iter().map(|p| if p.is_absolute() { p.display().to_string() } else { p.display().to_string() }).collect();
        let text = match args.deps_format {
            "make" => {
                let mut s = String::new();
                for o in &outs {
                    s.push_str(&format!("{}:", o.replace(' ', "\\ ")));
                    for i in &inputs {
                        s.push_str(&format!(" {}", i.replace(' ', "\\ ")));
                    }
                    s.push('\n');
                }
                s
            }
            "zero" => {
                let mut s = String::new();
                for i in &inputs {
                    s.push_str(i);
                    s.push('\0');
                }
                s.push('\0');
                for o in &outs {
                    s.push_str(o);
                    s.push('\0');
                }
                s
            }
            _ => serde_json::json!({ "inputs": inputs, "outputs": outs }).to_string(),
        };
        if deps.as_os_str() == "-" {
            print!("{text}");
        } else if let Err(e) = std::fs::write(deps, text) {
            crate::term::print_error(&format!("failed to write dependencies file ({e})"));
            return 1;
        }
    }
    if let Some(md) = args.make_deps {
        let inputs: Vec<String> = world.sources.iter().filter_map(|s| s.real.as_ref()).map(|p| relative_display(p)).collect();
        let mut s = String::new();
        for o in &outputs {
            s.push_str(&format!("{}:", o.display()));
            for i in &inputs {
                s.push_str(&format!(" {i}"));
            }
            s.push('\n');
        }
        let _ = std::fs::write(md, s);
    }

    let warnings = world.warnings.clone();
    print_diags(&world, &warnings, &wargs.diagnostic_format);
    0
}

fn relative_display(p: &Path) -> String {
    let cwd = std::env::current_dir().unwrap_or_default();
    match p.strip_prefix(&cwd) {
        Ok(rel) => rel.display().to_string(),
        Err(_) => p.display().to_string(),
    }
}

fn write_output(path: &Path, bytes: &[u8]) -> std::result::Result<(), String> {
    if path.as_os_str() == "-" {
        use std::io::Write;
        let mut out = std::io::stdout();
        out.write_all(bytes).map_err(|e| format!("failed to write to stdout ({e})"))?;
        out.flush().ok();
        return Ok(());
    }
    std::fs::write(path, bytes).map_err(|e| format!("failed to write {} ({e})", path.display()))
}

pub fn run_query(
    input: &Path,
    selector: &str,
    field: Option<&str>,
    one: bool,
    format: &str,
    pretty: bool,
    wargs: &WorldArgs,
) -> i32 {
    let abs = if input.is_absolute() { input.to_path_buf() } else { std::env::current_dir().unwrap_or_default().join(input) };
    let main_dir = if input.as_os_str() == "-" {
        std::env::current_dir().unwrap_or_default()
    } else {
        abs.parent().map(|d| d.to_path_buf()).unwrap_or_default()
    };
    let mut world = make_world(wargs, &main_dir);
    let main = match load_main(&mut world, input) {
        Ok(id) => id,
        Err(e) => {
            crate::term::print_error(&e);
            return 1;
        }
    };
    let deprecation = {
        let mut expr = format!("query({selector})");
        if let Some(f) = field {
            expr = format!("{expr}.map(it => it.{f})");
        }
        if one {
            expr = format!("{expr}.first()");
        }
        SourceDiagnostic::warning(Span::detached(), "the `typst query` subcommand is deprecated")
            .with_hint(format!("use `typst eval '{expr}' --in {}` instead", input.display()))
    };
    if let Err(diags) = compile_document(&mut world, main) {
        let mut all = diags;
        all.extend(world.warnings.clone());
        all.push(deprecation);
        print_diags(&world, &all, &wargs.diagnostic_format);
        return 1;
    }

    // Evaluate the selector.
    let file = world.add_source("/<selector>".into(), None, selector.to_string());
    let (exprs, errors) = parser::parse_code(selector);
    if !errors.is_empty() {
        let diags = parse_errors_to_diags(errors, file);
        print_diags(&world, &diags, &wargs.diagnostic_format);
        return 1;
    }
    let mut vm = Vm::new(&mut world, file, Scopes::new(true));
    let value = match vm.eval_code(&exprs) {
        Ok(v) => v,
        Err(diags) => {
            print_diags(&world, &diags, &wargs.diagnostic_format);
            return 1;
        }
    };
    let sel = match crate::library::cast_selector(&value, false) {
        Ok(s) => s,
        Err(e) => {
            let d = SourceDiagnostic::error(Span::new(0, selector.len()).with_file(file), e);
            print_diags(&world, &[d], &wargs.diagnostic_format);
            return 1;
        }
    };
    let results = world.introspector_query(&sel);
    let mut values: Vec<Value> = Vec::new();
    for c in results {
        match field {
            Some(f) => match crate::library::content_field(&c, f) {
                Ok(v) => values.push(v),
                Err(e) => {
                    let d = SourceDiagnostic::error(Span::detached(), e);
                    print_diags(&world, &[d], &wargs.diagnostic_format);
                    return 1;
                }
            },
            None => values.push(Value::Content(c)),
        }
    }
    let out = if one {
        match values.len() {
            1 => values.pop().unwrap(),
            n => {
                let d = SourceDiagnostic::error(Span::detached(), format!("expected exactly one element, found {n}"));
                print_diags(&world, &[d], &wargs.diagnostic_format);
                return 1;
            }
        }
    } else {
        Value::array(values)
    };
    println!("{}", serialize(&out, format, pretty));
    let mut warnings = world.warnings.clone();
    warnings.push(deprecation);
    print_diags(&world, &warnings, &wargs.diagnostic_format);
    0
}

