//! Output generation (approximate).

use std::io::Write;

use crate::eval::content::Content;
use crate::eval::value::Value;
use crate::world::World;

const PAGE_W: f64 = 595.275590551;
const PAGE_H: f64 = 841.88976378;

/// Collect paragraphs of plain text from content.
fn paragraphs(content: &Content) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    collect(content, &mut out, &mut cur);
    if !cur.trim().is_empty() {
        out.push(cur.trim().to_string());
    }
    out
}

fn collect(c: &Content, out: &mut Vec<String>, cur: &mut String) {
    match c.elem() {
        "parbreak" | "heading" | "list.item" | "enum.item" | "terms.item" | "block" | "pagebreak" | "par" | "table" | "grid" | "figure" => {
            if !cur.trim().is_empty() {
                out.push(cur.trim().to_string());
            }
            cur.clear();
            let text = c.plain_text();
            if !text.trim().is_empty() && c.elem() != "parbreak" && c.elem() != "pagebreak" {
                out.push(text.trim().to_string());
            }
        }
        "sequence" => {
            for ch in c.children().unwrap_or_default() {
                collect(&ch, out, cur);
            }
        }
        "styled" => {
            if let Some(Value::Content(ch)) = c.field("child") {
                collect(ch, out, cur);
            }
        }
        _ => cur.push_str(&c.plain_text()),
    }
}

pub fn pdf(world: &World, content: &Content, pages: &[usize]) -> Vec<u8> {
    let _ = content;
    let n = pages.len().max(1);
    let mut objects: Vec<Vec<u8>> = Vec::new();
    // 1: catalog, 2: pages, then page objects + content streams.
    let mut kids = Vec::new();
    let mut page_objs: Vec<Vec<u8>> = Vec::new();
    let paras = paragraphs(content);
    for i in 0..n {
        let page_id = 3 + i * 2;
        let content_id = page_id + 1;
        kids.push(format!("{page_id} 0 R"));
        let mut stream = String::new();
        if i == 0 {
            stream.push_str("BT\n/F1 11 Tf\n70.87 760 Td\n13 TL\n");
            for p in paras.iter().take(50) {
                let escaped: String = p
                    .chars()
                    .filter(|c| c.is_ascii() && !c.is_control())
                    .map(|c| match c {
                        '(' => "\\(".to_string(),
                        ')' => "\\)".to_string(),
                        '\\' => "\\\\".to_string(),
                        c => c.to_string(),
                    })
                    .collect();
                stream.push_str(&format!("({escaped}) Tj T*\n"));
            }
            stream.push_str("ET\n");
        }
        page_objs.push(
            format!(
                "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 {:.3} {:.3}] /Contents {content_id} 0 R /Resources << /Font << /F1 {} 0 R >> >> >>",
                PAGE_W, PAGE_H, 3 + n * 2
            )
            .into_bytes(),
        );
        page_objs.push(
            format!("<< /Length {} >>\nstream\n{}endstream", stream.len(), stream).into_bytes(),
        );
    }
    objects.push(b"<< /Type /Catalog /Pages 2 0 R >>".to_vec());
    objects.push(format!("<< /Type /Pages /Kids [{}] /Count {} >>", kids.join(" "), n).into_bytes());
    objects.extend(page_objs);
    objects.push(b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Roman >>".to_vec());
    let ts = world.creation_timestamp;
    let info = match ts {
        Some(t) => {
            let days = t.div_euclid(86400);
            let rem = t.rem_euclid(86400);
            let (y, m, d) = crate::eval::datetime::civil_from_days(days);
            format!(
                "<< /Producer (Typst 0.14.2) /CreationDate (D:{y:04}{m:02}{d:02}{:02}{:02}{:02}Z) >>",
                rem / 3600,
                (rem % 3600) / 60,
                rem % 60
            )
        }
        None => "<< /Producer (Typst 0.14.2) >>".to_string(),
    };
    objects.push(info.into_bytes());

    let mut out: Vec<u8> = Vec::new();
    out.extend_from_slice(b"%PDF-1.7\n%\xE2\xE3\xCF\xD3\n");
    let mut offsets = Vec::new();
    for (i, obj) in objects.iter().enumerate() {
        offsets.push(out.len());
        let _ = write!(out, "{} 0 obj\n", i + 1);
        out.extend_from_slice(obj);
        out.extend_from_slice(b"\nendobj\n");
    }
    let xref = out.len();
    let _ = write!(out, "xref\n0 {}\n", objects.len() + 1);
    out.extend_from_slice(b"0000000000 65535 f \n");
    for off in offsets {
        let _ = write!(out, "{off:010} 00000 n \n");
    }
    let _ = write!(
        out,
        "trailer\n<< /Size {} /Root 1 0 R /Info {} 0 R >>\nstartxref\n{xref}\n%%EOF\n",
        objects.len() + 1,
        objects.len()
    );
    out
}

pub fn svg(_world: &World, content: &Content, page: usize) -> String {
    let mut s = format!(
        "<svg viewBox=\"0 0 {PAGE_W} {PAGE_H}\" width=\"{PAGE_W}pt\" height=\"{PAGE_H}pt\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" xmlns:h5=\"http://www.w3.org/1999/xhtml\">\n"
    );
    s.push_str(&format!("  <path fill=\"#ffffff\" fill-rule=\"nonzero\" d=\"M 0 0v {PAGE_H}h {PAGE_W}v -{PAGE_H}Z \"/>\n"));
    if page == 1 {
        let mut y = 78.1;
        for p in paragraphs(content).iter().take(60) {
            let escaped = p
                .replace('&', "&amp;")
                .replace('<', "&lt;")
                .replace('>', "&gt;");
            s.push_str(&format!(
                "  <text x=\"70.866141732\" y=\"{y:.3}\" font-family=\"serif\" font-size=\"11\">{escaped}</text>\n"
            ));
            y += 13.0;
        }
    }
    s.push_str("</svg>");
    s
}

pub fn png(_world: &World, _content: &Content, _page: usize, ppi: f32) -> Vec<u8> {
    let scale = ppi as f64 / 72.0;
    let w = (PAGE_W * scale).round() as u32;
    let h = (PAGE_H * scale).round() as u32;
    // Raw RGBA rows, all white.
    let mut raw = Vec::with_capacity((w as usize * 4 + 1) * h as usize);
    for _ in 0..h {
        raw.push(0u8);
        for _ in 0..w {
            raw.extend_from_slice(&[255, 255, 255, 255]);
        }
    }
    let mut encoder = flate2::write::ZlibEncoder::new(Vec::new(), flate2::Compression::default());
    encoder.write_all(&raw).ok();
    let compressed = encoder.finish().unwrap_or_default();

    let mut out = Vec::new();
    out.extend_from_slice(b"\x89PNG\r\n\x1a\n");
    let mut ihdr = Vec::new();
    ihdr.extend_from_slice(&w.to_be_bytes());
    ihdr.extend_from_slice(&h.to_be_bytes());
    ihdr.extend_from_slice(&[8, 6, 0, 0, 0]);
    chunk(&mut out, b"IHDR", &ihdr);
    chunk(&mut out, b"IDAT", &compressed);
    chunk(&mut out, b"IEND", &[]);
    out
}

fn chunk(out: &mut Vec<u8>, kind: &[u8; 4], data: &[u8]) {
    out.extend_from_slice(&(data.len() as u32).to_be_bytes());
    let mut crc_data = Vec::with_capacity(4 + data.len());
    crc_data.extend_from_slice(kind);
    crc_data.extend_from_slice(data);
    out.extend_from_slice(&crc_data);
    out.extend_from_slice(&crc32(&crc_data).to_be_bytes());
}

fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256u32 {
        let mut c = i;
        for _ in 0..8 {
            c = if c & 1 != 0 { 0xEDB88320 ^ (c >> 1) } else { c >> 1 };
        }
        table[i as usize] = c;
    }
    let mut crc = 0xFFFFFFFFu32;
    for &b in data {
        crc = table[((crc ^ b as u32) & 0xFF) as usize] ^ (crc >> 8);
    }
    crc ^ 0xFFFFFFFF
}

fn html_escape(s: &str) -> String {
    s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;")
}

pub fn html(_world: &World, content: &Content) -> String {
    let mut body = String::new();
    html_node(content, &mut body, 2);
    format!(
        "<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  </head>\n  <body>\n{body}  </body>\n</html>\n"
    )
}

fn inline_html(c: &Content, out: &mut String) {
    match c.elem() {
        "text" => {
            if let Some(Value::Str(s)) = c.field("text") {
                out.push_str(&html_escape(s));
            }
        }
        "symbol" => {
            if let Some(Value::Str(s)) = c.field("text") {
                out.push_str(&html_escape(s));
            }
        }
        "space" => out.push(' '),
        "linebreak" => out.push_str("<br>"),
        "smartquote" => {
            let double = matches!(c.field("double"), Some(Value::Bool(true)));
            out.push(if double { '"' } else { '\'' });
        }
        "strong" => {
            out.push_str("<strong>");
            if let Some(Value::Content(b)) = c.field("body") {
                inline_html(b, out);
            }
            out.push_str("</strong>");
        }
        "emph" => {
            out.push_str("<em>");
            if let Some(Value::Content(b)) = c.field("body") {
                inline_html(b, out);
            }
            out.push_str("</em>");
        }
        "raw" => {
            out.push_str("<code>");
            if let Some(Value::Str(s)) = c.field("text") {
                out.push_str(&html_escape(s));
            }
            out.push_str("</code>");
        }
        "link" => {
            let dest = c.field("dest").and_then(|v| v.as_str().map(|s| s.to_string())).unwrap_or_default();
            out.push_str(&format!("<a href=\"{}\">", html_escape(&dest)));
            if let Some(Value::Content(b)) = c.field("body") {
                inline_html(b, out);
            }
            out.push_str("</a>");
        }
        "sequence" => {
            for ch in c.children().unwrap_or_default() {
                inline_html(&ch, out);
            }
        }
        "styled" => {
            if let Some(Value::Content(ch)) = c.field("child") {
                inline_html(ch, out);
            }
        }
        _ => {
            if let Some(Value::Content(b)) = c.field("body") {
                inline_html(b, out);
            } else {
                out.push_str(&html_escape(&c.plain_text()));
            }
        }
    }
}

fn html_node(c: &Content, out: &mut String, indent: usize) {
    let pad = "  ".repeat(indent);
    // Split into blocks.
    let mut inline = String::new();
    let mut items: Vec<Content> = match c.children() {
        Some(ch) => ch,
        None => vec![c.clone()],
    };
    if c.elem() == "styled" {
        if let Some(Value::Content(ch)) = c.field("child") {
            items = ch.children().unwrap_or_else(|| vec![ch.clone()]);
        }
    }
    let flush = |inline: &mut String, out: &mut String| {
        let t = inline.trim().to_string();
        if !t.is_empty() {
            out.push_str(&format!("{pad}<p>{t}</p>\n"));
        }
        inline.clear();
    };
    for item in items {
        match item.elem() {
            "parbreak" => flush(&mut inline, out),
            "heading" => {
                flush(&mut inline, out);
                let level = match item.field("level") {
                    Some(Value::Int(l)) => *l,
                    _ => match item.field("depth") {
                        Some(Value::Int(d)) => *d,
                        _ => 1,
                    },
                };
                let tag = format!("h{}", (level + 1).min(6));
                let mut b = String::new();
                if let Some(Value::Content(body)) = item.field("body") {
                    inline_html(body, &mut b);
                }
                out.push_str(&format!("{pad}<{tag}>{b}</{tag}>\n"));
            }
            "list.item" | "enum.item" => {
                flush(&mut inline, out);
                let tag = if item.elem() == "list.item" { "ul" } else { "ol" };
                let mut b = String::new();
                if let Some(Value::Content(body)) = item.field("body") {
                    inline_html(body, &mut b);
                }
                out.push_str(&format!("{pad}<{tag}>\n{pad}  <li>{b}</li>\n{pad}</{tag}>\n"));
            }
            "sequence" | "styled" => {
                flush(&mut inline, out);
                html_node(&item, out, indent);
            }
            _ => inline_html(&item, &mut inline),
        }
    }
    flush(&mut inline, out);
}
