use crate::eval::content::Content;
use crate::eval::value::{Dynamic, Location, Selector, Value};

fn locatable(name: &str) -> bool {
    matches!(
        name,
        "heading" | "figure" | "equation" | "footnote" | "ref" | "cite" | "metadata" | "quote"
            | "link" | "raw" | "list.item" | "enum.item" | "terms.item" | "table" | "grid"
            | "image" | "list" | "enum" | "terms" | "outline" | "title" | "par" | "bibliography"
            | "pagebreak" | "strong" | "emph" | "counter.update" | "state.update" | "figure.caption"
            | "table.cell" | "grid.cell" | "block" | "box" | "place" | "footnote.entry"
    )
}

fn collect_elems(c: &Content, out: &mut Vec<Content>, counter: &mut u64, styles: &mut Vec<(String, String, Value)>) {
    match c.elem() {
        "sequence" => {
            for ch in c.children().unwrap_or_default() {
                collect_elems(&ch, out, counter, styles);
            }
        }
        "styled" => {
            let mut added = 0;
            if let Some(Value::Styles(s)) = c.field("styles") {
                for rule in &s.rules {
                    if let crate::eval::value::StyleRule::Set { elem, fields } = rule {
                        for (k, v) in fields {
                            styles.push((elem.to_string(), k.clone(), v.clone()));
                            added += 1;
                        }
                    }
                }
            }
            if let Some(Value::Content(ch)) = c.field("child") {
                collect_elems(ch, out, counter, styles);
            }
            for _ in 0..added {
                styles.pop();
            }
        }
        name => {
            let mut c = c.clone();
            if locatable(name) {
                *counter += 1;
                c.set_location(Location { id: *counter });
                synthesize(&mut c, styles);
                out.push(c.clone());
            }
            // Recurse into children fields.
            for (_, v) in c.fields().to_vec() {
                match v {
                    Value::Content(ch) => collect_elems(&ch, out, counter, styles),
                    Value::Array(a) => {
                        for item in a.iter() {
                            if let Value::Content(ch) = item {
                                collect_elems(ch, out, counter, styles);
                            }
                        }
                    }
                    _ => {}
                }
            }
        }
    }
}

/// Fill in default fields for queried elements.
fn synthesize(c: &mut Content, styles: &[(String, String, Value)]) {
    let name = c.elem();
    let Some(def) = crate::library::elements::get(name) else { return };
    let get_style = |field: &str| -> Option<Value> {
        styles.iter().rev().find(|(e, k, _)| e == name && k == field).map(|(_, _, v)| v.clone())
    };
    let mut fields: Vec<(String, Value)> = c.fields().to_vec();
    for p in &def.params {
        if matches!(p.kind, crate::library::elements::Kind::Required | crate::library::elements::Kind::Variadic) {
            continue;
        }
        if p.name == "body" || fields.iter().any(|(n, _)| n == p.name) {
            continue;
        }
        if let Some(v) = get_style(p.name) {
            fields.push((p.name.to_string(), v));
        } else if let Some(d) = &p.default {
            if name == "heading" && p.name == "level" {
                continue;
            }
            fields.push((p.name.to_string(), d.clone()));
        }
    }
    if name == "heading" {
        if !fields.iter().any(|(n, _)| n == "level") {
            let depth = fields.iter().find(|(n, _)| n == "depth").map(|(_, v)| match v { Value::Int(i) => *i, _ => 1 }).unwrap_or(1);
            let offset = fields.iter().find(|(n, _)| n == "offset").map(|(_, v)| match v { Value::Int(i) => *i, _ => 0 }).unwrap_or(0);
            fields.push(("level".into(), Value::Int(depth + offset)));
        }
        if let Some(slot) = fields.iter_mut().find(|(n, _)| n == "supplement") {
            if matches!(slot.1, Value::Auto) {
                slot.1 = Value::Content(Content::text("Section"));
            }
        }
    }
    if name == "figure" {
        if let Some(slot) = fields.iter_mut().find(|(n, _)| n == "kind") {
            if matches!(slot.1, Value::Auto) {
                slot.1 = Value::Func(crate::eval::value::Func::Elem("image"));
            }
        }
        if let Some(slot) = fields.iter_mut().find(|(n, _)| n == "supplement") {
            if matches!(slot.1, Value::Auto) {
                slot.1 = Value::Content(Content::text("Figure"));
            }
        }
    }
    fields.sort_by_key(|(n, _)| def.params.iter().position(|p| p.name == n).unwrap_or(usize::MAX));
    let label = c.label().cloned();
    let loc = c.location();
    let mut out = Content::new(name);
    for (k, v) in fields {
        out.set_field(&k, v);
    }
    if let Some(l) = label {
        out.set_label(l);
    }
    if let Some(l) = loc {
        out.set_location(l);
    }
    *c = out;
}

fn matches_selector(c: &Content, s: &Selector, all: &[Content]) -> bool {
    match s {
        Selector::Elem(name, fields) => {
            if c.elem() != *name {
                return false;
            }
            match fields {
                Some(f) => f.iter().all(|(k, v)| c.field(k).is_some_and(|cv| crate::eval::ops::equal(cv, v))),
                None => true,
            }
        }
        Selector::Label(l) => c.label().is_some_and(|cl| cl == l),
        Selector::Regex(_) | Selector::Str(_) => false,
        Selector::Or(items) => items.iter().any(|i| matches_selector(c, i, all)),
        Selector::And(items) => items.iter().all(|i| matches_selector(c, i, all)),
        Selector::Before { selector, .. } | Selector::After { selector, .. } => matches_selector(c, selector, all),
        Selector::Location(l) => c.location() == Some(*l),
    }
}
