fn parse_page_range(s: &str) -> Result<(usize, Option<usize>), String> {
    let s = s.trim();
    let parse = |p: &str| -> Result<usize, String> {
        match p.trim().parse::<usize>() {
            Ok(0) => Err("page numbers start at one".into()),
            Ok(n) => Ok(n),
            Err(_) => Err("not a valid page number".into()),
        }
    };
    if let Some((a, b)) = s.split_once('-') {
        let start = if a.trim().is_empty() { 1 } else { parse(a)? };
        let end = if b.trim().is_empty() { None } else { Some(parse(b)?) };
        if let Some(e) = end {
            if e < start {
                return Err("page ranges must be ascending".into());
            }
        }
        Ok((start, end))
    } else {
        let n = parse(s)?;
        Ok((n, Some(n)))
    }
}

fn world_args(sub: &clap::ArgMatches) -> compile::WorldArgs {
