        .map(|v| {
            v.filter_map(|kv| kv.split_once('=').map(|(k, v)| (k.to_string(), v.to_string())))
                .collect()
        })
        .unwrap_or_default();
    compile::WorldArgs {
        root: sub.try_get_one::<PathBuf>("root").ok().flatten().cloned(),
        inputs,
        font_paths: sub
            .try_get_many::<PathBuf>("font-path")
