        ignore_embedded_fonts: sub.try_get_one::<bool>("ignore-embedded-fonts").ok().flatten().copied().unwrap_or(false),
        package_path: sub.try_get_one::<PathBuf>("package-path").ok().flatten().cloned(),
        package_cache_path: sub.try_get_one::<PathBuf>("package-cache-path").ok().flatten().cloned(),
        creation_timestamp: sub.try_get_one::<i64>("creation-timestamp").ok().flatten().copied(),
        features: sub
