        let mut errors: Vec<SyntaxError> = self.errors.into_iter().flatten().collect();
        errors.sort_by_key(|e| e.span.start);
        errors
    }

    // --- Node tracking (mirrors the structure of the syntax tree) ---

    fn marker(&self) -> usize {
        self.nodes.len()
    }

    fn before_trivia(&self) -> usize {
        let mut i = self.nodes.len();
        while i > 0 && matches!(self.nodes[i - 1], Node::Leaf { trivia: true }) {
            i -= 1;
        }
        i
    }

    /// Wrap the nodes from `m` until before the trailing trivia into one node.
    fn wrap(&mut self, m: usize) {
        let to = self.before_trivia();
        if m > to {
            return;
        }
        let tail = self.nodes.split_off(to);
        self.nodes.truncate(m);
        self.nodes.push(Node::Inner);
        self.nodes.extend(tail);
    }

    fn push_error_node(&mut self, at: usize, err: SyntaxError, empty: bool) {
        let idx = self.errors.len();
        self.errors.push(Some(err));
        let at = at.min(self.nodes.len());
        self.nodes.insert(at, Node::Error { idx, empty });
    }

    /// Convert the node at `m` into an error.
    fn convert_node_to_error(&mut self, m: usize, err: SyntaxError) {
        let idx = self.errors.len();
        self.errors.push(Some(err));
        if m < self.nodes.len() {
            self.nodes[m] = Node::Error { idx, empty: false };
        } else {
            self.nodes.push(Node::Error { idx, empty: false });
        }
