impl World {
    /// Check references, links and citations in the document.
    pub fn validate_document(&self) -> Vec<SourceDiagnostic> {
        let mut diags = Vec::new();
        let has_bib = self.elements.iter().any(|e| e.elem() == "bibliography");
        for e in &self.elements {
            match e.elem() {
                "ref" => {
                    let Some(Value::Label(target)) = e.field("target") else { continue };
                    let matches: Vec<&Content> =
                        self.elements.iter().filter(|c| c.label().is_some_and(|l| l == target)).collect();
                    match matches.len() {
                        0 => {
                            if has_bib {
                                continue;
                            }
                            diags.push(SourceDiagnostic::error(
                                e.span(),
                                format!("label `<{target}>` does not exist in the document"),
                            ));
                        }
                        1 => {
                            let t = matches[0];
                            let numbering_none = |c: &Content| matches!(c.field("numbering"), None | Some(Value::None));
                            match t.elem() {
                                "heading" => {
                                    if numbering_none(t) {
                                        diags.push(
                                            SourceDiagnostic::error(e.span(), "cannot reference heading without numbering")
                                                .with_hint("you can enable heading numbering with `#set heading(numbering: \"1.\")`"),
                                        );
                                    }
                                }
                                "equation" => {
                                    if numbering_none(t) {
                                        diags.push(
                                            SourceDiagnostic::error(e.span(), "cannot reference equation without numbering")
                                                .with_hint("you can enable equation numbering with `#set math.equation(numbering: \"1.\")`"),
                                        );
                                    }
                                }
                                "figure" => {
                                    if numbering_none(t) {
                                        diags.push(SourceDiagnostic::error(
                                            e.span(),
                                            "cannot reference figure without numbering",
                                        ));
                                    }
                                }
                                "footnote" => {}
                                other => {
                                    let name = other.rsplit('.').next().unwrap_or(other);
                                    diags.push(SourceDiagnostic::error(e.span(), format!("cannot reference {name}")));
                                }
                            }
                        }
                        _ => {
                            diags.push(SourceDiagnostic::error(
                                e.span(),
                                format!("label `<{target}>` occurs multiple times in the document"),
                            ));
                        }
                    }
                }
                "link" => {
                    if let Some(Value::Label(target)) = e.field("dest") {
                        let n = self.elements.iter().filter(|c| c.label().is_some_and(|l| l == target)).count();
                        if n == 0 {
                            diags.push(SourceDiagnostic::error(
                                e.span(),
                                format!("label `<{target}>` does not exist in the document"),
                            ));
                        } else if n > 1 {
                            diags.push(SourceDiagnostic::error(
                                e.span(),
                                format!("label `<{target}>` occurs multiple times in the document"),
                            ));
                        }
                    }
                }
                "cite" => {
                    if !has_bib {
                        diags.push(SourceDiagnostic::error(e.span(), "the document does not contain a bibliography"));
                    }
                }
                _ => {}
            }
        }
        diags
    }
}
