// ------------------------------------------------------------ Realization

/// Walk the document, evaluating context blocks and show-rule transforms to
/// surface errors that would occur during layout.
fn realize(vm: &mut Vm, content: &Content, styles: &mut Vec<Value>, depth: usize) -> Result<()> {
    if depth > 64 {
        return Ok(());
    }
    match content.elem() {
        "sequence" => {
            for ch in content.children().unwrap_or_default() {
                realize(vm, &ch, styles, depth)?;
            }
        }
        "styled" => {
            let mut added = 0;
            if let Some(Value::Styles(s)) = content.field("styles") {
                for rule in &s.rules {
                    if let StyleRule::Show { selector, transform } = rule {
                        styles.push(Value::array(vec![
                            match selector {
                                Some(sel) => Value::dynamic(Dynamic::Selector(sel.clone())),
                                None => Value::None,
                            },
                            transform.clone(),
                        ]));
                        added += 1;
                    }
                }
            }
            let r = match content.field("child") {
                Some(Value::Content(ch)) => realize(vm, ch, styles, depth),
                _ => Ok(()),
            };
            for _ in 0..added {
                styles.pop();
            }
            r?;
        }
        "context" => {
            if let Some(Value::Func(f)) = content.field("__func") {
                let saved = vm.context.clone();
                vm.context.introspect = true;
                vm.context.location = Some(Location { id: u64::MAX });
                let span = content.span();
                let result = vm.call_func(f, Args::new(span, vec![]), span);
                vm.context = saved;
                let value = result?;
                let out = crate::eval::vm::display(value);
                realize(vm, &out, styles, depth + 1)?;
            }
        }
        name => {
            // Apply matching show rules (innermost first).
            for rule in styles.clone().iter().rev() {
                let Value::Array(pair) = rule else { continue };
                let (sel, transform) = (&pair[0], &pair[1]);
                let Value::Func(f) = transform else { continue };
                let it = match sel {
                    Value::Dyn(d) => match &**d {
                        Dynamic::Selector(sel) => match_show_target(content, sel),
                        _ => None,
                    },
                    _ => None,
                };
                if let Some(it) = it {
                    let span = content.span();
                    let result = vm.call_func(f, Args::new(span, vec![Value::Content(it)]), span);
                    let value = result.map_err(|mut errs| {
                        let short = name.rsplit('.').next().unwrap_or(name);
                        for e in &mut errs {
                            if e.severity == Severity::Error && !span.is_detached() {
                                e.trace.push((span, format!("error occurred while applying show rule to this {short}")));
                            }
                        }
                        errs
                    })?;
                    let out = crate::eval::vm::display(value);
                    let mut inner: Vec<Value> = Vec::new();
                    realize(vm, &out, &mut inner, depth + 1)?;
                }
            }
            // Recurse into content fields.
            for (_, v) in content.fields() {
                match v {
                    Value::Content(ch) => realize(vm, ch, styles, depth)?,
                    Value::Array(a) => {
                        for item in a.iter() {
                            if let Value::Content(ch) = item {
                                realize(vm, ch, styles, depth)?;
                            }
                        }
                    }
                    _ => {}
                }
            }
        }
    }
    Ok(())
}

/// Determine the `it` value for a show rule applied to an element.
fn match_show_target(content: &Content, sel: &Selector) -> Option<Content> {
    match sel {
        Selector::Elem(name, fields) => {
            if content.elem() != *name {
                return None;
            }
            let mut it = content.clone();
            if content.elem() == "heading" && it.field("level").is_none() {
                let depth = match it.field("depth") { Some(Value::Int(d)) => *d, _ => 1 };
                let offset = match it.field("offset") { Some(Value::Int(o)) => *o, _ => 0 };
                it.set_field("level", Value::Int(depth + offset));
            }
            if let Some(f) = fields {
                for (k, v) in f.iter() {
                    match it.field(k) {
                        Some(cv) if crate::eval::ops::equal(cv, v) => {}
                        _ => return None,
                    }
                }
            }
            Some(it)
        }
        Selector::Label(l) => {
            if content.label().is_some_and(|cl| cl == l) {
                Some(content.clone())
            } else {
                None
            }
        }
        Selector::Str(s) => {
            if content.elem() == "text" {
                if let Some(Value::Str(t)) = content.field("text") {
                    if t.contains(&**s) {
                        return Some(Content::text(s));
                    }
                }
            }
            None
        }
        Selector::Regex(r) => {
            if content.elem() == "text" {
                if let Some(Value::Str(t)) = content.field("text") {
                    if let Some(m) = r.regex.find(t) {
                        return Some(Content::text(m.as_str()));
                    }
                }
            }
            None
        }
        Selector::Or(items) => items.iter().find_map(|i| match_show_target(content, i)),
        Selector::And(items) => {
            let mut out = None;
            for i in items {
                out = match_show_target(content, i);
                out.as_ref()?;
            }
            out
        }
        _ => None,
    }
}
