fn open_file(app: Option<&str>, path: &Path) -> std::result::Result<(), String> {
    let candidates: Vec<&str> = match app {
        Some(a) => vec![a],
        None => vec!["xdg-open", "gio", "gnome-open", "kde-open"],
    };
    let mut last_err = None;
    for c in &candidates {
        let mut cmd = std::process::Command::new(c);
        if *c == "gio" {
            cmd.arg("open");
        }
        cmd.arg(path);
        match cmd.stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null()).spawn() {
            Ok(_) => return Ok(()),
            Err(e) => last_err = Some(e),
        }
    }
    let err = last_err.map(|e| e.to_string()).unwrap_or_default();
    match app {
        Some(a) => Err(format!("failed to open file with {a} ({err})")),
        None => Err(format!(
            "failed to open file with any of these resource openers: xdg-open, gio, gnome-open, kde-open ({err})"
        )),
    }
}

