            out.push(callee);
            for a in &args.items {
                match a {
                    AstArg::Pos(e) | AstArg::Spread(e) | AstArg::Named(_, e) => out.push(e),
                }
            }
        }
        ExprKind::Closure(c) => {
            for p in &c.params {
                if let Param::Named(_, e) = p {
                    out.push(e);
                }
            }
            out.push(&c.body);
        }
        ExprKind::Let { init, .. } => {
            if let Some(e) = init {
                out.push(e);
            }
        }
        ExprKind::DestructAssign { value, .. } => out.push(value),
