                    AstArg::Pos(e) | AstArg::Spread(e) | AstArg::Named(_, e) => out.push(e),
                }
            }
            if let Some(c) = condition {
                out.push(c);
            }
        }
        ExprKind::Show { selector, transform } => {
            if let Some(s) = selector {
                out.push(s);
            }
            out.push(transform);
        }
        ExprKind::Conditional { cond, if_body, else_body } => {
            out.push(cond);
            out.push(if_body);
            if let Some(e) = else_body {
                out.push(e);
            }
        }
        ExprKind::While { cond, body } => {
            out.push(cond);
            out.push(body);
        }
        ExprKind::For { iterable, body, .. } => {
            out.push(iterable);
            out.push(body);
        }
        ExprKind::Import { source, .. } => out.push(source),
        ExprKind::Return(Some(e)) => out.push(e),
        _ => {}
    }
    out
}

